-- Таблицы для совместимости с остальным кодом
local SERVER_NAMES = {}

-- Автоматическое заполнение таблиц совместимости
local SERVER_LOOKUP_MAP = {}

local function registerServersToMap(servers_data, proj_name)
    for i, srv in ipairs(servers_data) do
        srv.project = proj_name -- Помечаем, к какому проекту относится сервер
        SERVER_LOOKUP_MAP[tostring(i)] = srv -- Фоллбэк для числовых ID серверов
        SERVER_LOOKUP_MAP[srv.id:lower()] = srv
        SERVER_LOOKUP_MAP[srv.name:lower()] = srv 
        SERVER_LOOKUP_MAP[srv.ip .. ":" .. srv.port] = srv
        SERVER_LOOKUP_MAP[srv.ip] = srv
        if srv.domains then
            for _, domain in ipairs(srv.domains) do
                SERVER_LOOKUP_MAP[domain] = srv
                SERVER_LOOKUP_MAP[domain .. ":" .. srv.port] = srv
            end
        end
    end
end

registerServersToMap(RODINA_SERVERS_DATA, "rodina")

function findServerConfig(input)
    if input then
        local s = tostring(input):lower():gsub("^https?://", "")
        if SERVER_LOOKUP_MAP[s] then 
            return SERVER_LOOKUP_MAP[s] 
        end
        -- ИСПРАВЛЕНИЕ: Если ID передан (чужая лавка), но мы его не знаем,
        -- мы НЕ должны брать сервер игрока. Возвращаем nil.
        return nil
    end

    -- Резервный метод по Hostname (Срабатывает только для СВОЕГО сервера, когда input = nil)
    local hostname = sampGetCurrentServerName()
    if hostname then
        local host_clean = hostname:lower():gsub("{......}", "")
        for _, srv in ipairs(RODINA_SERVERS_DATA) do
            if host_clean:find(srv.name:lower(), 1, true) then
                return srv
            end
        end
    end
    return nil
end

local SERVER_DISPLAY_CACHE = {}
function getServerDisplayName(serverId)
    if not serverId then return "Unknown" end
    if SERVER_DISPLAY_CACHE[serverId] then return SERVER_DISPLAY_CACHE[serverId] end

    local cfg = findServerConfig(serverId)
    local name = cfg and cfg.name or serverId
    SERVER_DISPLAY_CACHE[serverId] = name
    return name
end

function normalizeServerId(serverId)
    -- Сначала пробуем найти конфиг по переданному IP
    local cfg = findServerConfig(serverId)
    
    -- Если не нашли по IP, функция findServerConfig внутри себя попробует найти по Hostname
    -- Но на всякий случай вызовем поиск без аргументов, чтобы сработал фоллбэк на Hostname
    if not cfg then
        cfg = findServerConfig(nil)
    end

    if cfg then
        return cfg.id 
    end
    
    -- Если совсем ничего не нашли, возвращаем то, что пришло (чтобы хоть что-то ушло в лог)
    return serverId
end

-- ==================== УТИЛИТЫ (STRING & ITEM UTILITIES) ====================
-- Определяем часто используемые функции до их срастения в модулях

local ITEM_PREFIXES = {
    "Улучшение оружия", "Унив. тюнинг", "Виз. тюнинг", "Тех. тюнинг", "Авто. номер",
    "Аксессуар", "Сертификат", "Приманка", "Саженец", "Улучшение",
    "Винила", "Объект", "Одежда", "Телефон", "Урожай", "Чертёж",
    "Предмет", "Актер", "Ларец", "Рыба", "Семя", "Туша", "Шкура", "Ящик"
}

function enhancedCleanItemName(name)
    if not name or name == "" then return "" end
    name = name:gsub("{%x%x%x%x%x%x}", ""):gsub("%[.-%]", ""):gsub("%s*%(.-%)", ""):gsub("^[оеш]?[втг]%s+", "")
    return name:match("^%s*(.-)%s*$") or ""
end

local CLEAN_NAME_CACHE = {} -- Глобальный кэш

function cleanItemName(name)
    if not name or name == "" then return "" end
    
    -- Мгновенный возврат, если мы уже чистили это имя
    if CLEAN_NAME_CACHE[name] then return CLEAN_NAME_CACHE[name] end

    local original_name = name
    name = enhancedCleanItemName(name)
    name = name:gsub("^[Тт][Юю][Нн][Ии][Нн][Гг]%s+", "")
    
    for i = 1, #ITEM_PREFIXES do
        local pfx = ITEM_PREFIXES[i]
        local pfx_pattern = "^[" .. pfx:sub(1,1):upper() .. pfx:sub(1,1):lower() .. "]" .. pfx:sub(2) .. "%s+"
        name = name:gsub(pfx_pattern, "")
    end
    
    -- Капитализация
    if name ~= "" then
        local first_byte = name:byte(1)
        if first_byte >= 224 and first_byte <= 255 then
            name = string.char(first_byte - 32) .. name:sub(2)
        elseif first_byte == 184 then
            name = string.char(168) .. name:sub(2)
        end
    end
    
    local final_name = name:match("^%s*(.-)%s*$") or name
    
    -- Записываем в кэш для будущих вызовов
    CLEAN_NAME_CACHE[original_name] = final_name
    return final_name
end

    --- Извлечение категории товара по имени
function extractCategory(raw_name)
        if not raw_name or raw_name == "" then return "Предмет" end
        
        local clean = enhancedCleanItemName(raw_name)
        local lower_clean = to_lower(clean)

        for _, prefix in ipairs(ITEM_PREFIXES) do
            local lower_prefix = to_lower(prefix)
            if lower_clean:find("^" .. lower_prefix .. "%s") then
                return prefix
            end
        end
        return "Предмет" -- Дефолт
    end

--- Это просто алиасы для совместимости
function cleanItemNameKey(name) return enhancedCleanItemName(name) end
