-- ==================== DRAG & DROP СИСТЕМА ====================
local MagnetMove = {
    active = false,
    mode = nil,        -- "sell" или "buy"
    from_index = -1,
    item_data = nil,
    pickup_time = 0    -- [ФИКС] Время взятия предмета для защиты от моментальной отмены
}

local DragDropAction = {
    active = false,                              -- Активна ли операция перетаскивания
    type = "",                                   -- Тип операции: "move", "merge", "delete"
    source_list = nil,                           -- Источская таблица
    target_list = nil,                           -- Целевая таблица (для вложенности)
    from_idx = -1,                               -- Индекс источника
    to_idx = -1                                  -- Индекс назначения
}

-- Функция для выполнения отложенных действий (вызывать в конце renderAutoPRTab)
function resolveDragDropActions()
    if not DragDropAction.active then return end
    
    local act = DragDropAction
    
    if act.type == "move" and act.source_list then
        -- Обычное перемещение (сортировка)
        if act.from_idx ~= act.to_idx and act.source_list[act.from_idx] then
            local item = table.remove(act.source_list, act.from_idx)
            -- Коррекция индекса, если удалили сверху
            local dest = act.to_idx
            if dest > #act.source_list + 1 then dest = #act.source_list + 1 end
            table.insert(act.source_list, dest, item)
            saveSettings()
        end
        
    elseif act.type == "merge" and act.source_list then
        -- Объединение в группу
        -- Сначала получаем объекты, пока они есть
        local source_item = act.source_list[act.from_idx]
        local target_item = act.source_list[act.to_idx]
        
        if source_item and target_item then
            -- Удаляем оба из списка (сначала больший индекс, чтобы не сбить меньший)
            local idx1, idx2 = act.from_idx, act.to_idx
            if idx1 > idx2 then
                table.remove(act.source_list, idx1)
                table.remove(act.source_list, idx2)
            else
                table.remove(act.source_list, idx2)
                table.remove(act.source_list, idx1)
            end
            
            -- Создаем новую группу
            local new_group = {
                type = "group",
                name = u8"Группа",
                delay = 10,
                active = true,
                current_idx = 1,
                items = {},
                expanded = true,
                next_send = 0,
                channel = 1
            }
            
            -- Добавляем элементы в группу (Цель первая, Источник второй)
            -- Сбрасываем задержки, так как управляет группа
            target_item.delay = nil
            source_item.delay = nil
            table.insert(new_group.items, target_item)
            table.insert(new_group.items, source_item)
            
            -- Вставляем группу на позицию целевого элемента (минимальный из двух индексов)
            local insert_pos = math.min(idx1, idx2)
            table.insert(act.source_list, insert_pos, new_group)
            saveSettings()
        end
        
    elseif act.type == "add_to_group" and act.source_list then
        -- Добавление в существующую группу
        local source_item = table.remove(act.source_list, act.from_idx)
        
        -- Индекс группы мог сместиться, если удалили элемент выше
        local target_real_idx = act.to_idx
        if act.from_idx < act.to_idx then
            target_real_idx = target_real_idx - 1
        end
        
        local group_item = act.source_list[target_real_idx]
        if group_item and group_item.type == "group" then
            source_item.delay = nil
            table.insert(group_item.items, source_item)
            saveSettings()
        else
            -- Если что-то пошло не так, возвращаем элемент назад
            table.insert(act.source_list, act.from_idx, source_item)
        end
        
    elseif act.type == "delete" and act.source_list then
        if act.source_list[act.from_idx] then
            table.remove(act.source_list, act.from_idx)
            saveSettings()
        end
    end
    
    -- Сброс
    DragDropAction = { active = false, type = "", source_list = nil }
end

