local function cleanTextColors(text)
    if type(text) ~= 'string' or text == "" then return "" end
    return text:gsub("{%x+}", ""):gsub("%[%x%x%x%x%x%x%]", ""):match("^%s*(.-)%s*$") or text
end

function processPRVariables(text)
    if not text then return "" end
    
    local _, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    local myName = LOCAL_PLAYER_NICK or sampGetPlayerNickname(myId) or "Unknown"
    
    local vars = {
        ["{id}"] = tostring(myId),
        ["{name}"] = myName,
        ["{name_space}"] = myName:gsub("_", " "),
        ["{lvl}"] = tostring(sampGetPlayerScore(myId)),
        ["{time}"] = os.date("%H:%M")
    }
    
    return text:gsub("{(.-)}", function(k) return vars["{"..k.."}"] or "{"..k.."}" end)
end

