local Logger = {
    history = {},
    last_log_time = 0
}

function Logger.log(level, text)
    local prefix = "[RMarket]"
    local color = "{FFFFFF}"
    if level == "INFO" then color = "{AAAAAA}"
    elseif level == "WARN" then color = "{FFFF00}"
    elseif level == "ERR" then color = "{FF0000}" 
    elseif level == "OK" then color = "{00FF00}" end
    
    -- Дедупликация (не спамить одинаковыми сообщениями чаще чем раз в 2 сек)
    local now = os.clock()
    local key = level .. text
    if Logger.history[key] and (now - Logger.history[key] < 2.0) then return end
    Logger.history[key] = now
    
    -- Очистка истории каждые 60 сек
    if now - Logger.last_log_time > 60 then
        Logger.history = {}
        Logger.last_log_time = now
    end

    sampAddChatMessage(string.format("%s %s%s", prefix, color, text), -1)
end

