function isVerifiedVip()
    if not Data.is_vip then return false end
    
    if not Data.settings.telegram_token or string.len(Data.settings.telegram_token) < 10 then
        Data.is_vip = false
        return false
    end
    
    local current_time = os.time()
    
    -- [INNOVATION VIP] Точная проверка окончания подписки (секунда в секунду)
    if Data.vip_expire_ts and Data.vip_expire_ts > 0 then
        if current_time >= Data.vip_expire_ts then
            Data.is_vip = false
            -- Если VIP кончился прямо во время игры, очищаем кэши и радары мгновенно
            if #Data.radar_list > 0 then
                Data.radar_list = {}
                saveListsConfig()
                addToastNotification("Срок действия VIP истек. Радар отключен.", "warning", 5.0)
            end
            return false
        end
    end
    
    -- Защита от заморозки памяти (Обновляем данные минимум раз в 12 часов)
    if current_time - (Data.vip_validated_at or 0) > 43200 then
        Data.is_vip = false
        return false
    end
    
    return true
end

local function validateDataIntegrity()
    if not Data.buy_list or not Data.sell_list or not Data.buy_configs or not Data.sell_configs then return false end
    if Data.active_buy_config and not Data.buy_configs[Data.active_buy_config] then
        Data.active_buy_config = 1
        if not Data.buy_configs[1] then createBuyConfig("Main") end
    end
    return true
end

