function CarMarket.isPlayerInAutoBazar()
    local x, y, z = getCharCoordinates(PLAYER_PED)
    if not x then return false end
    -- Координаты АБ Эконом и Люкс (Расширены на 50м для машин у заборов)
    local zones = {
        { minX = -1550.0, maxX = -1250.0, minY = 1580.0, maxY = 1910.0 },
        { minX = -120.0,  maxX = 220.0,   minY = -1260.0, maxY = -960.0 }
    }
    for _, z_zone in ipairs(zones) do
        local x_min, x_max = math.min(z_zone.minX, z_zone.maxX), math.max(z_zone.minX, z_zone.maxX)
        local y_min, y_max = math.min(z_zone.minY, z_zone.maxY), math.max(z_zone.minY, z_zone.maxY)
        if x >= x_min and x <= x_max and y >= y_min and y <= y_max then return true end
    end
    return false
end

function CarMarket.processPrice(car_name, rarity_key, price)
    if not car_name or price <= 0 then return end
    car_name = car_name:gsub("{......}", ""):gsub("\n", ""):match("^%s*(.-)%s*$")
    if car_name == "" then return end
    
    local srv_db, server_id = CarMarket.getCurrentServerDB()
    
    -- Формируем уникальный локальный ключ "Имя [Качество]"
    local r_map = { ["tier1"] = "Хлам", ["tier2"] = "Обычное", ["tier3"] = "Идеальное" }
    local r_text = r_map[rarity_key] or "Обычное"
    local full_local_name = car_name .. " [" .. r_text .. "]"
    
    if not srv_db[full_local_name] then
        srv_db[full_local_name] = { p = {}, min = 0, max = 0 }
    end
    
    local car = srv_db[full_local_name]
    if (car.min > 0 and price < car.min) or (car.max > 0 and price > car.max) then return end
    
    for i = math.max(1, #car.p - 5), #car.p do
        if car.p[i] == price then return end
    end
    
    table.insert(car.p, price)
    if #car.p > 50 then table.remove(car.p, 1) end
    
    SaveScheduler.cars_dirty = true

    local payload = {
        server = server_id,
        car_name = u8(car_name),
        rarity = rarity_key,
        price = price
    }
    signed_request("POST", MarketConfig.HOST .. "/cars/submit", payload)
end

