function updateInvCategories()
    local unique_cats = {}
    local sorted_cats = {}
    
    -- Собираем уникальные категории из Data.scanned_items
    for _, item in ipairs(Data.scanned_items) do
        -- Находим категорию по model_id
        local cat = "Предмет"
        if item.model_id and Data.item_categories[tostring(item.model_id)] then
            cat = Data.item_categories[tostring(item.model_id)]
        elseif item.name then
            cat = extractCategory(item.name) -- фоллбэк
        end
        
        if cat and cat ~= "" and not unique_cats[cat] then
            unique_cats[cat] = true
            table.insert(sorted_cats, cat)
        end
    end
    
    table.sort(sorted_cats)
    
    inv_category_list_ui = {u8"Все категории"}
    inv_category_list_raw = {"All"}
    
    for _, cat in ipairs(sorted_cats) do
        table.insert(inv_category_list_ui, u8(cat))
        table.insert(inv_category_list_raw, cat)
    end
    
    if inv_category_filter_idx >= #inv_category_list_ui then
        inv_category_filter_idx = 0
    end
end

-- [NEW] Функция обновления списка категорий на основе доступных товаров
function updateBuyCategories()
    local unique_cats = {}
    local sorted_cats = {}
    
    -- Собираем уникальные категории из загруженных товаров для скупки
    for _, item in ipairs(Data.buyable_items) do
        if item.category and item.category ~= "" and not unique_cats[item.category] then
            unique_cats[item.category] = true
            table.insert(sorted_cats, item.category)
        end
    end
    
    table.sort(sorted_cats)
    
    -- Сбрасываем списки
    buy_category_list_ui = {u8"Все категории"}
    buy_category_list_raw = {"All"}
    
    -- Заполняем новыми данными
    for _, cat in ipairs(sorted_cats) do
        table.insert(buy_category_list_ui, u8(cat))
        table.insert(buy_category_list_raw, cat)
    end
    
    -- Если выбранный индекс вышел за пределы, сбрасываем на "Все"
    if buy_category_filter_idx >= #buy_category_list_ui then
        buy_category_filter_idx = 0
    end
end

