local LAVKA_MODELS = {
    [5894]  = { angle = -90              },
    [1342]  = { angle = 0                },
    [16656] = { angle = 90               },
    [6494]  = { angle = -90, offset = 1.2 },
    [6495]  = { angle = -90, offset = 1.2 },
    [6493]  = { angle = -90, offset = 1.2 },
    [6492]  = { angle = -90, offset = 1.2 },
