local function isLavkaModel(model) return LAVKA_MODELS[model] ~= nil end

local function dist2d_sq(x1,y1,x2,y2)
    local dx,dy = x1-x2, y1-y2
    return dx*dx+dy*dy
end

local function updateLavkas()
    lavkas = {}
    local px, py, pz = getCharCoordinates(PLAYER_PED)
    if not pz then return end
    frozenZ = pz - 0.9

    local objects = getAllObjects()
    if objects then
        -- [FPS BOOST] Выносим функции из цикла
        local getModel = getObjectModel
        local getCoords = getObjectCoordinates
        local getHeading = getObjectHeading
        local rad, cos, sin = math.rad, math.cos, math.sin
        
        for i = 1, #objects do
            local obj = objects[i]
            -- Убрали тяжелый doesObjectExist, getAllObjects и так возвращает валидные хэндлы
            local model = getModel(obj)
            local cfg = LAVKA_MODELS[model]
            
            if cfg then
                local ok, x, y, z = getCoords(obj)
                -- Отсекаем лавки, которые дальше 150 метров (экономим процессор)
                if ok and (math.abs(x - px) < 150.0 and math.abs(y - py) < 150.0) then
                    local offsetDist = cfg.offset or DEFAULT_OFFSET
                    local deg = getHeading and getHeading(obj) or 0.0
                    local heading = rad(deg + cfg.angle)
                    
                    table.insert(lavkas, {
                        x = x, y = y, z = z, model = model,
                        cx = x + cos(heading) * offsetDist, 
                        cy = y + sin(heading) * offsetDist,
                    })
                end
            end
        end
    end

    cachedBuiltZones  = {}
    cachedScreenZones = {}
    screenCacheCounter = 0
    buildAllZones()
end

local function pointInConvexPoly(px, py, poly)
    local n = #poly
    if n < 3 then return false end
    for i = 1, n do
        local a = poly[i]
        local b = poly[(i % n) + 1]
        local ex, ey = b[1]-a[1], b[2]-a[2]
        local fx, fy = px-a[1],   py-a[2]
        if ex*fy - ey*fx < -1e-6 then return false end
    end
    return true
end

local function getPlayerInsideLav()
    local px, py = getCharCoordinates(playerPed)
    for _, entry in ipairs(cachedBuiltZones) do
        if #entry.zone >= 3 and pointInConvexPoly(px, py, entry.zone) then
            return entry.lav
        end
    end
    return nil
end

local function clipByHalfplane(poly, lpx, lpy, nx, ny)
    if #poly == 0 then return poly end
    local result = {}

    local function inside(x, y)
        return (x-lpx)*nx + (y-lpy)*ny >= -1e-6
    end

    local function intersect(x1,y1, x2,y2)
        local dx, dy = x2-x1, y2-y1
        local denom = dx*nx + dy*ny
        if math.abs(denom) < 1e-10 then return x1, y1 end
        local t = ((lpx-x1)*nx + (lpy-y1)*ny) / denom
        return x1+t*dx, y1+t*dy
    end

    local n = #poly
    for i = 1, n do
        local cur  = poly[i]
        local next = poly[(i % n) + 1]
        local ci = inside(cur[1],  cur[2])
        local ni = inside(next[1], next[2])
        if ci then
            table.insert(result, cur)
            if not ni then
                local ix, iy = intersect(cur[1],cur[2], next[1],next[2])
                table.insert(result, {ix, iy})
            end
        elseif ni then
            local ix, iy = intersect(cur[1],cur[2], next[1],next[2])
            table.insert(result, {ix, iy})
        end
    end
    return result
end

local CIRCLE_SEGS = 48
local function clipPolygonByCircle(poly, cx, cy, R)
    for i = 0, CIRCLE_SEGS - 1 do
        local am = (i + 0.5) * (2*math.pi / CIRCLE_SEGS)
        local nx = math.cos(am)
        local ny = math.sin(am)
        poly = clipByHalfplane(poly, cx + R*nx, cy + R*ny, -nx, -ny)
        if #poly == 0 then return poly end
    end
    return poly
end

local BIG = 200.0

local function buildVoronoiZone(lav)
    local cx, cy = lav.cx, lav.cy
    local poly = {
        {cx - BIG, cy - BIG},
        {cx + BIG, cy - BIG},
        {cx + BIG, cy + BIG},
        {cx - BIG, cy + BIG},
    }
    for _, other in ipairs(lavkas) do
        if other ~= lav then
            local mx = (cx + other.cx) / 2
            local my = (cy + other.cy) / 2
            local dx = cx - other.cx
            local dy = cy - other.cy
            local d  = math.sqrt(dx*dx + dy*dy)
            if d > 0.001 then
                local nx = dx / d
                local ny = dy / d
                poly = clipByHalfplane(poly, mx, my, nx, ny)
                if #poly == 0 then return poly end
            end
        end
    end
    poly = clipPolygonByCircle(poly, cx, cy, RADIUS)
    return poly
end

function buildAllZones()
    cachedBuiltZones = {}
    for _, lav in ipairs(lavkas) do
        local zone = buildVoronoiZone(lav)
        table.insert(cachedBuiltZones, { lav = lav, zone = zone })
    end
end

local function applyAlpha(color, a)
    local r     = bit.band(color, 0xFF)
    local g     = bit.band(bit.rshift(color, 8),  0xFF)
    local b     = bit.band(bit.rshift(color, 16), 0xFF)
    local origA = bit.band(bit.rshift(color, 24), 0xFF)
    local newA  = math.floor(origA * a)
    return bit.bor(r, bit.lshift(g, 8), bit.lshift(b, 16), bit.lshift(newA, 24))
end

local FADE_START = RADIUS * 2.0
local FADE_END   = RADIUS * 8.0
local ALPHA_MIN  = 0.07

local function calcFadeAlpha(dist)
    if dist <= FADE_START then
        return 1.0
    elseif dist >= FADE_END then
        return ALPHA_MIN
    else
        local t = (dist - FADE_START) / (FADE_END - FADE_START)
        local smooth = t * t * (3 - 2*t)
        return math.max(ALPHA_MIN, 1.0 - smooth * (1.0 - ALPHA_MIN))
    end
end

-- [ОПТИМИЗАЦИЯ FPS] Статический пул полигонов (0 аллокаций памяти в кадре)
local STATIC_POLY_BUFFERS = {}
for i = 1, 100 do STATIC_POLY_BUFFERS[i] = imgui.new("ImVec2[30]") end

local function rebuildScreenZones()
    cachedScreenZones = {}
    local buffer_idx = 1
    
    for _, entry in ipairs(cachedBuiltZones) do
        local zone = entry.zone
        if #zone >= 3 and buffer_idx <= 100 then
            local buf = STATIC_POLY_BUFFERS[buffer_idx]
            local validN = 0
            
            for _, pt in ipairs(zone) do
                if validN >= 30 then break end -- Защита от переполнения
                local _, sx, sy, sz = convert3DCoordsToScreenEx(pt[1], pt[2], frozenZ)
                
                if sz and sz > 0.0001 and sx == sx and sy == sy then
                    if sx > -10000 and sx < 20000 and sy > -10000 and sy < 20000 then
                        buf[validN].x = sx
                        buf[validN].y = sy
                        validN = validN + 1
                    end
                end
            end
            
            if validN >= 3 then
                table.insert(cachedScreenZones, {
                    lav    = entry.lav,
                    buf    = buf,
                    validN = validN,
                })
                buffer_idx = buffer_idx + 1
            end
        end
    end
end

local function imColor(r, g, b, a)
    return bit.bor(r, bit.lshift(g, 8), bit.lshift(b, 16), bit.lshift(a, 24))
end

local function drawPlacementOverlay(dl, sW, sH, canPlace, alpha)
    if alpha <= 0.01 then return end

    local panelW = 300
    local panelH = 70
    local posX   = 10
    local posY   = sH - panelH - 370
    local finalAlpha = alpha

    -- Фон плашки (используем дизайн скрипта)
    local bgColor = imColor(19, 19, 24, math.floor(220 * finalAlpha))
    dl:AddRectFilled(
        imgui.ImVec2(posX, posY),
        imgui.ImVec2(posX + panelW, posY + panelH),
        bgColor, 8.0
    )

    -- Граница плашки
    local statusColor
    if canPlace then
        statusColor = imColor(230, 89, 89, math.floor(255 * finalAlpha)) -- Красный (нельзя)
    else
        statusColor = imColor(102, 204, 128, math.floor(255 * finalAlpha)) -- Зеленый (можно)
    end

    dl:AddRect(
        imgui.ImVec2(posX, posY),
        imgui.ImVec2(posX + panelW, posY + panelH),
        statusColor, 8.0, imgui.DrawCornerFlags.All, 2.0
    )

    -- Иконка статуса слева (кружок)
    local iconX = posX + 15
    local iconY = posY + panelH / 2
    dl:AddCircleFilled(imgui.ImVec2(iconX, iconY), 6.0, statusColor)

    -- Основной текст
    local labelText
    if canPlace then
        labelText = u8("Нельзя ставить лавку")
    else
        labelText = u8("Можно ставить лавку")
    end

    imgui.SetWindowFontScale(1.4)
    imgui.SetCursorScreenPos(imgui.ImVec2(posX + 35, posY + 12))
    imgui.TextColored(imgui.ImVec4(0.98, 0.98, 0.99, finalAlpha), labelText)
    imgui.SetWindowFontScale(1.0)

    -- Вспомогательный текст (подсказка)
    imgui.SetWindowFontScale(0.85)
    imgui.SetCursorScreenPos(imgui.ImVec2(posX + 35, posY + 40))
    if canPlace then
        imgui.TextColored(imgui.ImVec4(0.90, 0.35, 0.35, finalAlpha * 0.8), u8("Вы находитесь в радиусе чужой лавки"))
    else
        imgui.TextColored(imgui.ImVec4(0.40, 0.80, 0.50, finalAlpha * 0.8), u8("Место свободно для лавки"))
    end
    imgui.SetWindowFontScale(1.0)

    -- Вотермарка в правом нижнем углу
    local watermarkText = u8("Lavka Radius by Edward")
    local watermarkSize = GetStaticTextSize(watermarkText)
    local watermarkX = sW - watermarkSize.x - 15
    local watermarkY = sH - watermarkSize.y - 10

    imgui.SetWindowFontScale(0.75)
    imgui.SetCursorScreenPos(imgui.ImVec2(watermarkX, watermarkY))
    imgui.TextColored(imgui.ImVec4(0.60, 0.62, 0.70, finalAlpha * 0.5), watermarkText)
    imgui.SetWindowFontScale(1.0)
end

