local function BuildThemeU32(theme_table)
    local keys_to_process = {}
    for k, v in pairs(theme_table) do
        if type(v) == "cdata" and tostring(ffi.typeof(v)):find("ImVec4") then
            table.insert(keys_to_process, {k, v})
        end
    end
    for _, data in ipairs(keys_to_process) do
        local k, v = data[1], data[2]
        theme_table[k .. "_u32"] = imgui.ColorConvertFloat4ToU32(v)
        local hover_vec = imgui.ImVec4(math.min(v.x + 0.1, 1.0), math.min(v.y + 0.1, 1.0), math.min(v.z + 0.1, 1.0), v.w)
        theme_table[k .. "_hover"] = hover_vec
        theme_table[k .. "_hover_u32"] = imgui.ColorConvertFloat4ToU32(hover_vec)
    end
    return theme_table
end

for k, v in pairs(THEME_COLORS) do THEME_COLORS[k] = BuildThemeU32(v) end
local CURRENT_THEME = THEME_COLORS.RODINA_NATIVE

function applyTheme(theme_name)
    if THEME_COLORS[theme_name] then
        CURRENT_THEME = THEME_COLORS[theme_name]
        if Data.settings then
            Data.settings.current_theme = theme_name
            if not App.data_loading then saveSettings() end
        end
        if not App.data_loading then pcall(applyStrictStyle) end
    end
end

function applyStrictStyle()
    local style = imgui.GetStyle()
    local colors = style.Colors
    
    -- Скругления в стиле матового современного дизайна
    style.WindowRounding    = S(8.0)
    style.ChildRounding     = S(6.0)
    style.FrameRounding     = S(6.0)
    style.PopupRounding     = S(8.0)
    style.ScrollbarRounding = S(6.0)
    style.TabRounding       = S(6.0)
    
    style.WindowPadding     = imgui.ImVec2(S(20), S(20))
    style.FramePadding      = imgui.ImVec2(S(12), S(8)) 
    style.ItemSpacing       = imgui.ImVec2(S(10), S(10))
    
    style.ScrollbarSize     = S(4) 
    style.WindowBorderSize  = 0
    style.ChildBorderSize   = 0
    style.PopupBorderSize   = S(1)
    style.FrameBorderSize   = S(1) -- Рамка для инпутов
    
    local theme = CURRENT_THEME
    if not theme then return end
    
    -- Тотальный матовый фиолетовый контроль
    colors[imgui.Col.WindowBg]              = theme.bg_main
    colors[imgui.Col.ChildBg]               = theme.bg_secondary
    colors[imgui.Col.PopupBg]               = imgui.ImVec4(theme.bg_main.x, theme.bg_main.y, theme.bg_main.z, 0.98)
    colors[imgui.Col.Border]                = theme.border_light
    colors[imgui.Col.BorderShadow]          = imgui.ImVec4(0,0,0,0)
    
    colors[imgui.Col.Text]                  = theme.text_primary
    colors[imgui.Col.TextDisabled]          = theme.text_hint
    
    colors[imgui.Col.FrameBg]               = imgui.ImVec4(theme.bg_main.x, theme.bg_main.y, theme.bg_main.z, 0.5)
    colors[imgui.Col.FrameBgHovered]        = theme.accent_hover
    colors[imgui.Col.FrameBgActive]         = theme.accent_primary
    
    -- Заголовки
    colors[imgui.Col.Header]                = theme.bg_tertiary
    colors[imgui.Col.HeaderHovered]         = theme.accent_hover
    colors[imgui.Col.HeaderActive]          = theme.accent_primary
    
    -- Кнопки
    colors[imgui.Col.Button]                = theme.bg_tertiary
    colors[imgui.Col.ButtonHovered]         = theme.accent_hover
    colors[imgui.Col.ButtonActive]          = theme.accent_primary
    
    -- Чекмарки и слайдеры (Исправляет синие галочки)
    colors[imgui.Col.CheckMark]             = theme.accent_primary
    colors[imgui.Col.SliderGrab]            = theme.text_hint
    colors[imgui.Col.SliderGrabActive]      = theme.text_primary
    
    -- Скроллбар
    colors[imgui.Col.ScrollbarBg]           = imgui.ImVec4(0, 0, 0, 0)
    colors[imgui.Col.ScrollbarGrab]         = imgui.ImVec4(1, 1, 1, 0.08)
    colors[imgui.Col.ScrollbarGrabHovered]  = imgui.ImVec4(1, 1, 1, 0.15)
    colors[imgui.Col.ScrollbarGrabActive]   = imgui.ImVec4(1, 1, 1, 0.20)
    
    -- Выделение и сепараторы
    colors[imgui.Col.TextSelectedBg]        = imgui.ImVec4(1, 1, 1, 0.15)
    colors[imgui.Col.Separator]             = theme.border_light
    colors[imgui.Col.SeparatorHovered]      = theme.accent_secondary
    colors[imgui.Col.SeparatorActive]       = theme.accent_primary
end

function lerpColor(col1, col2, t)
    return imgui.ImVec4(
        col1.x + (col2.x - col1.x) * t,
        col1.y + (col2.y - col1.y) * t,
        col1.z + (col2.z - col1.z) * t,
        col1.w + (col2.w - col1.w) * t
    )
end

