local ItemImagesCache = {
    textures = {},
    last_used = {}, 
    queue = {},      -- Очередь на загрузку (чтобы не фризить игру)
    loading = {},    -- Флаги текущих загрузок
    failed = {},     -- Флаги отсутствующих иконок (чтобы не спамить диск)
    path = PATHS.CACHE .. 'icons/',
    max_textures = 600,
    last_cleanup = 0
}

if not doesDirectoryExist(ItemImagesCache.path) then
    createDirectory(ItemImagesCache.path)
end

local GLOBAL_FRAME_TIME = os.clock()

-- [FPS BOOST] Мгновенный конвертер прозрачности без вызова C++ ImGui
local function setAlphaU32(color_u32, alpha_float)
    local a = math.floor(alpha_float * 255)
    if a < 0 then a = 0 elseif a > 255 then a = 255 end
    return bit.bor(bit.band(color_u32, 0x00FFFFFF), bit.lshift(a, 24))
end

-- НОВАЯ ФУНКЦИЯ: Асинхронный обработчик очереди (вызывается 1 раз в кадр)
function processImageLoaderQueue()
    if GLOBAL_FRAME_TIME - ItemImagesCache.last_cleanup > 10.0 then
        ItemImagesCache.last_cleanup = GLOBAL_FRAME_TIME
        local count = 0
        local sortable_cache = {}
        for id, t_used in pairs(ItemImagesCache.last_used) do
            count = count + 1
            table.insert(sortable_cache, {id = id, t = t_used})
        end
        if count > ItemImagesCache.max_textures then
            table.sort(sortable_cache, function(a, b) return a.t < b.t end)
            for i = 1, 50 do
                if sortable_cache[i] then
                    local old_id = sortable_cache[i].id
                    ItemImagesCache.textures[old_id] = nil
                    ItemImagesCache.last_used[old_id] = nil
                    ItemImagesCache.loading[old_id] = nil
                end
            end
        end
    end

    local q_len = #ItemImagesCache.queue
    if q_len == 0 then return end

    -- [CRITICAL SCROLL FIX] Защита от переполнения очереди при быстром скролле.
    -- Оставляем только 12 последних запросов (то, что реально на экране), остальное сбрасываем.
    if q_len > 12 then
        for i = 1, q_len - 12 do
            ItemImagesCache.loading[ItemImagesCache.queue[i]] = false
        end
        local new_q = {}
        for i = q_len - 11, q_len do
            table.insert(new_q, ItemImagesCache.queue[i])
        end
        ItemImagesCache.queue = new_q
    end

    local id_str = table.remove(ItemImagesCache.queue)
    if ItemImagesCache.textures[id_str] then return end

    -- [ОПТИМИЗАЦИЯ] Изменен суффикс файла на _opt.png.
    -- Это заставит скрипт проигнорировать старые тяжелые FullHD картинки в папке cache,
    -- и скачать их заново, но уже в сжатом виде, навсегда избавив от фризов.
    local filepath = ItemImagesCache.path .. id_str .. '_opt.png'

    if doesFileExist(filepath) then
        local img, width, height = imgui.CreateTextureFromFile(filepath)
        if img then
            ItemImagesCache.textures[id_str] = img
            ItemImagesCache.last_used[id_str] = GLOBAL_FRAME_TIME
            ItemImagesCache.loading[id_str] = false
        else
            ItemImagesCache.failed[id_str] = true
            ItemImagesCache.loading[id_str] = false
        end
    else
        -- Берем оригинальный путь без https://
        local base_url = "reserve-cdn.azresources.cloud/projects/rodina-rp/systems/battlepass/items/" .. id_str .. ".png"
        
        -- [ОПТИМИЗАЦИЯ] Пропускаем через бесплатный прокси-ресайзер:
        -- w=128 & h=128 (сжимает до размера иконки), output=png (ImGui не понимает webp без плагинов)
        local url = "https://wsrv.nl/?url=" .. base_url .. "&w=128&h=128&fit=contain&output=png"

        asyncHttpRequest('GET', url, { timeout = 5 }, function(response)
            if response.status_code == 200 and response.text and #response.text > 100 then
                lua_thread.create(function()
                    local f = io.open(filepath, "wb")
                    if f then f:write(response.text) f:close() end
                    table.insert(ItemImagesCache.queue, id_str)
                end)
            else
                ItemImagesCache.failed[id_str] = true
                ItemImagesCache.loading[id_str] = false
            end
        end, function() 
            ItemImagesCache.failed[id_str] = true
            ItemImagesCache.loading[id_str] = false
        end)
    end
end

function getItemIconTexture(model_id)
    if not Data.settings.show_item_images then return nil end
    if not model_id or model_id <= 0 then return nil end
    local id_str = tostring(model_id)

    -- 1. Сразу отдаем текстуру, если она уже в памяти (0 задержек)
    local tex = ItemImagesCache.textures[id_str]
    if tex then
        if not ItemImagesCache.last_used[id_str] or (GLOBAL_FRAME_TIME - ItemImagesCache.last_used[id_str] > 2.0) then
             ItemImagesCache.last_used[id_str] = GLOBAL_FRAME_TIME
        end
        return tex
    end

    -- 2. Если файл битый или скачивается - игнорируем, чтобы не спамить
    if ItemImagesCache.loading[id_str] or ItemImagesCache.failed[id_str] then
        return nil
    end

    -- 3. Добавляем в очередь. Диск прочитает отдельный обработчик!
    ItemImagesCache.loading[id_str] = true
    table.insert(ItemImagesCache.queue, id_str)

    return nil
end

function addToastNotification(message, notification_type, duration)
    -- [FIX] Инициализация таблицы, если она отсутствует (защита от краша)
    if not toast_notifications then toast_notifications = {} end

    notification_type = notification_type or "info"
    duration = duration or 3.0
    
    local color_map = {
        success = CURRENT_THEME.accent_success,
        error = CURRENT_THEME.accent_danger,
        warning = CURRENT_THEME.accent_warning,
        info = CURRENT_THEME.accent_primary
    }
    
    table.insert(toast_notifications, {
        message = message,
        type = notification_type,
        color = color_map[notification_type] or CURRENT_THEME.accent_primary,
        created_at = os.clock(),
        duration = duration,
        alpha = 0.0
    })
    
    -- [OPTIMIZATION] Ограничиваем количество уведомлений, чтобы не перегружать рендер
    if #toast_notifications > 5 then
        table.remove(toast_notifications, 1)
    end
end

function renderHorizontalCategoryBar(width)
    local draw_list = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local height = S(44) -- Высота всей полосы
    
    -- Настройки отступов: S(8) слева/справа, S(10) между кнопками
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), 0))
    imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(S(10), 0))
    imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0)) -- Прозрачный фон
    
    -- Флаги:
    -- HorizontalScrollbar: Включает логику горизонтальной прокрутки
    -- NoScrollbar: Скрывает саму серую полосу (визуально чище)
    local flags = imgui.WindowFlags.HorizontalScrollbar + imgui.WindowFlags.NoScrollbar
    
    if imgui.BeginChild("##HorizCatScroll", imgui.ImVec2(width, height), false, flags) then
        
        -- === [ГЛАВНАЯ ЛОГИКА СКРОЛЛА] ===
        -- Проверяем, находится ли курсор над нашей лентой категорий
        if imgui.IsWindowHovered() then
            local wheel = imgui.GetIO().MouseWheel -- Получаем движение колеса (обычно вверх/вниз)
            
            if wheel ~= 0 then
                -- Скорость прокрутки. Можно увеличить число (например 60), чтобы крутилось быстрее
                local scroll_speed = S(45)
                
                local current_scroll = imgui.GetScrollX()
                local max_scroll = imgui.GetScrollMaxX()
                
                -- Формула: Текущая позиция МИНУС (колесо * скорость).
                -- Колесо ВНИЗ (отрицательное) -> минус на минус дает плюс -> скролл ВПРАВО
                -- Колесо ВВЕРХ (положительное) -> скролл ВЛЕВО
                local new_scroll = current_scroll - (wheel * scroll_speed)
                
                -- Устанавливаем новую позицию
                imgui.SetScrollX(new_scroll)
            end
        end
        -- ================================

        -- Центрируем кнопки по вертикали внутри полосы
        local btn_height = S(28)
        imgui.SetCursorPosY((height - btn_height) / 2)
        
        for i, cat_name in ipairs(buy_category_list_ui) do
            local is_selected = (buy_category_filter_idx == i - 1)
            
            -- Расчет ширины кнопки на основе текста
            local text_size = GetStaticTextSize(cat_name)
            local item_w = text_size.x + S(24) -- Добавляем отступы (padding) по бокам
            
            local cursor_x = imgui.GetCursorPosX()
            local cursor_y = imgui.GetCursorPosY()
            
            -- Рисуем невидимую кнопку для обработки клика
            if imgui.InvisibleButton("cat_btn_"..i, imgui.ImVec2(item_w, btn_height)) then
                buy_category_filter_idx = i - 1
                BuyableItems.force_refresh = true
            end
            
            local is_hovered = imgui.IsItemHovered()
            
            -- Цвета в зависимости от состояния
            local bg_col
            local text_col
            local border_col
            
            if is_selected then
                -- Активная (выбранная) категория
                bg_col = CURRENT_THEME.accent_primary
                text_col = CURRENT_THEME.text_primary
                border_col = CURRENT_THEME.accent_primary
            else
                -- Обычная категория
                if is_hovered then
                    -- При наведении чуть светлее
                    bg_col = imgui.ImVec4(CURRENT_THEME.bg_tertiary.x + 0.15, CURRENT_THEME.bg_tertiary.y + 0.15, CURRENT_THEME.bg_tertiary.z + 0.15, 1.0)
                    text_col = CURRENT_THEME.text_primary
                    border_col = CURRENT_THEME.text_hint
                else
                    bg_col = CURRENT_THEME.bg_tertiary
                    text_col = CURRENT_THEME.text_secondary
                    border_col = CURRENT_THEME.border_light
                end
            end
            
            -- Рисуем фон (Форма пилюли / Pill shape)
            local rect_min = imgui.ImVec2(p.x + cursor_x, p.y + cursor_y)
            local rect_max = imgui.ImVec2(rect_min.x + item_w, rect_min.y + btn_height)
            
            -- Скругление = половина высоты (делает идеальные круглые бока)
            draw_list:AddRectFilled(rect_min, rect_max, imgui.ColorConvertFloat4ToU32(bg_col), btn_height / 2)
            
            -- Рисуем тонкую обводку, если элемент не выбран
            if not is_selected then
                draw_list:AddRect(rect_min, rect_max, imgui.ColorConvertFloat4ToU32(border_col), btn_height / 2, 15, S(1))
            end
            
            -- Рисуем текст по центру кнопки
            local text_pos = imgui.ImVec2(
                rect_min.x + (item_w - text_size.x) / 2,
                rect_min.y + (btn_height - text_size.y) / 2
            )
            draw_list:AddText(text_pos, imgui.ColorConvertFloat4ToU32(text_col), cat_name)
            
            -- Ставим следующий элемент в ту же строку (справа от текущего)
            imgui.SameLine()
        end
    end
    imgui.EndChild()
    
    imgui.PopStyleColor()
    imgui.PopStyleVar(2)
end

if not VipData.sub_tab then VipData.sub_tab = 1 end

function renderVipAnalyticsTab()
    local w = imgui.GetContentRegionAvail().x
    local h = imgui.GetContentRegionAvail().y
    
    if not isVerifiedVip() then
        -- [SECURITY] Если флаг подделан, чистим кэш трендов
        VipData.top_resale = {}
        renderVipPromoOverlay("Раздел Трендов, Радар и Сделки доступны только для VIP.")
        return
    end

    if not VipData.sub_tab then VipData.sub_tab = 1 end

    -- === ГОРИЗОНТАЛЬНЫЕ ПОДВКЛАДКИ ===
    local p = imgui.GetCursorScreenPos()
    local dl = imgui.GetWindowDrawList()
    local header_h = S(45)
    
    -- Рисуем фон подвкладок
    dl:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
    
    local tab_w = w / 3 -- ТЕПЕРЬ ДЕЛИМ НА 3 КНОПКИ
    
    -- Функция отрисовки кнопок подвкладок
    local function drawVipSubTabBtn(id, name, icon, offset_x)
        local btn_p = imgui.ImVec2(p.x + offset_x, p.y)
        imgui.SetCursorScreenPos(btn_p)
        
        local is_act = (VipData.sub_tab == id)
        local col = is_act and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
        
        if imgui.InvisibleButton("##vtab_"..id, imgui.ImVec2(tab_w, header_h)) then 
            VipData.sub_tab = id 
        end
        
        local txt = u8(" " .. name)
        local txt_sz = GetStaticTextSize(txt)
        local icon_sz = {x=0, y=0}
        
        if font_fa then 
            imgui.PushFont(font_fa)
            icon_sz = GetStaticTextSize(icon)
            dl:AddText(imgui.ImVec2(btn_p.x + (tab_w - (icon_sz.x + txt_sz.x))/2, btn_p.y + (header_h - icon_sz.y)/2), imgui.ColorConvertFloat4ToU32(col), icon)
            imgui.PopFont()
        end
        
        dl:AddText(imgui.ImVec2(btn_p.x + (tab_w - (icon_sz.x + txt_sz.x))/2 + icon_sz.x, btn_p.y + (header_h - txt_sz.y)/2), imgui.ColorConvertFloat4ToU32(col), txt)
        
        if is_act then
            dl:AddRectFilled(imgui.ImVec2(btn_p.x, btn_p.y + header_h - S(3)), imgui.ImVec2(btn_p.x + tab_w, btn_p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(2))
        end
    end

    drawVipSubTabBtn(1, "Тренды рынка", fa('chart_pie'), 0)
    drawVipSubTabBtn(2, "Радар товаров", fa('satellite_dish'), tab_w)
    drawVipSubTabBtn(3, "Выгодные сделки", fa('handshake'), tab_w * 2)

    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + header_h + S(10)))
    
    -- === ЛОГИКА ОТОБРАЖЕНИЯ ===
    local content_h = h - header_h - S(10)
    if VipData.sub_tab == 1 then
        renderVipTrendsContent(w, content_h)
    elseif VipData.sub_tab == 2 then
        renderVipRadarContent(w, content_h)
    elseif VipData.sub_tab == 3 then
        renderVipDealsContent(w, content_h)
    end
end

-- === СТАРЫЙ КОД ТРЕНДОВ ВЫНЕСЕН СЮДА ===
function renderVipTrendsContent(w, h)
    -- Мы убрали renderPriceGraphModal(), так как он теперь вызывается глобально в imgui.OnFrame

    if VipData.is_loading and #VipData.top_resale == 0 then
        imgui.Dummy(imgui.ImVec2(0, h/3))
        centerText(u8"Анализируем рынок...")
        return
    end

    if #VipData.top_resale == 0 then
        if VipData.last_update == 0 then
            api_GetVipAnalytics('top_resale')
        else
            renderEmptyState(fa('chart_pie'), "Нет трендов", "Пока не нашли супер-выгодных товаров.")
        end
        return
    end

    if not VipData.cached_trends_filtered or ffi.string(Buffers.trends_search) ~= VipData.last_trends_search_str then
        VipData.last_trends_search_str = ffi.string(Buffers.trends_search)
        VipData.cached_trends_filtered = filterList(VipData.top_resale, Buffers.trends_search)
    end
    local filtered_trends = VipData.cached_trends_filtered
    
    if #filtered_trends == 0 then
        imgui.Dummy(imgui.ImVec2(0, h/3))
        centerText(u8"По запросу ничего не найдено")
        return
    end

    local pad_x = S(15)
    local col_1_x = pad_x
    local col_2_x = w * 0.42
    local col_3_x = w * 0.58
    local col_4_x = w * 0.70
    
    local header_dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local header_h = S(35)
    
    header_dl:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8), 1 + 2)

    local function DrawHeaderSortBtn(label, mode, x_pos)
        local is_active = (VipData.sort_mode == mode)
        local txt = u8(label)
        local tsz = GetStaticTextSize(txt)
        imgui.SetCursorScreenPos(imgui.ImVec2(p.x + x_pos, p.y + (header_h - tsz.y)/2))
        
        if imgui.InvisibleButton("sort_"..mode, imgui.ImVec2(tsz.x + S(20), header_h)) then
            if VipData.sort_mode == mode then VipData.sort_asc = not VipData.sort_asc
            else VipData.sort_mode = mode; VipData.sort_asc = false end
            
            table.sort(VipData.top_resale, function(a, b)
                local val_a, val_b
                if mode == 1 then val_a, val_b = a.profit, b.profit end
                if mode == 2 then val_a, val_b = tonumber(a.roi), tonumber(b.roi) end
                if mode == 3 then val_a, val_b = a.vol, b.vol end
                if VipData.sort_asc then return val_a < val_b else return val_a > val_b end
            end)
        end
        
        local col = is_active and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
        if imgui.IsItemHovered() then col = CURRENT_THEME.text_primary end
        
        header_dl:AddText(imgui.ImVec2(p.x + x_pos, p.y + (header_h - tsz.y)/2), imgui.ColorConvertFloat4ToU32(col), txt)
        if is_active and font_fa then
            local arr_icon = VipData.sort_asc and fa('arrow_up') or fa('arrow_down')
            imgui.PushFont(font_fa)
            header_dl:AddText(imgui.ImVec2(p.x + x_pos + tsz.x + S(5), p.y + (header_h - tsz.y)/2), imgui.ColorConvertFloat4ToU32(col), arr_icon)
            imgui.PopFont()
        end
    end

    DrawHeaderSortBtn("ТОВАР / ЦЕНЫ", 0, col_1_x)
    DrawHeaderSortBtn("ПРОФИТ", 1, col_2_x)
    DrawHeaderSortBtn("ROI %", 2, col_3_x)
    DrawHeaderSortBtn("ОБЪЕМ", 3, col_4_x)

    imgui.SetCursorPosY(p.y + header_h - imgui.GetWindowPos().y)
    local list_h = h - header_h
    
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    if imgui.BeginChild("VipTrendListNative", imgui.ImVec2(w, list_h), false) then
        local child_dl = imgui.GetWindowDrawList()
        local item_h = S(50) 
        local clipper = imgui.ImGuiListClipper(#filtered_trends)
        
        while clipper:Step() do
            for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
                local item = filtered_trends[i]
                if item then
                    local cur_p = imgui.GetCursorScreenPos()
                    local center_y = cur_p.y + item_h/2
                    
                    local is_hovered = imgui.IsMouseHoveringRect(cur_p, imgui.ImVec2(cur_p.x + w, cur_p.y + item_h))
                    local bg_col = (i % 2 == 0) and CURRENT_THEME.bg_secondary or CURRENT_THEME.bg_tertiary
                    
                    if is_hovered then bg_col = imgui.ImVec4(bg_col.x + 0.08, bg_col.y + 0.08, bg_col.z + 0.08, 1.0) end
                    child_dl:AddRectFilled(cur_p, imgui.ImVec2(cur_p.x + w, cur_p.y + item_h), imgui.ColorConvertFloat4ToU32(bg_col))
                    
                    local displayName = enhancedCleanItemName(item.name)
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_1_x, cur_p.y + S(6)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8(displayName))
                    
                    local price_buy_str = formatMoney(item.buy) .. " $"
                    local price_sell_str = formatMoney(item.sell) .. " $"
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_1_x, cur_p.y + S(26)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), price_buy_str)
                    
                    local pb_sz = GetStaticTextSize(price_buy_str)
                    if font_fa then
                        imgui.PushFont(font_fa)
                        child_dl:AddText(imgui.ImVec2(cur_p.x + col_1_x + pb_sz.x + S(5), cur_p.y + S(27)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('arrow_right_long'))
                        imgui.PopFont()
                    end
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_1_x + pb_sz.x + S(25), cur_p.y + S(26)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), price_sell_str)

                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_2_x, center_y - S(7)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), "+"..formatMoney(item.profit).."$")

                    -- ROI
                    local roi_bg = (tonumber(item.roi) > 100) and 0xFFDDAA00 or 0xFF00AA44
                    local roi_sz = GetStaticTextSize(item.roi .. "%")
                    child_dl:AddRectFilled(imgui.ImVec2(cur_p.x + col_3_x, center_y - S(10)), imgui.ImVec2(cur_p.x + col_3_x + roi_sz.x + S(12), center_y + S(10)), roi_bg, S(6))
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_3_x + S(6), center_y - roi_sz.y/2), 0xFFFFFFFF, item.roi .. "%")

                    -- Vol
                    local vol_bg = (tonumber(item.vol) > 30) and 0xFFCC4400 or 0xFF555555
                    local vol_txt = (tonumber(item.vol) > 30) and "HIGH" or "LOW"
                    local vol_sz = GetStaticTextSize(vol_txt)
                    child_dl:AddRectFilled(imgui.ImVec2(cur_p.x + col_4_x, center_y - S(10)), imgui.ImVec2(cur_p.x + col_4_x + vol_sz.x + S(12), center_y + S(10)), vol_bg, S(6))
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_4_x + S(6), center_y - vol_sz.y/2), 0xFFFFFFFF, vol_txt)
                    child_dl:AddText(imgui.ImVec2(cur_p.x + col_4_x + vol_sz.x + S(17), center_y - vol_sz.y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), "("..item.vol..")")

                    local act_x = cur_p.x + w - S(40)
                    local chart_x = act_x - S(35)
                    
                    -- Кнопка Графика
                    imgui.SetCursorScreenPos(imgui.ImVec2(chart_x, center_y - S(13)))
                    if imgui.InvisibleButton("chart_trend_"..i, imgui.ImVec2(S(26), S(26))) then
                        api_GetVipAnalytics('price_history', displayName)
                    end
                    local chart_hov = imgui.IsItemHovered()
                    renderIconInButton(child_dl, fa('chart_column'), chart_x, center_y, S(26), chart_hov, CURRENT_THEME.accent_primary_u32)
                    if chart_hov then imgui.SetTooltip(u8"Открыть график цен") end

                    -- Кнопка Добавить
                    imgui.SetCursorScreenPos(imgui.ImVec2(act_x, center_y - S(13)))
                    if imgui.InvisibleButton("add_"..i, imgui.ImVec2(S(26), S(26))) then
                        table.insert(Data.buy_list, { name = displayName, price = item.buy, amount = 1, active = true, index = -1 })
                        saveListsConfig()
                        calculateBuyTotal()
                        addToastNotification("Добавлено в скупку: " .. displayName, "success")
                    end
                    renderIconInButton(child_dl, fa('plus'), act_x, center_y, S(26), imgui.IsItemHovered(), CURRENT_THEME.accent_success_u32)
                    
                    imgui.SetCursorScreenPos(imgui.ImVec2(cur_p.x, cur_p.y + item_h))
                end
            end
        end
    end
    imgui.EndChild()
    imgui.PopStyleColor()
end

local RadarUI = {
    results = {},
    last_query = "",
    show_popup = false
}

-- === НОВЫЙ КОД РАДАРА ТОВАРОВ ===
function renderVipRadarContent(w, h)
    local draw = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    
    local form_h = S(55)
    draw:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + form_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
    
    local pad = S(10)
    local total_avail = w - (pad * 5)
    local input_name_w = total_avail * 0.40
    local input_price_w = total_avail * 0.20
    local type_w = total_avail * 0.23
    local btn_w = total_avail * 0.17
    
    local curs_x = p.x + pad
    local cy = p.y + (form_h - S(34))/2
    
    -- ==========================================
    -- 1. ПОЛЕ НАЗВАНИЯ ТОВАРА И АВТОЗАПОЛНЕНИЕ
    -- ==========================================
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, cy))
    
    local input_str = ffi.string(Buffers.radar_name)
    
    -- Логика поиска
    if input_str ~= RadarUI.last_query then
        RadarUI.last_query = input_str
        RadarUI.results = {}
        
        if #input_str >= 2 then
            local q = to_lower(u8:decode(input_str))
            local count = 0
            if Data.buyable_items then
                for _, item in ipairs(Data.buyable_items) do
                    if item.name and to_lower(item.name):find(q, 1, true) then
                        table.insert(RadarUI.results, item.name)
                        count = count + 1
                        if count >= 15 then break end 
                    end
                end
            end
            table.sort(RadarUI.results)
        end
    end

    -- Отрисовка поля ввода
    imgui.SetNextItemWidth(input_name_w)
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(10), (S(34) - imgui.GetFontSize())/2))
    
    imgui.InputTextWithHint("##rad_name", u8"Название товара...", Buffers.radar_name, 128)
    
    local is_input_active = imgui.IsItemActive()
    local input_rect_min = imgui.GetItemRectMin()
    local input_rect_max = imgui.GetItemRectMax()
    
    imgui.PopStyleVar()
    imgui.PopStyleColor()
    
    -- Управление открытием списка
    if is_input_active and #RadarUI.results > 0 then
        imgui.OpenPopup("RadarAutocompletePopup")
        RadarUI.show_popup = true
    elseif #RadarUI.results == 0 then
        RadarUI.show_popup = false
    end
    
    -- Отрисовка выпадающего списка (через систему Popup для наложения поверх всего)
    imgui.SetNextWindowPos(imgui.ImVec2(input_rect_min.x, input_rect_max.y + S(2)), imgui.Cond.Always)
    imgui.SetNextWindowSizeConstraints(imgui.ImVec2(input_name_w, S(30)), imgui.ImVec2(input_name_w, S(250)))
    
    -- Стилизация именно для Popup окна
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(5), S(5)))
    imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
    imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
    imgui.PushStyleVarFloat(imgui.StyleVar.PopupBorderSize, S(1))
    
    local popup_flags = imgui.WindowFlags.NoTitleBar + 
                        imgui.WindowFlags.NoMove + 
                        imgui.WindowFlags.NoResize + 
                        imgui.WindowFlags.NoSavedSettings + 
                        imgui.WindowFlags.NoFocusOnAppearing
    
    if imgui.BeginPopup("RadarAutocompletePopup", popup_flags) then
        for i, res_name in ipairs(RadarUI.results) do
            local u8_name = u8(res_name)
            
            -- Цвета при наведении на элемент
            imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.4))
            imgui.PushStyleColor(imgui.Col.HeaderActive, imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.6))
            
            -- Уникальный ID для каждого элемента
            if imgui.Selectable(u8_name .. "##rad_ac_" .. i) then
                imgui.StrCopy(Buffers.radar_name, u8_name)
                RadarUI.results = {}
                RadarUI.last_query = u8_name
                RadarUI.show_popup = false
                imgui.CloseCurrentPopup()
            end
            
            imgui.PopStyleColor(2)
        end
        imgui.EndPopup()
    else
        RadarUI.show_popup = false
    end
    
    imgui.PopStyleVar(2)
    imgui.PopStyleColor(2)
    
    curs_x = curs_x + input_name_w + pad
    
    -- ==========================================
    -- 2. ПОЛЕ ЦЕНЫ
    -- ==========================================
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, cy))
    renderModernInput("##rad_price", Buffers.radar_price, input_price_w, "Целевая Цена")
    renderMoneyTooltip(ffi.string(Buffers.radar_price))
    curs_x = curs_x + input_price_w + pad
    
    -- ==========================================
    -- 3. ВЫБОР ТИПА
    -- ==========================================
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, cy))
    local types = {u8"В продаже", u8"В скупке"}
    
    imgui.PushItemWidth(type_w)
    imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0,0,0,0))
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(10), (S(34) - imgui.GetFontSize())/2))
    
    draw:AddRectFilled(imgui.ImVec2(curs_x, cy), imgui.ImVec2(curs_x + type_w, cy + S(34)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8))
    draw:AddRect(imgui.ImVec2(curs_x, cy), imgui.ImVec2(curs_x + type_w, cy + S(34)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8), 15, S(1))
    
    if imgui.BeginCombo("##radar_type_combo", types[Buffers.radar_type[0] + 1]) then
        for i, t_name in ipairs(types) do
            if imgui.Selectable(t_name, Buffers.radar_type[0] == (i - 1)) then
                Buffers.radar_type[0] = i - 1
            end
        end
        imgui.EndCombo()
    end
    imgui.PopStyleVar()
    imgui.PopStyleColor(2)
    imgui.PopItemWidth()
    curs_x = curs_x + type_w + pad
    
    -- ==========================================
    -- 4. КНОПКА ДОБАВИТЬ
    -- ==========================================
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, cy))
    if renderCustomButton(u8"Добавить", btn_w, S(34), CURRENT_THEME.accent_primary, fa('plus')) then
        local r_name = u8:decode(ffi.string(Buffers.radar_name))
        local r_price = tonumber(ffi.string(Buffers.radar_price)) or 0
        
        if r_name == "" or r_price <= 0 then
            addToastNotification("Введите название и цену!", "error")
        else
            table.insert(Data.radar_list, {
                name = r_name,
                price = r_price,
                type = Buffers.radar_type[0],
                added = os.time()
            })
            saveListsConfig()
            
            -- СИНХРОНИЗАЦИЯ С СЕРВЕРОМ
            api_SyncRadar()

            imgui.StrCopy(Buffers.radar_name, "")
            imgui.StrCopy(Buffers.radar_price, "")
            RadarUI.results = {}
            RadarUI.last_query = "" 
            RadarUI.show_popup = false -- Жестко скрываем попап
            addToastNotification("Радар активирован. Уведомления в реальном времени включены!", "success", 4.0)
        end
    end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + form_h + S(10)))
    
    -- ==========================================
    -- === СПИСОК ОТСЛЕЖИВАЕМЫХ ТОВАРОВ ===
    -- ==========================================
    local list_h = h - form_h - S(10)
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    
    renderSmoothScrollBox("RadarItemsList", imgui.ImVec2(w, list_h), function()
        if not Data.radar_list or #Data.radar_list == 0 then
            renderEmptyState(fa('satellite_dish'), "Радар пуст", "Впишите товар сверху. Бот моментально пришлет уведомление в Telegram, как только товар появится в любой лавке.")
        else
            for i, item in ipairs(Data.radar_list) do
                local item_p = imgui.GetCursorScreenPos()
                local item_h = S(50)
                
                draw:AddRectFilled(item_p, imgui.ImVec2(item_p.x + w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
                
                local type_col = (item.type == 0) and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary
                draw:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + item_h), imgui.ColorConvertFloat4ToU32(type_col), S(8), 5)
                
                local text_y = item_p.y + (item_h - imgui.GetFontSize())/2
                
                if font_fa then
                    imgui.PushFont(font_fa)
                    local icon = (item.type == 0) and fa('box') or fa('bag_shopping')
                    draw:AddText(imgui.ImVec2(item_p.x + S(15), text_y), imgui.ColorConvertFloat4ToU32(type_col), icon)
                    imgui.PopFont()
                end
                
                draw:AddText(imgui.ImVec2(item_p.x + S(40), text_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8(item.name))
                
                local condition = (item.type == 0) and u8"Продают дешевле: " or u8"Скупают дороже: "
                local price_str = condition .. formatMoney(item.price) .. " $"
                local p_sz = GetStaticTextSize(price_str)
                
                draw:AddText(imgui.ImVec2(item_p.x + w - p_sz.x - S(50), text_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), price_str)
                
                local del_sz = S(28)
                imgui.SetCursorScreenPos(imgui.ImVec2(item_p.x + w - del_sz - S(10), item_p.y + (item_h - del_sz)/2))
                if imgui.InvisibleButton("##del_radar_"..i, imgui.ImVec2(del_sz, del_sz)) then
                    table.remove(Data.radar_list, i)
                    saveListsConfig()
                    api_SyncRadar() -- Синхронизируем удаление
                    addToastNotification("Товар убран из радара", "info")
                end
                
                local del_col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_secondary
                if font_fa then
                    imgui.PushFont(font_fa)
                    local d_sz = GetStaticTextSize(fa('trash'))
                    draw:AddText(imgui.ImVec2(item_p.x + w - del_sz - S(10) + (del_sz-d_sz.x)/2, item_p.y + (item_h-d_sz.y)/2), imgui.ColorConvertFloat4ToU32(del_col), fa('trash'))
                    imgui.PopFont()
                end
                
                -- ИСПРАВЛЕНИЕ ОТСТУПОВ: Используем Dummy вместо SetCursorPosY
                imgui.SetCursorScreenPos(item_p)
                imgui.Dummy(imgui.ImVec2(w, item_h + S(5)))
            end
        end
    end)
    imgui.PopStyleColor()
end

function renderVipDealsContent(w, h)
    -- Инициализация подвкладки (1 - Дешевые товары, 2 - Дорогая скупка, 3 - Исключения)
    if not VipData.deals_tab then VipData.deals_tab = 1 end

    -- Проверка на пустоту
    if not MarketData.shops_list or #MarketData.shops_list == 0 then
        renderEmptyState(fa('shop'), "Нет данных с Маркета", "Откройте вкладку 'Маркет' и нажмите кнопку обновления, чтобы загрузить лавки сервера.", "Перейти в Маркет", function() App.active_tab = 4 end)
        return
    end

    -- Получаем текущий сервер игрока
    local ip, port = sampGetCurrentServerAddress()
    local current_server_id = normalizeServerId(ip .. ":" .. port)

    -- Асинхронное кэширование выгодных сделок (без фризов)
    if not VipData.deals_cache or VipData.deals_last_fetch ~= MarketData.last_fetch then
        if not VipData.deals_is_loading then
            VipData.deals_is_loading = true
            VipData.deals_cache = {} 
            
            lua_thread.create(function()
                local temp_deals = {}
                local count = 0
                
                for _, shop in ipairs(MarketData.shops_list) do
                    if shop.serverId == current_server_id then
                        
                        -- Ищем дешевые продажи
                        if shop.sell_list then
                            for _, item in ipairs(shop.sell_list) do
                                local avg = getAveragePriceForItem({name = item.name}, "sell")
                                if avg and avg > 0 and item.price and item.price > 0 and item.price < avg then
                                    local diff = avg - item.price
                                    if (diff / avg) > 0.05 then
                                        table.insert(temp_deals, { shop = shop, item = item, is_sell = true, profit = diff, avg = avg })
                                    end
                                end
                                count = count + 1
                                if count % 50 == 0 then wait(0) end 
                            end
                        end
                        
                        -- Ищем дорогую скупку
                        if shop.buy_list then
                            for _, item in ipairs(shop.buy_list) do
                                local avg = getAveragePriceForItem({name = item.name}, "buy")
                                if avg and avg > 0 and item.price and item.price > avg then
                                    local diff = item.price - avg
                                    if (diff / avg) > 0.05 then
                                        table.insert(temp_deals, { shop = shop, item = item, is_sell = false, profit = diff, avg = avg })
                                    end
                                end
                                count = count + 1
                                if count % 50 == 0 then wait(0) end 
                            end
                        end
                    end
                end
                
                table.sort(temp_deals, function(a, b) return a.profit > b.profit end)
                VipData.deals_cache = temp_deals
                VipData.deals_last_fetch = MarketData.last_fetch
                VipData.deals_is_loading = false
            end)
        end
    end

    if VipData.deals_is_loading then
        imgui.Dummy(imgui.ImVec2(0, h/3))
        centerText(u8"Анализируем лавки вашего сервера...")
        return
    end

    -- === ЛОГИКА ФИЛЬТРАЦИИ И ЧЕРНОГО СПИСКА ===
    local all_deals = VipData.deals_cache or {}
    local filtered_deals = {}
    
    -- Вспомогательная функция проверки товара в исключениях
    local function isBlacklisted(item_name)
        if not Data.deals_blacklist then return false end
        local clean = enhancedCleanItemName(item_name)
        for _, b_name in ipairs(Data.deals_blacklist) do
            if b_name == clean then return true end
        end
        return false
    end

    if VipData.deals_tab == 1 or VipData.deals_tab == 2 then
        for _, deal in ipairs(all_deals) do
            -- Добавляем только если товара нет в исключениях
            if not isBlacklisted(deal.item.name) then
                if VipData.deals_tab == 1 and deal.is_sell then
                    table.insert(filtered_deals, deal)
                elseif VipData.deals_tab == 2 and not deal.is_sell then
                    table.insert(filtered_deals, deal)
                end
            end
        end
    end

    -- === ОТРИСОВКА ПЕРЕКЛЮЧАТЕЛЯ (ТАБОВ) ===
