    drawLocalTabBtn(2, u8"Продать дороже", fa('sack_dollar'), CURRENT_THEME.accent_primary)
    imgui.SameLine()
    drawLocalTabBtn(3, u8"Исключения", fa('ban'), CURRENT_THEME.accent_danger)
    
    imgui.EndGroup()
    imgui.PopStyleVar()
    
    imgui.Dummy(imgui.ImVec2(0, S(5)))

    -- === ОТРИСОВКА СПИСКА ===
    local list_h = imgui.GetContentRegionAvail().y
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    
    if imgui.BeginChild("VipDealsListNormalScroll", imgui.ImVec2(w, list_h), false) then
        local child_draw_list = imgui.GetWindowDrawList()

        -- ==== ВКЛАДКА 3: ИСКЛЮЧЕНИЯ ====
        if VipData.deals_tab == 3 then
            local bl_list = Data.deals_blacklist or {}
            
            if #bl_list == 0 then
                renderEmptyState(fa('check_double'), "Нет исключений", "Вы не добавили ни одного товара в черный список.\nЧтобы скрыть товар из сделок, нажмите по нему Правой Кнопкой Мыши (ПКМ).")
            else
                imgui.TextColored(CURRENT_THEME.text_secondary, u8("Скрытых товаров: " .. #bl_list))
