                            child_draw_list:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + item_h), bg_col, S(8))
                            child_draw_list:AddRectFilled(p, imgui.ImVec2(p.x + S(4), p.y + item_h), imgui.ColorConvertFloat4ToU32(type_col), S(8), 5)
                            
                            local icon_size = S(36)
                            local icon_x = p.x + S(15)
                            local icon_y = p.y + (item_h - icon_size)/2
                            child_draw_list:AddCircleFilled(imgui.ImVec2(icon_x + icon_size/2, icon_y + icon_size/2), icon_size/2, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary))
                            
                            if font_fa then
                                imgui.PushFont(font_fa)
                                local isz = GetStaticTextSize(type_icon)
                                child_draw_list:AddText(imgui.ImVec2(icon_x + (icon_size - isz.x)/2, icon_y + (icon_size - isz.y)/2), imgui.ColorConvertFloat4ToU32(type_col), type_icon)
