    end
    imgui.EndChild()
    imgui.PopStyleColor()
end

function renderToastNotifications()
    if not toast_notifications or #toast_notifications == 0 then return end

    local draw_list = imgui.GetForegroundDrawList()
    local sw, sh = getScreenResolution()
    local current_time = os.clock()
    
    local y_offset = sh - S(120)
    if App and App.script_loaded and Buffers and Buffers.settings and Buffers.settings.show_live_hud and Buffers.settings.show_live_hud[0] then
        if not isGamePaused() and not isCursorVisible() then
            y_offset = sh - S(260)
        end
    end
    
    for i = #toast_notifications, 1, -1 do
        local toast = toast_notifications[i]
        local elapsed = current_time - toast.created_at
        
        if elapsed < 0.3 then
            toast.alpha = elapsed / 0.3
        elseif elapsed > (toast.duration - 0.3) then
            toast.alpha = (toast.duration - elapsed) / 0.3
        else
            toast.alpha = 1.0
        end
        
        if toast.alpha > 0.05 then
            local text_size = GetStaticTextSize(u8(toast.message))
            local width = text_size.x + S(30)
            local height = math.max(text_size.y + S(15), S(35))
            
            local x = sw - width - S(20)
            local y = y_offset - height - S(10)
            
            local bg_color = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.bg_secondary.x, CURRENT_THEME.bg_secondary.y, CURRENT_THEME.bg_secondary.z, toast.alpha * 0.9))
            local text_color = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, toast.alpha))

            draw_list:AddRectFilled(imgui.ImVec2(x, y), imgui.ImVec2(x + width, y + height), bg_color, S(5))
            draw_list:AddText(imgui.ImVec2(x + S(15), y + (height - text_size.y)/2), text_color, u8(toast.message))
            
            y_offset = y
        end
        
        if elapsed > toast.duration then
            table.remove(toast_notifications, i)
        end
    end
end

function calculateSellTotal()
    local now = os.clock()
    -- [ОПТИМИЗАЦИЯ] Проверяем кэш В САМОМ НАЧАЛЕ. Сверяем инвентарь только раз в 0.5 сек.
    if (now - CacheSystem.totals.sell.timestamp) < 0.5 then
        return CacheSystem.totals.sell.value
    end

    local total = 0
    for _, item in ipairs(Data.sell_list) do
        if item.active ~= false then
             -- Синхронизация количества
             local max_inv_amount = getInventoryAmountForItem(item.model_id, item.slot)
             if item.auto_max then 
                 item.amount = max_inv_amount 
             end
             if not item.auto_max and (item.amount or 0) > max_inv_amount and max_inv_amount > 0 then
                 item.amount = max_inv_amount
             end
             item.missing = (max_inv_amount == 0)
             
             -- [ФИКС] Если товара временно нет в инвентаре (missing), 
             -- мы умножаем его на 0, чтобы не учитывать в общей сумме
             local calc_amount = item.missing and 0 or (tonumber(item.amount) or 1)
             total = total + (tonumber(item.price) or 0) * calc_amount
        end
    end
    
    State.sell_total = total
    CacheSystem.totals.sell.value = total
    CacheSystem.totals.sell.timestamp = now
    return total
end

function calculateBuyTotal()
    local now = os.clock()
    if (now - CacheSystem.totals.buy.timestamp) < 0.5 then
        return CacheSystem.totals.buy.value
    end
    
    local total = 0
    for _, item in ipairs(Data.buy_list) do
        if item.active ~= false then 
            local price = tonumber(item.price) or 0
            local amount = tonumber(item.amount) or 0
            total = total + (price * amount)
        end
    end
    
    State.buy_total = total
    CacheSystem.totals.buy.value = total
    CacheSystem.totals.buy.timestamp = now
    return total
end

function ensureDirectories()
    local dirs = {
        PATHS.ROOT, 
        PATHS.DATA, 
        PATHS.CACHE, 
        PATHS.LOGS,
        PATHS.PROFILES_BUY,
        PATHS.PROFILES_SELL
    }
    for _, dir in ipairs(dirs) do
        if not doesDirectoryExist(dir) then
            createDirectory(dir)
        end
    end
end

function loadJsonFile(path, default_value)
    local f = io.open(path, "r")
    if not f then return default_value end
    local content = f:read("*a")
    f:close()
    if not content or content == "" then return default_value end
    
    local s, r = pcall(json.decode, content)
    return s and fromUTF8(r) or default_value
end

function loadConfigsFromDir(directory)
    local configs = {}
    if not doesDirectoryExist(directory) then return configs end
    
    for file in lfs.dir(directory) do
        if file ~= "." and file ~= ".." and file:match("%.json$") then
            local full_path = directory .. file
            -- Загружаем с дефолтным nil, чтобы поймать ошибку
            local data = loadJsonFile(full_path, nil) 
            
            -- INVARIANT: Конфиг обязан быть таблицей и иметь поле items
            if data and type(data) == "table" then
                if not data.items then data.items = {} end -- Self-healing
                data._filename = file 
                table.insert(configs, data)
            else
                --
            end
        end
    end
    
    -- Сортировка по имени для стабильности списка
    table.sort(configs, function(a, b) 
        return (a.name or "") < (b.name or "") 
    end)
    
    return configs
end

function saveJsonFile(path, data)
    if not data then return false end
    
    local utf8_data = toUTF8(data)
    -- [ФИКС 1] Убрано { indent = true }, так как cjson в Moonloader от него крашится втихую
    local status, content = pcall(json.encode, utf8_data)
    if not status or type(content) ~= "string" or #content == 0 then 
        return false 
    end

    local temp_path = path .. ".tmp"
    local bak_path = path .. ".bak"
    
    local file = io.open(temp_path, "w+")
    if not file then 
        ensureDirectories()
        file = io.open(temp_path, "w+")
        if not file then return false end
    end
    
    local success = file:write(content)
    file:close()
    
    if not success or #content == 0 then
        os.remove(temp_path)
        return false 
    end

    if doesFileExist(path) then
        os.remove(bak_path)
        os.rename(path, bak_path)
        -- [ФИКС 2] Обязательно удаляем оригинальный файл!
        -- В Windows функция os.rename НЕ заменяет существующие файлы и просто игнорируется.
        os.remove(path)
    end
    
    os.rename(temp_path, path)
    return true
end

-- Сохранение конкретного конфига (профиля)
function saveSingleConfig(directory, config_data)
    if not config_data.name then config_data.name = "Unnamed" end
    
    if not config_data._filename then
        local safe_name = tostring(config_data.name):gsub("[^%w%s%-_]", ""):gsub("%s+", "_")
        -- [ИННОВАЦИЯ] Исключаем коллизию, добавляя рандом и микросекунды
        if safe_name == "" then 
            safe_name = "config" 
        end
        local unique_hash = os.time() .. "_" .. math.random(1000, 9999)
        config_data._filename = safe_name .. "_" .. unique_hash .. ".json"
    end
    
    local save_path = directory .. config_data._filename
    
    local data_to_save = {
        name = config_data.name,
        items = config_data.items or {}
    }
    
    local success = saveJsonFile(save_path, data_to_save)
    -- ИСПРАВЛЕНИЕ: Отключаем автоматический триггер облака при сохранении профиля, 
    -- чтобы скрипт не спамил синхронизацией каждый раз, когда у вас покупают 1 товар.
    -- Облако будет обновляться фоновым воркером самостоятельно.
    
    return success -- Возвращаем статус успеха
end

function deleteConfigFile(directory, filename)
    if not filename then return end
    local path = directory .. filename
    if doesFileExist(path) then
        os.remove(path)
    end
end

function sanitizeItemData(item)
    if not item then return nil end
    local clean = {}
    
    -- 1. Копируем строго определенные поля
    for key, _ in pairs(PERSISTENT_FIELDS) do
        if item[key] ~= nil then
            clean[key] = item[key]
        end
    end
    
    -- 2. Принудительная типизация для критических полей
    clean.price = tonumber(clean.price) or 0
    clean.amount = tonumber(clean.amount) or 0
    if clean.model_id then clean.model_id = tonumber(clean.model_id) end
    if clean.index then clean.index = tonumber(clean.index) end
    
    return clean
end

