function saveActiveBuyProfile()
    if not App.script_loaded or not validateDataIntegrity() then return end
    
    local idx = Data.active_buy_config
    local config = Data.buy_configs[idx]
    if not config then return end
    
    -- Sync Logic
    local clean_items = {}
    for _, item in ipairs(Data.buy_list) do
        table.insert(clean_items, sanitizeItemData(item))
    end
    
    config.items = clean_items
    saveSingleConfig(PATHS.PROFILES_BUY, config)
end

function saveActiveSellProfile()
    if not App.script_loaded then return end
    if not Data.active_sell_config or not Data.sell_configs[Data.active_sell_config] then
        --
        return 
    end
    
    local clean_items = {}
    for _, item in ipairs(Data.sell_list) do
        table.insert(clean_items, sanitizeItemData(item))
    end
    
    Data.sell_configs[Data.active_sell_config].items = clean_items
    saveSingleConfig(PATHS.PROFILES_SELL, Data.sell_configs[Data.active_sell_config])
end

function saveBuyConfigState() 
	saveActiveBuyProfile()
end
function saveSellConfigState() saveActiveSellProfile() end

