            Marketplace.sessionToken = data.token
            --
        end
    end
end

function recursiveUTF8(tbl)
    if type(tbl) ~= "table" then return tbl end
    local res = {}
    for k, v in pairs(tbl) do
        local key = k
        if type(k) == "string" then
            -- Пробуем конвертировать, если не вышло - оставляем как есть
            local s, r = pcall(u8, k)
            if s then key = r end
        end
        
        if type(v) == "table" then
            res[key] = recursiveUTF8(v)
        elseif type(v) == "string" then
            local s, r = pcall(u8, v)
            if s then 
                res[key] = r 
            else
                res[key] = v
            end
        else
            res[key] = v
        end
    end
    return res
end

function toUTF8(tbl)
    if type(tbl) ~= 'table' then
        if type(tbl) == 'string' then return u8(tbl) end
        return tbl
    end
    local res = {}
    for k, v in pairs(tbl) do
        local key = (type(k) == 'string') and u8(k) or k
        res[key] = toUTF8(v)
    end
    return res
end

-- Рекурсивное перекодирование таблицы из UTF-8 в CP1251 (для загрузки)
function fromUTF8(tbl)
    if type(tbl) ~= 'table' then
        if type(tbl) == 'string' then
            -- Пытаемся декодировать, если это валидный UTF-8
            local success, result = pcall(u8.decode, u8, tbl)
            return success and result or tbl
        end
        return tbl
    end
    local res = {}
    for k, v in pairs(tbl) do
        local key = k
        if type(k) == 'string' then
            local s, r = pcall(u8.decode, u8, k)
            if s then key = r end
        end
        res[key] = fromUTF8(v)
    end
    return res
end

function saveItemNames()
    -- Сохраняем в новом формате: ID = { n = "Имя", c = "Категория" }
    local db_to_save = {}
    for id, name in pairs(Data.item_names) do
        db_to_save[id] = {
            n = name,
            c = Data.item_categories[id] or "Предмет"
        }
    end
    saveJsonFile(FILES.ITEMS_DB, db_to_save)
end

function loadItemNames()
    local items_file = FILES.ITEMS_DB

    Data.item_names = {}
    Data.item_categories = {}
    Data.item_names_reversed = {}

    local result = loadJsonFile(items_file, nil)

    if result then
        -- [ПРОФЕССИОНАЛЬНАЯ ОПТИМИЗАЦИЯ] Выделяем бюджет в 10 мс на 1 кадр
        local t_start = os.clock() 
        
        for id, val in pairs(result) do
            local final_name = ""
            local final_cat  = "Предмет"

            if type(val) == "table" then
                final_name = val.n or ""
                final_cat  = val.c or "Предмет"
            else
                final_name = val
                final_cat  = extractCategory(final_name)
                final_name = cleanItemName(final_name)
            end

            local str_id = tostring(id)

            Data.item_names[str_id]      = final_name
            Data.item_categories[str_id] = final_cat

            if type(final_name) == "string" and final_name ~= "" then
                local clean_key = cleanItemNameKey(final_name)
                Data.item_names_reversed[clean_key] = tonumber(str_id)
            end

            -- Time-Based Yield: отдаем управление игре, если превышен лимит времени (10мс).
            -- Гарантирует абсолютно плавную загрузку без фризов даже на калькуляторах.
            if os.clock() - t_start > 0.010 then
                wait(0)
                t_start = os.clock()
            end
        end
    else
        saveJsonFile(items_file, {})
    end
end

function sendCEF(payload)
    local bs = raknetNewBitStream()
    raknetBitStreamWriteInt8(bs, 220)
    raknetBitStreamWriteInt8(bs, 18)
    raknetBitStreamWriteInt16(bs, #payload)
    raknetBitStreamWriteString(bs, payload)
    raknetBitStreamWriteInt32(bs, 0)
    raknetSendBitStream(bs, 2, 9, 6)
    raknetDeleteBitStream(bs)
end

function closeCEFInventory()
    sendCEF("inventoryClose")
    App.cef_inventory_active = false
    Data.cef_inventory_items = {}
end

function refreshSellListMissingStatus()
    local pool = {}
    local source_data = Data.cef_slots_data
    local use_scanned = false
    
    if countTable(source_data) == 0 then
        source_data = Data.scanned_items
        use_scanned = true
    end
    
    -- 1. Собираем пул из ИНВЕНТАРЯ
    if use_scanned then
        for _, item in ipairs(source_data) do
            if type(item) == "table" then -- [CRASH FIX] Защита от userdata (cjson.null)
                local mid = tonumber(item.model_id)
                if mid and not item.is_blocked then
                    if not pool[mid] then pool[mid] = { inv = 0, shop = 0, slots = {} } end
                    local amt = tonumber(item.amount) or 1
                    pool[mid].inv = pool[mid].inv + amt
                    table.insert(pool[mid].slots, { slot = tonumber(item.slot), amount = amt })
                end
            end
        end
    else
        for slot, item in pairs(source_data) do
            if type(item) == "table" and tonumber(item.available) == 1 then -- [CRASH FIX]
                local mid = tonumber(item.model_id)
                if mid then
                    if not pool[mid] then pool[mid] = { inv = 0, shop = 0, slots = {} } end
                    local amt = tonumber(item.amount) or 1
                    pool[mid].inv = pool[mid].inv + amt
                    table.insert(pool[mid].slots, { slot = tonumber(slot), amount = amt })
                end
            end
        end
    end

    -- 2. [CORE FIX] Добавляем в пул то, что УЖЕ выставлено в ЛАВКУ
    if App.live_shop_active and Data.live_shop and Data.live_shop.sell then
        for _, item in pairs(Data.live_shop.sell) do
            if type(item) == "table" then -- [CRASH FIX]
                local mid = tonumber(item.model_id)
                if mid then
                    if not pool[mid] then pool[mid] = { inv = 0, shop = 0, slots = {} } end
                    pool[mid].shop = pool[mid].shop + (tonumber(item.amount) or 1)
                end
            end
        end
    end

    -- Сортируем инвентарные слоты
    for _, data in pairs(pool) do
        table.sort(data.slots, function(a, b) return a.slot < b.slot end)
    end

    -- 3. Распределяем по UI конфигу
    for _, sell_item in ipairs(Data.sell_list) do
        if type(sell_item) == "table" then -- [CRASH FIX]
            local mid = tonumber(sell_item.model_id)
            local matched = false
            
            if mid and pool[mid] then
                local total_available = pool[mid].inv + pool[mid].shop
                
                if total_available > 0 then
                    matched = true
                    local needed_amt = tonumber(sell_item.amount) or 1
                    
                    -- Подгоняем количество (авто-макс теперь видит общую сумму)
                    if sell_item.auto_max then
                        sell_item.amount = total_available
                        needed_amt = total_available
                    else
                        if needed_amt > total_available then
                            sell_item.amount = total_available
                            needed_amt = total_available
                        end
                    end
                    
                    -- Если товар физически есть в инвентаре, привязываем слот
                    if pool[mid].inv > 0 and #pool[mid].slots > 0 then
                        local found_idx = 1
                        if sell_item.slot then
                            for i, s_data in ipairs(pool[mid].slots) do
                                if s_data.slot == tonumber(sell_item.slot) then
                                    found_idx = i
                                    break
                                end
                            end
                        end
                        sell_item.slot = pool[mid].slots[found_idx].slot
                        
                        -- Списываем из пула инвентаря
                        local deduct = math.min(needed_amt, pool[mid].slots[found_idx].amount)
                        pool[mid].slots[found_idx].amount = pool[mid].slots[found_idx].amount - deduct
                        pool[mid].inv = pool[mid].inv - deduct
                        
                        if pool[mid].slots[found_idx].amount <= 0 then
                            table.remove(pool[mid].slots, found_idx)
                        end
                    end
                    
                    -- Остаток списываем из пула лавки (чтобы следующий дубликат товара знал, сколько осталось)
                    if needed_amt > 0 then
                        pool[mid].shop = math.max(0, pool[mid].shop - needed_amt)
                    end
                end
            end
            
            sell_item.missing = not matched
        end
    end
    
    rebuildLookupTables()
end

function updateLocalInventoryFromLog(transaction)
    if not Marketplace.enabled then return end
    local updated = false

    if transaction.type == "sale" then
        -- 1. Обновляем конфиг (UI скрипта)
        for _, item in ipairs(Data.sell_list) do
            if type(item) == "table" and item.name == transaction.item and item.active then
                local current = tonumber(item.amount) or 0
                local new_amount = current - transaction.amount
                if new_amount < 0 then new_amount = 0 end
                item.amount = new_amount
                if new_amount == 0 then item.missing = true end
                break 
            end
        end
        refreshSellListMissingStatus()

        -- 2. Обновляем РЕАЛЬНОЕ состояние лавки для синхронизации
        if Data.live_shop and Data.live_shop.sell then
            for slot, item in pairs(Data.live_shop.sell) do
                if type(item) == "table" and item.name == transaction.item then
                    item.amount = item.amount - transaction.amount
                    if item.amount <= 0 then
                        Data.live_shop.sell[slot] = nil -- Удаляем, если кончилось
                    end
                    updated = true
                    break
                end
            end
        end

    elseif transaction.type == "purchase" then
        if Data.live_shop and Data.live_shop.buy then
            for slot, item in pairs(Data.live_shop.buy) do
                if type(item) == "table" and item.name == transaction.item then
                    item.amount = item.amount - transaction.amount
                    if item.amount <= 0 then
                        Data.live_shop.buy[slot] = nil
                    end
                    updated = true
                    break
                end
            end
        end
    end

    if updated then
        saveLiveShopState()
        -- [FIX] Если купят 5 товаров подряд за секунду, отправится только 1 запрос в конце
        MarketConfig.SYNC_QUEUED_TIME = os.clock() + 1.5 
        saveListsConfig()
        calculateSellTotal()
        calculateBuyTotal()
    end
end

function parseShopMessage(text)
    -- Очищаем сразу всё, чтобы не зависеть от цветов внутри [Лавка]
    local clean_text = text:gsub("{%x+}", ""):match("^%s*(.-)%s*$")
    if not clean_text then return nil end
    
    -- Проверка на начало строки
    if clean_text:sub(1, 7) ~= "[Лавка]" then return nil end
    
    -- Отрезаем "[Лавка] " (8 символов)
    clean_text = clean_text:sub(9)

    local transaction = {
        timestamp = os.time(),
        date = os.date("%Y-%m-%d %H:%M:%S"),
        type = nil, player = nil, item = nil, amount = 0, price = 0, total = 0
    }

    if clean_text:find("продал Вам", 1, true) then
        local player, raw_item_and_amount, total_str = clean_text:match("^(.-) продал Вам (.-) за ([%d%.%,%s]+) руб%.")
        if player then
            transaction.type = "purchase"
            transaction.player = player
            
            raw_item_and_amount = raw_item_and_amount:gsub("%s*%(id:%s*%d+%)$", ""):gsub("%s*%(id:%s*%d+%)%s*", " ")
            local item_only, amount = raw_item_and_amount:match("^(.-)%s*%((%d+) шт%.%)$")
            if not item_only then
                item_only = raw_item_and_amount
                amount = 1
            end
            
            transaction.item = cleanItemName(item_only)
            transaction.amount = tonumber(amount) or 1
            -- [FIX] Используем %D для жесткого удаления любых символов кроме цифр (в т.ч. неразрывных пробелов)
            transaction.total = tonumber((total_str:gsub("%D", ""))) or 0
            transaction.price = transaction.amount > 0 and math.floor(transaction.total / transaction.amount) or transaction.total
            return transaction
        end
    elseif clean_text:find("приобрел у Вас", 1, true) then
        local player, raw_item_and_amount, total_str = clean_text:match("^(.-) приобрел у Вас (.-) за ([%d%.%,%s]+) руб%.")
        if player then
            transaction.type = "sale"
            transaction.player = player
            
            raw_item_and_amount = raw_item_and_amount:gsub("%s*%(id:%s*%d+%)$", ""):gsub("%s*%(id:%s*%d+%)%s*", " ")
            local item_only, amount = raw_item_and_amount:match("^(.-)%s*%((%d+) шт%.%)$")
            if not item_only then
                item_only = raw_item_and_amount
                amount = 1
            end
            
            transaction.item = cleanItemName(item_only)
            transaction.amount = tonumber(amount) or 1
            transaction.total = tonumber((total_str:gsub("[%s%.%,]", ""))) or 0
            transaction.price = transaction.amount > 0 and math.floor(transaction.total / transaction.amount) or transaction.total
            return transaction
        end
    end
    
    return nil
end

function addTransactionLog(transaction)
    if not transaction then return end

    -- === 1. ОБНОВЛЕНИЕ ОСТАТКОВ ТОВАРА (ЛОКАЛЬНО) ===
    updateLocalInventoryFromLog(transaction)

    -- [NEW] Подсчет комиссии и чистого дохода
    local tax_percent = Data.settings.shop_tax_percent or 0
    local total_gross = transaction.total or 0
    local tax_amount = 0
    
    -- Комиссия берется только с ПРОДАЖИ (когда мы получаем деньги)
    if transaction.type == "sale" then
        tax_amount = math.floor(total_gross * (tax_percent / 100))
    end
    
    local total_net = total_gross - tax_amount
    
    -- Добавляем данные в объект транзакции для сохранения в лог
    transaction.tax_percent = tax_percent
    transaction.tax_amount = tax_amount
    transaction.net_total = total_net

    -- === 2. СОХРАНЕНИЕ ЛОКАЛЬНОГО ЛОГА ===
    local current_date_str = os.date("%Y-%m-%d")
    local file_path = PATHS.LOGS .. current_date_str .. ".json"
    local day_logs = loadJsonFile(file_path, {})

    table.insert(day_logs, transaction)
    saveJsonFile(file_path, day_logs)

    if App.active_tab == 3 then
        refreshLogDates()
        updateLogView()
    end
    
    -- [NEW] Мгновенно обновляем HUD после записи лога
    calculateTodayStats()

    -- === 3. TELEGRAM УВЕДОМЛЕНИЕ ===
    if Data.settings.telegram_token and Data.settings.telegram_token ~= "" then
        sendTelegramNotification(transaction)
    end
end

function formatMoney(amount)
    local n = tonumber(amount) or 0
    if n == 0 then return "0" end
    
    local formatted = tostring(math.floor(math.abs(n)))
    local k = #formatted
    while k > 3 do
        formatted = formatted:sub(1, k - 3) .. "." .. formatted:sub(k - 2)
        k = k - 3
    end
    
    if n < 0 then return "-" .. formatted end
    return formatted
end

function getSafeLocalNickname()
    local nick = LOCAL_PLAYER_NICK or Data.settings.last_nickname
    if nick and nick ~= "" then
        return nick:gsub("_", " ")
    end
    return "Unknown Player"
end

function PrepareMarketplaceData()
    Marketplace.items_sell = {}
    Marketplace.count_sell = {}
    Marketplace.price_sell = {}
    Marketplace.items_buy = {}
    Marketplace.count_buy = {}
    Marketplace.price_buy = {}
    if Data.live_shop and Data.live_shop.sell then
        for slot, item in pairs(Data.live_shop.sell) do
            if type(item) == 'table' and item.model_id and (tonumber(item.amount) or 0) > 0 then
                table.insert(Marketplace.items_sell, tonumber(item.model_id))
                table.insert(Marketplace.count_sell, tonumber(item.amount))
                table.insert(Marketplace.price_sell, tonumber(item.price) or 0)
            end
        end
    end
    if Data.live_shop and Data.live_shop.buy then
        for slot, item in pairs(Data.live_shop.buy) do
            if type(item) == 'table' and item.model_id then
                table.insert(Marketplace.items_buy, tonumber(item.model_id))
                local b_amount = tonumber(item.amount) or 1
                if b_amount < 1 then b_amount = 1 end
                table.insert(Marketplace.count_buy, b_amount)
                table.insert(Marketplace.price_buy, tonumber(item.price) or 0)
            end
        end
    end
    local ip, port = sampGetCurrentServerAddress()
    local my_nick = getSafeLocalNickname()
    Marketplace.username = u8(my_nick)
    Marketplace.serverId = normalizeServerId(ip .. ":" .. port)
    local res, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if LOCAL_PLAYER_ID ~= -1 then
        Marketplace.playerId = LOCAL_PLAYER_ID
    else
        Marketplace.playerId = res and myId or -1
    end
    if Marketplace.LavkaUid == 0 then
        Marketplace.LavkaUid = os.time()
    end
end

function ProcessMarketplacePing()
    if not App.script_loaded then return end
    if not Marketplace.enabled or not Marketplace.sessionToken then return end
    
    -- Защита от частого пинга (раз в 15 сек)
    local current_time = os.time()
    if current_time < MarketConfig.LAST_PING + MarketConfig.PING_INTERVAL then
        return
    end
    
    local payload = {
        username = Marketplace.username,
        serverId = Marketplace.serverId,
        token = Marketplace.sessionToken
    }
    
    -- Используем signed_request
    signed_request("POST", MarketConfig.HOST .. "/marketplace?action=ping", 
            payload,
            function(response)
                -- [FIX] Если сервер ответил 404 (сессия не найдена), молча сбрасываем
                if response.status_code == 404 or response.status_code == 403 then
                    Marketplace.sessionToken = nil
                    MarketConfig.LAST_SYNC = 0 
                else
                    -- [FIX] Продлеваем жизнь локальному кэшу, чтобы лавка не исчезала 
                    -- при долгом АФК без изменения товаров
                    if Data.live_shop then
                        Data.live_shop.saved_at = os.time()
                        saveLiveShopState()
                    end
                end
            end
        )
    
    MarketConfig.LAST_PING = current_time
end

function ProcessMarketplaceSync()
    if not App.script_loaded then return end
    if not Marketplace.enabled then return end

    -- [FIX RACE CONDITION] Блокируем синхронизацию во время активной работы скрипта, 
    -- чтобы не создавать DDoS и гонку HTTP-потоков. Скрипт синхронизирует лавку сам в конце.
    if App.is_selling_cef or App.is_removing_sale or State.buying.active or App.is_removing_buy then
        return
    end

    -- SECURITY: не отправляем, если ник некорректный
    if Marketplace.username == "" or Marketplace.username == "Unknown Player" then
        local my_nick = getSafeLocalNickname()
        if my_nick ~= "Unknown Player" then
             Marketplace.username = u8(my_nick)
        else
             return
        end
    end
    
    -- Убраны проверки токена и VIP. Теперь ВСЕ игроки могут отправлять свои лавки как активные.
    local current_time = os.time()
    if current_time < (MarketConfig.LAST_SYNC + MarketConfig.SYNC_INTERVAL) then
        return
    end

    -- Подготавливаем данные витрины
    PrepareMarketplaceData()

    local payload = {
        username     = Marketplace.username,
        enabled      = true,
        serverId     = Marketplace.serverId,
        token        = Marketplace.sessionToken or "", 
        playerId     = Marketplace.playerId,
        LavkaUid     = Marketplace.LavkaUid,
        vip          = Data.is_vip or false,
        items_sell   = Marketplace.items_sell,
        count_sell   = Marketplace.count_sell,
        price_sell   = Marketplace.price_sell,
        items_buy    = Marketplace.items_buy,
        count_buy    = Marketplace.count_buy,
        price_buy    = Marketplace.price_buy
    }

    signed_request(
		"POST",
		MarketConfig.HOST .. "/marketplace?action=insert", 
		payload,
        function(response)
            if response.status_code ~= 200 then
                if response.status_code == 403 or response.status_code == 401 then
                    Marketplace.sessionToken = nil
                    MarketConfig.LAST_SYNC = 0 
                end
                return
            end

            local ok, data = pcall(json.decode, response.text)
            if not ok or not data then return end

            if data.token and Marketplace.sessionToken ~= data.token then
                Marketplace.sessionToken = data.token
                saveSessionToken()
            end
        end
    )

    MarketConfig.LAST_SYNC = current_time
end

function reconstructInventoryFromCache()
    Data.cef_slots_data = {}
    Data.inventory_item_amounts = {}
    
    -- Если кэш пуст, ничего не делаем
    if not Data.scanned_items or #Data.scanned_items == 0 then return end
    
    --

    for _, item in ipairs(Data.scanned_items) do
        if item.slot and item.model_id then
            local slot = tonumber(item.slot)
            local model = tonumber(item.model_id)
            local amount = tonumber(item.amount) or 1
            
            -- Восстанавливаем технические данные слота
            Data.cef_slots_data[slot] = {
                model_id = model,
                slot = slot,
                amount = amount,
                available = 1, -- Считаем доступным, раз он был в кэше
                text = item.text,
                time = item.time
            }
            
            -- Восстанавливаем общие количества
            local s_id = tostring(model)
            Data.inventory_item_amounts[s_id] = (Data.inventory_item_amounts[s_id] or 0) + amount
        end
    end

    -- Обновляем статусы "НЕТ В ИНВЕНТАРЕ" для списка продажи
    -- [УЛУЧШЕНО] Используем единую функцию для проверки missing статуса
    refreshSellListMissingStatus()
    
    calculateSellTotal()
end

function tryAutoUpdatePrices()
    local now = os.time()
    
    -- 1. Предметы
    local meta = loadJsonFile(FILES.PRICE_META, {})
    local last_ts = tonumber(meta.last_update) or 0
    if last_ts == 0 or (now - last_ts) > 86400 then
        local reason = (last_ts == 0) and "первый запуск" or "прошло 24 часа"
        print("[RMarket] Запуск авто-обновления средних цен (" .. reason .. ")...")
        api_DownloadAveragePrices()
    else
        print(string.format("[RMarket] Средние цены актуальны (обновлено %.1f ч. назад)", (now - last_ts) / 3600))
    end
    
    -- 2. Машины АБ
    local car_meta = loadJsonFile(PATHS.CACHE .. 'car_meta.json', {})
    local car_last_ts = tonumber(car_meta.last_update) or 0
    if car_last_ts == 0 or (now - car_last_ts) > 86400 then
        print("[RMarket] Запуск авто-обновления цен АБ...")
        api_FetchCarPrices(true) -- silent update
    end
end

function api_DownloadVipCache()
    asyncHttpRequest("GET", MarketConfig.HOST .. "/get_vips", { timeout = 15 },
        function(response)
            if response.status_code == 200 then
                local ok, data = pcall(json.decode, response.text)
                if ok and type(data) == "table" then
                    -- СОЗДАЕМ ЧИСТУЮ ТАБЛИЦУ (чтобы стереть тех, у кого VIP истек)
                    local new_vip_cache = {} 
                    local loaded_count = 0
                    
                    for vip_nick, months in pairs(data) do
                        if type(vip_nick) == "number" then 
                            vip_nick = months 
                            months = 1 
                        end
                        local dec_nick = u8:decode(vip_nick)
                        local m = tonumber(months) or 1
                        
                        new_vip_cache[dec_nick] = m
                        new_vip_cache[dec_nick:gsub(" ", "_")] = m
                        loaded_count = loaded_count + 1
                    end
                    
                    -- Восстанавливаем локального игрока в кэше, если API еще не обновилось
                    if Data.is_vip and LOCAL_PLAYER_NICK then
                        local local_m = Data.vip_months or 1 -- [FIX] Берем точный стаж без математики
                        new_vip_cache[LOCAL_PLAYER_NICK] = local_m
                        new_vip_cache[LOCAL_PLAYER_NICK:gsub(" ", "_")] = local_m
                    end
                    
                    -- Перезаписываем глобальную таблицу и сохраняем
                    Data.vip_users_cache = new_vip_cache
                    saveJsonFile(FILES.VIP_CACHE, Data.vip_users_cache)
                    print("[RMarket] База VIP обновлена: " .. loaded_count .. " ников (истекшие удалены)")
                end
            end
        end
    )
end

function loadAllData()
    if App.data_loading then return end
    App.data_loading = true
    initServerFilters() 
    
    lua_thread.create(function()
