function getUniqueFingerprint()
    local ip, port = sampGetCurrentServerAddress()
    local nick = getSafeLocalNickname() -- Ваша функция получения ника
    -- Отпечаток: Nickname@IP:PORT (Привязка к аккаунту и серверу)
    return string.format("%s@%s:%s", nick, ip, port)
end

function safeParseMarketItems(ids_tbl, counts_tbl, prices_tbl)
    local list = {}
    if type(ids_tbl) ~= "table" then return list end
    local keys = {}
    for k, _ in pairs(ids_tbl) do table.insert(keys, k) end
    table.sort(keys, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
    for _, k in ipairs(keys) do
        local model_id = tonumber(ids_tbl[k]) or 0
        local c_val = 0
        if type(counts_tbl) == "table" then
            c_val = counts_tbl[k] or counts_tbl[tostring(k)] or counts_tbl[tonumber(k)] or 0
        end
        local p_val = 0
        if type(prices_tbl) == "table" then
            p_val = prices_tbl[k] or prices_tbl[tostring(k)] or prices_tbl[tonumber(k)] or 0
        end
        if model_id > 0 then
            local item_name = Data.item_names[tostring(model_id)] or ("Item_" .. tostring(model_id))
            table.insert(list, {
                name = item_name,
                model_id = model_id,
                amount = tonumber(c_val) or 0,
                price = tonumber(p_val) or 0
            })
        end
    end
    return list
end

function loadLocalMarketCache()
    local cache_path = PATHS.CACHE .. 'market_dump.json'
    if not doesFileExist(cache_path) then return end

    local data = loadJsonFile(cache_path, nil)
    if not data or type(data) ~= "table" then return end

    MarketData.shops_list = {}
    for _, shop in ipairs(data) do
        -- [FIX] Вызов безопасной функции для парсинга кэша
        local s_list = safeParseMarketItems(shop.items_sell, shop.count_sell, shop.price_sell)
        local b_list = safeParseMarketItems(shop.items_buy, shop.count_buy, shop.price_buy)

        local raw_nick = shop.user or shop.username
        local safe_nick = safe_decode(raw_nick)
        
        table.insert(MarketData.shops_list, {
            nickname = safe_nick,
            serverId = shop.id or shop.serverId,
            vip = shop.vip or false,
            is_passive = shop.is_passive or false,
            sell_count = #s_list,
            buy_count = #b_list,
            shop_name = "Лавка " .. tostring(safe_nick),
            sell_list = s_list,
            buy_list = b_list
        })
    end
    MarketData.online_count = #MarketData.shops_list
    MarketData.last_fetch = os.time()
end

function sendTelegramNotification(transaction)
    if not Data.settings.telegram_token or Data.settings.telegram_token == "" then return end
    local ip, port = sampGetCurrentServerAddress()
    local srv_id = normalizeServerId(ip .. ":" .. port)
    local current_money = getPlayerMoney()
    local current_date_str = os.date("%Y-%m-%d")
    local day_logs = loadLogsForDate(current_date_str) 
    local earned_today = 0
    local spent_today = 0
    for _, log in ipairs(day_logs) do
        local log_total = tonumber(log.net_total) or tonumber(log.total) or 0
        if log_total == 0 then
            local amt = tonumber(log.amount) or 1
            local p = tonumber(log.price) or 0
            log_total = p * amt
        end
        if log.type == "sale" then
            earned_today = earned_today + log_total
        elseif log.type == "purchase" then
            spent_today = spent_today + log_total
        end
    end
    local profit_today = earned_today - spent_today
    local item_profit = 0
    local avg_buy_price = 0
    if transaction.type == "sale" then
        local clean = cleanItemName(transaction.item)
        if Data.average_prices and Data.average_prices[clean] then
            avg_buy_price = Data.average_prices[clean].buy or 0
        end
        if avg_buy_price > 0 then
            local gross_per_item = transaction.price
            local net_per_item = gross_per_item * (1 - (Data.settings.shop_tax_percent or 0)/100)
            item_profit = math.floor((net_per_item - avg_buy_price) * transaction.amount)
        end
    end
    local payload = {
        secret_key = Data.settings.telegram_token,
        data = {
            type = transaction.type,
            player = u8(transaction.player), 
            item = u8(transaction.item),
            amount = transaction.amount,
            price = transaction.price,
            total = transaction.total,
            tax_percent = transaction.tax_percent or 0,
            tax_amount = transaction.tax_amount or 0,
            net_total = transaction.net_total or transaction.total,
            est_item_profit = item_profit, 
            avg_buy_price = avg_buy_price,
            server = srv_id,
            balance = current_money,
            earned = earned_today,
            spent = spent_today,
            profit = profit_today
        }
    }
    signed_request("POST", MarketConfig.HOST .. "/notify", payload, function(response) end)
end

