end

function processCarPrice(car_name, price)
    if not car_name or price <= 0 then return end
    
    -- Очистка имени (убираем пробелы по краям и переводы строк)
    car_name = car_name:gsub("\n", ""):match("^%s*(.-)%s*$")
    
    if not Data.car_prices[car_name] then
        Data.car_prices[car_name] = { p = {}, min = 0, max = 0 }
    end
    
    local car = Data.car_prices[car_name]
    
    -- Проверка пользовательских лимитов (чтобы не парсить сливы или оверпрайс)
    if (car.min > 0 and price < car.min) or (car.max > 0 and price > car.max) then
        return
    end
    
    -- Ищем, нет ли уже такой цены в последних 5, чтобы не флудить
    for i = math.max(1, #car.p - 5), #car.p do
        if car.p[i] == price then return end
    end
    
    table.insert(car.p, price)
    -- Храним только 50 последних цен для рассчета среднего, чтобы не забивать память
    if #car.p > 50 then table.remove(car.p, 1) end
    
    saveJsonFile(FILES.CAR_PRICES, Data.car_prices)
end
