local last_gamestate = -1
local is_currently_disconnected = false
local last_disconnect_notif_time = 0

local PACKET_DISCONNECTION_NOTIFICATION = 32
local PACKET_CONNECTION_LOST = 33
local PACKET_CONNECTION_BANNED = 36
local PACKET_CONNECTION_ATTEMPT_FAILED = 39
local RPC_CONNECTIONREJECTED = 130

function sendDisconnectNotification(reason, is_sync)
    if not Data.settings.telegram_token or Data.settings.telegram_token == "" then return end
    local now = os.time()
    if now - last_disconnect_notif_time < 60 then return end
    last_disconnect_notif_time = now
    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    local server_name = getServerDisplayName(server_id)
    local nick = getSafeLocalNickname()
    local payload_table = {
        secret_key = Data.settings.telegram_token,
        data = {
            type = "connection_status",
            reason = u8(reason),
            server = u8(server_name),
            account = u8(nick)
        }
    }
    Marketplace_Clear(true)
    if is_sync then
        local ok, requests = pcall(require, 'requests')
        if ok then
            local json_body = json.encode(payload_table)
            local timestamp = tostring(os.time())
            local signature = md5_lib.sumhexa(json_body .. timestamp .. Data.settings.telegram_token)
            pcall(function()
                requests.post(MarketConfig.HOST .. "/notify", {
                    headers = {
                        ["Content-Type"] = "application/json",
                        ["Content-Length"] = tostring(#json_body),
                        ["X-Auth-Key"] = Data.settings.telegram_token,
                        ["X-Timestamp"] = timestamp,
                        ["X-Signature"] = signature,
                        ["User-Agent"] = "RMarket-Client/5.15"
                    },
                    data = json_body,
                    timeout = 3
                })
            end)
        end
    else
        signed_request("POST", MarketConfig.HOST .. "/notify", payload_table)
    end
end

-- Хелпер для парсинга цен Родины (355.9к, 1.5кк)
local PRICE_MULTIPLIERS = {
    ["k"] = 1e3, ["к"] = 1e3,
    ["m"] = 1e6, ["м"] = 1e6, ["kk"] = 1e6, ["кк"] = 1e6,
    ["kkk"] = 1e9, ["ккк"] = 1e9
}

function parseRodinaPrice(text)
    if type(text) ~= "string" then return 0 end
    
    -- Вытаскиваем число и суффикс за один проход, игнорируя мусор вроде "руб."
    local num_str, suffix = text:lower():match("([%d%.%,]+)%s*([kкmм]*)")
    if not num_str then return 0 end
    
    local num = tonumber((num_str:gsub(",", "."))) or 0
    local multiplier = PRICE_MULTIPLIERS[suffix] or 1
    
    return math.floor(num * multiplier)
end

function api_SyncInventory()
    if not Data.settings.telegram_token or Data.settings.telegram_token == "" then return end
    local inv_payload = {}
    for _, item in ipairs(Data.scanned_items) do
        table.insert(inv_payload, {
            name = u8(item.name),
            model_id = tonumber(item.model_id) or 0,
            amount = tonumber(item.amount) or 1,
            slot = tonumber(item.slot) or -1,
            is_blocked = item.is_blocked == true
        })
    end
    local payload = {
        secret_key = Data.settings.telegram_token, 
        inventory = inv_payload
    }
    signed_request("POST", MarketConfig.HOST .. "/sync_inventory", payload, function(response)
        if response.status_code == 200 then
            print("[RMarket] Inventory synced successfully!")
        else
            print("[RMarket] Sync Error: " .. response.status_code .. " | " .. tostring(response.text))
        end
    end)
end

function api_GetVipAnalytics(action, item_name)
    if not isVerifiedVip() then 
        addToastNotification("Функция доступна только для VIP", "error")
        return 
    end

    if VipData.is_loading then return end

    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    local url = MarketConfig.HOST .. "/vip_analytics?server=" .. url_encode(server_id) .. "&action=" .. action
    
    if item_name then
        local utf8_name = u8(item_name)
        url = url .. "&item=" .. url_encode(utf8_name)
    end

    VipData.is_loading = true
    
    -- [СЕКЬЮРИТИ ФИКС] Передаем токен скрыто
    asyncHttpRequest("GET", url, { 
        headers = {["X-Auth-Key"] = Data.settings.telegram_token}, 
        timeout = 20 
    }, 
        function(response)
            -- Запускаем обработку в отдельном потоке, чтобы не вешать игру
            lua_thread.create(function()
                if response.status_code == 200 then
                    -- Защита: проверяем, не пришел ли HTML (ошибка сервера) вместо JSON
                    if response.text and (response.text:sub(1, 1) == "<" or response.text:find("<html>")) then
                        print("[RMarket] Ошибка: Сервер вернул HTML вместо JSON")
                        addToastNotification("Сервер перегружен, попробуйте позже", "error")
                        VipData.is_loading = false
                        return
                    end

                    local ok, data = pcall(json.decode, response.text)
                    if ok and data then
                        if data.error == 'vip_required' then
                            Data.is_vip = false
                            addToastNotification("VIP статус истек", "error")
                            VipData.is_loading = false
                            return
                        end

                        if action == 'top_resale' then
                            -- Создаем временную таблицу
                            local temp_list = {}
                            local count = 0
                            
                            -- Обрабатываем данные частями
                            for _, item in ipairs(data) do
                                -- Конвертация имени
                                local name_cp1251 = item.name
                                if u8 then
                                    local s, r = pcall(u8.decode, u8, item.name)
                                    if s then name_cp1251 = r end
                                end
                                item.name = name_cp1251
                                table.insert(temp_list, item)
                                
                                -- !!! ГЛАВНОЕ ИСПРАВЛЕНИЕ ЗАВИСАНИЯ !!!
                                -- Каждые 5 товаров делаем паузу на 1 кадр
                                count = count + 1
                                if count % 5 == 0 then wait(0) end
                            end
                            
                            VipData.top_resale = temp_list
                            VipData.last_update = os.time()
                            
                        elseif action == 'price_history' then
                            VipData.graph_points = data
                            VipData.selected_item_history = item_name
                            VipData.show_graph_modal = true
                        end
                    else
                        print("[RMarket] JSON Decode Error: " .. tostring(data))
                        addToastNotification("Ошибка обработки данных", "error")
                    end
                else
                    print("[RMarket] HTTP Error: " .. response.status_code)
                    addToastNotification("Ошибка сервера: " .. response.status_code, "error")
                end
                
                VipData.is_loading = false
            end)
        end,
        function(err) 
            VipData.is_loading = false 
            print("[RMarket] Connection Error: " .. tostring(err))
            addToastNotification("Ошибка соединения", "error")
        end
    )
end

function renderPriceGraphModal()
    if not VipData.show_graph_modal then return end

    local sw, sh = getScreenResolution()
    local modal_w, modal_h = S(600), S(420) -- Чуть расширили для красоты
    
    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(modal_w, modal_h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1))
    
    if imgui.Begin("##PriceGraphModal", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse) then
        local dl = imgui.GetWindowDrawList()
        local p = imgui.GetCursorScreenPos()
        local w = imgui.GetWindowWidth()
        local h = imgui.GetWindowHeight()
        
        -- === ХЕДЕР ===
        local header_h = S(55)
        dl:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 5)
        dl:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
        
        -- Кнопка закрытия
        local close_sz = S(30)
        local close_x = p.x + w - close_sz - S(15)
        local close_y = p.y + (header_h - close_sz)/2
        
        imgui.SetCursorScreenPos(imgui.ImVec2(close_x, close_y))
        if imgui.InvisibleButton("##cls_grp", imgui.ImVec2(close_sz, close_sz)) then
            VipData.show_graph_modal = false
        end
        local is_close_hov = imgui.IsItemHovered()
        if is_close_hov then
            dl:AddCircleFilled(imgui.ImVec2(close_x + close_sz/2, close_y + close_sz/2), close_sz/2, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 0.3, 0.3, 0.2)))
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local ic = fa('xmark')
            local isz = GetStaticTextSize(ic)
            dl:AddText(imgui.ImVec2(close_x + (close_sz-isz.x)/2, close_y + (close_sz-isz.y)/2), imgui.ColorConvertFloat4ToU32(is_close_hov and CURRENT_THEME.accent_danger or CURRENT_THEME.text_secondary), ic)
            imgui.PopFont()
        end
        
        -- Заголовок
        local title = u8(VipData.selected_item_history or "Аналитика товара")
        if font_fa then
            imgui.PushFont(font_fa)
            dl:AddText(imgui.ImVec2(p.x + S(20), p.y + (header_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), fa('chart_area'))
            imgui.PopFont()
            dl:AddText(imgui.ImVec2(p.x + S(45), p.y + (header_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), title)
        else
            dl:AddText(imgui.ImVec2(p.x + S(20), p.y + (header_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), title)
        end
        
        -- === ЗОНА ГРАФИКА ===
        local graph_x = p.x + S(20)
        local graph_y = p.y + header_h + S(20)
        local graph_w = w - S(40)
        local graph_h = h - header_h - S(40)
        
        -- Фон графика
        dl:AddRectFilled(imgui.ImVec2(graph_x, graph_y), imgui.ImVec2(graph_x + graph_w, graph_y + graph_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8))
        dl:AddRect(imgui.ImVec2(graph_x, graph_y), imgui.ImVec2(graph_x + graph_w, graph_y + graph_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8), 15, S(1))
        
        if not VipData.graph_points or #VipData.graph_points < 2 then
            local txt = u8"Недостаточно данных для построения графика"
            local tsz = GetStaticTextSize(txt)
            dl:AddText(imgui.ImVec2(graph_x + (graph_w-tsz.x)/2, graph_y + (graph_h-tsz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), txt)
        else
            -- 1. Вычисление Min/Max для масштабирования
            local min_p, max_p = 999999999999, 0
            for _, pt in ipairs(VipData.graph_points) do
                local s = tonumber(pt.avg_sell) or tonumber(pt.sell) or 0
                local b = tonumber(pt.avg_buy)  or tonumber(pt.buy)  or 0
                if s > 0 then min_p = math.min(min_p, s); max_p = math.max(max_p, s) end
                if b > 0 then min_p = math.min(min_p, b); max_p = math.max(max_p, b) end
            end
            
            if min_p == 999999999999 then min_p = 0 end
            if max_p == 0 then max_p = 100 end
            
            -- Добавляем отступы (padding) по Y (15% сверху и снизу)
            local diff = max_p - min_p
            if diff == 0 then diff = max_p * 0.2 end
            max_p = max_p + (diff * 0.15)
            min_p = math.max(0, min_p - (diff * 0.15))
            
            -- Внутренние отступы для отрисовки
            local pad_x = S(40)  -- Отступ слева/справа для точек
            local pad_y = S(30)  -- Отступ снизу для дат
            local draw_w = graph_w - pad_x * 2
            local draw_h = graph_h - pad_y - S(20) -- Место под график
            
            -- 2. Отрисовка горизонтальной сетки (Grid)
            local grid_lines = 4
            imgui.PushFont(font_default)
            imgui.SetWindowFontScale(0.85)
            for i = 0, grid_lines do
                local t = i / grid_lines
                local grid_val = min_p + (max_p - min_p) * t
                local gy = graph_y + S(10) + draw_h - (t * draw_h)
                
                -- Линия сетки
                dl:AddLine(imgui.ImVec2(graph_x + S(10), gy), imgui.ImVec2(graph_x + graph_w - S(10), gy), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.05)), 1.0)
                
                -- Цена сбоку (слева)
                local price_str = formatMoney(math.floor(grid_val))
                local psz = GetStaticTextSize(price_str)
                dl:AddText(imgui.ImVec2(graph_x + S(12), gy - psz.y - S(2)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), price_str)
            end
            imgui.SetWindowFontScale(1.0)
            imgui.PopFont()

            -- 3. Подготовка координат точек
            local points_count = #VipData.graph_points
            local step_x = draw_w / math.max(1, points_count - 1)
            
            local sell_pts = {}
            local buy_pts = {}
            
            for i, pt in ipairs(VipData.graph_points) do
                local s = tonumber(pt.avg_sell) or tonumber(pt.sell) or 0
                local b = tonumber(pt.avg_buy)  or tonumber(pt.buy)  or 0
                local x = graph_x + pad_x + (i - 1) * step_x
                
                if s > 0 then
                    local y = graph_y + S(10) + draw_h - (((s - min_p) / (max_p - min_p)) * draw_h)
                    table.insert(sell_pts, {x = x, y = y, val = s, date = pt.date_str or "?"})
                end
                
                if b > 0 then
                    local y = graph_y + S(10) + draw_h - (((b - min_p) / (max_p - min_p)) * draw_h)
                    table.insert(buy_pts, {x = x, y = y, val = b, date = pt.date_str or "?"})
                end
                
                -- Отрисовка дат по оси X (не для всех точек, чтобы не слипались)
                if points_count <= 7 or (i % math.ceil(points_count/6) == 1) or i == points_count then
                    local date_str = pt.date_str or pt.label or "?"
                    if #date_str > 5 then date_str = date_str:sub(1, 5) end
                    
                    imgui.PushFont(font_default)
                    imgui.SetWindowFontScale(0.85)
                    local dsz = GetStaticTextSize(date_str)
                    dl:AddText(imgui.ImVec2(x - dsz.x/2, graph_y + graph_h - pad_y/2 - dsz.y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), date_str)
                    imgui.SetWindowFontScale(1.0)
                    imgui.PopFont()
                end
            end
            
            -- Цвета графиков
            local col_sell = CURRENT_THEME.accent_danger -- Красный (Продажа)
            local col_buy  = CURRENT_THEME.accent_primary -- Синий/Зеленый (Скупка)
            
            -- Вспомогательная функция для отрисовки линии с градиентной заливкой
            local function drawGraphLine(pts, color_vec)
                if #pts < 2 then return end
                local base_y = graph_y + S(10) + draw_h
                
                -- [FPS FIX] Конвертируем Vec4 в U32 один раз, а затем управляем прозрачностью аппаратно
                local base_u32 = imgui.ColorConvertFloat4ToU32(color_vec)
                local col_line = setAlphaU32(base_u32, 1.0)
                local col_fill_top = setAlphaU32(base_u32, 0.4)
                local col_fill_bot = setAlphaU32(base_u32, 0.0)

                for i = 2, #pts do
                    local p1 = pts[i-1]
                    local p2 = pts[i]
                    
                    -- Полигон заливки (2 треугольника) с градиентом
                    -- В mimgui нет AddQuadFilledMultiColor, поэтому делаем обходной путь через обычные полигоны
                    dl:AddTriangleFilled(imgui.ImVec2(p1.x, p1.y), imgui.ImVec2(p2.x, p2.y), imgui.ImVec2(p1.x, base_y), col_fill_top)
                    dl:AddTriangleFilled(imgui.ImVec2(p2.x, p2.y), imgui.ImVec2(p2.x, base_y), imgui.ImVec2(p1.x, base_y), col_fill_top)
                    
                    -- Линия
                    dl:AddLine(imgui.ImVec2(p1.x, p1.y), imgui.ImVec2(p2.x, p2.y), col_line, S(2.5))
                end
                
                -- Точки (кружки)
                for _, pt in ipairs(pts) do
                    dl:AddCircleFilled(imgui.ImVec2(pt.x, pt.y), S(3.5), col_line)
                    dl:AddCircleFilled(imgui.ImVec2(pt.x, pt.y), S(1.5), 0xFFFFFFFF) -- Белый центр
                end
            end

            -- Сначала рисуем скупку (она обычно ниже), потом продажу
            drawGraphLine(buy_pts, col_buy)
            drawGraphLine(sell_pts, col_sell)
            
            -- 4. Логика наведения (Crosshair & Tooltip)
            local mouse_pos = imgui.GetMousePos()
            local is_mouse_inside = imgui.IsMouseHoveringRect(imgui.ImVec2(graph_x, graph_y), imgui.ImVec2(graph_x + graph_w, graph_y + graph_h))
            
            if is_mouse_inside then
                -- Поиск ближайшего индекса по оси X
                local nearest_idx = 1
                local min_dist = math.huge
                
                for i = 1, points_count do
                    local target_x = graph_x + pad_x + (i - 1) * step_x
                    local dist = math.abs(mouse_pos.x - target_x)
                    if dist < min_dist then
                        min_dist = dist
                        nearest_idx = i
                    end
                end
                
                -- Рисуем вертикальный Crosshair, если курсор близко
                if min_dist < (step_x / 1.5) then
                    local cross_x = graph_x + pad_x + (nearest_idx - 1) * step_x
                    -- Вертикальная линия
                    dl:AddLine(imgui.ImVec2(cross_x, graph_y + S(10)), imgui.ImVec2(cross_x, graph_y + S(10) + draw_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.3)), 1.5)
                    
                    local current_data = VipData.graph_points[nearest_idx]
                    local c_sell = tonumber(current_data.avg_sell) or tonumber(current_data.sell) or 0
                    local c_buy  = tonumber(current_data.avg_buy)  or tonumber(current_data.buy)  or 0
                    
                    -- СТИЛЬНЫЙ TOOLTIP
                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(12), S(10)))
                    imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.08, 0.08, 0.10, 0.98))
                    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
                    imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
                    
                    imgui.BeginTooltip()
                    
                    imgui.TextColored(CURRENT_THEME.text_secondary, u8"Дата: ")
                    imgui.SameLine()
                    imgui.TextColored(CURRENT_THEME.text_primary, current_data.date_str or "?")
                    
                    imgui.Separator()
                    
                    local align_x = S(150) -- Увеличенный отступ, чтобы не наезжало
                    if c_sell > 0 then
                        imgui.TextColored(col_sell, fa('arrow_down') .. u8" Продажа:")
                        imgui.SameLine(align_x)
                        imgui.TextColored(col_sell, formatMoney(c_sell) .. " $")
                    end
                    
                    if c_buy > 0 then
                        imgui.TextColored(col_buy, fa('arrow_up') .. u8" Скупка:")
                        imgui.SameLine(align_x)
                        imgui.TextColored(col_buy, formatMoney(c_buy) .. " $")
                    end
                    
                    if c_sell > 0 and c_buy > 0 then
                        local diff = c_sell - c_buy
                        local perc = (diff / c_buy) * 100
                        imgui.Spacing()
                        imgui.TextColored(CURRENT_THEME.text_hint, u8"Разница (Спред):")
                        imgui.SameLine(align_x)
                        imgui.TextColored(CURRENT_THEME.accent_warning, string.format("+%s $ (%.1f%%)", formatMoney(diff), perc))
                    end
                    
                    imgui.EndTooltip()
                    imgui.PopStyleColor(2)
                    imgui.PopStyleVar(2)
                    
                    -- Выделение точек на крестовине
                    for _, sp in ipairs(sell_pts) do
                        if math.abs(sp.x - cross_x) < 1.0 then
                            dl:AddCircleFilled(imgui.ImVec2(sp.x, sp.y), S(6), imgui.ColorConvertFloat4ToU32(col_sell))
                            dl:AddCircleFilled(imgui.ImVec2(sp.x, sp.y), S(3), 0xFFFFFFFF)
                        end
                    end
                    for _, bp in ipairs(buy_pts) do
                        if math.abs(bp.x - cross_x) < 1.0 then
                            dl:AddCircleFilled(imgui.ImVec2(bp.x, bp.y), S(6), imgui.ColorConvertFloat4ToU32(col_buy))
                            dl:AddCircleFilled(imgui.ImVec2(bp.x, bp.y), S(3), 0xFFFFFFFF)
                        end
                    end
                end
            end
            
            -- Легенда графика (в правом верхнем углу)
            local leg_y = graph_y + S(10)
            local leg_x = graph_x + graph_w - S(100)
            
            dl:AddRectFilled(imgui.ImVec2(leg_x - S(15), leg_y + S(4)), imgui.ImVec2(leg_x - S(5), leg_y + S(14)), imgui.ColorConvertFloat4ToU32(col_sell), S(2))
            dl:AddText(imgui.ImVec2(leg_x, leg_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), u8"Продажа")
            
            dl:AddRectFilled(imgui.ImVec2(leg_x - S(15), leg_y + S(24)), imgui.ImVec2(leg_x - S(5), leg_y + S(34)), imgui.ColorConvertFloat4ToU32(col_buy), S(2))
            dl:AddText(imgui.ImVec2(leg_x, leg_y + S(20)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), u8"Скупка")
            
        end
    end
    imgui.End()
    imgui.PopStyleColor(2)
    imgui.PopStyleVar(3)
end

function api_TestTelegramToken(token)
    if not token or token == "" then return end
    
    -- [FIX] Приостанавливаем синхронизацию лавки на время проверки ключа
    local old_sync_time = MarketConfig.LAST_SYNC
    MarketConfig.LAST_SYNC = os.time() + 60 
    
    lua_thread.create(function()
        addToastNotification("Проверка и привязка ключа...", "info")
        
        -- Берем ID из сохраненных настроек
        if LOCAL_ACCOUNT_ID == 0 and Data.settings.last_account_id and Data.settings.last_account_id > 0 then
            LOCAL_ACCOUNT_ID = Data.settings.last_account_id
        end

        if LOCAL_ACCOUNT_ID == 0 or LOCAL_PLAYER_NICK == nil then
            if not State.stats_requested_by_script then
                State.stats_requested_by_script = true
                sampSendChat("/stats")
            end
            
            local attempts = 0
            while (LOCAL_PLAYER_NICK == nil or LOCAL_ACCOUNT_ID == 0) and attempts < 20 do
                wait(100)
                attempts = attempts + 1
            end
        end
        
        local current_nick = getSafeLocalNickname()
        
        local payload = {
            secret_key = token,
            nickname = u8(current_nick),
            account_id = LOCAL_ACCOUNT_ID
        }

        asyncHttpRequest("POST", MarketConfig.HOST .. "/test_tg", 
            {
                headers = {["Content-Type"] = "application/json"},
                data = json.encode(payload)
            },
            function(response)
                -- Возвращаем синхронизацию лавки
                MarketConfig.LAST_SYNC = 0 

                if response.status_code == 200 then
                    local ok, res = pcall(json.decode, response.text)

                    if ok and res.status == 'success' then
                        local new_status = res.is_vip or false

                        Data.is_vip = new_status
                        Data.vip_validated_at = os.time()
                        Data.vip_months = tonumber(res.vip_months) or 1
                        Data.vip_checked = true
                        
                        -- [INNOVATION VIP] сохраняем точное время окончания VIP
                        Data.vip_expire_ts = tonumber(res.expire_ts) or 0

                        saveSettings(true)
                        
                        local bind_msg = (LOCAL_ACCOUNT_ID > 0) 
                            and ("ID: " .. LOCAL_ACCOUNT_ID) 
                            or ("Ник: " .. current_nick)

                        addToastNotification("Успешно! Привязано к " .. bind_msg, "success", 5.0)
                        
                        -- Если VIP отсутствует — чистим локальный радар
                        if not new_status and Data.radar_list and #Data.radar_list > 0 then
                            Data.radar_list = {}
                            saveListsConfig()
                        end
                        
                        -- Обновляем статус VIP
                        checkVipStatus(token) 
                        
                        -- [CLOUD] Запускаем принудительное скачивание конфигов из облака
                        api_PullConfigsFromCloud(token)

                    elseif ok and res.message then
                        addToastNotification("Ошибка: " .. u8:decode(res.message), "error", 6.0)
                    else
                        addToastNotification("Ошибка ответа сервера", "error")
                    end

                elseif response.status_code == 403 then
                    addToastNotification("Ошибка: Неверный ключ!", "error")
                else
                    addToastNotification("Ошибка соединения: " .. response.status_code, "error")
                end
            end,
            function(err)
                -- [ОПТИМИЗАЦИЯ] Восстанавливаем оригинальное время синхронизации
                MarketConfig.LAST_SYNC = old_sync_time
                addToastNotification("Ошибка запроса. Попробуйте еще раз.", "error")
            end
        )
    end)
end

function initializeLocalPlayer()
    local res, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not res then return false end
    
    local raw_nick = sampGetPlayerNickname(myId)
    if raw_nick then
        -- Преобразуем Name_Surname в Name Surname для внутреннего использования
        local clean_nick = raw_nick:gsub("_", " ")
        
        LOCAL_PLAYER_NICK = clean_nick
        LOCAL_PLAYER_ID = myId
        
        -- Проверяем, совпадает ли ник с сохраненным
        if Data.settings.last_nickname ~= clean_nick then
            print("[RMarket] Обнаружен новый никнейм. Обновление записи...")
            Data.settings.last_nickname = clean_nick
            -- Если ник новый, сбрасываем VIP статус до проверки
            -- Data.is_vip = false 
            saveSettings(true)
            
            -- Для нового ника полезно пробить stats для обновления данных API
            State.stats_requested_by_script = true
            sampSendChat("/stats")
        else
            print("[RMarket] Быстрая авторизация успешна: " .. clean_nick)
        end
        return true
    end
    return false
end

function saveSettings(force)
    -- GUARD: Не сохранять, если настройки еще не были загружены
    if not Lifecycle.settings_loaded then return end

    if not force then
        scheduleSaveSettings()
        return
    end

    local status, err = pcall(function()
        Data.settings.auto_name_enabled     = Buffers.settings.auto_name[0]
        Data.settings.shop_name             = ffi.string(Buffers.settings.shop_name)
        Data.settings.shop_color            = Buffers.settings.shop_color[0]
        Data.settings.ui_scale_mode         = Buffers.settings.ui_scale_combo[0]
        Data.settings.show_remote_shop_menu = Buffers.settings.show_remote_shop_menu[0]
        Data.settings.delay_placement       = Buffers.settings.delay_placement[0]
        Data.settings.telegram_token        = ffi.string(Buffers.settings.telegram_token)
		Data.settings.show_live_hud         = Buffers.settings.show_live_hud[0]
		Data.settings.live_hud_only_in_shop = Buffers.settings.live_hud_only_in_shop[0] -- [NEW]
		Data.settings.show_item_images      = Buffers.settings.show_item_images[0]      -- [NEW]
		Data.settings.hide_own_vip_crown    = Buffers.settings.hide_own_vip_crown[0]
		Data.settings.price_download_percent = Buffers.settings.price_download_percent[0]
		Data.settings.shop_tax_percent       = Buffers.settings.shop_tax_percent[0]
        
        if App.hud_saved_pos_x then Data.settings.hud_pos_x = App.hud_saved_pos_x end
        if App.hud_saved_pos_y then Data.settings.hud_pos_y = App.hud_saved_pos_y end

        -- Сохраняем новую систему тем
        local themes = {[0]="RODINA_NATIVE", [1]="RODINA_VIP"}
        Data.settings.current_theme = themes[Buffers.settings.theme_combo[0]] or "RODINA_NATIVE"

        -- [ФИКС СОХРАНЕНИЯ] Запоминаем выбранные профили скупки и продажи
        Data.settings.active_buy_config = Data.active_buy_config
        Data.settings.active_sell_config = Data.active_sell_config

        -- ===============================
        -- AUTO PR (ИСПРАВЛЕНО)
        -- ===============================
        -- Убрали старые привязки к delay_min/max, так как теперь настройки внутри каждого сообщения
        local pr_clean = {
            active = Data.auto_pr.active,
            items = {}
        }
        
        for _, item in ipairs(Data.auto_pr.items or {}) do
            local clean_item = {
                type = item.type,
                text = item.text,
                channel = item.channel,
                delay = item.delay,
                active = item.active,
                name = item.name,
                expanded = item.expanded,
                shop_only = item.shop_only
            }
            
            if item.type == "group" and item.items then
                clean_item.items = {}
                for _, sub in ipairs(item.items) do
                    table.insert(clean_item.items, {
                        text = sub.text,
                        channel = sub.channel
                    })
                end
            end
            
            table.insert(pr_clean.items, clean_item)
        end
        
        Data.settings.auto_pr = pr_clean
        
        -- ===============================
        -- СОХРАНЕНИЕ
        -- ===============================
        saveJsonFile(PATHS.SETTINGS, Data.settings)
    end)

    if not status then
        print('[RMarket] Error saving settings: ' .. tostring(err))
    end
end

function saveListsConfig(force)
    if not force then
        scheduleSaveLists()
        return
    end
    
    if not App.script_loaded then return end

    -- 1. Сохраняем "Текущее состояние" (Session State)
    -- Сюда пишем как есть, включая некоторые runtime поля, если нужно восстановить UI 1-в-1
    -- Но лучше тоже очистить от мусора, чтобы не раздувать файл
    local session_sell = {}
    for _, v in ipairs(Data.sell_list) do table.insert(session_sell, sanitizeItemData(v)) end
    
    local session_buy = {}
    for _, v in ipairs(Data.buy_list) do table.insert(session_buy, sanitizeItemData(v)) end

    saveJsonFile(FILES.CURRENT_SELL_LIST, session_sell)
    saveJsonFile(FILES.CURRENT_BUY_LIST, session_buy)
	saveJsonFile(PATHS.DATA .. 'radar_list.json', Data.radar_list)
    saveJsonFile(FILES.DEALS_BLACKLIST, Data.deals_blacklist)
    saveJsonFile(FILES.WAREHOUSES, Data.warehouses) -- [NEW] Сохранение складов
    
    -- 2. Сохраняем Persistent Profiles (Долгосрочное хранение)
    -- Используем новый Safe API
    saveActiveBuyProfile() 
    saveActiveSellProfile()
    
    rebuildIndexes()
    rebuildLookupTables() -- << ДОБАВИТЬ ЭТУ СТРОКУ
end

function lerp(a, b, t) 
    return a + (b - a) * t 
end

function triggerScrollToBottom(window_id)
    -- [ФИКС ПРОКРУТКИ] Сохраняем ID панели, которую реально нужно прокрутить
    App.pending_scroll_target = window_id
end

function renderSmoothScrollBox(str_id, size, content_func)
    if imgui.BeginChild(str_id, size, true) then
        content_func()
        
        -- Выполняем скролл только внутри правильного контекста ImGui окна
