function url_encode(str)
    if str then
        str = str:gsub("\n", "\r\n")
        str = str:gsub("([^%w %-%_%.%~])",
            function (c) return string.format ("%%%02X", string.byte(c)) end)
        str = str:gsub(" ", "+")
    end
    return str
end

function App.tasks.add(name, code, wait_time)
    
    App.tasks.remove_by_name(name)
    local task = {
        name = name, 
        code = code, 
        start_time = os.clock() * 1000, 
        wait_time = wait_time,
        dead = false 
    }
    table.insert(App.tasks_list, task)
end

function App.tasks.process()
    local n = #App.tasks_list
    if n == 0 then return end
    
    local current_time = os.clock() * 1000
    local alive_tasks = {}
    local tasks_to_run = {}
    
    -- [FPS BOOST] Собираем живые задачи в новый список без вызова table.remove
    for i = 1, n do
        local task = App.tasks_list[i]
        if not task.dead then
            if current_time >= (task.start_time + task.wait_time) then
                table.insert(tasks_to_run, task)
            else
                table.insert(alive_tasks, task)
            end
        end
    end
    
    App.tasks_list = alive_tasks
    
    -- Выполняем готовые задачи
    for i = 1, #tasks_to_run do
        local t = tasks_to_run[i]
        local status, err = pcall(t.code)
        if not status then
            print("[RMarket Task Error] " .. tostring(t.name) .. ": " .. tostring(err))
        end
    end
end

function App.tasks.remove_by_name(name)
    for i, v in ipairs(App.tasks_list) do
        if v.name == name then 
            v.dead = true 
            return 
        end
    end
end

function events.onServerMessage(color, text)
    local is_text_modified = false

    local clean_text_for_rp = text:gsub("{......}", "")
    local is_rp = false
    
    -- [ОПТИМИЗАЦИЯ] Быстрые проверки plain-text (true) перед вызовом тяжелых Regex-паттернов
    if clean_text_for_rp:find('", %- сказал', 1, true) then 
        is_rp = true 
    elseif clean_text_for_rp:find(")", 1, true) and clean_text_for_rp:match("%([a-zA-Z\192-\255\168\184]+[_%s][a-zA-Z\192-\255\168\184]+%)%s*%[%d+%]") then 
        is_rp = true 
    elseif clean_text_for_rp:find("]", 1, true) and clean_text_for_rp:match("^[a-zA-Z\192-\255\168\184]+[_%s][a-zA-Z\192-\255\168\184]+%s*%[%d+%]") then
        if not (clean_text_for_rp:find("говорит:", 1, true) or 
                clean_text_for_rp:find("кричит:", 1, true) or 
                clean_text_for_rp:find("шепчет:", 1, true)) then
            is_rp = true
        end
    end

    if not is_rp then
        local base_color_hex = string.format("{%06X}", bit.band(bit.rshift(color, 8), 0xFFFFFF))
        local function getActiveColor(full_str, pos)
            local active_color = base_color_hex
            for c_pos, hex in full_str:gmatch("(){(%x%x%x%x%x%x)}") do
                if c_pos < pos then active_color = "{" .. hex .. "}" else break end
            end
            return active_color
        end

        local new_text = text:gsub("()([a-zA-Z\192-\255\168\184]+[_%s][a-zA-Z\192-\255\168\184]+)(%s*%-?{?%x*}?%s*)%[(%d+)%]", function(pos, name, spacer, id)
            local check_nick_space = name:gsub("_", " ")
            local check_nick_under = name:gsub(" ", "_")
            local cached_val = Data.vip_users_cache[check_nick_space] or Data.vip_users_cache[check_nick_under]

            if cached_val then
                if Data.settings.hide_own_vip_crown then
                    local my_nick_en = LOCAL_PLAYER_NICK and LOCAL_PLAYER_NICK:gsub("_", " ") or ""
                    local my_nick_ru = LOCAL_PLAYER_NICK_RUS and LOCAL_PLAYER_NICK_RUS:gsub("_", " ") or ""
                    if check_nick_space == my_nick_en or check_nick_space == my_nick_ru then
                        return name .. spacer .. "[" .. id .. "]"
                    end
                end
                is_text_modified = true
                local prev_color = getActiveColor(text, pos)
                local m = (type(cached_val) == "number") and cached_val or 1
                m = math.max(1, math.min(m, 10))
                local emoji_hex = string.format("%x", 0xf250 + m - 1)
                local vip_prefix = string.format("{FFD700}:crown: :u%s: ", emoji_hex)
                return vip_prefix .. prev_color .. name .. spacer .. "[" .. id .. "]"
            end
            return name .. spacer .. "[" .. id .. "]"
        end)

        if is_text_modified then text = new_text end
    end

    local clean_text = cleanTextColors(text)
    
    if clean_text:find("^Server closed the connection%.") or clean_text:find("^Сервер закрыл соединение%.") then
        sendDisconnectNotification("Кик / Сервер закрыл соединение")
    elseif clean_text:find("^You are banned from this server%.") then
        sendDisconnectNotification("IP или Аккаунт заблокирован сервером")
    elseif clean_text:find("Вы были кикнуты") or clean_text:find("You were kicked") then
        sendDisconnectNotification("Вас кикнул Администратор")
    end
    
    if clean_text:find("Используйте клавишу X, либо пишите в чат, чтобы разговаривать по телефону") then
        if not App.last_call_accept_time or os.clock() - App.last_call_accept_time > 2.0 then
            App.last_call_accept_time = os.clock()
            local payload = { secret_key = Data.settings.telegram_token, data = { type = "phone_started" } }
            signed_request("POST", MarketConfig.HOST .. "/notify", payload)
        end
    end
    
    if ScanCollector.current_shop_owner and ScanCollector.waiting_for_id then
        local target_search = ScanCollector.current_shop_owner:gsub(" ", "_")
        if clean_text:find("Имя:%s*" .. target_search) and clean_text:find("ID:%s*%d+") then
            local found_id = clean_text:match("ID:%s*(%d+)")
            if found_id then
                ScanCollector.current_shop_id = tonumber(found_id)
                ScanCollector.waiting_for_id = false
                App.tasks.remove_by_name("scan_id_timeout")
                return false
            end
        end
    end

    if GPSFinder.active and GPSFinder.target_nick and GPSFinder.waiting_for_id then
        local target = GPSFinder.target_nick
        if clean_text:find("ID:%s*(%d+)%s*|%s*Имя:%s*" .. target) then
            local found_id = clean_text:match("ID:%s*(%d+)")
            if found_id then
                GPSFinder.active = false
                GPSFinder.waiting_for_id = false
                App.tasks.remove_by_name("gps_timeout")
                App.tasks.remove_by_name("gps_id_timeout")
                sampSendChat("/findilavka " .. found_id)
                addToastNotification("Метка установлена! ID: " .. found_id, "success")
                return false
            end
        end
        if clean_text:find("Игрок не найден") or clean_text:find("Ничего не найдено") then
            GPSFinder.active = false
            GPSFinder.waiting_for_id = false
            App.tasks.remove_by_name("gps_timeout")
            App.tasks.remove_by_name("gps_id_timeout")
            addToastNotification("Игрок оффлайн.", "error")
            return false
        end
    end

    if PassiveChecker.active and (PassiveChecker.current_nick or #PassiveChecker.queue == 0) then
        local clean_line = text:gsub("{......}", ""):gsub("%[......%]", "")
        clean_line = clean_line:gsub("%[Mobile%]", ""):gsub("%[PC%]", ""):gsub("%[Launcher%]", "")
        clean_line = clean_line:gsub("%- AFK:.*", "")
        clean_line = clean_line:gsub("%s+", " "):lower()
        
        local target_lower = ""
        if PassiveChecker.current_nick then
            target_lower = PassiveChecker.current_nick:gsub(" ", "_"):lower()
        end
        
        local id_match = clean_line:match("^id:%s*(%d+)%s*|")
        local nick_found = (target_lower ~= "") and clean_line:find(target_lower, 1, true) or false
        
        if id_match and nick_found and PassiveChecker.waiting_for_id then
            PassiveChecker.waiting_for_id = false
            App.tasks.remove_by_name("passive_id_timeout")
            App.tasks.remove_by_name("passive_check_timeout")
            local found_id = tonumber(id_match)
            local expected = PassiveChecker.current_expected_id
            
            if expected and expected > 0 and found_id and found_id ~= expected then
                deletePassiveShop(PassiveChecker.current_nick)
            else
                pingPassiveShop(PassiveChecker.current_nick)
                local shop_obj = PassiveChecker.current_shop_obj
                if shop_obj then
                    if found_id then shop_obj.playerId = found_id end
                    local exists = false
                    for _, s in ipairs(MarketData.shops_list) do
                        if s.nickname == shop_obj.nickname then exists = true break end
                    end
                    if not exists then
                        table.insert(MarketData.shops_list, shop_obj)
                        MarketData.online_count = #MarketData.shops_list
                        MarketData.last_executed_search = ""
                    end
                end
            end
            lua_thread.create(function() wait(50) processNextPassiveCheck() end)
            return false
        end
        
        if clean_line:find("игрок не найден") or clean_line:find("ничего не найдено") or clean_line:find("не найден") then
            if PassiveChecker.current_nick then
                PassiveChecker.waiting_for_id = false
                App.tasks.remove_by_name("passive_id_timeout")
                App.tasks.remove_by_name("passive_check_timeout")
                deletePassiveShop(PassiveChecker.current_nick)
                lua_thread.create(function() wait(50) processNextPassiveCheck() end)
            end
            return false
        end
        if #PassiveChecker.queue == 0 and (id_match or clean_line:find("игрок не найден")) then return false end
    end
    
    if (clean_text:find("Банковский чек") or clean_text:find("PAYDAY")) and clean_text:find("_+") then
        State.payday.active = true
        State.payday.timer = os.clock()
        State.payday.data = { dep = 0, dep_cur = 0, bank = 0, bank_cur = 0, exp = 0, exp_cur = 0, exp_max = 0, az = 0, az_cur = 0, lvl = 0, shard = nil }
        if is_text_modified then return {color, text} end
        return
    end

    if State.payday.active then
        local function sendPayDayData()
            State.payday.active = false
            if Data.settings.telegram_token and Data.settings.telegram_token ~= "" then
                local payload = {
                    secret_key = Data.settings.telegram_token,
                    data = {
                        type = "payday",
                        deposit = tonumber(State.payday.data.dep) or 0, deposit_current = tonumber(State.payday.data.dep_cur) or 0,
                        bank = tonumber(State.payday.data.bank) or 0, bank_current = tonumber(State.payday.data.bank_cur) or 0,
                        exp = tonumber(State.payday.data.exp) or 0, exp_current = tonumber(State.payday.data.exp_cur) or 0, exp_max = tonumber(State.payday.data.exp_max) or 0,
                        az = tonumber(State.payday.data.az) or 0, az_current = tonumber(State.payday.data.az_cur) or 0,
                        level = tonumber(State.payday.data.lvl) or 0,
                        shard = State.payday.data.shard and u8(State.payday.data.shard) or ""
                    }
                }
                signed_request("POST", MarketConfig.HOST .. "/notify", payload)
            end
        end

        -- Фолбэк: если нижняя черта не была найдена, но данные собраны (таймаут)
        if os.clock() - State.payday.timer > 8.0 then 
            sendPayDayData() 
        end 
        
        if clean_text:find("Депозит в банке:") then
            local current = clean_text:match("Депозит в банке:%s*([%d%.,%s]+)")
            local plus = clean_text:match("%+%s*([%d%.,%s]+)")
            if current then State.payday.data.dep_cur = current:gsub("[%.,%s]", "") end
            if plus then State.payday.data.dep = plus:gsub("[%.,%s]", "") end
        elseif clean_text:find("На банковском счету:") then
            local current = clean_text:match("На банковском счету:%s*([%d%.,%s]+)")
            local plus = clean_text:match("%+%s*([%d%.,%s]+)")
            if current then State.payday.data.bank_cur = current:gsub("[%.,%s]", "") end
            if plus then State.payday.data.bank = plus:gsub("[%.,%s]", "") end
        elseif clean_text:find("Ваш игровой уровень:") then
            local lvl, exp_c, exp_m = clean_text:match("уровень:%s*(%d+).-опыта:%s*(%d+)%s*/%s*(%d+)")
            local plus = clean_text:match("опыта.-%+%s*([%d%.,%s]+)")
            if lvl then State.payday.data.lvl = lvl end
            if exp_c then State.payday.data.exp_cur = exp_c end
            if exp_m then State.payday.data.exp_max = exp_m end
            if plus then State.payday.data.exp = plus:gsub("[%.,%s]", "") end
        elseif clean_text:find("Всего донат%-очков:") then
            local current = clean_text:match("донат%-очков:%s*([%d%.,%s]+)")
            local plus = clean_text:match("%+%s*([%d%.,%s]+)")
            if current then State.payday.data.az_cur = current:gsub("[%.,%s]", "") end
            if plus then State.payday.data.az = plus:gsub("[%.,%s]", "") end
        elseif clean_text:find("%[Бонус%] Вы получили Осколок") then
            local shard_name = clean_text:match("%[Бонус%] Вы получили (Осколок [^%.]+)")
            if shard_name then State.payday.data.shard = shard_name end
        elseif clean_text:find("^%s*[_=]+%s*$") and (os.clock() - State.payday.timer > 0.5) then
            -- Ищем подчеркивания или равно внизу чека
            sendPayDayData()
        end
        if is_text_modified then return {color, text} end
        return
    end

    if clean_text:match("^%s*%[Телефон%]") then
        local caller, msg_text = clean_text:match("%[Телефон%]%s*(.-):%s*(.*)")
        if caller and msg_text then
            local my_nick_no_space = LOCAL_PLAYER_NICK and LOCAL_PLAYER_NICK:gsub(" ", "_") or "Unknown"
            if caller ~= LOCAL_PLAYER_NICK and caller ~= my_nick_no_space and caller ~= "Вы" then
                local payload = { secret_key = Data.settings.telegram_token, data = { type = "phone_message", caller = u8(caller), text = u8(msg_text) } }
                signed_request("POST", MarketConfig.HOST .. "/notify", payload)
            end
        end
    end

    if clean_text:find("ID:%s*%d+%s*|%s*Имя:") then
        local msg_id, msg_nick = clean_text:match("ID:%s*(%d+)%s*|%s*Имя:%s*([%w_]+)")
        local res, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
        if msg_id and msg_nick and res then
            if tonumber(msg_id) == tonumber(myId) then
                LOCAL_PLAYER_NICK = msg_nick:gsub("_", " ")
                LOCAL_PLAYER_ID = tonumber(msg_id)
                return false
            end
        end
        if is_text_modified then return {color, text} end
        return
    end

    if not clean_text:find("^%[Лавка%]") then 
        if is_text_modified then return {color, text} end
        return 
    end
    
    local transaction = parseShopMessage(text)
    
    if clean_text:find("Вы отказались от аренды лавки") or clean_text:find("Вы сняли лавку") or clean_text:find("Ваша лавка была закрыта") or clean_text:find("Вы покинули лавку") then
        Marketplace_Clear()
    end
    
    if transaction then
        addTransactionLog(transaction)
        if transaction.type == "sale" then
            addToastNotification(string.format("Продано: %s (%dх) за %s руб.", transaction.item, transaction.amount, formatMoney(transaction.total)), "success", 4.0)
        else
            addToastNotification(string.format("Куплено: %s (%dх) за %s руб.", transaction.item, transaction.amount, formatMoney(transaction.total)), "info", 4.0)
        end
    end
    
    if is_text_modified then return {color, text} end
end

-- [ОПТИМИЗАЦИЯ FPS] Кэшированная таблица перевода регистров (работает на скорости Си)
local LOWERCASE_MAP = {}
for i = 0, 255 do
    local char = string.char(i)
    if i >= 192 and i <= 223 then
        LOWERCASE_MAP[char] = string.char(i + 32)
    elseif i == 168 then
        LOWERCASE_MAP[char] = string.char(184)
    else
        LOWERCASE_MAP[char] = string.lower(char)
    end
end

function to_lower(str)
    if type(str) ~= "string" then return "" end
    -- gsub с таблицей заменяет символы мгновенно, без циклов в Lua
    return (str:gsub(".", LOWERCASE_MAP))
end

function isAccessory(name)
    if not name or name == "" then return false end
    
    if name:sub(1, 18) == "Аксессуар " or name:sub(1, 18) == "аксессуар " then return true end
    
    if Data and Data.item_names_reversed and Data.item_categories then
        local id = Data.item_names_reversed[cleanItemNameKey(name)]
        if id then
            local cat = Data.item_categories[tostring(id)]
            return cat == "Аксессуар"
        end
    end
    
    return false
end

function renderAnimatedSearchBar(buffer, hint, width)
    local changed = false
    local height = S(42)
    local p = imgui.GetCursorScreenPos()
    
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(12), (height - imgui.GetFontSize()) / 2))
    imgui.PushStyleVarFloat(imgui.StyleVar.FrameRounding, height / 2)
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    
    imgui.SetNextItemWidth(width - S(40))
    changed = imgui.InputTextWithHint("##search_bar_clean", u8(hint), buffer, 128)
    
    imgui.PopStyleColor()
    imgui.PopStyleVar(2)

    -- Кнопка очистки
    if buffer[0] ~= 0 then
        imgui.SameLine()
        imgui.SetCursorPosY(p.y + (height - S(24)) / 2)
        if imgui.Button(u8"X", imgui.ImVec2(S(28), S(28))) then
            buffer[0] = 0
            changed = true
        end
    end
    
    return changed
end

function filterList(list, buffer_char)
    if not list or #list == 0 then 
        return {} 
    end
    
    -- Получаем строку из буфера ImGui
    local query_utf8 = ffi.string(buffer_char)
    
    if query_utf8 == "" then 
        return list 
    end
    
    -- Декодируем из UTF-8 в CP1251 (так как ImGui вводит в UTF-8, а скрипт в CP1251)
    local query = u8:decode(query_utf8)
    
    if not query or query == "" then 
        return list 
    end
    
    local results_with_score = {}
    
    for i, item in ipairs(list) do
        if item and item.name then
            -- Очищаем имя товара от цветов и тегов перед поиском
            local clean_name = enhancedCleanItemName(item.name)
            local score = SmartSearch.getMatchScore(query, clean_name)
            
            if score > 0 then
                table.insert(results_with_score, {data = item, score = score})
            end
        end
    end
    
    -- Сортируем по релевантности (чем больше score, тем выше)
    table.sort(results_with_score, function(a, b)
        return a.score > b.score
    end)
    
    local final_result = {}
    for _, entry in ipairs(results_with_score) do
        table.insert(final_result, entry.data)
    end
    
    return final_result
end

function tableContains(tbl, field_name, value)
    for _, item in ipairs(tbl) do
        if item[field_name] == value then
            return true
        end
    end
    return false
end

function tableFind(tbl, field_name, value)
    for idx, item in ipairs(tbl) do
        if item[field_name] == value then
            return idx, item
        end
    end
    return nil
end

local stat_card_anims = {} -- Кэш анимаций для карточек

function drawStatCard(label, value, color_bg, width, height)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    
    imgui.Dummy(imgui.ImVec2(width, height))
    local is_hovered = imgui.IsItemHovered()
    
