local function http_worker_entry(chan_in, chan_out, worker_id, p_path, p_cpath)
    package.path = p_path
    package.cpath = p_cpath
    
    -- Загружаем библиотеки один раз при старте потока
    local req_ok, requests = pcall(require, 'requests')
    local sock_ok, socket = pcall(require, 'socket') -- Для пауз между попытками
    if not req_ok then 
        return 
    end
    
    -- Настройки по умолчанию
    local default_headers = {
        ["User-Agent"] = "RMarket-Client/4.6 (Optimization Update)",
        ["Connection"] = "close" -- [FIX DPI] Закрываем соединение после каждого запроса
    }

    while true do
        local task = chan_in:pop()
        
        if task then
            if task.command == 'STOP' then break end
            
            local args = task.args or {}
            args.headers = args.headers or {}
            for k, v in pairs(default_headers) do
                if not args.headers[k] then args.headers[k] = v end
            end

            -- Таймауты и SSL (Увеличили таймаут до 20с для слабых интернет-каналов)
            args.timeout = args.timeout or 20 
            args.verify = false
            args.sslParams = { mode = "client", protocol = "any", verify = "none", options = "all" }

            -- Оптимизированный прямой запрос без блокировок потока
            local status, result = pcall(requests.request, task.method, task.url, args)
            local response = { id = task.id, success = status }
            
            if status and result then
                -- Если сервер (или VPN/DPI) жестко оборвал соединение и вернул пустышку
                if not result.status_code then
                    response.success = false
                    response.error = "Connection reset by DPI/VPN (Empty response)"
                else
                    response.code = result.status_code
                    response.text = result.text
                    
                    -- Безопасная обработка хедеров
                    if result.headers then
                        local h = {}
                        pcall(function() 
                            if type(result.headers) == 'table' then
                                for k,v in pairs(result.headers) do h[tostring(k)] = tostring(v) end 
                            end
                        end)
                        response.headers = h
                    end
                end
            else
                response.error = tostring(result)
            end
            
            -- Отправляем результат обратно
            chan_out:push(response)
        end
    end
end

-- Инициализация ПУЛА ПОТОКОВ (3 воркера вместо 1)
function initHttpWorker()
    if HttpSystem.threads_initialized then return end
    
    local p_path, p_cpath = package.path, package.cpath
    
    -- Запускаем 3 параллельных потока
    for i = 1, 3 do
        -- Сохраняем ссылку на поток в таблицу
        local t = effil.thread(http_worker_entry)(HttpSystem.channel_in, HttpSystem.channel_out, i, p_path, p_cpath)
        table.insert(HttpSystem.threads, t)
    end
    
    HttpSystem.threads_initialized = true
    print("[RMarket] HTTP Multi-thread system started (3 workers)")
end

-- Новая функция запроса
function asyncHttpRequest(method, url, args, resolve, reject)
    -- Проверяем правильный флаг! Иначе будет бесконечное создание потоков
    if not HttpSystem.threads_initialized then initHttpWorker() end
    
    local req_id = os.clock() .. math.random(1000,99999)
    
    HttpSystem.callbacks[req_id] = {
        resolve = resolve or function() end,
        reject = reject or function() end,
        timestamp = os.clock()
    }
    
    -- Отправляем в поток
    HttpSystem.channel_in:push({
        id = req_id,
        method = method,
        url = url,
        args = args
    })
end

function processHttpCallbacks()
    -- [ОПТИМИЗАЦИЯ IO] Ограничиваем обработку колбэков
    local processed_this_frame = 0
    local max_per_frame = 5

    while processed_this_frame < max_per_frame do
        local response = HttpSystem.channel_out:pop(0)
        if not response then break end
        
        local cb = HttpSystem.callbacks[response.id]
        if cb then
            if response.success then
                local fake_res = {
                    status_code = response.code,
                    text = response.text,
                    headers = response.headers
                }
                pcall(cb.resolve, fake_res)
            else
                local err_str = tostring(response.error)
                -- [ФИКС СПАМА В ЛОГИ] Игнорируем дефолтные фоновые таймауты
                if not err_str:find("timeout") and not err_str:find("Connection reset") and not err_str:find("closed") then
                    -- Извлекаем только суть ошибки без длинного пути к файлу requests.lua
                    local clean_err = err_str:match("error in.-request: (.+)") or err_str
                    print(string.format("[RMarket Network] Request failed: %s", clean_err))
                end
                pcall(cb.reject, response.error)
            end
            HttpSystem.callbacks[response.id] = nil
        end
        processed_this_frame = processed_this_frame + 1
    end
    
    -- Очистка зависших колбэков (старее 120 сек)
    local now = os.clock()
    if now % 10.0 < 0.1 then
        for id, cb in pairs(HttpSystem.callbacks) do
            if now - cb.timestamp > 120 then
                HttpSystem.callbacks[id] = nil
            end
        end
    end
end

function saveLiveShopState()
    local shop_state = {
        sell = Data.live_shop.sell or {},
        buy = Data.live_shop.buy or {},
        is_active = App.live_shop_active,
        marketplace_enabled = Marketplace.enabled,
        marketplace_uid = Marketplace.LavkaUid,
        publish_sell = Marketplace.publish_sell,
        publish_buy = Marketplace.publish_buy,
        saved_at = os.time() -- [NEW] Сохраняем время последней активности
    }
    saveJsonFile(PATHS.DATA .. 'live_shop_state.json', shop_state)
end

function loadLiveShopState()
    local path = PATHS.DATA .. 'live_shop_state.json'
    if doesFileExist(path) then
        local data = loadJsonFile(path, {})
        if data then
            -- Конвертируем строковые ключи JSON обратно в числовые (слоты)
            Data.live_shop.sell = {}
            if data.sell then
                for k, v in pairs(data.sell) do Data.live_shop.sell[tonumber(k) or k] = v end
            end
            
            Data.live_shop.buy = {}
            if data.buy then
                for k, v in pairs(data.buy) do Data.live_shop.buy[tonumber(k) or k] = v end
			end
			
			-- [FIX] Лавка хранится локально 24 часа. Сервер сам удалит её из онлайна при таймауте, 
			-- но локальный кэш должен пережить перезаходы и краши без случайных удалений.
			local saved_time = tonumber(data.saved_at) or 0
			if (os.time() - saved_time) <= 86400 then
				if data.is_active or data.marketplace_enabled then
                    App.live_shop_active = true
                    Marketplace.enabled = true
                    Marketplace.LavkaUid = data.marketplace_uid or os.time()
                    Marketplace.publish_sell = data.publish_sell or false
                    Marketplace.publish_buy = data.publish_buy or false
                    MarketConfig.LAST_SYNC = 0
                end
            else
                -- Сессия устарела (выходили из игры), сбрасываем статус лавки
                App.live_shop_active = false
                Marketplace.enabled = false
                Marketplace.is_cleared = true
            end
        end
    else
        Data.live_shop = { sell = {}, buy = {} }
    end
end

function safe_decode(str)
    if type(str) ~= "string" or str == "" then return tostring(str or ""):gsub("userdata:.*", "") end
    local status, result = pcall(u8.decode, u8, str)
    return status and result or str 
end

function parseServerTime(date_str)
    if not date_str then return 0 end
    -- Формат базы данных: YYYY-MM-DD HH:MM:SS
    local Y, M, D, h, m, s = string.match(date_str, "(%d+)-(%d+)-(%d+) (%d+):(%d+):(%d+)")
    if Y then
        return os.time({year=Y, month=M, day=D, hour=h, min=m, sec=s})
    end
    return 0
end

function getTimeAgo(timestamp)
    if not timestamp or timestamp == 0 then return "Давно" end
    local diff = os.time() - timestamp
    
    if diff < 60 then return diff .. " сек. назад" end
    if diff < 3600 then return math.floor(diff/60) .. " мин. назад" end
    if diff < 86400 then return math.floor(diff/3600) .. " ч. назад" end
    return math.floor(diff/86400) .. " дн. назад"
end

function api_SyncRadar()
    if not Data.settings.telegram_token or Data.settings.telegram_token == "" then return end
    if not isVerifiedVip() then 
        if #Data.radar_list > 0 then
            Data.radar_list = {}
            saveListsConfig()
        end
        return 
    end
    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    local payload = {
        server_id = server_id,
        radar_list = {},
        is_empty = (#Data.radar_list == 0)
    }
    for _, item in ipairs(Data.radar_list) do
        local model_id = findRealIndexByName(item.name) or -1
        if model_id > 0 then
            table.insert(payload.radar_list, {
                item_id = model_id,
                price = tonumber(item.price) or 0,
                type = tonumber(item.type) or 0
            })
        end
    end
    signed_request("POST", MarketConfig.HOST .. "/sync_radar", payload)
end

function api_FetchCarPrices(silent)
    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    
    if not silent then addToastNotification("Обновление базы автобазара...", "info", 2.0) end
    
    asyncHttpRequest("GET", MarketConfig.HOST .. "/cars/get?server=" .. url_encode(server_id), {}, 
        function(response)
            if response.status_code == 200 then
                local ok, data = pcall(json.decode, response.text)
                if ok and type(data) == "table" then
                    local srv_db, srv_id = CarMarket.getCurrentServerDB()
                    local count = 0
                    
                    for _, car in ipairs(data) do
                        if car.car_name then
                            local safe_car_name = u8:decode(car.car_name) 
                            local rarity_key = car.rarity or "tier2"
                            
                            local r_map = { ["tier1"] = "Хлам", ["tier2"] = "Обычное", ["tier3"] = "Идеальное" }
                            local r_text = r_map[rarity_key] or "Обычное"
                            local full_local_name = safe_car_name .. " [" .. r_text .. "]"
                            
                            if not srv_db[full_local_name] then
                                srv_db[full_local_name] = { p = {}, min = 0, max = 0 }
                            end
                            
                            local avg = tonumber(car.avg_price) or 0
                            if avg > 0 then
                                srv_db[full_local_name].avg = avg
                                count = count + 1
                            end
                            
                            if car.min_price and tonumber(car.min_price) > 0 then srv_db[full_local_name].min = tonumber(car.min_price) end
                            if car.max_price and tonumber(car.max_price) > 0 then srv_db[full_local_name].max = tonumber(car.max_price) end
                        end
                    end
                    
                    CarMarket.save()
                    saveJsonFile(PATHS.CACHE .. 'car_meta.json', { last_update = os.time() })
                    
                    if not silent then addToastNotification("База АБ обновлена! Загружено: " .. count, "success", 3.0) end
                end
            elseif not silent then
                addToastNotification("Ошибка обновления БД машин", "error")
            end
        end,
        function(err)
            if not silent then addToastNotification("Ошибка сети при обновлении АБ", "error") end
        end
    )
end

function api_FetchMarketList()
    -- [ВАЖНО] Включаем индикатор загрузки, но НЕ очищаем список здесь, 
    -- чтобы пользователь видел кэш (старые данные) пока грузятся новые.
    MarketData.is_loading = true
    
    -- Сбрасываем очередь проверки пассивных лавок
    PassiveChecker.queue = {}
    PassiveChecker.active = false
    
    -- [FIX КЭШИРОВАНИЯ] Добавляем метку времени к URL, чтобы Nginx и провайдеры не кэшировали ответ
    local url_no_cache = MarketConfig.HOST .. '/marketplace?action=list&t=' .. tostring(os.clock())
    
    asyncHttpRequest('GET', url_no_cache, 
        {timeout = 20}, 
        function(response)
            if response.status_code == 200 then
                -- Сохраняем полный дамп локально
                local file = io.open(PATHS.CACHE .. 'market_dump.json', "w")
                if file then
                    file:write(response.text)
                    file:close()
                end

                local decode_ok, data = pcall(json.decode, response.text)
                if decode_ok and type(data) == "table" then
                    
                    -- [FIX DUPLICATES] Очищаем список ТОЛЬКО СЕЙЧАС, когда пришли новые данные
                    MarketData.shops_list = {} 
                    
                    local ip, port = sampGetCurrentServerAddress()
                    local current_server_id = normalizeServerId(ip .. ":" .. port)
                    local passive_count_to_check = 0

                    for _, shop in ipairs(data) do
                        -- [FIX] Используем безопасный парсинг, созданный выше (обход багов с ключами JSON)
                        local s_list = safeParseMarketItems(shop.items_sell, shop.count_sell, shop.price_sell)
                        local b_list = safeParseMarketItems(shop.items_buy, shop.count_buy, shop.price_buy)

                        -- [NEW] Игнорируем полностью пустые лавки (совместимо с Lua 5.1)
                        if #s_list > 0 or #b_list > 0 then
                            local raw_nick = shop.username or shop.user or "Unknown"
                            local safe_nick = safe_decode(raw_nick)
                            local is_vip_shop = shop.vip or false
                            
                            -- [FIX] ВОТ ЭТОЙ СТРОКИ НЕ БЫЛО, ИЗ-ЗА ЭТОГО ВСЕ ЛАВКИ БЫЛИ "ВОСТОЧНЫЙ"
                            local srv_id = shop.serverId or shop.server_id
                            
                            -- [NEW] Пополняем кэш для чата (не сбрасывая уровень)
                            if is_vip_shop then
                                if not Data.vip_users_cache[safe_nick] then Data.vip_users_cache[safe_nick] = 1 end
                                if not Data.vip_users_cache[safe_nick:gsub(" ", "_")] then Data.vip_users_cache[safe_nick:gsub(" ", "_")] = 1 end
                            end
                            
                            -- [NEW] Парсинг времени обновления
                            local update_ts = parseServerTime(shop.updated_at)
                            
                            local shop_obj = {
                                nickname = safe_nick,
                                serverId = srv_id, 
                                vip = shop.vip or false,
                                is_passive = shop.is_passive or false,
                                sell_count = #s_list,
                                buy_count = #b_list,
                                shop_name = "Лавка " .. safe_nick,
                                sell_list = s_list,
                                buy_list = b_list,
                                playerId = shop.playerId,
                                updated_at = shop.updated_at,
                                updated_ts = update_ts
                            }

                            -- [FIX] Вырезана ЛОГИКА РАЗДЕЛЕНИЯ и PassiveChecker.
                            -- В реалиях SAMP спам командами /id приводит к кику и не прогружает лавки.
                            -- Теперь все лавки сразу добавляются в список отображения.
                            table.insert(MarketData.shops_list, shop_obj)
                        end
                    end
                    
                    MarketData.online_count = #MarketData.shops_list
                    MarketData.last_fetch = os.time()
                    MarketData.is_loading = false
					
                    MarketData.last_executed_search = ""
                    addToastNotification("Список лавок успешно загружен!", "success", 3.0)
                else
                    MarketData.is_loading = false
                end
            else
                addToastNotification("Ошибка API: " .. response.status_code, "error")
                MarketData.is_loading = false
            end
        end,
        function(err)
            addToastNotification("Ошибка соединения", "error")
            MarketData.is_loading = false
        end
    )
end

function findPlayerIdByNickname(nick)
    if not nick or nick == "" then return -1 end

    -- Предварительная подготовка искомого ника (один раз)
    local target = nick:gsub("{......}", ""):gsub("%[.-%]", ""):gsub(" ", "_"):match("^%s*(.-)%s*$"):lower()
    
    local max_players = sampGetMaxPlayerId(false)
    for i = 0, max_players do
        if sampIsPlayerConnected(i) then
            local pNick = sampGetPlayerNickname(i)
            
            -- [ОПТИМИЗАЦИЯ] sampGetPlayerNickname УЖЕ возвращает ник с _, gsub не нужен.
            -- Сначала делаем быструю проверку длины, затем приводим к lower()
            if pNick and #pNick == #target and not pNick:find("^Player_%d+$") then
                if pNick:lower() == target then
                    return i
                end
            end
        end
    end

    return -1
end

function api_FetchShopDetails(server_id, nickname)
    if not nickname then return end
    
    -- Ищем локально в уже загруженном списке
    local found_shop = nil
    
    -- 1. Сначала ищем в активном списке
    for _, shop in ipairs(MarketData.shops_list) do
        if shop.nickname == nickname and (not server_id or shop.serverId == server_id) then
            found_shop = shop
            break
        end
    end
    
    -- 2. Если не нашли (например, из поиска), ищем в кэше дампе
    if not found_shop then
        local cache_path = PATHS.CACHE .. 'market_dump.json'
        if doesFileExist(cache_path) then
            local data = loadJsonFile(cache_path, {})
            if data and type(data) == "table" then
                for _, s in ipairs(data) do
                    local s_nick = safe_decode(s.username or s.user)
                    if s_nick == nickname then
                        -- Восстанавливаем объект шоп как в api_FetchMarketList
                        -- (упрощенный вариант для примера, лучше использовать общую функцию парсинга)
                        -- Но так как мы нажали на карточку, она скорее всего уже в MarketData.shops_list
                    end
                end
            end
        end
    end

    if found_shop then
        -- Если ID игрока не актуален (-1), пробуем найти в игре
        if not found_shop.playerId or found_shop.playerId == -1 then
             found_shop.playerId = findPlayerIdByNickname(found_shop.nickname)
        end
        
        MarketData.selected_shop = found_shop
        -- addToastNotification("Лавка открыта (Локально)", "success", 1.0) -- Можно убрать для бесшовности
    else
        addToastNotification("Ошибка: данные лавки не найдены в кэше. Обновите список.", "error")
    end
end

