function renderModernShopItemGridCard(item, is_sell, w, h, index)
    imgui.PushIDInt(index)
    local p = imgui.GetCursorScreenPos()
    local is_hovered = imgui.IsMouseHoveringRect(p, imgui.ImVec2(p.x + w, p.y + h))

    local bg_col = is_hovered and CURRENT_THEME.bg_tertiary_u32 or CURRENT_THEME.bg_secondary_u32

    imgui.PushStyleColor(imgui.Col.ChildBg, is_hovered and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary)
    imgui.PushStyleColor(imgui.Col.Border, is_hovered and CURRENT_THEME.accent_primary or CURRENT_THEME.border_light)
    imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, S(8))
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))

    if imgui.BeginChild("##shop_item_card", imgui.ImVec2(w, h), true, imgui.WindowFlags.NoScrollbar) then
        local child_p = imgui.GetWindowPos()
        local dl = imgui.GetWindowDrawList()
        local padding = S(12)
        
        if imgui.IsWindowHovered() and imgui.IsMouseClicked(0) and not imgui.IsAnyItemHovered() then
            setClipboardText(item.name)
            addToastNotification("Название скопировано", "info")
        end
        if imgui.IsWindowHovered() and not imgui.IsAnyItemHovered() then 
            imgui.SetTooltip(u8"Нажмите, чтобы скопировать название") 
        end
        
        -- 1. ОТРИСОВКА ИКОНКИ
        local target_model_id = item._cached_model_id or item.model_id or findRealIndexByName(item.name) or -1
        item._cached_model_id = target_model_id
        
        local img_box_sz = S(45)
        local icon_p = imgui.ImVec2(child_p.x + padding, child_p.y + padding)
        
        dl:AddRectFilled(icon_p, imgui.ImVec2(icon_p.x + img_box_sz, icon_p.y + img_box_sz), CURRENT_THEME.bg_main_u32, S(6))
        dl:AddRect(icon_p, imgui.ImVec2(icon_p.x + img_box_sz, icon_p.y + img_box_sz), CURRENT_THEME.border_light_u32, S(6), 15, S(1))
        
        local texture = getItemIconTexture(tonumber(target_model_id))
