                imgui.PopFont()
            end
        end

        -- 2. ТЕКСТОВАЯ ЧАСТЬ
        local text_start_x = icon_p.x + img_box_sz + padding
        local tools_w = Data.is_vip and S(35) or 0
        local max_name_w = w - (img_box_sz + padding * 2) - tools_w - S(5)
        
        local raw_name = item.name or ""
        raw_name = raw_name:gsub("%s*%(Перенос:%s*.-%)", "")
        if not item._c_u8_name then item._c_u8_name = u8(raw_name) end
        
        local name_y = child_p.y + padding - S(2)
