        local r_sz = GetStaticTextSize(radar_icon)
        local r_col = radar_hovered and CURRENT_THEME.accent_warning or CURRENT_THEME.text_hint
        draw_list:AddText(imgui.ImVec2(radar_btn_x + (radar_btn_sz - r_sz.x)/2, radar_btn_y + (radar_btn_sz - r_sz.y)/2), imgui.ColorConvertFloat4ToU32(r_col), radar_icon)
        imgui.PopFont()
    end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(start_x, start_y + h + S(6)))
end

function renderShopDetailsView()
    local shop = MarketData.selected_shop
    local total_w = imgui.GetContentRegionAvail().x
    
    local padding_x = S(15)
    local content_w = total_w - (padding_x * 2)

    if not MarketData.details_tab then MarketData.details_tab = 1 end

    local function setIndent() imgui.SetCursorPosX(padding_x) end

    if not shop then
        setIndent()
        imgui.TextColored(CURRENT_THEME.text_hint, u8"Данные отсутствуют.")
        setIndent()
        if imgui.Button(u8"Вернуться", imgui.ImVec2(S(120), S(35))) then
            MarketData.selected_shop = nil
        end
        return
    end

    imgui.Dummy(imgui.ImVec2(0, S(10))) -- Отступ от верха
    setIndent()
    
    local p = imgui.GetCursorScreenPos()
    local card_h = S(75)
    local draw_list = imgui.GetWindowDrawList()
    
    -- === 1. ФОН КАРТОЧКИ ШАПКИ (Адаптивный стиль) ===
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + content_w, p.y + card_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
    draw_list:AddRect(p, imgui.ImVec2(p.x + content_w, p.y + card_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8))
    
    -- === 2. КНОПКА НАЗАД ===
    local btn_sz = S(40)
    local back_x = p.x + S(15)
    local center_y = p.y + (card_h - btn_sz) / 2
    
    imgui.SetCursorScreenPos(imgui.ImVec2(back_x, center_y))
    if imgui.InvisibleButton("##btn_back_market", imgui.ImVec2(btn_sz, btn_sz)) then
        MarketData.selected_shop = nil
    end
    
    local back_hov = imgui.IsItemHovered()
    local back_bg = back_hov and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary)
    draw_list:AddRectFilled(imgui.ImVec2(back_x, center_y), imgui.ImVec2(back_x + btn_sz, center_y + btn_sz), back_bg, S(8))
    
    if font_fa then
        imgui.PushFont(font_fa)
        local icon_back = fa('arrow_left')
        local isz = GetStaticTextSize(icon_back)
        local icon_col = back_hov and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary
        draw_list:AddText(imgui.ImVec2(back_x + (btn_sz - isz.x)/2, center_y + (btn_sz - isz.y)/2), imgui.ColorConvertFloat4ToU32(icon_col), icon_back)
        imgui.PopFont()
    end
    
    -- === 3. АВАТАР ПРОДАВЦА ===
    local ava_sz = S(46)
    local ava_x = back_x + btn_sz + S(15)
    local ava_y = p.y + (card_h - ava_sz) / 2
    
    draw_list:AddRectFilled(imgui.ImVec2(ava_x, ava_y), imgui.ImVec2(ava_x + ava_sz, ava_y + ava_sz), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8))
    draw_list:AddRect(imgui.ImVec2(ava_x, ava_y), imgui.ImVec2(ava_x + ava_sz, ava_y + ava_sz), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8), 15, S(1))
    
    local first_letter = shop.nickname and shop.nickname:sub(1,1):upper() or "?"
    imgui.PushFont(font_default)
    imgui.SetWindowFontScale(1.3)
    local l_sz = GetStaticTextSize(first_letter)
    draw_list:AddText(imgui.ImVec2(ava_x + (ava_sz - l_sz.x)/2, ava_y + (ava_sz - l_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), first_letter)
    imgui.SetWindowFontScale(1.0)
    imgui.PopFont()
    
    -- === 4. ТЕКСТОВАЯ ИНФОРМАЦИЯ ===
    local text_x = ava_x + ava_sz + S(15)
    draw_list:AddText(imgui.ImVec2(text_x, p.y + S(16)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8(shop.nickname))
    
    if font_fa then
        imgui.PushFont(font_fa)
        local srv_icon = fa('server')
        local srv_isz = GetStaticTextSize(srv_icon)
        draw_list:AddText(imgui.ImVec2(text_x, p.y + S(40)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), srv_icon)
        imgui.PopFont()
        text_x = text_x + srv_isz.x + S(6)
    end
    
    local server_name = getServerDisplayName(shop.serverId)
    draw_list:AddText(imgui.ImVec2(text_x, p.y + S(39)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), u8(server_name))

    -- === 5. КНОПКА GPS (Плоский дизайн) ===
    local ip, port = sampGetCurrentServerAddress()
    local is_same_server = (normalizeServerId(ip .. ":" .. port) == normalizeServerId(shop.serverId))
    local can_click_gps = is_same_server and (shop.nickname and shop.nickname ~= "")
    
    local gps_w = S(150)
    local gps_x = p.x + content_w - gps_w - S(15)
    
    imgui.SetCursorScreenPos(imgui.ImVec2(gps_x, center_y))
    
    -- Плоские цвета для GPS (Адаптивные)
    local gps_bg = CURRENT_THEME.bg_tertiary
    local gps_txt_col = CURRENT_THEME.text_primary
    local gps_icon = fa('location_crosshairs')
    local gps_txt = u8"Найти лавку"
    
    if not can_click_gps then
        gps_bg = CURRENT_THEME.bg_main
        gps_txt_col = CURRENT_THEME.text_hint
        gps_icon = fa('location_dot')
        gps_txt = u8"Другой сервер"
    elseif GPSFinder.active then
        gps_bg = CURRENT_THEME.bg_main
        gps_icon = fa('spinner')
        gps_txt = u8"Поиск..."
    end
    
    if imgui.InvisibleButton("##gps_btn_modern", imgui.ImVec2(gps_w, btn_sz)) then
        if can_click_gps and not GPSFinder.active then
            GPSFinder.active = true
            GPSFinder.target_nick = shop.nickname:gsub(" ", "_")
            GPSFinder.waiting_for_id = true
            sampSendChat("/id " .. GPSFinder.target_nick)
            addToastNotification("Поиск ID игрока " .. GPSFinder.target_nick .. "...", "info", 2.0)
        end
    end
    
    if imgui.IsItemHovered() and can_click_gps and not GPSFinder.active then
        gps_bg = CURRENT_THEME.bg_main
    end
    
    draw_list:AddRectFilled(imgui.ImVec2(gps_x, center_y), imgui.ImVec2(gps_x + gps_w, center_y + btn_sz), imgui.ColorConvertFloat4ToU32(gps_bg), S(8))
    
    local i_w = 0
    if font_fa then 
        imgui.PushFont(font_fa)
        i_w = GetStaticTextSize(gps_icon).x + S(6)
        imgui.PopFont()
    end
    local t_w = GetStaticTextSize(gps_txt).x
    local content_start = gps_x + (gps_w - (i_w + t_w)) / 2
    
    if font_fa then
        imgui.PushFont(font_fa)
        draw_list:AddText(imgui.ImVec2(content_start, center_y + (btn_sz - GetStaticTextSize(gps_icon).y)/2), imgui.ColorConvertFloat4ToU32(gps_txt_col), gps_icon)
        imgui.PopFont()
    end
    draw_list:AddText(imgui.ImVec2(content_start + i_w, center_y + (btn_sz - GetStaticTextSize(gps_txt).y)/2), imgui.ColorConvertFloat4ToU32(gps_txt_col), gps_txt)
    
    -- === ВЛАДКИ ПРОДАЖА/СКУПКА ===
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + card_h + S(15)))
    setIndent()
    local tab_w = content_w / 2
    local tab_h = S(35)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(0, 0))
    
    local function drawTabBtn(id, name, icon, count)
        local is_act = MarketData.details_tab == id
        local bg_color = is_act and CURRENT_THEME.bg_tertiary or imgui.ImVec4(0, 0, 0, 0)
        local text_color = is_act and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary
        
        imgui.PushStyleColor(imgui.Col.Button, bg_color)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, CURRENT_THEME.bg_tertiary)
        imgui.PushStyleColor(imgui.Col.ButtonActive, CURRENT_THEME.bg_main)
        imgui.PushStyleColor(imgui.Col.Text, text_color)
        
        local label = string.format("%s %s (%d)", icon, name, count)
        if imgui.Button(label, imgui.ImVec2(tab_w, tab_h)) then MarketData.details_tab = id end
        
        imgui.PopStyleColor(4)
    end
    
    drawTabBtn(1, u8"ПРОДАЖА", fa('arrow_up_from_bracket'), #shop.sell_list)
    imgui.SameLine()
    drawTabBtn(2, u8"СКУПКА", fa('arrow_down_to_bracket'), #shop.buy_list)
    
    imgui.PopStyleVar()
    
    imgui.Dummy(imgui.ImVec2(0, S(5)))
    setIndent()
    
    -- ========================================================
    -- [INNOVATION] GRID РЕНДЕР ТОВАРОВ ЛАВКИ
    -- ========================================================
    local list_h = imgui.GetContentRegionAvail().y - S(5)
    
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    renderSmoothScrollBox("DetailsListScroll", imgui.ImVec2(content_w, list_h), function()
        
        local list = (MarketData.details_tab == 1) and shop.sell_list or shop.buy_list
        local is_sell = (MarketData.details_tab == 1)
        
        if #list == 0 then
            imgui.Dummy(imgui.ImVec2(0, S(60)))
            local txt = u8"Витрина пуста"
            local tw = GetStaticTextSize(txt).x
            imgui.SetCursorPosX((content_w - tw) / 2)
            imgui.TextColored(CURRENT_THEME.text_hint, txt)
        else
            -- Математика сетки (AAA Layout - Широкие карточки)
            local spacing_x = S(12)
            local spacing_y = S(12)
            local min_card_w = S(320) -- Увеличиваем минимальную ширину в 2+ раза
            
            local columns = math.floor((content_w + spacing_x) / (min_card_w + spacing_x))
            if columns < 1 then columns = 1 end
            if columns > 2 then columns = 2 end -- Ограничиваем макс 2 колонками для красоты
            
            local card_w = math.floor((content_w - spacing_x * (columns - 1)) / columns)
            local card_h = S(110) -- Уменьшаем высоту, делаем карточку прямоугольной
            
            local total_rows = math.ceil(#list / columns)
            local row_h = card_h + spacing_y
            
            local current_scroll = imgui.GetScrollY()
            local visible_height = imgui.GetWindowHeight()
            local start_row = math.floor(current_scroll / row_h)
            local end_row = start_row + math.ceil(visible_height / row_h) + 1
            
            start_row = math.max(0, start_row)
            end_row = math.min(total_rows - 1, end_row)

            imgui.Dummy(imgui.ImVec2(0, S(5)))
            local start_y_local = imgui.GetCursorPosY() + (start_row * row_h)
            
            -- [FIX STAIRCASE] Жестко задаем позицию каждой карточки в сетке (Grid)
            -- Это 100% исключает баг с "лесенкой", так как мы не используем SameLine()
            for row = start_row, end_row do
                for col = 0, columns - 1 do
                    local idx = row * columns + col + 1
                    if idx <= #list then
                        local item = list[idx]
                        
                        -- Вычисляем точные координаты для карточки
                        local target_x = col * (card_w + spacing_x)
                        local target_y = start_y_local + (row - start_row) * row_h
                        
                        -- Принудительно устанавливаем курсор
                        imgui.SetCursorPos(imgui.ImVec2(target_x, target_y))
                        
                        -- Вызов отрисовки карточки
                        renderModernShopItemGridCard(item, is_sell, card_w, card_h, idx)
                    end
                end
            end
            
            -- Сдвигаем курсор в самый низ для корректной работы скроллбара
            local rendered_rows = (end_row - start_row + 1)
            imgui.SetCursorPosY(start_y_local + rendered_rows * row_h)
            
            local remaining_rows = total_rows - 1 - end_row
            if remaining_rows > 0 then
                imgui.SetCursorPosY(imgui.GetCursorPosY() + (remaining_rows * row_h))
            end
            
            imgui.Dummy(imgui.ImVec2(0, S(10)))
        end
        
    end)
    imgui.PopStyleColor()
end

function searchItemsInShops(search_query)
    local search_q = to_lower(search_query)
    local results_sell = {}
    local results_buy = {}
    
    if search_q == "" then return {}, {} end
    
    local selected_server_name = nil
    if server_filter_idx > 0 and server_name_list[server_filter_idx + 1] then
        selected_server_name = server_name_list[server_filter_idx + 1]
    end
    
    for _, shop in ipairs(MarketData.shops_list) do
        local pass_server = true
        if selected_server_name then
            local shop_server_name = getServerDisplayName(shop.serverId)
            if shop_server_name ~= selected_server_name then pass_server = false end
        end

        if pass_server then
            if shop.sell_list then
                for _, item in ipairs(shop.sell_list) do
                    local i_name = item.name or ""
                    local clean_name = enhancedCleanItemName(i_name)
                    local score = SmartSearch.getMatchScore(search_q, clean_name)
                    if score > 0 then
                        table.insert(results_sell, {
                            item_name = clean_name, 
                            _u8_item_name = u8(clean_name),
                            original_name = i_name, price = item.price, amount = item.amount,
                            model_id = item.model_id,
                            shop_nickname = shop.nickname, server_id = shop.serverId, server_name = getServerDisplayName(shop.serverId),
                            _u8_shop_info = u8(shop.nickname .. " | " .. getServerDisplayName(shop.serverId)),
                            _u8_amount_str = u8("В наличии: " .. formatNumber(item.amount or 0)),
                            is_sell = true, vip = shop.vip, is_passive = shop.is_passive, score = score 
                        })
                    end
                end
            end
            if shop.buy_list then
                for _, item in ipairs(shop.buy_list) do
                    local i_name = item.name or ""
                    local clean_name = enhancedCleanItemName(i_name)
                    local score = SmartSearch.getMatchScore(search_q, clean_name)
                    if score > 0 then
                        table.insert(results_buy, {
                            item_name = clean_name, 
                            _u8_item_name = u8(clean_name),
                            original_name = i_name, price = item.price, amount = item.amount,
                            model_id = item.model_id,
                            shop_nickname = shop.nickname, server_id = shop.serverId, server_name = getServerDisplayName(shop.serverId),
                            _u8_shop_info = u8(shop.nickname .. " | " .. getServerDisplayName(shop.serverId)),
                            _u8_amount_str = u8("В наличии: " .. formatNumber(item.amount or 0)),
                            is_sell = false, vip = shop.vip, is_passive = shop.is_passive, score = score 
                        })
                    end
                end
            end
        end
    end
    
    table.sort(results_sell, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return (a.price or 0) < (b.price or 0)
    end)
    table.sort(results_buy, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return (a.price or 0) > (b.price or 0)
    end)
    
    return results_sell, results_buy
end

function runAsyncShopSearch(query)
    if MarketData.is_searching_process then return end
    
    lua_thread.create(function()
        MarketData.is_searching_process = true
        
        local search_q = to_lower(query)
        local results_sell = {}
        local results_buy = {}
        
        local selected_server_name = nil
        if server_filter_idx > 0 and server_name_list[server_filter_idx + 1] then
            selected_server_name = server_name_list[server_filter_idx + 1]
        end
        
        local processed = 0
        
        for _, shop in ipairs(MarketData.shops_list) do
            if MarketData.pending_search_query ~= query then
                MarketData.is_searching_process = false
                return 
            end

            local pass_server = true
            if selected_server_name then
                local shop_server_name = getServerDisplayName(shop.serverId)
                if shop_server_name ~= selected_server_name then pass_server = false end
            end

            if pass_server then
                local nick_score = SmartSearch.getMatchScore(search_q, shop.nickname)
                local is_nick_search = (nick_score > 75)

                if shop.sell_list then
                    for _, item in ipairs(shop.sell_list) do
                        local i_name = item.name or ""
                        local clean_name = enhancedCleanItemName(i_name)
                        
                        local score = 0
                        if is_nick_search then
                            score = nick_score
                        else
                            score = SmartSearch.getMatchScore(search_q, clean_name)
                        end
                        
                        if score > 0 then
                            table.insert(results_sell, {
                                item_name = clean_name, 
                                _u8_item_name = u8(clean_name),
                                original_name = i_name,
                                price = item.price,
                                amount = item.amount,
                                model_id = item.model_id,
                                shop_nickname = shop.nickname,
                                server_id = shop.serverId,
                                server_name = getServerDisplayName(shop.serverId),
                                _u8_shop_info = u8(shop.nickname .. " | " .. getServerDisplayName(shop.serverId)),
                                _u8_amount_str = u8("В наличии: " .. formatNumber(item.amount or 0)),
                                is_sell = true,
                                vip = shop.vip,
                                is_passive = shop.is_passive, 
                                score = score 
                            })
                        end
                    end
                end
                
                if shop.buy_list then
                    for _, item in ipairs(shop.buy_list) do
                        local i_name = item.name or ""
                        local clean_name = enhancedCleanItemName(i_name)
                        
                        local score = 0
                        if is_nick_search then
                            score = nick_score
                        else
                            score = SmartSearch.getMatchScore(search_q, clean_name)
                        end
                        
                        if score > 0 then
                            table.insert(results_buy, {
                                item_name = clean_name, 
                                _u8_item_name = u8(clean_name),
                                original_name = i_name,
                                price = item.price,
                                amount = item.amount,
                                model_id = item.model_id,
                                shop_nickname = shop.nickname,
                                server_id = shop.serverId,
                                server_name = getServerDisplayName(shop.serverId),
                                _u8_shop_info = u8(shop.nickname .. " | " .. getServerDisplayName(shop.serverId)),
                                _u8_amount_str = u8("В наличии: " .. formatNumber(item.amount or 0)),
                                is_sell = false,
                                vip = shop.vip,
                                is_passive = shop.is_passive,
                                score = score 
                            })
                        end
                    end
                end
            end
            
            processed = processed + 1
            if processed % 50 == 0 then wait(0) end
        end
        
        local function getUserWeight(res)
            if res.vip then return 3 end
            if res.is_passive then return 1 end
            return 2
        end
        
        local function sortResults(a, b, ascendingPriceDefault)
            if MarketData.sort_mode == 1 then
                if a.price ~= b.price then return (a.price or 0) < (b.price or 0) end
            elseif MarketData.sort_mode == 2 then
                if a.price ~= b.price then return (a.price or 0) > (b.price or 0) end
            elseif MarketData.sort_mode == 3 then
                if a.amount ~= b.amount then return (a.amount or 0) > (b.amount or 0) end
            else
                if a.score ~= b.score then return a.score > b.score end
                
                local wA, wB = getUserWeight(a), getUserWeight(b)
                if wA ~= wB then return wA > wB end
                
                if ascendingPriceDefault then
                    return (a.price or 0) < (b.price or 0) 
                else
                    return (a.price or 0) > (b.price or 0) 
                end
            end
            
            return false
        end
        
        table.sort(results_sell, function(a, b) return sortResults(a, b, true) end)
        table.sort(results_buy, function(a, b) return sortResults(a, b, false) end)
        
        MarketData.cached_sell_results = results_sell
        MarketData.cached_buy_results = results_buy
        MarketData.last_executed_search = query
        MarketData.is_searching_process = false
    end)
end

function renderShopCardGrid(shop, width)
    if not shop then return end
    local height = S(85)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()

    local is_vip = shop.vip
    local is_passive = shop.is_passive

    -- 1. ЛОГИКА КЛИКА
    local btn_id = "##scard_" .. tostring(shop.nickname) .. "_" .. tostring(shop.serverId)
    
    imgui.SetCursorScreenPos(p)
    if imgui.InvisibleButton(btn_id, imgui.ImVec2(width, height)) then
        api_FetchShopDetails(shop.serverId, shop.nickname)
    end
    local is_hovered = imgui.IsItemHovered()

    -- 2. ФОН И РАМКА
    local bg_col = is_hovered and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary)
    local border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light)

    if is_vip then
        bg_col = imgui.ColorConvertFloat4ToU32(is_hovered and imgui.ImVec4(0.18, 0.16, 0.10, 1.0) or imgui.ImVec4(0.15, 0.12, 0.05, 1.0))
        border_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.85, 0.70, 0.20, 1.0))
    elseif is_hovered then
        border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
    end

    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), bg_col, S(8))
    draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), border_col, S(8), 15, is_hovered and S(2) or S(1))

    -- 3. СТРОКА 1: [Корона] Имя (Строго по центру, БЕЗ кружка с буквой)
    local nick_str = shop._c_nick_u8 or u8(shop.nickname or "Unknown")

    imgui.PushFont(font_default)
    local nick_sz = GetStaticTextSize(nick_str)
    imgui.PopFont()

    local spacing = S(6)
    local crown_w = 0
    if is_vip and font_fa then
        imgui.PushFont(font_fa)
        crown_w = GetStaticTextSize(fa('crown')).x + spacing
        imgui.PopFont()
    end

    -- Считаем общую ширину для центрирования (только корона и ник)
    local total_line1_w = crown_w + nick_sz.x
    local line1_x = p.x + (width - total_line1_w) / 2
    local line1_y = p.y + S(12)

    local current_x = line1_x

    -- Рисуем корону (если VIP)
    if is_vip and font_fa then
        imgui.PushFont(font_fa)
        local crown_sz = GetStaticTextSize(fa('crown'))
        draw_list:AddText(imgui.ImVec2(current_x, line1_y + (nick_sz.y - crown_sz.y)/2), 0xFF40C0FF, fa('crown')) -- ABGR Gold
        imgui.PopFont()
        current_x = current_x + crown_w
    end

    -- Рисуем никнейм
    imgui.PushFont(font_default)
    draw_list:AddText(imgui.ImVec2(current_x, line1_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), nick_str)
    imgui.PopFont()

    -- 4. СТРОКА 2: Иконка сервера + Название (Строго по центру)
    local srv_str = shop._c_srv_u8 or u8(getServerDisplayName(shop.serverId))
    local srv_y = line1_y + nick_sz.y + S(6)

    imgui.PushFont(font_default)
    imgui.SetWindowFontScale(0.85)
    local srv_txt_sz = GetStaticTextSize(srv_str)
    local srv_icon_w = 0
    if font_fa then
        imgui.PushFont(font_fa)
        srv_icon_w = GetStaticTextSize(fa('server')).x + S(6)
        imgui.PopFont()
    end

    local total_line2_w = srv_icon_w + srv_txt_sz.x
    local line2_x = p.x + (width - total_line2_w) / 2

    if font_fa then
        imgui.PushFont(font_fa)
        local ic_sz = GetStaticTextSize(fa('server'))
        draw_list:AddText(imgui.ImVec2(line2_x, srv_y + (srv_txt_sz.y - ic_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), fa('server'))
        imgui.PopFont()
    end
    
    draw_list:AddText(imgui.ImVec2(line2_x + srv_icon_w, srv_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), srv_str)
    imgui.SetWindowFontScale(1.0)
    imgui.PopFont()

    -- 5. СТРОКА 3: Статистика (Строго по центру снизу)
    local stat_y = p.y + height - S(25)
    
    -- [FPS BOOST] Кэшируем вычисление статистики прямо в объекте лавки
    if not shop._c_stat_str then
        local sell_c = tonumber(shop.sell_count) or 0
        local buy_c = tonumber(shop.buy_count) or 0
        local stat_str = ""
        if sell_c > 0 and buy_c > 0 then
            stat_str = string.format("Продажа: %d | Скупка: %d", sell_c, buy_c)
        elseif sell_c > 0 then
            stat_str = string.format("В продаже: %d", sell_c)
        elseif buy_c > 0 then
            stat_str = string.format("В скупке: %d", buy_c)
        else
            stat_str = "Пустая лавка"
        end
        shop._c_stat_str = u8(stat_str)
    end

    imgui.PushFont(font_default)
    imgui.SetWindowFontScale(0.85)
    local stat_sz = imgui.CalcTextSize(shop._c_stat_str)
    draw_list:AddText(SetVec(REN_VEC_1, p.x + (width - stat_sz.x)/2, stat_y), CURRENT_THEME.text_secondary_u32, shop._c_stat_str)
    imgui.SetWindowFontScale(1.0)
    imgui.PopFont()

    -- 6. ИКОНКА "ПАССИВНАЯ" (Справа сверху)
    if is_passive and font_fa then
        imgui.PushFont(font_fa)
        local warn = fa('triangle_exclamation')
        local w_sz = GetStaticTextSize(warn)
        local warn_x = p.x + width - w_sz.x - S(10)
        local warn_y = p.y + S(10)
        draw_list:AddText(imgui.ImVec2(warn_x, warn_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), warn)
        imgui.PopFont()

        if is_hovered and imgui.IsMouseHoveringRect(imgui.ImVec2(warn_x, warn_y), imgui.ImVec2(warn_x + w_sz.x, warn_y + w_sz.y)) then
            imgui.SetTooltip(u8"Игрок не использует RMarket.\nДанные могут быть устаревшими.")
        end
    end

    if is_hovered and not is_passive then
        imgui.SetTooltip(u8("Открыть лавку игрока " .. shop.nickname))
    end
end

function renderShopsListView()
    local full_w = imgui.GetContentRegionAvail().x
    local full_h = imgui.GetContentRegionAvail().y
    
    local search_raw = ffi.string(MarketData.search_buffer)
    local search_q = (search_raw ~= "") and safe_decode(search_raw) or ""
    local is_search_mode = (search_q ~= "")
    
    if not is_search_mode then MarketData.last_executed_search = "" end
    
    local ip, port = sampGetCurrentServerAddress()
    local current_server_id = normalizeServerId(ip .. ":" .. port)
    local current_server_name = getServerDisplayName(current_server_id)

    -- Состояния загрузки / Пустоты
    if MarketData.is_loading then
        imgui.SetCursorPosY(full_h / 2 - S(20))
        centerText(u8"Загрузка рынка...")
        return
    end

    if #MarketData.shops_list == 0 and not PassiveChecker.active then
         imgui.SetCursorPosY(full_h / 2 - S(20))
         centerText(u8"Нет данных для сервера " .. current_server_name .. ".")
         return
    elseif #MarketData.shops_list == 0 and PassiveChecker.active then
         imgui.SetCursorPosY(full_h / 2 - S(20))
         centerText(u8"Поиск активных лавок...")
         return
    end

    -- РЕЖИМ ПОИСКА ПО ТОВАРАМ (Оставлен без изменений, так как он использует свой отдельный рендер)
    if is_search_mode then
        -- (Оригинальная логика поиска остается здесь)
        local current_time = os.clock()
        if search_q ~= MarketData.pending_search_query then
            MarketData.pending_search_query = search_q
            MarketData.search_debounce_timer = current_time + 0.5 
            MarketData.cached_sell_results = {}
            MarketData.cached_buy_results = {}
        end
        if current_time > MarketData.search_debounce_timer 
           and search_q ~= MarketData.last_executed_search 
           and not MarketData.is_searching_process then
            runAsyncShopSearch(search_q)
        end

        local is_processing_visual = MarketData.is_searching_process or (search_q ~= MarketData.last_executed_search)
        imgui.Dummy(imgui.ImVec2(0, S(5)))
        
        local found_sell = MarketData.cached_sell_results
        local found_buy = MarketData.cached_buy_results
        local has_results = (#found_sell > 0) or (#found_buy > 0)

        if is_processing_visual and not has_results then
            imgui.SetCursorPosY(full_h / 2 - S(10))
            centerText(u8"Поиск...")
        elseif not has_results then
            imgui.SetCursorPosY(full_h / 2 - S(10))
            centerText(u8"Товары не найдены")
        else
            -- Логика рендера 2х колонок поиска
            local spacing = S(10)
            local col_width = (full_w - spacing) / 2
            local list_h = imgui.GetContentRegionAvail().y - S(5)

            local function RenderVirtualResultList(str_id, list, width, height, start_id_offset)
                imgui.BeginChild(str_id, imgui.ImVec2(width, height), false)
                if #list == 0 then
                    imgui.TextColored(CURRENT_THEME.text_hint, u8" Нет предложений")
                else
                    local item_h_real = S(65) + S(6)
                    local total_items = #list
                    local clipper = imgui.ImGuiListClipper(total_items)
                    while clipper:Step() do
                        for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
                            local result = list[i]
                            if result then renderMarketSearchResultCard(result, width, i + start_id_offset) end
                        end
                    end
                end
                imgui.EndChild()
            end

            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
            imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
            
            imgui.BeginChild("SearchColSell", imgui.ImVec2(col_width, list_h), false, imgui.WindowFlags.NoScrollbar)
                renderUnifiedHeader(u8"Продают (" .. #found_sell .. ")", fa('arrow_up_from_bracket'))
                RenderVirtualResultList("SearchListSell", found_sell, col_width, imgui.GetContentRegionAvail().y, 0)
            imgui.EndChild()
            
            imgui.SameLine()
            imgui.SetCursorPosX(col_width + spacing)
            
            imgui.BeginChild("SearchColBuy", imgui.ImVec2(col_width, list_h), false, imgui.WindowFlags.NoScrollbar)
                renderUnifiedHeader(u8"Скупают (" .. #found_buy .. ")", fa('arrow_down_to_bracket'))
                RenderVirtualResultList("SearchListBuy", found_buy, col_width, imgui.GetContentRegionAvail().y, 10000)
            imgui.EndChild()
            
            imgui.PopStyleColor()
            imgui.PopStyleVar()
        end
    else
        -- ====================================================================
        -- ОБЫЧНЫЙ РЕЖИМ (СЕТКА ЛАВОК) - ИСПОЛЬЗУЕМ СИСТЕМУ imgui.BeginTable
        -- ====================================================================
        renderSmoothScrollBox("MarketListScroll", imgui.ImVec2(full_w, 0), function()
            
            if not MarketData.ui_cache then 
                MarketData.ui_cache = { list = {}, server_idx = -1, last_count = -1 } 
            end
            
            local safe_server_idx = type(server_filter_idx) == "number" and server_filter_idx or 0
            local current_shop_count = #MarketData.shops_list
            
            -- Выполняем фильтрацию и предкэширование строк ТОЛЬКО при изменениях
            if MarketData.ui_cache.server_idx ~= safe_server_idx or MarketData.ui_cache.last_count ~= current_shop_count then
                local filtered_shops = {}
                local selected_server_name = (safe_server_idx > 0) and server_name_list[safe_server_idx + 1] or nil
                
                for _, shop in ipairs(MarketData.shops_list) do
                    if not selected_server_name or getServerDisplayName(shop.serverId) == selected_server_name then
                        -- [FPS BOOST] Готовим строки для C-рендера 1 раз!
                        if not shop._c_nick_u8 then
                            local n = shop.nickname or "Unknown"
                            -- Убрано искусственное ограничение длины ника, 
                            -- теперь длинные имена занимают всю ширину карточки
                            shop._c_nick_u8 = u8(n)
                            shop._c_srv_u8 = u8(getServerDisplayName(shop.serverId))
                        end
                        table.insert(filtered_shops, shop)
                    end
                end
                
                table.sort(filtered_shops, function(a, b)
                    local function getShopWeight(s)
                        if not s then return 1 end
                        if s.is_passive then return 0 end
                        if s.vip then return 2 end
                        return 1
                    end
                    local wA, wB = getShopWeight(a), getShopWeight(b)
                    if wA ~= wB then return wA > wB end
                    local countA = (tonumber(a.sell_count) or 0) + (tonumber(a.buy_count) or 0)
                    local countB = (tonumber(b.sell_count) or 0) + (tonumber(b.buy_count) or 0)
                    return countA > countB
                end)
                
                MarketData.ui_cache.list = filtered_shops
                MarketData.ui_cache.server_idx = safe_server_idx
                MarketData.ui_cache.last_count = current_shop_count
            end
            
            local filtered_shops = MarketData.ui_cache.list
            
            if #filtered_shops == 0 then
                imgui.Dummy(imgui.ImVec2(0, S(20)))
                centerText(u8"На выбранном сервере нет активных лавок")
            else
                -- [FIX] Информационный текст перенесен в Header
                -- Делаем аккуратный отступ сверху перед началом сетки
                imgui.Dummy(imgui.ImVec2(0, S(8)))
                
                -- Высчитываем 3 колонки и боковые отступы (Padding)
                local padding_sides = S(16) -- Свободное место слева и справа
                local spacing_x = S(12)     -- Отступ между карточками по горизонтали
                local spacing_y = S(12)     -- Отступ между карточками по вертикали
                local columns = 3           -- Строго 3 колонки (решает проблему обрезки имен)
                
                -- Рабочая ширина (без учета боковых отступов)
                local usable_w = full_w - (padding_sides * 2)
                
                -- Высчитываем размер одной карточки
                local card_w = math.floor((usable_w - spacing_x * (columns - 1)) / columns)
                local card_h = S(85) -- Оставляем высоту фиксированной
                
                -- Ручная высокопроизводительная сетка (Clipper)
                local row_h = card_h + spacing_y
                local total_rows = math.ceil(#filtered_shops / columns)
                
                local current_scroll = imgui.GetScrollY()
                local visible_height = imgui.GetWindowHeight()
                local start_row = math.floor(current_scroll / row_h)
                local end_row = start_row + math.ceil(visible_height / row_h) + 1
                
                start_row = math.max(0, start_row)
                end_row = math.min(total_rows - 1, end_row)

                -- ВАЖНО: Добавляем боковой отступ (padding_sides) к начальной позиции X
                local start_x_local = imgui.GetCursorPosX() + padding_sides
                local start_y_local = imgui.GetCursorPosY()
                
                for row = start_row, end_row do
                    for col = 0, columns - 1 do
                        local idx = row * columns + col + 1
                        if idx <= #filtered_shops then
                            local target_x = start_x_local + col * (card_w + spacing_x)
                            local target_y = start_y_local + (row * row_h)
                            
                            imgui.SetCursorPos(imgui.ImVec2(target_x, target_y))
                            renderShopCardGrid(filtered_shops[idx], card_w)
                        end
                    end
                end
                
                -- Выставляем финальную высоту для скроллбара
                imgui.SetCursorPosY(start_y_local + (total_rows * row_h))
                imgui.Dummy(imgui.ImVec2(0, S(20)))
            end
        end)
    end
end

function renderMarketSearchResultCard(result, width, index)
    local draw_list = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local height = S(65)
    
    local type_color = result.is_sell and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary
    local icon_char = result.is_sell and fa('box') or fa('bag_shopping')
    
    local is_me = (result.shop_nickname == getSafeLocalNickname())
    local is_vip = result.vip
    if is_me and Data.is_vip then is_vip = true end
    local is_passive = result.is_passive

    -- Фон
    local col_bg_base = CURRENT_THEME.bg_secondary
    
    if is_vip then
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.12, 0.12, 0.14, 1.0)), S(8))
        local gold_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
        draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), gold_col, S(8), 15, S(1.5))
    else
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(col_bg_base), S(8))
        local border_col = is_passive and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.05)) or 0
        if border_col ~= 0 then
            draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), border_col, S(8))
        end
    end
    
    local bar_col_u32 = is_vip and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary) or imgui.ColorConvertFloat4ToU32(type_color)
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + S(4), p.y + height), bar_col_u32, S(8), 9)
    
    local icon_size = S(38)
    local icon_x = p.x + S(16)
    local icon_y = p.y + (height - icon_size) / 2
    
    draw_list:AddCircleFilled(imgui.ImVec2(icon_x + icon_size/2, icon_y + icon_size/2), 
        icon_size/2, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary))
    
    if font_fa then
        imgui.PushFont(font_fa)
        local txt_sz = GetStaticTextSize(icon_char)
        local ico_col = is_vip and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
        draw_list:AddText(imgui.ImVec2(icon_x + (icon_size - txt_sz.x)/2, icon_y + (icon_size - txt_sz.y)/2), 
            ico_col, icon_char)
        imgui.PopFont()
    end
    
    local info_x = icon_x + icon_size + S(12)
    local right_margin = S(12)
    
    local price_str = formatMoney(result.price or 0) .. u8" $"
    imgui.PushFont(font_default)
    local price_sz = GetStaticTextSize(price_str)
    imgui.PopFont()
    
    local price_x = p.x + width - price_sz.x - right_margin
    local price_y = p.y + (height/2) - price_sz.y
    
    local line1_y = p.y + S(10)
    imgui.PushFont(font_default)
    
    local text_col = CURRENT_THEME.text_primary
    local max_name_w = price_x - info_x - S(20) 
    
    imgui.PushClipRect(imgui.ImVec2(info_x, line1_y), imgui.ImVec2(info_x + max_name_w, line1_y + S(20)), true)
    draw_list:AddText(imgui.ImVec2(info_x, line1_y), imgui.ColorConvertFloat4ToU32(text_col), u8(result.item_name))
    imgui.PopClipRect()
    imgui.PopFont()
    
    local line2_y = p.y + S(28)
    local shop_info = string.format("%s | %s", result.shop_nickname, result.server_name)
    local shop_info_col = is_vip and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
    
    draw_list:AddText(imgui.ImVec2(info_x, line2_y), shop_info_col, u8(shop_info))
    
    if is_passive then
        local shop_info_sz = GetStaticTextSize(u8(shop_info))
        if font_fa then
            imgui.PushFont(font_fa)
            local warn_icon = fa('triangle_exclamation')
            local w_sz = GetStaticTextSize(warn_icon)
            local warn_pos = imgui.ImVec2(info_x + shop_info_sz.x + S(8), line2_y)
            draw_list:AddText(warn_pos, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), warn_icon)
            if imgui.IsMouseHoveringRect(warn_pos, imgui.ImVec2(warn_pos.x + w_sz.x, warn_pos.y + w_sz.y)) then
                imgui.BeginTooltip()
                imgui.TextColored(CURRENT_THEME.accent_warning, u8"Внимание!")
                imgui.Text(u8"Игрок не использует RMarket.")
                imgui.TextDisabled(u8"Данные могут быть устаревшими (до 5 мин).")
                imgui.EndTooltip()
            end
            imgui.PopFont()
        end
    end
    
    local line3_y = p.y + S(44)
    local amount_str = "В наличии: " .. formatNumber(result.amount or 0)
    draw_list:AddText(imgui.ImVec2(info_x, line3_y), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), u8(amount_str))
    
    imgui.PushFont(font_default)
    draw_list:AddText(imgui.ImVec2(price_x, price_y), 
        imgui.ColorConvertFloat4ToU32(type_color), price_str)
    imgui.PopFont()
    
    local lbl_txt = u8"Цена за шт."
    local lbl_sz = GetStaticTextSize(lbl_txt)
    draw_list:AddText(imgui.ImVec2(p.x + width - lbl_sz.x - right_margin, price_y + price_sz.y + S(2)), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), lbl_txt)
    
    local unique_id = string.format("##res_%s_%s_%d", result.shop_nickname, result.item_name, index)
    imgui.SetCursorScreenPos(p)
    if imgui.InvisibleButton(unique_id, imgui.ImVec2(width, height)) then
        api_FetchShopDetails(result.server_id, result.shop_nickname)
    end
    
    if imgui.IsItemHovered() then
        draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), 
            imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.1)), S(8), 15, S(2))
        if not is_passive then
            imgui.SetTooltip(u8("Нажмите, чтобы открыть лавку игрока " .. result.shop_nickname))
        end
    end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + height + S(6)))
end

function detectCurrentServerIndex()
    local ip, port = sampGetCurrentServerAddress()
    local my_server_id = normalizeServerId(ip .. ":" .. port)
    local my_server_name = getServerDisplayName(my_server_id)
    
    for i, name in ipairs(server_name_list) do
        if name == my_server_name then
            server_filter_idx = i - 1 -- -1 так как 0 это "Все"
            return
        end
    end
end

-- ========== КАСТОМНЫЙ СЕЛЕКТОР ==========
function renderCustomSelector(items, selected_index, width, is_vip_check, selector_id)
	selector_id = selector_id or "default"
	local changed = false
	local new_selected = selected_index
	local item_height = S(50)
	
	for i, item in ipairs(items) do
		local is_selected = (selected_index == i - 1)
		local item_p = imgui.GetCursorScreenPos()
		local draw_list = imgui.GetWindowDrawList()
		
		-- Проверка VIP блокировки
		local is_vip_locked = (i == 3 and is_vip_check and not Data.is_vip)
		
		-- Фон элемента
		local bg_color = CURRENT_THEME.bg_tertiary
		if is_selected then
			bg_color = CURRENT_THEME.accent_primary
		end
		
		local hover = imgui.IsMouseHoveringRect(item_p, imgui.ImVec2(item_p.x + width, item_p.y + item_height))
		if hover and not is_vip_locked then
			bg_color = imgui.ImVec4(
				math.min(bg_color.x + 0.08, 1.0),
				math.min(bg_color.y + 0.08, 1.0),
				math.min(bg_color.z + 0.08, 1.0),
				bg_color.w
			)
		end
		
		-- Рисуем фон
		draw_list:AddRectFilled(
			item_p,
			imgui.ImVec2(item_p.x + width, item_p.y + item_height),
			imgui.ColorConvertFloat4ToU32(bg_color),
			S(6)
		)
		
		-- Граница если выбран
		if is_selected then
			draw_list:AddRect(
				item_p,
				imgui.ImVec2(item_p.x + width, item_p.y + item_height),
				imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_secondary),
				S(6),
				nil,
				S(2)
			)
		end
		
		-- Невидимая кнопка для клика
		if imgui.InvisibleButton("##selector_"..selector_id.."_item_"..i, imgui.ImVec2(width, item_height)) then
			if not is_vip_locked then
				new_selected = i - 1
				changed = true
			end
		end
		
		-- Текст элемента (рисуем после кнопки)
		local text_color = CURRENT_THEME.text_primary
		if is_selected then
			text_color = CURRENT_THEME.bg_main
		elseif is_vip_locked then
			text_color = imgui.ImVec4(0.5, 0.5, 0.5, 1.0)
		end
		
		local text_pos = imgui.ImVec2(item_p.x + S(15), item_p.y + S(14))
		draw_list:AddText(text_pos, imgui.ColorConvertFloat4ToU32(text_color), item)
		
		-- Минимальный отступ между кнопками
		imgui.Dummy(imgui.ImVec2(width, S(0)))
	end
	
	return changed, new_selected
end

-- ========== УЛУЧШЕННАЯ ВКЛАДКА НАСТРОЕК ==========
function renderEnhancedSettingsTab()
	local avail_w = imgui.GetContentRegionAvail().x
	local pad_x = S(25)
	local content_w = avail_w - (pad_x * 2)
	
	local function SetLayout()
		imgui.SetCursorPosX(pad_x)
	end
	
	local function DrawHelpIcon(text)
		imgui.SameLine()
		imgui.TextDisabled("(?)")
		if imgui.IsItemHovered() then
			imgui.SetTooltip(u8(text))
		end
	end
	
	imgui.Dummy(imgui.ImVec2(0, S(15)))
	
	-- ========== РАЗДЕЛ: НАСТРОЙКИ ЛАВКИ ==========
	SetLayout()
	imgui.TextColored(CURRENT_THEME.accent_primary, fa('store') .. u8" НАСТРОЙКИ ЛАВКИ")
	imgui.Spacing()
	
	SetLayout()
	imgui.BeginGroup()
		-- Авто-название лавки
		if renderAAAToggle("##auto_name_toggle", Buffers.settings.auto_name[0]) then
