function formatNumber(n)
    if n == nil then return "0" end
    local s = tostring(math.floor(n))
    
    local formatted = s:reverse():gsub("(...)", "%1 "):reverse()
    formatted = formatted:gsub("^%s+", "")
    return formatted
end

function renderMarketSearchResultCard(result, width, index)
    local draw_list = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local height = S(65)
    
    local type_color = result.is_sell and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary
    local icon_char = result.is_sell and fa('box') or fa('bag_shopping')
    
    local is_me = (result.shop_nickname == getSafeLocalNickname())
    local is_vip = result.vip
    if is_me and isVerifiedVip() then is_vip = true end
    local is_passive = result.is_passive

    -- === ГЛАВНАЯ НЕВИДИМАЯ КНОПКА (Для открытия лавки) ===
    -- Динамический отступ: если не VIP, кнопки скрыты, текст занимает всю ширину
    local right_btns_w = Data.is_vip and S(75) or S(5) 
    local unique_id = string.format("##res_%s_%s_%d", result.shop_nickname, result.item_name, index)
    
    imgui.SetCursorScreenPos(p)
    if imgui.InvisibleButton(unique_id, imgui.ImVec2(width - right_btns_w, height)) then
        api_FetchShopDetails(result.server_id, result.shop_nickname)
    end
    local card_hovered = imgui.IsItemHovered()
    imgui.SetItemAllowOverlap() -- Важно: разрешаем кликать кнопки поверх

    -- Фон
    local col_bg_base = CURRENT_THEME.bg_secondary
    if is_vip then
        -- Для VIP используем bg_tertiary для выделения, а не жестко закодированный цвет
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8))
        local gold_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
        draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), gold_col, S(8), 15, S(1.5))
    else
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(col_bg_base), S(8))
        local border_col = is_passive and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light) or 0
        if border_col ~= 0 then draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), border_col, S(8)) end
    end
    
    -- Цветная полоска слева (статус)
    local base_accent = is_vip and CURRENT_THEME.accent_primary or type_color
    local bar_col_u32 = imgui.ColorConvertFloat4ToU32(base_accent)
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + S(4), p.y + height), bar_col_u32, S(8), 5) 
    
    -- ААА Иконка (Аватар предмета)
    local img_box_sz = S(42)
    local img_box_x = p.x + S(14)
    local img_box_y = p.y + (height - img_box_sz) / 2
    
    local box_min = imgui.ImVec2(img_box_x, img_box_y)
    local box_max = imgui.ImVec2(img_box_x + img_box_sz, img_box_y + img_box_sz)
    local box_rounding = S(8)

    -- Адаптивный цвет слота
    local slot_bg_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main)
    draw_list:AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)
    
    local base_accent_u32 = is_vip and CURRENT_THEME.accent_primary_u32 or (result.is_sell and CURRENT_THEME.accent_success_u32 or CURRENT_THEME.accent_primary_u32)
    
    local glow_col = setAlphaU32(base_accent_u32, 0.15)
    draw_list:AddRectFilled(box_min, box_max, glow_col, box_rounding)
    draw_list:AddRect(box_min, box_max, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), box_rounding, 15, S(1.5))

    if not result._cached_model_id then
        result._cached_model_id = result.model_id or findRealIndexByName(result.item_name) or -1
    end
    
    local texture = getItemIconTexture(tonumber(result._cached_model_id))

    if texture then
        local pad = S(4)
        local uv0, uv1 = imgui.ImVec2(0, 0), imgui.ImVec2(1, 1)
        local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.8))
        
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(2)), imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(2)), uv0, uv1, shadow_col)
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad), imgui.ImVec2(box_max.x - pad, box_max.y - pad), uv0, uv1, 0xFFFFFFFF)
    else
        if font_fa then
            imgui.PushFont(font_fa)
            local p_sz = GetStaticTextSize(icon_char)
            local pulse = (math.sin(os.clock() * 4) + 1) * 0.5
            local icon_alpha = 0.2 + (pulse * 0.3)
            local ph_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(base_accent.x, base_accent.y, base_accent.z, icon_alpha))
            draw_list:AddText(imgui.ImVec2(img_box_x + (img_box_sz - p_sz.x)/2, img_box_y + (img_box_sz - p_sz.y)/2), ph_col, icon_char)
            imgui.PopFont()
        end
    end

    -- [NEW] Увеличенная иконка при наведении (Tooltip)
    imgui.SetCursorScreenPos(box_min)
    imgui.InvisibleButton("##img_hover_grid_" .. index, imgui.ImVec2(img_box_sz, img_box_sz))
    if texture and imgui.IsItemHovered() then
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(8)))
        imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.05, 0.05, 0.06, 0.98))
        imgui.PushStyleColor(imgui.Col.Border, base_accent)
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
        
        imgui.BeginTooltip()
        imgui.Image(texture, imgui.ImVec2(S(130), S(130)))
        imgui.EndTooltip()
        
        imgui.PopStyleVar(2)
        imgui.PopStyleColor(2)
    end
    
    local info_x = img_box_x + img_box_sz + S(12)
    local right_margin = S(12) + right_btns_w -- Учитываем кнопки справа
    
    -- Правая часть (Цены)
    local price_str = formatMoney(result.price or 0) .. u8" $"
    imgui.PushFont(font_default) 
    local price_sz = GetStaticTextSize(price_str)
    imgui.PopFont()
    
    local price_x = p.x + width - price_sz.x - right_margin
    local price_y = p.y + (height/2) - price_sz.y -- Чуть выше центра
    
    -- 1. Название товара
    local line1_y = p.y + S(10)
    imgui.PushFont(font_default)
    
    local text_col = CURRENT_THEME.text_primary
    local max_name_w = price_x - info_x - S(20) 
    
    imgui.PushClipRect(imgui.ImVec2(info_x, line1_y), imgui.ImVec2(info_x + max_name_w, line1_y + S(20)), true)
    -- [FPS FIX] Используем кэш строки из памяти
    draw_list:AddText(imgui.ImVec2(info_x, line1_y), imgui.ColorConvertFloat4ToU32(text_col), result._u8_item_name or u8(result.item_name))
    imgui.PopClipRect()
    imgui.PopFont()
    
    -- 2. Инфо о продавце и сервере
    local line2_y = p.y + S(28)
    local shop_info_col = is_vip and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
    
    -- [FPS FIX] Используем кэш строки
    draw_list:AddText(imgui.ImVec2(info_x, line2_y), shop_info_col, result._u8_shop_info or u8(result.shop_nickname .. " | " .. result.server_name))
    
    -- Иконка "Без скрипта"
    if is_passive then
        -- [FPS FIX] Кэшируем размер текста 
        if not result._shop_info_sz then result._shop_info_sz = GetStaticTextSize(result._u8_shop_info or u8(result.shop_nickname .. " | " .. result.server_name)) end
        if font_fa then
            imgui.PushFont(font_fa)
            local warn_icon = fa('triangle_exclamation')
            local w_sz = GetStaticTextSize(warn_icon)
            local warn_pos = imgui.ImVec2(info_x + result._shop_info_sz.x + S(8), line2_y)
            draw_list:AddText(warn_pos, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), warn_icon)
            
            if imgui.IsMouseHoveringRect(warn_pos, imgui.ImVec2(warn_pos.x + w_sz.x, warn_pos.y + w_sz.y)) then
                imgui.BeginTooltip()
                imgui.TextColored(CURRENT_THEME.accent_warning, u8"Внимание!")
                imgui.Text(u8"Игрок не использует RMarket.")
                imgui.TextDisabled(u8"Данные могут быть устаревшими (до 5 мин).")
                imgui.EndTooltip()
            end
            imgui.PopFont()
        end
    end
    
    -- 3. Количество
    local line3_y = p.y + S(44)
    -- [FPS FIX] Используем кэш количества
    draw_list:AddText(imgui.ImVec2(info_x, line3_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), result._u8_amount_str or u8("В наличии: " .. formatNumber(result.amount or 0)))
    
    -- 4. Цена (Рендер)
    imgui.PushFont(font_default)
    draw_list:AddText(imgui.ImVec2(price_x, price_y), imgui.ColorConvertFloat4ToU32(type_color), price_str)
    imgui.PopFont()
    
    local lbl_txt = u8"Цена за шт."
    local lbl_sz = GetStaticTextSize(lbl_txt)
    draw_list:AddText(imgui.ImVec2(p.x + width - lbl_sz.x - right_margin, price_y + price_sz.y + S(2)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), lbl_txt)

    -- === КНОПКИ СПРАВА (График и Радар) ===
    if isVerifiedVip() then
        local radar_btn_sz = S(30)
        local radar_btn_x = p.x + width - radar_btn_sz - S(10)
        local chart_btn_x = radar_btn_x - radar_btn_sz - S(8)
        local btns_y = p.y + (height - radar_btn_sz) / 2

        -- Кнопка Графика
        imgui.SetCursorScreenPos(imgui.ImVec2(chart_btn_x, btns_y))
        if imgui.InvisibleButton("chart_btn_m_" .. index, imgui.ImVec2(radar_btn_sz, radar_btn_sz)) then
            api_GetVipAnalytics('price_history', result.item_name)
        end
        local chart_hovered = imgui.IsItemHovered()
        if chart_hovered then
            draw_list:AddRectFilled(imgui.ImVec2(chart_btn_x, btns_y), imgui.ImVec2(chart_btn_x + radar_btn_sz, btns_y + radar_btn_sz), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(6))
            imgui.SetTooltip(u8"Открыть график изменения цен")
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local chart_icon = fa('chart_column')
            local c_sz = GetStaticTextSize(chart_icon)
            local c_col = chart_hovered and CURRENT_THEME.accent_primary or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(chart_btn_x + (radar_btn_sz - c_sz.x)/2, btns_y + (radar_btn_sz - c_sz.y)/2), imgui.ColorConvertFloat4ToU32(c_col), chart_icon)
            imgui.PopFont()
        end

        -- Кнопка Радара
        imgui.SetCursorScreenPos(imgui.ImVec2(radar_btn_x, btns_y))
        if imgui.InvisibleButton("radar_add_m_" .. index, imgui.ImVec2(radar_btn_sz, radar_btn_sz)) then
            table.insert(Data.radar_list, {
                name = cleanItemName(result.item_name),
                price = tonumber(result.price) or 0,
                type = result.is_sell and 0 or 1,
                added = os.time()
            })
            saveListsConfig()
            api_SyncRadar()
            addToastNotification("Товар добавлен в Радар!", "success", 3.0)
        end
        local radar_hovered = imgui.IsItemHovered()
        if radar_hovered then
            draw_list:AddRectFilled(imgui.ImVec2(radar_btn_x, btns_y), imgui.ImVec2(radar_btn_x + radar_btn_sz, btns_y + radar_btn_sz), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(6))
            imgui.SetTooltip(u8"Отслеживать появление товара в Радаре")
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local radar_icon = fa('satellite_dish')
            local r_sz = GetStaticTextSize(radar_icon)
            local r_col = radar_hovered and CURRENT_THEME.accent_warning or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(radar_btn_x + (radar_btn_sz - r_sz.x)/2, btns_y + (radar_btn_sz - r_sz.y)/2), imgui.ColorConvertFloat4ToU32(r_col), radar_icon)
            imgui.PopFont()
        end
        
        -- Ховер эффект всей карточки (если мышь не на кнопках)
        if card_hovered and not chart_hovered and not radar_hovered then
            draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.1)), S(8), 15, S(2))
            if not is_passive then imgui.SetTooltip(u8("Нажмите, чтобы открыть лавку игрока " .. result.shop_nickname)) end
        end
    else
        -- Ховер эффект для не-VIP (нет кнопок, поэтому просто проверяем ховер карты)
        if card_hovered then
            draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.1)), S(8), 15, S(2))
            if not is_passive then imgui.SetTooltip(u8("Нажмите, чтобы открыть лавку игрока " .. result.shop_nickname)) end
        end
    end
    
    -- Отступ снизу
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + height + S(6)))
end

function renderModernLogCard(log, width)
    local draw_list = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local height = S(60)
    
    local is_sale = log.type == "sale"
    local theme_col = is_sale and CURRENT_THEME.accent_success or CURRENT_THEME.accent_danger
    
    -- [ОПТИМИЗАЦИЯ] Используем кэшированные U32 цвета
    local theme_col_u32 = is_sale and CURRENT_THEME.accent_success_u32 or CURRENT_THEME.accent_danger_u32
    local bg_sec_u32 = CURRENT_THEME.bg_secondary_u32
    
    local icon = is_sale and fa('arrow_up_from_bracket') or fa('cart_shopping')
    
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), bg_sec_u32, S(8))
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + S(4), p.y + height), theme_col_u32, S(8), 9)

    local img_box_sz = S(38)
    local img_box_x = p.x + S(14)
    local img_box_y = p.y + (height - img_box_sz) / 2

    local box_min = imgui.ImVec2(img_box_x, img_box_y)
    local box_max = imgui.ImVec2(img_box_x + img_box_sz, img_box_y + img_box_sz)
    local box_rounding = S(8)

    local slot_bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.05, 0.06, 1.0))
    draw_list:AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)
    
    local glow_col = setAlphaU32(theme_col_u32, 0.15)
    draw_list:AddRectFilled(box_min, box_max, glow_col, box_rounding)
    draw_list:AddRect(box_min, box_max, 0x1EFFFFFF, box_rounding, 15, S(1.5))

    -- [FPS OPTIMIZATION FIX] Используем заранее закэшированный ID, избегая тяжелого поиска!
    local target_model_id = log._cached_model_id or -1
    local texture = getItemIconTexture(tonumber(target_model_id))

    if texture then
        local pad = S(4)
        local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.8))
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(2)), imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(2)), imgui.ImVec2(0,0), imgui.ImVec2(1,1), shadow_col)
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad), imgui.ImVec2(box_max.x - pad, box_max.y - pad))
    else
        if font_fa then
            imgui.PushFont(font_fa)
            local p_sz = GetStaticTextSize(icon)
            local ph_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(theme_col.x, theme_col.y, theme_col.z, 0.5))
            draw_list:AddText(imgui.ImVec2(img_box_x + (img_box_sz - p_sz.x)/2, img_box_y + (img_box_sz - p_sz.y)/2), ph_col, icon)
            imgui.PopFont()
        end
    end

    if texture and imgui.IsMouseHoveringRect(box_min, box_max) then
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(8)))
        imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.05, 0.05, 0.06, 0.98))
        imgui.PushStyleColor(imgui.Col.Border, theme_col)
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
        
        imgui.BeginTooltip()
        imgui.Image(texture, imgui.ImVec2(S(130), S(130)))
        imgui.EndTooltip()
        
        imgui.PopStyleVar(2)
        imgui.PopStyleColor(2)
    end

    local content_x = img_box_x + img_box_sz + S(12)
    local right_margin = S(15)
    
    -- [FPS OPTIMIZATION FIX] Используем закэшированное имя
    local item_name = log._u8_item or u8(log.item)
    local max_name_w = width - S(200) 
    imgui.PushClipRect(imgui.ImVec2(content_x, p.y), imgui.ImVec2(content_x + max_name_w, p.y + height), true)
    draw_list:AddText(imgui.ImVec2(content_x, p.y + S(8)), CURRENT_THEME.text_primary_u32, item_name)
    imgui.PopClipRect()
    
    -- [FPS FIX] Используем заранее закэшированную строку без вызова string.format и match
    draw_list:AddText(imgui.ImVec2(content_x, p.y + S(34)), CURRENT_THEME.text_hint_u32, log._u8_meta_text or "?")
    
    -- [FPS OPTIMIZATION FIX] Используем закэшированную строку цены
    local total_str = (log._fmt_total or formatMoney(log.total)) .. " $"
    local total_sz = GetStaticTextSize(total_str)
    
    draw_list:AddText(
        imgui.ImVec2(p.x + width - total_sz.x - right_margin, p.y + S(8)), 
        imgui.ColorConvertFloat4ToU32(is_sale and CURRENT_THEME.accent_success or CURRENT_THEME.accent_danger), 
        total_str
    )
    
    local details_str = log.amount > 1 and string.format("%s шт. x %s $", log.amount, log._fmt_price or log.price) or "1 шт."
    local details_u8 = u8(details_str)
    local details_sz = GetStaticTextSize(details_u8)
    
    local del_btn_sz = S(20)
    local text_right_offset = right_margin + del_btn_sz + S(5)
    
    draw_list:AddText(
        imgui.ImVec2(p.x + width - details_sz.x - text_right_offset, p.y + S(34)), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), 
        details_u8
    )
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + width - right_margin - del_btn_sz, p.y + S(32)))
    if imgui.InvisibleButton("##del_log_"..tostring(log.timestamp), imgui.ImVec2(del_btn_sz, del_btn_sz)) then
        local selected_idx = Buffers.logs_current_date_idx
        local date_str = (selected_idx > 0 and Buffers.logs_dates_cache[selected_idx]) or os.date("%Y-%m-%d")
        local file_path = PATHS.LOGS .. date_str .. ".json"
        
        local day_logs = loadJsonFile(file_path, {})
        for k, v in ipairs(day_logs) do
            if v.timestamp == log.timestamp and v.item == log.item and v.type == log.type then
                table.remove(day_logs, k)
                break
            end
        end
        saveJsonFile(file_path, day_logs)
        LogsState.cached_income, LogsState.cached_expense = updateLogView()
        calculateTodayStats()
        addToastNotification("Запись удалена из истории", "success")
    end
    
    local is_del_hov = imgui.IsItemHovered()
    if font_fa then
        imgui.PushFont(font_fa)
        local t_icon = fa('trash')
        local t_col = is_del_hov and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
        draw_list:AddText(imgui.ImVec2(p.x + width - right_margin - del_btn_sz + S(4), p.y + S(32) + S(2)), imgui.ColorConvertFloat4ToU32(t_col), t_icon)
        imgui.PopFont()
    end
    if is_del_hov then imgui.SetTooltip(u8"Удалить эту запись") end
    
    imgui.SetCursorScreenPos(p)
    imgui.InvisibleButton("##log_"..tostring(log.timestamp), imgui.ImVec2(width - right_margin - del_btn_sz - S(5), height))
    
    if imgui.IsItemHovered() then
        draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(8), 15, S(1))
    end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + height + S(8)))
end

function string.trim(s)
    return s:match("^%s*(.-)%s*$")
end

-- ==================== NOTE ====================
-- Функции для утилит (cleanItemName, extractCategory, enhancedCleanItemName, и т.д.)
-- ОПРЕДЕЛЕНЫ РАНЕЕ в начале скрипта (раздел "УТИЛИТЫ (STRING & ITEM UTILITIES)")
-- для избежания forward-деклараций
-- =======================

function parseStatsDialog(text)
    -- Инициализация с дефолтными значениями
    local data = {
        level = 0,
        vip = "Нет",
        cash = 0,
        bank = 0,
        deposit = 0,
        job = "Нет",
        org = "Нет",
        fam = "Нет"
    }
    
    -- Вспомогательная функция для удаления пробелов по краям
    local function trim(s)
        return s:match("^%s*(.-)%s*$")
    end
    
    -- Проходим по тексту ПОСТРОЧНО (это решает проблему захвата лишнего текста)
    for line in text:gmatch("[^\r\n]+") do
        -- Очистка строки от цветовых кодов и табуляции
        local clean_line = line
            :gsub("{%x+}", "")       -- {FFFFFF}
            :gsub("%[[%x]+%]", "")   -- [BE433D]
            :gsub("\t", " ")         -- Табы в пробелы
            :gsub("\194\160", " ")   -- Неразрывные пробелы
        
        -- Удаляем лишние пробелы внутри строки (но оставляем структуру)
        clean_line = clean_line:gsub("%s+", " ")
        clean_line = trim(clean_line)

        -- 1. ДЕНЬГИ (Ищем цифры с точками)
        if clean_line:find("Наличные деньги:") then
            local num_str = clean_line:match("Наличные деньги:%s*([%d%.]+)")
            if num_str then data.cash = tonumber((num_str:gsub("%.", ""))) or 0 end
            
        elseif clean_line:find("Деньги в банке:") then
            local num_str = clean_line:match("Деньги в банке:%s*([%d%.]+)")
            if num_str then data.bank = tonumber((num_str:gsub("%.", ""))) or 0 end
            
        elseif clean_line:find("Деньги на депозите:") then
            local num_str = clean_line:match("Деньги на депозите:%s*([%d%.]+)")
            if num_str then data.deposit = tonumber((num_str:gsub("%.", ""))) or 0 end

        -- 2. СТАТИСТИКА
        elseif clean_line:find("Уровень:") then
            local lvl = clean_line:match("Уровень:%s*(%d+)")
            if lvl then data.level = tonumber(lvl) end
            
        elseif clean_line:find("VIP статус:") then
            local vip = clean_line:match("VIP статус:%s*(.+)")
            if vip then data.vip = u8(trim(vip)) end

        -- 3. ТЕКСТОВЫЕ ПОЛЯ (Работа, Орга, Семья)
        -- Используем жесткую привязку, чтобы не взять лишнего
        
        elseif clean_line:find("Работа:") and not clean_line:find("Опыт") then
            -- Берем всё после двоеточия
            local job_val = clean_line:match("Работа:%s*(.*)")
            if job_val then 
                -- Если в строке после работы есть другие заголовки (баг парсинга), отрезаем их
                -- На всякий случай, хотя построчный режим это лечит
                job_val = job_val:gsub(" Организация:.*", "") 
                data.job = u8(trim(job_val))
            end

        elseif clean_line:find("Организация:") then
            local org_val = clean_line:match("Организация:%s*(.*)")
            if org_val then
                org_val = org_val:gsub(" Должность:.*", "")
                data.org = u8(trim(org_val))
            end

        elseif clean_line:find("Семья:") and not clean_line:find("В семье с") then
            local fam_val = clean_line:match("Семья:%s*(.*)")
            if fam_val then
                -- Удаляем ID семьи в скобках [ID: 108] и "Ранг..."
                fam_val = fam_val:gsub("%s*%[ID:.-%]", ""):gsub(" Ранг.*", "")
                data.fam = u8(trim(fam_val))
            end
        
        -- 4. РУССКИЙ НИК
        elseif clean_line:find("Имя %(рус%.%):") then
            local rus = clean_line:match("Имя %(рус%.%):%s*(.*)")
            if rus then 
                -- [FIX] Обязательно заменяем подчеркивание на пробел
                LOCAL_PLAYER_NICK_RUS = trim(rus):gsub("_", " ")
                data.nickname_rus = LOCAL_PLAYER_NICK_RUS
            end
        end
    end
    
    return data
end

function sendStatsToAPI(statsData)
    if Data.settings.telegram_token == "" then return end
    local current_nick = LOCAL_PLAYER_NICK
    if not current_nick then
        local _, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
        local nick = sampGetPlayerNickname(myId)
        if nick then current_nick = nick:gsub("_", " ") end
    end
    statsData.nickname = u8(current_nick or "Unknown")
    if not statsData.job or statsData.job == "" then statsData.job = u8("Нет") end
    if not statsData.org or statsData.org == "" then statsData.org = u8("Нет") end
    if not statsData.fam or statsData.fam == "" then statsData.fam = u8("Нет") end
    if statsData.nickname_rus then
        statsData.nickname_rus = u8(statsData.nickname_rus)
    end
    local payload = {
        secret_key = Data.settings.telegram_token,
        data = statsData
    }
    signed_request("POST", MarketConfig.HOST .. "/receive_stats", payload, function(response) end)
end

function checkVipStatus(token)
    if not token or token == "" then 
        Data.is_vip = false 
        Data.vip_checked = true 
        return 
    end
    
    local current_nick = getSafeLocalNickname()
    if current_nick == "Unknown Player" or current_nick == "Loading..." then return end
    
    local payload = { 
        secret_key = token, 
        nickname = u8(current_nick),
        -- Отправляем русский ник на сервер, если он есть (для статистики)
        nickname_rus = LOCAL_PLAYER_NICK_RUS and u8(LOCAL_PLAYER_NICK_RUS) or "",
        account_id = LOCAL_ACCOUNT_ID
    }
    
    asyncHttpRequest("POST", MarketConfig.HOST .. "/check_vip", 
        { headers = {["Content-Type"] = "application/json"}, data = json.encode(payload) },
        function(response)
            if response.status_code == 200 then
                local ok, res = pcall(json.decode, response.text)
                if ok and res.status == 'success' then
                    local new_status = res.is_vip
                    
                    Data.is_vip = new_status
                    Data.vip_validated_at = os.time() 
                    Data.vip_days = res.days_left
                    Data.vip_months = tonumber(res.vip_months) or 1 
                    -- [INNOVATION VIP] Сохраняем точный UNIX timestamp с сервера
                    Data.vip_expire_ts = tonumber(res.expire_ts) or 0
                    
                    -- Если сервер сказал, что VIP нет, чистим локальный радар принудительно
                    if not new_status and #Data.radar_list > 0 then
                        Data.radar_list = {}
                        saveListsConfig()
                    end
                    
                    -- [FIX] Добавляем себя в кэш VIP пользователей для чата
                     if Data.is_vip then
                        local m = tonumber(res.vip_months) or 1
                        -- 1. Добавляем английский ник
                        if current_nick then
                            Data.vip_users_cache[current_nick] = m
                            Data.vip_users_cache[current_nick:gsub(" ", "_")] = m
                        end
                        
                        -- 2. Добавляем РУССКИЙ ник
                        if LOCAL_PLAYER_NICK_RUS then
                            Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS] = m
                            Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS:gsub(" ", "_")] = m
                        end
                        
                        -- СОХРАНЯЕМ В JSON ФАЙЛ
                        saveJsonFile(FILES.VIP_CACHE, Data.vip_users_cache)
                    end
                    
                    if res.online_vips and type(res.online_vips) == "table" then
                        for _, vip_nick in ipairs(res.online_vips) do
                            local dec_nick = u8:decode(vip_nick)
                            -- Записываем строго как число месяцев (1 по умолчанию)
                            Data.vip_users_cache[dec_nick] = 1
                            Data.vip_users_cache[dec_nick:gsub(" ", "_")] = 1
                        end
                    end
                elseif ok and res.status == 'error' then
                    Logger.log("ERR", "Ошибка VIP: " .. (res.msg or "unknown"))
                end
            end
            Data.vip_checked = true 
        end,
        function(err)
            Data.vip_checked = true 
        end
    )
end

function switchToRemoteProfile(mode)
    local profileName = "Remote_Import"
    local configs = (mode == "sell") and Data.sell_configs or Data.buy_configs
    local targetIndex = -1

    -- 1. Ищем существующий профиль
    for i, cfg in ipairs(configs) do
        if cfg.name == profileName then
            targetIndex = i
            break
        end
    end

    -- 2. Если нет - создаем
    if targetIndex == -1 then
        if mode == "sell" then
            targetIndex = createSellConfig(profileName)
        else
            targetIndex = createBuyConfig(profileName)
        end
        -- Перезагружаем список, так как create возвращает индекс
        configs = (mode == "sell") and Data.sell_configs or Data.buy_configs
    end

    -- 3. Переключаемся на него
    if mode == "sell" then
        selectSellConfig(targetIndex)
    else
        selectBuyConfig(targetIndex)
    end
    
    return targetIndex
end

function startUsingMoney(slot, amount)
    if App.is_scanning or App.is_selling_cef or State.buying.active or App.is_removing_sale or App.is_removing_buy then 
        sampAddChatMessage('[RMarket] {ff0000}Скрипт занят другим действием! Дождитесь завершения.', -1)
        return 
    end
    
    MoneyUseState.active = true
    MoneyUseState.slot = slot
    MoneyUseState.amount = amount
    MoneyUseState.step = 1
    
    sampSendChat('/invent')
    
    App.tasks.add("money_use_timeout", function()
        if MoneyUseState.active then
            MoneyUseState.active = false
            sampAddChatMessage('[RMarket] {ff0000}Таймаут обмена денег! Операция прервана.', -1)
            sendCEF("inventoryClose")
        end
    end, 15000)
end

function checkRemoteActions()
    if Data.settings.telegram_token == "" then return end
    if App.is_scanning or App.is_selling_cef or State.buying.active then return end 
    if App.is_checking_remote then return end
    App.is_checking_remote = true
    local url = MarketConfig.HOST .. "/action?type=check"
    asyncHttpRequest("GET", url, { 
        headers = {["X-Auth-Key"] = Data.settings.telegram_token}, 
        timeout = 15 
    },
        function(response)
            App.is_checking_remote = false 
            if response.status_code ~= 200 then return end
            if not response.text or response.text == "" then return end
            local ok, res = pcall(json.decode, response.text)
            if not ok or not res or not res.command or res.command == "none" then return end
            if res.command == 'stats' then
                State.stats_requested_by_script = true 
                sampSendChat("/stats")
            end
			if res.command == 'phone_accept' then
                sendCEF("callApp.callStarted")
                sampAddChatMessage('[RMarket] {00ff00}Звонок принят через Telegram!', -1)
            end
            if res.command == 'phone_reject' then
                sendCEF("callApp.callFinished")
                sampAddChatMessage('[RMarket] {ff0000}Вы сбросили вызов через Telegram.', -1)
            end
            if res.command == 'phone_msg' and res.payload and res.payload.text then
                local chat_text = res.payload.text
                if u8 then
                    local s, r = pcall(u8.decode, u8, chat_text)
                    if s then chat_text = r end
                end
                sampSendChat(chat_text)
            end
            if res.command == 'scan_inventory' then
                if os.clock() - (State.last_inventory_scan_time or 0) > 10 then
                    sampAddChatMessage('[RMarket] {ffff00}Сканирование инвентаря...', -1)
                    State.last_inventory_scan_time = os.clock()
                    startScanning()
                end
            end
            if res.command == 'start_sell' and res.payload then
                sampAddChatMessage('[RMarket] {ffff00}Команда на продажу (Remote)', -1)
                local is_smart_sell = false
                local smart_sell_list = {}
                Data.cef_sell_queue = {}
                Data.cef_slots_data = {} 
                for _, item in ipairs(res.payload) do
                    local name_cp = item.name
                    if u8 then
                        local s, r = pcall(u8.decode, u8, item.name)
                        if s then name_cp = r end
                    end
                    local model_id = tonumber(item.model_id) or -1
                    if model_id == -1 then
                        is_smart_sell = true
                        table.insert(smart_sell_list, {
                            name = name_cp,
                            price = tonumber(item.price),
                            amount = tonumber(item.amount),
                            active = true,
                            auto_max = false 
                        })
                    else
                        table.insert(Data.cef_sell_queue, {
                            slot = tonumber(item.slot),
                            model = model_id,
                            amount = tonumber(item.amount),
                            price = tonumber(item.price),
                            name = name_cp,
                            retry_count = 0
                        })
                    end
                end
                App.live_shop_active = true
                Marketplace.enabled = true
                Marketplace.is_cleared = false
                Marketplace.publish_sell = false
                if is_smart_sell then
                    saveListsConfig() 
                    Data.sell_list = smart_sell_list
                    sampAddChatMessage('[RMarket] {00ff00}Smart Sell: ' .. #smart_sell_list .. ' товаров', -1)
                    startCEFSelling() 
                else
                    if #Data.cef_sell_queue > 0 then
                        App.is_selling_cef = true
                        App.current_sell_item_index = 0
                        App.current_processing_item = nil
                        sampAddChatMessage('[RMarket] {00ff00}Продажа по слотам: ' .. #Data.cef_sell_queue .. ' товаров', -1)
                        lua_thread.create(function()
                            wait(500)
                            setVirtualKeyDown(0x12, true) 
                            wait(150)
                            setVirtualKeyDown(0x12, false)
                        end)
                    end
                end
            end
            if res.command == 'use_money' and res.payload then
                sampAddChatMessage('[RMarket] {ffff00}Команда на обмен предмета "Деньги"...', -1)
                local slot = tonumber(res.payload.slot)
                local amount = tonumber(res.payload.amount)
                if slot and amount then
                    startUsingMoney(slot, amount)
                end
            end
            if res.command == 'remove_single_sell' and res.payload then
                sampAddChatMessage('[RMarket] {ffff00}Команда на снятие товара с продажи...', -1)
                local model_id = tonumber(res.payload.model_id)
                if model_id then
                    startSingleSaleRemoval(model_id)
                end
            end
            if res.command == 'start_buy' and res.payload then
                sampAddChatMessage('[RMarket] {ffff00}Команда на скупку', -1)
                local temp_buy_list = {}
                for _, item in ipairs(res.payload) do
                    local name_cp = item.name
                    if u8 then
                        local s, r = pcall(u8.decode, u8, item.name)
                        if s then name_cp = r end
                    end
                    local item_idx = tonumber(item.model_id)
                    if not item_idx or item_idx == -1 then
                         if Data.item_names_reversed then
                             local clean = cleanItemNameKey(name_cp)
                             item_idx = Data.item_names_reversed[clean] or -1
                         end
                    end
                    table.insert(temp_buy_list, {
                        name = name_cp,
                        index = item_idx, 
                        amount = tonumber(item.amount),
                        price = tonumber(item.price),
                        active = true
                    })
                end
                if #temp_buy_list > 0 then
                    sampAddChatMessage('[RMarket] {00ff00}Скупка: ' .. #temp_buy_list .. ' товаров', -1)
                    startBuying(true, temp_buy_list)
                else
                    sampAddChatMessage('[RMarket] {ff0000}Ошибка списка товаров', -1)
                end
            end
        end,
        function(err)
            App.is_checking_remote = false 
        end
    )
end

function api_SyncConfigsToMiniApp()
    if Data.settings.telegram_token == "" then return end
    if CloudSync.is_syncing then return end
    
    CloudSync.is_syncing = true
    CloudSync.status = "syncing"

    local payload = {
        secret_key = Data.settings.telegram_token,
        configs = toUTF8({
            sell = Data.sell_configs,
            buy = Data.buy_configs
        })
    }
    
    signed_request("POST", MarketConfig.HOST .. "/action?type=upload_configs", payload, function(response)
        CloudSync.is_syncing = false
        if response.status_code == 200 then
            CloudSync.status = "synced"
            print("[RMarket] Конфиги успешно синхронизированы с облаком!")
        else
            CloudSync.status = "error"
            print("[RMarket Cloud] Ошибка выгрузки: " .. response.status_code)
        end
    end)
end

function api_PullConfigsFromCloud(token)
    if not token or token == "" then return end
    
    addToastNotification("Синхронизация профиля с облаком...", "info")
    
    local payload = { secret_key = token }
    signed_request("POST", MarketConfig.HOST .. "/action?type=download_configs", payload, function(response)
        if response.status_code == 200 then
            local ok, res = pcall(json.decode, response.text)
            if ok and res.status == 'success' and res.configs then
                local cloud_configs = fromUTF8(res.configs)
                local has_changes = false

                -- Восстановление конфигов продажи
                if cloud_configs.sell and #cloud_configs.sell > 0 then
                    Data.sell_configs = cloud_configs.sell
                    for _, cfg in ipairs(Data.sell_configs) do
                        saveSingleConfig(PATHS.PROFILES_SELL, cfg)
                    end
                    has_changes = true
                end

                -- Восстановление конфигов скупки
                if cloud_configs.buy and #cloud_configs.buy > 0 then
                    Data.buy_configs = cloud_configs.buy
                    for _, cfg in ipairs(Data.buy_configs) do
                        saveSingleConfig(PATHS.PROFILES_BUY, cfg)
                    end
                    has_changes = true
                end
                
                if has_changes then
                    -- Перезагружаем списки
                    selectBuyConfig(1)
                    selectSellConfig(1)
                    addToastNotification("Конфиги успешно загружены из облака!", "success", 4.0)
                    CloudSync.status = "synced"
                else
                    -- Если облако пустое, заливаем туда наши локальные файлы
                    triggerCloudSync()
                end
            end
        else
            addToastNotification("Не удалось загрузить конфиги из облака", "error")
        end
    end)
end

local last_log_refresh_timer = 0

function renderLogsTab()
    local full_avail_w = imgui.GetContentRegionAvail().x
    local avail_h = imgui.GetContentRegionAvail().y 
    local margin_side = S(20)
    -- Уменьшили нижний отступ, так как там больше ничего нет
    local margin_bottom = S(10) 
    
    local content_w = full_avail_w - (margin_side * 2)

    local current_time = os.clock()
    if current_time - last_log_refresh_timer > 2.0 then
        refreshLogDates()
        last_log_refresh_timer = current_time
        
        if Buffers.logs_current_date_idx == 0 or Buffers.logs_current_date_idx == 1 then
             LogsState.cached_income, LogsState.cached_expense = updateLogView()
        end
    end

    local function setIndent()
        imgui.SetCursorPosX(margin_side) 
    end
    
    local current_idx = Buffers.logs_current_date_idx
    local current_boxes = tostring(Buffers.log_filters.show_sales[0]) .. tostring(Buffers.log_filters.show_purchases[0])
    
    -- Обновляем данные, если изменились фильтры (даже если они переключаются в хедере)
    if current_idx ~= UIFilters.last_log_idx or current_boxes ~= LogsState.last_check_boxes or not Data.current_view_logs then
        LogsState.cached_income, LogsState.cached_expense = updateLogView()
        UIFilters.last_log_idx = current_idx
        LogsState.last_check_boxes = current_boxes
    end
    
    local profit = LogsState.cached_income - LogsState.cached_expense
    local filtered_list = Data.current_view_logs or {}
    
    imgui.Dummy(imgui.ImVec2(0, S(10)))

    -- 1. КАРТОЧКИ СТАТИСТИКИ
    setIndent()
    imgui.BeginGroup()
        local card_h = S(70)
        local gap = S(15)
        local card_w = (content_w - (gap * 2)) / 3

        drawStatCard("Доход", LogsState.cached_income, imgui.ImVec4(0.15, 0.35, 0.20, 0.6), card_w, card_h)
        imgui.SameLine(nil, gap)
        drawStatCard("Расход", LogsState.cached_expense, imgui.ImVec4(0.35, 0.15, 0.15, 0.6), card_w, card_h)
        imgui.SameLine(nil, gap)
        local profit_col = profit >= 0 and imgui.ImVec4(0.2, 0.2, 0.35, 0.6) or imgui.ImVec4(0.35, 0.2, 0.2, 0.6)
        drawStatCard("Прибыль", profit, profit_col, card_w, card_h)
    imgui.EndGroup()

    imgui.Dummy(imgui.ImVec2(0, S(15)))
    
    -- Разделитель
    setIndent()
    imgui.PushItemWidth(content_w)
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    -- Рисуем тонкую линию вместо стандартного separator
    dl:AddLine(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + content_w, p.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
    imgui.PopItemWidth()
    
    imgui.Dummy(imgui.ImVec2(0, S(10)))

    -- 2. СПИСОК ЛОГОВ (Теперь занимает все место)
    local remaining_h = imgui.GetContentRegionAvail().y
    local list_height = remaining_h - margin_bottom
    
    setIndent()
    
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main) 
    renderSmoothScrollBox("LogsListScroll", imgui.ImVec2(content_w, list_height), function()
        if #filtered_list == 0 then
            -- Если список пуст
            local text = u8("История операций пуста")
            if Buffers.log_filters.show_sales[0] == false and Buffers.log_filters.show_purchases[0] == false then
                text = u8("Включите фильтры в заголовке окна")
            end
            
            local t_size = GetStaticTextSize(text)
            imgui.SetCursorPosX((content_w - t_size.x) / 2)
            imgui.SetCursorPosY(S(60))
            if font_fa then
                imgui.PushFont(font_fa)
                local icon = fa('box_open')
                local i_size = GetStaticTextSize(icon)
                imgui.SetCursorPosX((content_w - i_size.x) / 2)
                imgui.TextColored(CURRENT_THEME.text_hint, icon)
                imgui.PopFont()
            end
            imgui.SetCursorPosX((content_w - t_size.x) / 2)
            imgui.TextColored(CURRENT_THEME.text_hint, text)
        else
            -- ОПТИМИЗИРОВАННЫЙ РЕНДЕР (CLIPPER)
            local clipper = imgui.ImGuiListClipper(#filtered_list)
            while clipper:Step() do
                for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
                    local log = filtered_list[i]
                    if log then
                        renderModernLogCard(log, content_w)
                    end
                end
            end
        end
        -- Небольшой отступ внизу списка
        imgui.Dummy(imgui.ImVec2(0, S(5)))
    end)
    imgui.PopStyleColor()
end

function countTable(tbl)
    local count = 0
    for _ in pairs(tbl) do count = count + 1 end
    return count
end

function attemptOpenSettings()
    if not App.is_scanning or not State.inventory_scan.active then return end

    State.inventory_scan.attempts = (State.inventory_scan.attempts or 0) + 1

    if State.inventory_scan.attempts > 3 then
        App.is_scanning = false
        State.inventory_scan.active = false
        State.inventory_scan.waiting_for_packets = false
        sampAddChatMessage('[RMarket] {ff0000}Сканирование прервано', -1)
        return
    end

    if State.inventory_scan.attempts > 1 then
        sampAddChatMessage(string.format('[RMarket] {ffff00}Открытие меню (%d/3)', State.inventory_scan.attempts), -1)
    end

    sampSendChat('/settings')

    App.tasks.add("scan_retry_wait", function()
        attemptOpenSettings()
    end, 3000)
end

function startScanning()
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active then return end
    
    if not State.inventory_scan then
        State.inventory_scan = { active = false, waiting_for_packets = false }
    end

    Data.cef_inventory_items = {}
    Data.scanned_items = {}
    Data.cef_slots_data = {} 
    
    App.is_scanning = true
    State.inventory_scan.active = true
    State.inventory_scan.waiting_for_packets = false 
    State.inventory_scan.attempts = 0
    
    State.inventory_scan.last_packet_time = 0
    State.inventory_scan.has_received_data = false
    State.inventory_scan.start_wait_time = 0
    
    sampAddChatMessage('[RMarket] {ffff00}Сканирование через настройки...', -1)
    
    attemptOpenSettings()
end

function startCEFScanning()
    App.cef_inventory_active = true
    Data.cef_inventory_items = {}
    Data.scanned_items = {}
    App.is_scanning = true
    sampAddChatMessage('[RMarket] {ffff00}Сканирование инвентаря...', -1)
    sampSendChat('/invent')
    App.tasks.add("wait_cef_data", function()
        if not App.cef_inventory_active or not App.is_scanning then return end
        
        
        

        for _, item_data in pairs(Data.cef_inventory_items) do
            if not isItemUnsellable(item_data.model_id) then
                local is_money = (item_data.model_id == 3660)
                local display_name = is_money and "Деньги" or item_data.name
                
                if not is_money and item_data.amount and item_data.amount > 1 then
                    display_name = display_name .. " (x" .. item_data.amount .. ")"
                end

                table.insert(Data.scanned_items, {
                    name = display_name, 
                    original_name = is_money and "Деньги" or item_data.name,
                    model_id = item_data.model_id,
                    amount = item_data.amount
                })
            end
        end
        closeCEFInventory()
        
        local inventory_ids = {}
        for _, item in ipairs(Data.scanned_items) do
            inventory_ids[tostring(item.model_id)] = true
        end
        
        -- [УЛУЧШЕНО] Используем функцию который проверяет наличие по model_id И slot, не только по model_id
        refreshSellListMissingStatus()
        
        
        
        saveJsonFile(PATHS.CACHE .. 'scanned_items.json', Data.scanned_items)
        saveJsonFile(PATHS.DATA .. 'item_amounts.json', Data.inventory_item_amounts) 
        saveListsConfig() 
        
        App.is_scanning = false
        Data.cached_sell_filtered = nil 
        App.inv_ui_cache = nil -- [FIX] Очищаем современный кэш UI инвентаря
        
        sampAddChatMessage('[RMarket] {00ff00}Сканирование завершено: ' .. #Data.scanned_items .. ' слотов', -1)
        App.win_state[0] = true
    end, 500)
end

function rebuildLookupTables()
    Data.sell_lookup = {}
    Data.sell_count_lookup = {} -- Добавлено кэширование количества (FPS FIX)
    for _, item in ipairs(Data.sell_list) do
        if item.model_id then
            local key = tostring(item.model_id) .. "_" .. tostring(item.slot or "nil")
            Data.sell_lookup[key] = true
            Data.sell_lookup[tostring(item.model_id)] = true

            local mid_str = tostring(item.model_id)
            Data.sell_count_lookup[mid_str] = (Data.sell_count_lookup[mid_str] or 0) + 1
        end
    end
end

function isSlotInSellList(slot_id, model_id)
    if not slot_id or not model_id then return false end
    if not Data.sell_lookup then Data.sell_lookup = {} end
    
    local key = tostring(model_id) .. "_" .. tostring(slot_id)
    return Data.sell_lookup[key] == true
end

function setSlotAddedStatus(slot_id, model_id, status)
    if not Data.sell_lookup then Data.sell_lookup = {} end
    if not Data.sell_count_lookup then Data.sell_count_lookup = {} end

    local key = tostring(model_id) .. "_" .. tostring(slot_id)
    local mid_str = tostring(model_id)

    if status then
        Data.sell_lookup[key] = true
        Data.sell_lookup[mid_str] = true
        Data.sell_count_lookup[mid_str] = (Data.sell_count_lookup[mid_str] or 0) + 1
    else
        Data.sell_lookup[key] = nil
        Data.sell_count_lookup[mid_str] = math.max(0, (Data.sell_count_lookup[mid_str] or 0) - 1)
        if Data.sell_count_lookup[mid_str] == 0 then
            Data.sell_lookup[mid_str] = nil
        end
    end
end

function isItemInSellList(model_id)
    if not model_id then return false end
    if not Data.sell_lookup then return false end
    return Data.sell_lookup[tostring(model_id)] == true
end

function countItemInSellList(model_id)
    if not model_id then return 0 end
    if not Data.sell_count_lookup then return 0 end
    return Data.sell_count_lookup[tostring(model_id)] or 0
end

function getItemCounts(model_id)
    if not model_id then return 0, 0 end
    local model_str = tostring(model_id)
    
    
    local count_in_sell = countItemInSellList(model_id)
    
    
    local count_in_inv = 0
    for _, item in ipairs(Data.scanned_items) do
        if item and item.model_id and tostring(item.model_id) == model_str then 
            count_in_inv = count_in_inv + 1 
        end
    end
    
    
    return count_in_sell, count_in_inv
end

function isItemUnsellable(model_id)
    if not model_id then return false end
    for _, unsellable_id in ipairs(Data.unsellable_items) do
        if tostring(unsellable_id) == tostring(model_id) then return true end
    end
    return false
end

function api_CheckAndDownloadItemsDB(force)
    if App.is_downloading_db then return end
    App.is_downloading_db = true
    if force then addToastNotification("Скачивание базы предметов...", "info") end
    
    local url = "https://rodina-market.store/data/Rodina/items_db.json?t=" .. os.time()
    asyncHttpRequest("GET", url, {timeout = 15}, 
        function(response)
            App.is_downloading_db = false
            if response.status_code == 200 and response.text and #response.text > 100 then
                local f = io.open(FILES.ITEMS_DB, "w")
                if f then
                    f:write(response.text)
                    f:close()
                    loadItemNames()
                    
                    local new_buyables = {}
                    for id, name in pairs(Data.item_names) do
                        table.insert(new_buyables, {
                            name = name,
                            category = Data.item_categories[tostring(id)] or "Предмет",
                            index = tonumber(id)
                        })
                    end
                    Data.buyable_items = new_buyables
                    saveJsonFile(FILES.CACHE_BUYABLES, Data.buyable_items)
                    
                    BuyableItems.force_refresh = true
                    BuyableItems.items = {}
                    updateBuyCategories()
                    
                    if force then addToastNotification("База предметов успешно обновлена!", "success") end
                end
            elseif force then
                addToastNotification("Ошибка скачивания базы: " .. response.status_code, "error")
            end
        end,
        function(err)
            App.is_downloading_db = false
            if force then addToastNotification("Ошибка сети при скачивании базы", "error") end
        end
    )
end

function waitForInventoryAndStart(callback)
    local check_start = os.clock()
    local last_count = 0
    local stability_start = os.clock()
    
    -- Не очищаем кэш жестко, если это восстановление, но лучше обновить
    -- Data.cef_slots_data = {} 
    
    App.tasks.remove_by_name("smart_inv_wait")

    App.tasks.add("smart_inv_wait", function()
        if not App.is_selling_cef then return end
        
        local current_count = countTable(Data.cef_slots_data)
        local now = os.clock()
        
        -- Если количество слотов меняется, ждем стабилизации
        if current_count ~= last_count then
            last_count = current_count
            stability_start = now
        end
        
        -- Ждем 0.5 сек тишины после последнего обновления данных
        local is_stable = (now - stability_start > 0.5)
        local is_timeout = (now - check_start > 8.0) -- Увеличили таймаут до 8 сек
        
        if (current_count > 0 and is_stable) or is_timeout then
            if current_count == 0 then
                -- Если так и не загрузилось - пробуем открыть настройки для триггера обновления
                sampSendChat("/settings") -- Трюк для обновления CEF
                App.tasks.add("retry_inv_fail", function()
                     if countTable(Data.cef_slots_data) > 0 then callback() 
                     else 
                        sampAddChatMessage('[RMarket] {ff0000}Ошибка: Инвентарь не прогрузился. Повторите.', -1)
                        App.is_selling_cef = false
                        App.live_shop_active = true
                     end
                end, 2000)
            else
                callback() -- Данные есть, запускаем
            end
        else
            App.tasks.add("smart_inv_wait", debug.getinfo(1).func, 100)
        end
    end, 100)
end

function startCEFSelling()
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active or App.is_removing_sale then return end

    local active_items = 0
    for _, item in ipairs(Data.sell_list) do
        if item.active ~= false and (tonumber(item.price) or 0) > 0 then
            active_items = active_items + 1
        end
    end

    if active_items == 0 then
        sampAddChatMessage('[RMarket] {ff0000}Нет активных товаров с ценой > 0', -1)
        return
    end
    
    startCEFSelling_Process()
end

function startCEFSelling_Process()
    App.live_shop_active = true
    Marketplace.enabled = true
    Marketplace.is_cleared = false
    Marketplace.publish_sell = true
    Marketplace.LavkaUid = os.time()
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()

    App.is_selling_cef = true
    App.current_sell_item_index = 0
    App.current_processing_item = nil 
    Data.cef_sell_queue = {}
    Data.cef_slots_data = {} 

    local tasks_to_kill = {"cef_dialog_timeout", "cef_next_item_delay", "cef_sell_press_alt", "cef_sell_release_alt", "wait_cef_data_after_dialog", "wait_cef_dialog_failsafe", "retry_cef_check", "smart_inv_wait"}
    for _, t in ipairs(tasks_to_kill) do App.tasks.remove_by_name(t) end

    sampAddChatMessage('[RMarket] {ffff00}Запуск продажи...', -1)

    if sampIsDialogActive() and sampGetCurrentDialogId() == 9 then
        sampSendDialogResponse(9, 1, 0, "") 
        waitForInventoryAndStart(prepareCEFSellQueue)
        return
    end

    App.tasks.add("cef_sell_press_alt", function()
        setVirtualKeyDown(0x12, true)
        App.tasks.add("cef_sell_release_alt", function() setVirtualKeyDown(0x12, false) end, 100)
    end, 500)
    
    App.tasks.add("wait_cef_dialog_failsafe", function()
        if App.is_selling_cef and countTable(Data.cef_slots_data) == 0 and not sampIsDialogActive() then
             sampAddChatMessage('[RMarket] {ff0000}Диалог лавки не открылся. Подойдите ближе.', -1)
             App.is_selling_cef = false
             
             -- Если не открылось, нужно вернуть старый инвентарь
             if Data.settings.use_old_inventory then
                 State.inventory_switch_active = true
                 State.inventory_switch_mode = "disabling"
                 sampSendChat("/settings")
             end
        end
    end, 5000)
end

function runSmartInventoryWait()
    local check_start = os.clock()
    local last_count = 0
    local stable_start = 0
    
    App.tasks.add("smart_inv_wait", function()
        if not App.is_selling_cef then return end
        
        local current_count = countTable(Data.cef_slots_data)
        local now = os.clock()
        
        -- Если количество изменилось, сбрасываем таймер стабильности
        if current_count ~= last_count then
            last_count = current_count
            stable_start = now
        end
        
        -- Условия старта:
        -- 1. Есть данные (>0) И прошло 0.5 сек с последнего изменения (все пакеты дошли)
        -- 2. ИЛИ прошло более 5 сек (таймаут)
        if (current_count > 0 and (now - stable_start > 0.5)) or (now - check_start > 5.0) then
            if current_count == 0 then
                sampAddChatMessage('[RMarket] {ff0000}Ошибка: Инвентарь не загрузился', -1)
                App.is_selling_cef = false
            else
                -- Данные готовы, запускаем анализ
                prepareCEFSellQueue()
            end
        else
            -- Продолжаем ждать
            App.tasks.add("smart_inv_wait", debug.getinfo(1).func, 100)
        end
    end, 100)
end

function stopSelling()
    App.is_selling_cef = false
    Data.cef_sell_queue = {}
    App.current_processing_item = nil

    local tasks_to_remove = {"cef_sell_press_alt", "cef_sell_release_alt", "wait_cef_dialog_failsafe", "cef_dialog_timeout", "cef_next_item_delay", "retry_cef_check", "smart_inv_wait", "finish_sell_sequence"}
    for _, t in ipairs(tasks_to_remove) do
        App.tasks.remove_by_name(t)
    end

    sendCEF("inventoryClose")
    
    if sampIsDialogActive() then
        sampCloseCurrentDialogWithButton(0)
    end
    
    syncLiveShopSell()
    
    App.live_shop_active = true
    Marketplace.publish_sell = true
    MarketConfig.SYNC_QUEUED_TIME = 0 
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()

    sampAddChatMessage('[RMarket] {00ff00}Продажа завершена!', -1)
    
    App.win_state[0] = true
end

function startSaleRemoval()
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active or App.is_removing_sale then return end
    startSaleRemoval_Process()
end

function startSingleSaleRemoval(model_id)
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active or App.is_removing_sale then return end
    
    App.single_remove_model = model_id
    App.is_removing_sale = true
    Data.removal_queue = {}
    Data.removal_slots_buffer = {} 
    
    sampAddChatMessage('[RMarket] {ffff00}Открытие лавки для снятия товара...', -1)

    if sampIsDialogActive() and sampGetCurrentDialogId() == 9 then
        sampSendDialogResponse(9, 1, 0, "") 
        waitForSingleShopDataAndRemove()
        return
    end

    App.tasks.add("rem_single_sell_press_alt", function()
        setVirtualKeyDown(0x12, true)
        App.tasks.add("rem_single_sell_release_alt", function() setVirtualKeyDown(0x12, false) end, 100)
    end, 800)
    
    App.tasks.add("rem_sell_timeout", function()
        if App.is_removing_sale then
            stopSaleRemoval()
            sampAddChatMessage('[RMarket] {ff0000}Таймаут операции (диалог не открылся)', -1)
        end
    end, 20000)
end

function waitForSingleShopDataAndRemove()
    local check_start = os.clock()
    local last_count = 0
    local stability_start = os.clock()
    
    App.tasks.add("smart_single_rem_wait", function()
        if not App.is_removing_sale then return end
        
        local current_count = countTable(Data.removal_slots_buffer)
        local now = os.clock()
        
        if current_count ~= last_count then
            last_count = current_count
            stability_start = now
        end
        
        local is_stable = (current_count > 0 and (now - stability_start > 1.0))
        local collection_timeout = (now - check_start > 5.0)
        
        if is_stable or collection_timeout then
            local target_slot = -1
            for slot, item_model in pairs(Data.removal_slots_buffer) do
                if item_model == App.single_remove_model then
                    target_slot = slot
                    break
                end
            end
            
            if target_slot ~= -1 then
                Data.removal_queue = {target_slot}
                sampAddChatMessage('[RMarket] {00ff00}Товар найден. Снимаю...', -1)
                processNextRemovalItem() -- Он сам закроет диалог после 1 клика
            else
                sampAddChatMessage('[RMarket] {ff0000}Товар не найден на витрине.', -1)
                stopSaleRemoval()
            end
        else
            App.tasks.add("smart_single_rem_wait", debug.getinfo(1).func, 100)
        end
    end, 100)
end

function startSaleRemoval_Process()
    App.live_shop_active = true
    Marketplace.enabled = true
    
    App.is_removing_sale = true
    Data.removal_queue = {}
    Data.removal_slots_buffer = {} 
    
    sampAddChatMessage('[RMarket] {ffff00}Запуск снятия товаров...', -1)

    -- Если диалог уже открыт
    if sampIsDialogActive() and sampGetCurrentDialogId() == 9 then
        sampSendDialogResponse(9, 1, 0, "") 
        waitForShopDataAndRemove()
