    end

    -- Если диалога нет, нажимаем ALT
    App.tasks.add("rem_sell_press_alt", function()
        setVirtualKeyDown(0x12, true)
        App.tasks.add("rem_sell_release_alt", function() setVirtualKeyDown(0x12, false) end, 100)
    end, 800) -- Увеличил задержку, чтобы успело закрыться меню настроек
    
    -- Тайм-аут
    App.tasks.add("rem_sell_timeout", function()
        if App.is_removing_sale then
            stopSaleRemoval()
            sampAddChatMessage('[RMarket] {ff0000}Таймаут операции (диалог не открылся)', -1)
        end
    end, 20000)
end

function waitForShopDataAndRemove()
    local check_start = os.clock()
    local last_count = 0
    local stability_start = os.clock()
    
    Data.removal_slots_buffer = {} -- Очищаем перед сбором

    -- Ждем накопления данных
    App.tasks.add("smart_rem_wait", function()
        if not App.is_removing_sale then return end
        
        local current_count = countTable(Data.removal_slots_buffer)
        local now = os.clock()
        
        -- Если количество изменилось (пришли новые пакеты), обновляем таймер
        if current_count ~= last_count then
            last_count = current_count
            stability_start = now
        end
        
        -- Увеличили время ожидания: ждем 1.0 сек тишины после последнего пакета
        -- Или таймаут 5 секунд
        local is_stable = (current_count > 0 and (now - stability_start > 1.0))
        local collection_timeout = (now - check_start > 5.0)
        
        if is_stable or collection_timeout then
            prepareRemovalQueue()
        else
            App.tasks.add("smart_rem_wait", debug.getinfo(1).func, 100)
        end
    end, 100)
end

function prepareRemovalQueue()
    Data.removal_queue = {}
    
    -- Переносим слоты из буфера в очередь
    for slot, available in pairs(Data.removal_slots_buffer) do
        if available then
            table.insert(Data.removal_queue, tonumber(slot))
        end
    end
    
    -- Сортируем от БОЛЬШЕГО к меньшему (безопаснее для инвентаря)
    table.sort(Data.removal_queue, function(a, b) return a > b end)
    
    if #Data.removal_queue > 0 then
        sampAddChatMessage('[RMarket] {00ff00}Найдено товаров: ' .. #Data.removal_queue .. '. Начинаю снятие...', -1)
        processNextRemovalItem()
    else
        sampAddChatMessage('[RMarket] {ffff00}Лавка пуста или данные не загрузились.', -1)
        stopSaleRemoval()
    end
end

function processNextRemovalItem()
    if not App.is_removing_sale then return end
    
    if #Data.removal_queue == 0 then
        -- Небольшая пауза перед завершением
        App.tasks.add("rem_finish_wait", function()
            stopSaleRemoval()
            sampAddChatMessage('[RMarket] {00ff00}Снятие товаров завершено!', -1)
        end, 500)
        return
    end
    
    local slot = table.remove(Data.removal_queue, 1)
    
    -- Отправляем клик по слоту магазина (Type 9)
    local payload = string.format('clickOnBlock|{"slot": %d, "type": 9}', slot)
    sendCEF(payload)
    
    -- Задержка: 10мс минимум, чтобы сервер успевал обрабатывать
    -- Если слишком быстро кликать, сервер может игнорировать запросы
    local delay = math.max(Data.settings.delay_placement or 10, 10)
    
    App.tasks.add("rem_next_delay", processNextRemovalItem, delay)
end

function stopSaleRemoval()
    App.is_removing_sale = false
    App.single_remove_model = nil
    Data.removal_queue = {}
    Data.removal_slots_buffer = {}
    
    local tasks = {"rem_sell_press_alt", "rem_sell_release_alt", "rem_sell_timeout", "smart_rem_wait", "rem_next_delay", "rem_finish_wait"}
    for _, t in ipairs(tasks) do App.tasks.remove_by_name(t) end
    
    sendCEF("inventoryClose")
    
    if not App.single_remove_model then
        if Data.live_shop then Data.live_shop.sell = {} end
        saveLiveShopState()
    end
    
    App.live_shop_active = true
    Marketplace.publish_sell = true
    MarketConfig.SYNC_QUEUED_TIME = 0 
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()
    
    App.win_state[0] = true

end

function startBuyRemoval()
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active or App.is_removing_sale or App.is_removing_buy then return end
    startBuyRemoval_Process()
end

function startBuyRemoval_Process()
    App.live_shop_active = true
    Marketplace.enabled = true
    
    App.is_removing_buy = true
    Data.removal_queue = {}
    Data.removal_slots_buffer = {} 
    Data.removal_retry_count = 0 
    Data.removal_processed_total = 0 -- Обнуляем счетчик
    
    sampAddChatMessage('[RMarket] {ffff00}Запуск снятия скупки...', -1)

    -- Если диалог уже открыт
    if sampIsDialogActive() and sampGetCurrentDialogId() == 9 then
        -- Нажимаем "3. Перестать скупать товар" (List Index 2)
        sampSendDialogResponse(9, 1, 2, "") 
        waitForShopDataAndRemoveBuy()
        return
    end

    -- Если диалога нет, нажимаем ALT
    App.tasks.add("rem_buy_press_alt", function()
        setVirtualKeyDown(0x12, true)
        App.tasks.add("rem_buy_release_alt", function() setVirtualKeyDown(0x12, false) end, 100)
    end, 800)
    
    -- Тайм-аут на открытие (20 сек). Он будет удален в prepareBuyRemovalQueue
    App.tasks.add("rem_buy_timeout", function()
        if App.is_removing_buy then
            stopBuyRemoval()
            sampAddChatMessage('[RMarket] {ff0000}Таймаут операции (слишком долго)', -1)
        end
    end, 20000)
end

function waitForShopDataAndRemoveBuy()
    local check_start = os.clock()
    local last_count = 0
    local stability_start = os.clock()
    
    Data.removal_slots_buffer = {} -- Очищаем буфер

    -- Ждем накопления данных.
    -- Родина отправляет данные кусками. Ждем пока количество перестанет меняться.
    App.tasks.add("smart_rem_buy_wait", function()
        if not App.is_removing_buy then return end
        
        local current_count = countTable(Data.removal_slots_buffer)
        local now = os.clock()
        
        -- Если пришли новые данные, сбрасываем таймер "тишины"
        if current_count ~= last_count then
            last_count = current_count
            stability_start = now
        end
        
        -- УСЛОВИЕ ЗАПУСКА:
        -- 1. Есть данные (>0)
        -- 2. И прошло 1.5 секунды с последнего изменения (чтобы точно всё дошло)
        local is_stable = (current_count > 0 and (now - stability_start > 1.5))
        
        -- Или таймаут 8 секунд
        local collection_timeout = (now - check_start > 8.0)
        
        if is_stable or collection_timeout then
            prepareBuyRemovalQueue()
        else
            App.tasks.add("smart_rem_buy_wait", debug.getinfo(1).func, 100)
        end
    end, 100)
end

function prepareBuyRemovalQueue()
    -- [FIX] ВАЖНО: Отключаем таймер таймаута, так как данные получены и мы начинаем работу
    App.tasks.remove_by_name("rem_buy_timeout") 

    Data.removal_queue = {}
    
    -- Переносим слоты из буфера в очередь
    for slot, available in pairs(Data.removal_slots_buffer) do
        -- available = 1 означает, что в слоте есть товар на скупку
        if available then
            table.insert(Data.removal_queue, tonumber(slot))
        end
    end
    
    -- Сортируем от БОЛЬШЕГО к меньшему (с конца списка)
    table.sort(Data.removal_queue, function(a, b) return a > b end)
    
    if #Data.removal_queue > 0 then
        sampAddChatMessage('[RMarket] {00ff00}Найдено лотов скупки: ' .. #Data.removal_queue .. '. Снимаю...', -1)
        processNextBuyRemovalItem()
    else
        sampAddChatMessage('[RMarket] {ffff00}Список скупки пуст или данные не прогрузились.', -1)
        stopBuyRemoval()
    end
end

function processNextBuyRemovalItem()
    if not App.is_removing_buy then return end
    
    -- Если очередь закончилась
    if #Data.removal_queue == 0 then
        -- Ждем 2 секунды перед финальной проверкой
        App.tasks.add("rem_buy_verify_wait", function()
            local remaining_slots = {}
            -- Проверяем буфер: остались ли слоты, которые сервер не обновил в available=0
            for slot, available in pairs(Data.removal_slots_buffer) do
                if available then 
                    table.insert(remaining_slots, tonumber(slot))
                end
            end
            
            if #remaining_slots > 0 then
                Data.removal_retry_count = (Data.removal_retry_count or 0) + 1
                
                if Data.removal_retry_count > 3 then
                    stopBuyRemoval()
                    sampAddChatMessage('[RMarket] {ff0000}Часть товаров не снялась (лаг сервера). Попробуйте еще раз.', -1)
                    return
                end
                
                -- Перезапускаем очередь с оставшимися слотами
                table.sort(remaining_slots, function(a, b) return a > b end)
                Data.removal_queue = remaining_slots
                Data.removal_processed_total = 0 -- Сбрасываем счетчик пакетов для новой партии
                
                sampAddChatMessage('[RMarket] {ffff00}Дочистка: ' .. #remaining_slots .. ' товаров (Попытка ' .. Data.removal_retry_count .. ')...', -1)
                processNextBuyRemovalItem()
            else
                stopBuyRemoval()
                sampAddChatMessage('[RMarket] {00ff00}Скупка полностью очищена!', -1)
            end
        end, 2000)
        return
    end
    
    local slot = table.remove(Data.removal_queue, 1)
    Data.removal_processed_total = (Data.removal_processed_total or 0) + 1
    
    -- Отправляем клик по слоту магазина (Type 10 = Скупка)
    local payload = string.format('clickOnBlock|{"slot": %d, "type": 10}', slot)
    sendCEF(payload)
    
    -- Базовая задержка 10 мс
    local delay = math.max(Data.settings.delay_placement or 10, 10)
    
    -- [FIX] Анти-флуд пауза: каждые 25 товаров ждем 1.5 секунды
    if Data.removal_processed_total % 25 == 0 then
        delay = 1500 
    end
    
    App.tasks.add("rem_buy_next_delay", processNextBuyRemovalItem, delay)
end

function stopBuyRemoval()
    App.is_removing_buy = false
    Data.removal_queue = {}
    Data.removal_slots_buffer = {}
    
    local tasks = {"rem_buy_press_alt", "rem_buy_release_alt", "rem_buy_timeout", "smart_rem_buy_wait", "rem_buy_next_delay", "rem_buy_finish_wait", "rem_buy_verify_wait"}
    for _, t in ipairs(tasks) do App.tasks.remove_by_name(t) end
    
    sendCEF("inventoryClose")
    
    if Data.live_shop then Data.live_shop.buy = {} end
    saveLiveShopState()
    
    App.live_shop_active = true
    Marketplace.publish_buy = true
    MarketConfig.SYNC_QUEUED_TIME = 0 
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()
    
    App.win_state[0] = true
end

function prepareCEFSellQueue()
    Data.cef_sell_queue = {}
    local inventory_map = {}
    
    -- Собираем физические слоты
    for slot, item_data in pairs(Data.cef_slots_data) do
        if tonumber(item_data.available) == 1 then
            local mid = tonumber(item_data.model_id)
            if mid then
                local raw_amt = tonumber(item_data.amount)
                local real_amount = (raw_amt and raw_amt > 0) and raw_amt or 1
                if not inventory_map[mid] then inventory_map[mid] = {} end
                table.insert(inventory_map[mid], { slot = tonumber(slot), amount = real_amount })
            end
        end
    end
    
    for _, list in pairs(inventory_map) do
        table.sort(list, function(a, b) return a.slot < b.slot end)
    end
    
    local updated_slots_count = 0
    
    for _, sell_item in ipairs(Data.sell_list) do
        local p_check = tonumber(sell_item.price) or 0
        if sell_item.active ~= false and p_check > 0 then
            local target_model = tonumber(sell_item.model_id)
            local found_entry = nil
            
            if inventory_map[target_model] and #inventory_map[target_model] > 0 then
                found_entry = table.remove(inventory_map[target_model], 1)
            end
            
            if found_entry then
                if sell_item.slot ~= found_entry.slot then
                    sell_item.slot = found_entry.slot
                    updated_slots_count = updated_slots_count + 1
                end
                
                local amount_to_sell = tonumber(sell_item.amount) or 1
                if sell_item.auto_max then
                    amount_to_sell = found_entry.amount
                else
                    if amount_to_sell > found_entry.amount then amount_to_sell = found_entry.amount end
                end
                
                if amount_to_sell > 0 then
                    table.insert(Data.cef_sell_queue, {
                        slot = found_entry.slot, 
                        model = target_model, 
                        amount = amount_to_sell, 
                        price = p_check, 
                        name = sell_item.name,
                        retry_count = 0 
                    })
                end
            end
        end
    end
    
    if updated_slots_count > 0 then saveListsConfig(true) end
    
    -- [CORE FIX] Вызываем обновление визуального статуса вручную
    refreshSellListMissingStatus()
    
    if #Data.cef_sell_queue > 0 then
        sampAddChatMessage('[RMarket] {00ff00}Очередь: ' .. #Data.cef_sell_queue .. ' лотов. Начинаю выставление...', -1)
        processNextCEFSellItem()
    else
        sampAddChatMessage('[RMarket] {ff0000}Нет доступных товаров для выставления! Проверьте наличие.', -1)
        App.is_selling_cef = false
        App.live_shop_active = true
    end
end

function processNextCEFSellItem()
    if not App.is_selling_cef then return end
    
    if #Data.cef_sell_queue == 0 then
        App.tasks.add("finish_sell_sequence", function()
             stopSelling()
        end, 800)
        return
    end
    
    if not App.current_processing_item then
        App.current_processing_item = table.remove(Data.cef_sell_queue, 1)
        App.current_sell_item_index = (App.current_sell_item_index or 0) + 1
    end

    local item = App.current_processing_item
    
    if item.retry_count >= 5 then
        sampAddChatMessage(string.format('[RMarket] {ff0000}Не удалось выставить: "%s" (skip)', item.name), -1)
        App.current_processing_item = nil 
        processNextCEFSellItem()
        return
    end

    item.retry_count = item.retry_count + 1
    
    local click_slot = item.slot
    
    local slot_valid = false
    if Data.cef_slots_data[click_slot] then
        local d = Data.cef_slots_data[click_slot]
        if tonumber(d.model_id) == tonumber(item.model) and tonumber(d.available) == 1 then
            slot_valid = true
        end
    end
    
    if not slot_valid then
        for s, d in pairs(Data.cef_slots_data) do
            if tonumber(d.model_id) == tonumber(item.model) and tonumber(d.available) == 1 then
                click_slot = tonumber(s)
                item.slot = click_slot
                slot_valid = true
                break
            end
        end
    end
    
    if not slot_valid then
        App.current_processing_item = nil
        processNextCEFSellItem()
        return
    end

    local payload_click = string.format('clickOnBlock|{"slot": %d, "type": 1}', click_slot)
    sendCEF(payload_click)
    
    App.tasks.add("cef_dialog_timeout", function()
        if App.is_selling_cef and App.current_processing_item == item then
            processNextCEFSellItem() 
        end
    end, 6000)
end

function startBuying(is_remote_start, custom_buy_list) 
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active then return end

    -- Определяем, какой список использовать: временный или из конфига
    local source_list = custom_buy_list or Data.buy_list
    local is_temporary_mode = (custom_buy_list ~= nil)

    local active_count = 0
    
    -- Сбрасываем контекст
    Marketplace.single_buy_context = nil
    
    if is_temporary_mode then
        Marketplace.single_buy_context = {}
        for _, item in ipairs(source_list) do
            Marketplace.single_buy_context[item.name] = true
        end
    end
    
    for i, item in ipairs(source_list) do
        if not item._uid_cache then
            item._uid_cache = tostring(os.clock()) .. "_" .. i .. "_rem"
        end
        if item.active then 
            active_count = active_count + 1 
            
            -- [FIX] Пытаемся восстановить ID, если он потерян (-1)
            -- Это предотвращает ошибки поиска по названию
            if (not item.index or item.index == -1) and item.name and Data.item_names_reversed then
                local clean = cleanItemNameKey(item.name)
                local found_id = Data.item_names_reversed[clean]
                if found_id then 
                    item.index = found_id 
                    print("[RMarket] ID восстановлен для: " .. item.name .. " -> " .. found_id)
                end
            end
        end
    end

    if active_count == 0 then
        sampAddChatMessage('[RMarket] {ff0000}Нет активных товаров', -1)
        return
    end

    App.live_shop_active = true
    Marketplace.enabled = true
    Marketplace.is_cleared = false
    Marketplace.publish_buy = true
    Marketplace.LavkaUid = os.time()
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()

    if not is_temporary_mode then
        -- Синхронизация буферов (логика как была)
        if is_remote_start then
            for i, item in ipairs(Data.buy_list) do
                local uid = item._uid_cache
                local buf_key_price = "bp_" .. uid
                local buf_key_amount = "ba_" .. uid
                Buffers.buy_input_buffers[buf_key_price] = imgui.new.char[32](tostring(item.price or 0))
                Buffers.buy_input_buffers[buf_key_amount] = imgui.new.char[32](tostring(item.amount or 0))
            end
        else
            for i, item in ipairs(Data.buy_list) do
                local uid = item._uid_cache or (i .. "_b") 
                local buf_key_price = "bp_" .. uid
                local buf_key_amount = "ba_" .. uid
                if Buffers.buy_input_buffers[buf_key_price] then
                    local price_str = ffi.string(Buffers.buy_input_buffers[buf_key_price])
                    item.price = tonumber(price_str) or 0
                end
                if Buffers.buy_input_buffers[buf_key_amount] then
                    local amount_str = ffi.string(Buffers.buy_input_buffers[buf_key_amount])
                    item.amount = tonumber(amount_str) or 0
                end
            end
        end
        saveListsConfig()
    end

    State.buying = {
        active = true, 
        stage = 'waiting_menu',
        current_item_index = 1, 
        items_to_buy = {}, 
        last_search_name = nil,
        waiting_for_alt = false
    }

    local skipped_count = 0

    for _, item in ipairs(source_list) do
        if item.active then
            local is_acc = isAccessory(item.name)
            if (item.price and item.price > 0) then
                if is_acc or (item.amount and item.amount > 0) then
                    -- Строгая проверка наличия индекса
                    local target_idx = tonumber(item.index)
                    if not target_idx or target_idx <= 0 then
                        -- Пропускаем молча, чтобы не спамить в чат. Считаем только товары с хоть каким-то именем.
                        if item.name and item.name:match("%S") then
                            skipped_count = skipped_count + 1
                            print(string.format('[RMarket] Warning: Skipped "%s" - missing ID.', item.name))
                        end
                    else
                        table.insert(State.buying.items_to_buy, {
                            name = item.name,
                            index = target_idx,
                            amount = math.floor(tonumber(item.amount) or 0),
                            price = math.floor(tonumber(item.price) or 0)
                        })
                    end
                end
            end
        end
    end
    
    if skipped_count > 0 then
        addToastNotification("Пропущено товаров: " .. skipped_count .. " (Нет ID)", "warning", 4.0)
    end

    if not State.buying.items_to_buy or #State.buying.items_to_buy == 0 then
        sampAddChatMessage('[RMarket] {ff0000}Ошибка: Нет активных товаров с указанным ID, ценой и количеством', -1)
        State.buying.active = false
        return
    end

    sampAddChatMessage(string.format('[RMarket] {ffff00}Скупка %d товаров...', #State.buying.items_to_buy), -1)

    lua_thread.create(function()
        wait(500)
        setVirtualKeyDown(0x12, true)
        wait(150)
        setVirtualKeyDown(0x12, false)
    end)

    App.tasks.add("wait_buy_start", function()
        if State.buying.active and State.buying.stage == 'waiting_menu' then
            State.buying.waiting_for_alt = true
            sampAddChatMessage('[RMarket] {ffff00}Откройте лавку вручную (ALT)', -1)
        end
    end, 2000)
end

function startRealShopScan()
    if App.is_scanning or State.buying.active or State.real_shop_scan.active then return end
    
    State.real_shop_scan.active = true
    State.real_shop_scan.step = 1
    State.real_shop_scan.waiting_dialog = false
    
    sampAddChatMessage('[RMarket] {ffff00}Обновление списка...', -1)
    
    
    lua_thread.create(function()
        setVirtualKeyDown(0x12, true) 
        wait(100)
        setVirtualKeyDown(0x12, false) 
    end)
    
    
    App.tasks.add("wait_real_shop_dialog", function()
        if State.real_shop_scan.active and not State.real_shop_scan.waiting_dialog then
            sampAddChatMessage('[RMarket] {ffff00}Откройте меню лавки (ALT)', -1)
            State.real_shop_scan.waiting_dialog = true
        end
    end, 2000)
    
    
    App.tasks.add("real_shop_timeout", function()
        if State.real_shop_scan.active then
            State.real_shop_scan.active = false
            sampAddChatMessage('[RMarket] {ff0000}Таймаут', -1)
        end
    end, 15000)
end

function parseRestorationDialog(text)
    local sell_items = {}
    local buy_items = {}
    local current_mode = nil -- "sell" or "buy"
    
    -- Очищаем текст от цветов
    local clean_text = cleanTextColors(text)
    
    for line in clean_text:gmatch("[^\r\n]+") do
        -- Определяем секцию
        if line:find("Продажа:") then
            current_mode = "sell"
        elseif line:find("Скупка:") then
            current_mode = "buy"
        else
            -- Парсим строку вида: "Название товара, 12345 руб."
            -- Паттерн ищет всё до запятой как имя, и цифры перед "руб." как цену
            local name_part, price_part = line:match("^(.-),%s*(%d+)%s*руб%.")
            
            if name_part and price_part then
                -- Дополнительная очистка имени (на всякий случай)
                local name = cleanItemName(name_part)
                local price = tonumber(price_part) or 0
                
                -- Ищем ID предмета в нашей базе (для корректной работы конфигов)
                local model_id = -1
                local item_idx = -1
                
                if Data.item_names_reversed then
                    local clean_key = cleanItemNameKey(name)
                    if Data.item_names_reversed[clean_key] then
                        item_idx = Data.item_names_reversed[clean_key]
                        model_id = item_idx
                    end
                end

                local item_entry = {
                    name = name,
                    price = price,
                    amount = 1, -- При восстановлении кол-во неизвестно, ставим 1
                    model_id = model_id,
                    index = item_idx,
                    active = true,
                    auto_max = true -- Для продажи включаем авто-подгон под инвентарь
                }
                
                if current_mode == "sell" then
                    table.insert(sell_items, item_entry)
                elseif current_mode == "buy" then
                    -- Для скупки amount не важен, если не аксессуар, но поставим 1
                    table.insert(buy_items, item_entry)
                end
            end
        end
    end
    
    return sell_items, buy_items
end

function syncLiveShopSell()
    if not Data.live_shop then Data.live_shop = { sell = {}, buy = {} } end
    Data.live_shop.sell = {}
    
    local slot_idx = 1
    for _, item in ipairs(Data.sell_list) do
        if item.active and not item.missing and (tonumber(item.price) or 0) > 0 then
            Data.live_shop.sell[slot_idx] = {
                name = item.name,
                price = tonumber(item.price) or 0,
                amount = tonumber(item.amount) or 1,
                model_id = tonumber(item.model_id) or -1
            }
            slot_idx = slot_idx + 1
        end
    end
    saveLiveShopState()
end

function syncLiveShopBuy()
    if not State.buying or not State.buying.items_to_buy then return end
    if not Data.live_shop then Data.live_shop = { sell = {}, buy = {} } end
    
    Data.live_shop.buy = {} 

    local processed_count = State.buying.current_item_index - 1
    if processed_count > #State.buying.items_to_buy then
        processed_count = #State.buying.items_to_buy
    end

    for i = 1, processed_count do
        local item = State.buying.items_to_buy[i]
        if item then
            local display_amount = tonumber(item.amount) or 1
            if isAccessory(item.name) then display_amount = 1 end
            if display_amount < 1 then display_amount = 1 end

            Data.live_shop.buy[i] = {
                name = item.name,
                price = tonumber(item.price) or 0,
                amount = display_amount,
                model_id = tonumber(item.index) or -1
            }
        end
    end
    saveLiveShopState()
end

function stopBuying()
    State.buying.active = false
    App.live_shop_active = true

    syncLiveShopBuy() -- Синхронизируем список до остановки

    MarketConfig.SYNC_QUEUED_TIME = 0 -- [FIX RACE CONDITION] Сброс таймера антифлуда
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()

    local tasks_to_clear = {"wait_buy_start", "wait_buy_items_dialog", "wait_buy_name_dialog", "wait_buy_select_dialog", "wait_buy_price_dialog", "wait_buy_next_item", "wait_buy_finish"}
    for _, t in ipairs(tasks_to_clear) do
        App.tasks.remove_by_name(t)
    end
    
    sampAddChatMessage('[RMarket] {ffff00}Скупка остановлена', -1)
end

function finishBuying()
    State.buying.active = false
    App.live_shop_active = true
    
    syncLiveShopBuy() -- Синхронизируем успешный список
    
    MarketConfig.SYNC_QUEUED_TIME = 0 -- [FIX RACE CONDITION] Сброс таймера антифлуда
    MarketConfig.LAST_SYNC = 0
    PrepareMarketplaceData()
    
    local tasks_to_clear = {"wait_buy_start", "wait_buy_items_dialog", "wait_buy_name_dialog", "wait_buy_select_dialog", "wait_buy_price_dialog", "wait_buy_next_item", "wait_buy_finish"}
    for _, t in ipairs(tasks_to_clear) do App.tasks.remove_by_name(t) end
    
    sampAddChatMessage('[RMarket] {00ff00}Скупка завершена', -1)
end

function events.onShowDialog(id, style, title, b1, b2, text)
    local clean_title = cleanTextColors(title)
    local clean_text  = cleanTextColors(text)
    local is_modified = false

    -- [NEW] ПЕРЕХВАТ ИНФОРМАЦИИ О ПРЕДМЕТЕ (ОБЫЧНЫЙ ДИАЛОГ)
    if clean_title:find("Информация о предмете") then
        local item_name = parseItemNameFromModal(text)
        if item_name and item_name ~= "" then
            showItemPriceOverlay(item_name)
        end
    end

    -- [NEW] ПЕРЕХВАТ ДИАЛОГА ПРОДАЖИ НА АВТОБАЗАРЕ
    if id == 148 and style == 1 and clean_text:find("Автобазар забирает") then
        App.show_car_sell_dialog_overlay = true
        -- Очищаем поиск при новом открытии диалога
        imgui.StrCopy(Buffers.car_sell_search, "")
    end

    -- [NEW] ПЕРЕХВАТ НАЗВАНИЯ БАГАЖНИКА / ШКАФА
    if clean_title:find("Багажник") then
        App.current_open_trunk = clean_title:match("Багажник%s+(.*)")
    elseif clean_title:find("Шкаф") then
        -- Захватываем всё после слова Шкаф, либо оставляем просто "Шкаф"
        App.current_open_trunk = clean_title:match("Шкаф%s+(.*)") or "Шкаф"
    end

    if App.current_open_trunk then
        -- Очищаем от возможных пробелов по краям
        App.current_open_trunk = App.current_open_trunk:gsub("^%s*(.-)%s*$", "%1")
    end

    if State.inventory_switch_active then
        local mode = State.inventory_switch_mode
        if id == 731 or id == 1191 then
            if State.restoration_finished then
                sampSendDialogResponse(id, 0, -1, "")
                State.inventory_switch_active = false
                State.restoration_finished = false
                if mode == "enabling" then
                    App.tasks.add("post_switch_action", function()
                        if State.switch_context == "remove" then startSaleRemoval_Process()
                        elseif State.switch_context == "remove_buy" then startBuyRemoval_Process()
                        else startCEFSelling_Process() end
                        State.switch_context = nil
                    end, 600)
                elseif mode == "disabling" then
                    sampAddChatMessage('[RMarket] {00ff00}Старый инвентарь возвращен', -1)
                end
                return false
            end
            local list_idx = -1
            local current_idx = 0
            for line in text:gmatch("[^\r\n]+") do
                local c_line = line:gsub("%[.-%]", ""):gsub("{.-}", ""):gsub("%s+", "")
                if c_line:find("Настройкиинвентаря") then 
                    list_idx = (style == 5 and current_idx - 1) or current_idx 
                    break 
                end
                current_idx = current_idx + 1
            end
            if list_idx ~= -1 then
                sampSendDialogResponse(id, 1, list_idx, "")
                return false
            end
        end

        if id == 734 or id == 1190 then
            local list_idx = -1
            local current_idx = 0
            local is_enabled = false
            local found = false
            for line in text:gmatch("[^\r\n]+") do
                local c_line = line:gsub("%[.-%]", ""):gsub("{.-}", ""):gsub("%s+", "")
                if c_line:find("Новыйинвентарь") or c_line:find("НовыйCEFинвентарь") then
                    list_idx = (style == 5 and current_idx - 1) or current_idx; found = true
                    if c_line:find("Включено") or c_line:find("Включен") then is_enabled = true end
                    break
                end
                current_idx = current_idx + 1
            end
            if found then
                if mode == "enabling" then
                    if not is_enabled then
                        sampSendDialogResponse(id, 1, list_idx, "")
                        State.restoration_finished = true
                    else
                        sampSendDialogResponse(id, 0, -1, "")
                        State.inventory_switch_active = false
                        startCEFSelling_Process()
                    end
                elseif mode == "disabling" then
                    if is_enabled then
                        sampSendDialogResponse(id, 1, list_idx, "")
                        State.restoration_finished = true
                    else
                        sampSendDialogResponse(id, 0, -1, "")
                        State.inventory_switch_active = false
                        State.restoration_finished = false
                        sampAddChatMessage('[RMarket] {00ff00}Старый инвентарь уже активен', -1)
                        App.win_state[0] = true
                    end
                end
                return false
            end
        end
    end

    if App.is_removing_buy and (id == 9 or title:find("Управление лавкой")) then
        sampSendDialogResponse(id, 1, 2, "")
        waitForShopDataAndRemoveBuy()
        return false
    end

    if App.is_selling_cef and (id == 9 or title:find("Управление лавкой")) then
        sampSendDialogResponse(id, 1, 0, "")
        if #Data.cef_sell_queue > 0 then
            waitForInventoryAndStart(function() processNextCEFSellItem() end)
        else
            waitForInventoryAndStart(prepareCEFSellQueue)
        end
        return false
    end

    -- [ФИКС] Обработка диалога ввода цены (240), который сервер перевел на обычные SA-MP диалоги
    if App.is_selling_cef and App.current_processing_item and id == 240 then
        App.tasks.remove_by_name("cef_dialog_timeout")

        local item = App.current_processing_item
        local clean_body = cleanTextColors(text)
        local body_lower = clean_body:lower()

        -- Парсинг заточки и переноса
        local upgrade_lvl = clean_body:match("Улучшение:%s*(%d+)%s*/") or clean_body:match("Заточка:%s*(%d+)")
        local source_acc = clean_body:match("Исходный аксессуар:%s*([^\r\n]+)")

        local suffix = ""
        if upgrade_lvl and tonumber(upgrade_lvl) > 0 then
            suffix = suffix .. " +" .. upgrade_lvl
        end
        if source_acc then
            source_acc = source_acc:match("^%s*(.-)%s*$")
            if source_acc ~= "" then
                suffix = suffix .. " (Перенос: " .. source_acc .. ")"
            end
        end

        if suffix ~= "" then
            if not item.name:find(suffix, 1, true) then
                item.name = item.name .. suffix
            end
            if Data.sell_list then
                for _, s_item in ipairs(Data.sell_list) do
                    if s_item.slot == item.slot and s_item.model_id == item.model then
                        if not s_item.name:find(suffix, 1, true) then
                            s_item.name = s_item.name .. suffix
                            s_item._u8_display_name = nil
                            s_item._price_check_time = 0
                        end
                        break
                    end
                end
                saveListsConfig()
            end
        end

        -- Определение формата ввода (с количеством или только цена)
        local needs_comma = false
        if body_lower:find("запятую") or body_lower:find("введите количество") or body_lower:find("укажите количество") then
            needs_comma = true
        end

        local safe_price = tonumber(item.price) or 0
        local safe_amount = math.floor(tonumber(item.amount) or 1)

        local input_text = string.format("%.0f", safe_price)

        if needs_comma then
            local stack_in_dialog = clean_body:match("стаке:%s*(%d+)") or clean_body:match("выставить%s*(%d+)%s*шт")
            if stack_in_dialog then
                local real_stack = tonumber(stack_in_dialog)
                if real_stack and real_stack > 1 then
                    if safe_amount == 1 then safe_amount = real_stack
                    elseif safe_amount > real_stack then safe_amount = real_stack end
                end
            end
            input_text = string.format("%d,%.0f", safe_amount, safe_price)
        end

        -- Отправляем стандартный ответ на диалог вместо CEF пакета
        sampSendDialogResponse(240, 1, -1, input_text)

        App.current_processing_item = nil
        -- [ФИКС СКОРОСТИ] Ограничение снижено до 10мс.
        local delay = math.max(Data.settings.delay_placement or 10, 10)

        App.tasks.add("cef_next_item_delay", processNextCEFSellItem, delay)
        return false -- Полностью скрывает диалог от пользователя
    end

    if id == 913 then
        local sell, buy = parseRestorationDialog(text)
        State.restoration.pending_sell = sell
        State.restoration.pending_buy = buy
        State.restoration.waiting_confirmation = false
        return
    end

    if clean_title:find("Статистика игрока") or clean_text:find("Текущее состояние счета") then
        local found_nick = nil
        local found_acc_id = 0
        for line in clean_text:gmatch("[^\r\n]+") do
            if line:find("Имя %(en%.%):") then
                local nick_match = line:match("Имя %(en%.%):%s*([%w_]+)")
                if nick_match then found_nick = nick_match end
            end
            if line:find("Номер аккаунта:") then
                local id_match = line:match("Номер аккаунта:%s*(%d+)")
                if id_match then found_acc_id = tonumber(id_match) end
            end
        end

        if found_nick and LOCAL_PLAYER_NICK ~= found_nick then
            LOCAL_PLAYER_NICK = found_nick
            Data.settings.last_nickname = found_nick
            saveSettings(true)
        end
        if found_acc_id > 0 and LOCAL_ACCOUNT_ID ~= found_acc_id then
            LOCAL_ACCOUNT_ID = found_acc_id
            if Data.settings.telegram_token and Data.settings.telegram_token ~= "" then
                checkVipStatus(Data.settings.telegram_token)
            end
        end

        local stats = parseStatsDialog(text)
        if stats and stats.vip then
            local vip_str = u8:decode(stats.vip):lower()
            local is_vip_active = (vip_str ~= "нет" and vip_str ~= "none" and vip_str ~= "")
            Data.is_vip = is_vip_active 
            
            if is_vip_active then
                local my_vip_level = Data.vip_months or 1 
                if LOCAL_PLAYER_NICK then
                    Data.vip_users_cache[LOCAL_PLAYER_NICK] = my_vip_level
                    Data.vip_users_cache[LOCAL_PLAYER_NICK:gsub("_", " ")] = my_vip_level
                end
                if LOCAL_PLAYER_NICK_RUS then
                    local clean_rus = LOCAL_PLAYER_NICK_RUS:match("^%s*(.-)%s*$")
                    if clean_rus then 
                        Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS] = my_vip_level
                        Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS:gsub(" ", "_")] = my_vip_level
                        Data.vip_users_cache[clean_rus] = my_vip_level
                    end
                end
            else
                if LOCAL_PLAYER_NICK then
                    Data.vip_users_cache[LOCAL_PLAYER_NICK] = nil
                    Data.vip_users_cache[LOCAL_PLAYER_NICK:gsub("_", " ")] = nil
                end
                if LOCAL_PLAYER_NICK_RUS then
                    Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS] = nil
                    Data.vip_users_cache[LOCAL_PLAYER_NICK_RUS:gsub(" ", "_")] = nil
                end
            end
            saveJsonFile(FILES.VIP_CACHE, Data.vip_users_cache)
        end

        if stats and stats.level and stats.level > 0 then
            if found_acc_id > 0 then stats.account_id = found_acc_id end
            sendStatsToAPI(stats)
        end
        
        if State.stats_requested_by_script then
            State.stats_requested_by_script = false
            if App.pending_menu_open then
                App.pending_menu_open = false
                App.win_state[0] = true
            end
            return false
        end
        return
    end

    if (id == 1295 or id == 1296) and Data.auto_pr.pending_vr_response then
        sampSendDialogResponse(id, 1, -1, "")
        if id == 1295 then
            Data.auto_pr.pending_vr_response = false
            App.tasks.remove_by_name("vr_dialog_failsafe")
        end
        return false
    end

    if App.is_removing_sale and (id == 9 or title:find("Управление лавкой")) then
        sampSendDialogResponse(id, 1, 0, "")
        if App.single_remove_model then waitForSingleShopDataAndRemove() else waitForShopDataAndRemove() end
        return false
    end

    if (id == 9 or id == 3040) and (title:find("Управление лавкой") or title:find("Лавка")) and not (State.real_shop_scan and State.real_shop_scan.active) then
        App.live_shop_active = true
        local line_count = 0
        for _ in text:gmatch("[^\r\n]+") do line_count = line_count + 1 end
        State.dialog_9_line_count = line_count
        text = text .. "\n" .. "{00ff00}[МЕНЮ] {ffffff}RMarket"
        is_modified = true
    end

    if State.real_shop_scan and State.real_shop_scan.active then
        if id == 9 then
            if State.real_shop_scan.step == 1 then
                State.real_shop_scan.waiting_dialog = true
                App.tasks.remove_by_name("wait_real_shop_dialog")
                local list_index = -1
                local current_idx = 0
                for line in text:gmatch("[^\r\n]+") do
                    if line:find("Мои товары") then list_index = current_idx break end
                    current_idx = current_idx + 1
                end
                if list_index ~= -1 then
                    State.real_shop_scan.step = 2
                    sampSendDialogResponse(id, 1, list_index, "")
                    return false
                else
                    sampAddChatMessage('[RMarket] {ff0000}Ошибка: "Мои товары" не найден', -1)
                    State.real_shop_scan.active = false
                    return
                end
            elseif State.real_shop_scan.step == 3 then
                State.real_shop_scan.active = false
                App.tasks.remove_by_name("real_shop_timeout")
                sampSendDialogResponse(id, 0, -1, "")
                sampAddChatMessage('[RMarket] {00ff00}Лавка обновлена', -1)
                return false
            end
        end
        if id == 211 and State.real_shop_scan.step == 2 then
            local sell, buy = parseRealShopDialog(text)
            Data.live_shop.sell = {}
            for i, v in ipairs(sell) do Data.live_shop.sell[i] = v end
            Data.live_shop.buy = {}
            for i, v in ipairs(buy) do Data.live_shop.buy[i] = v end
            saveLiveShopState()
            MarketConfig.LAST_SYNC = 0 
            State.real_shop_scan.step = 3
            sampSendDialogResponse(id, 1, -1, "")
            return false
        end
    end

    if State.inventory_scan and State.inventory_scan.active then
        App.tasks.remove_by_name("scan_retry_wait")
        if State.inventory_scan.waiting_for_packets then
            sampSendDialogResponse(id, 0, -1, "")
            return false
        end
        if id == 731 or id == 1191 then
            local list_idx = -1
            local current_idx = 0
            for line in text:gmatch("[^\r\n]+") do
                local c_line = line:gsub("%[.-%]", ""):gsub("{.-}", ""):gsub("%s+", "")
                if c_line:find("Настройкиинвентаря") then 
                    list_idx = (style == 5 and current_idx - 1) or current_idx 
                    break 
                end
                current_idx = current_idx + 1
            end
            if list_idx ~= -1 then
                sampSendDialogResponse(id, 1, list_idx, "")
                return false
            else
                sampAddChatMessage('[RMarket] {ff0000}Ошибка: Пункт настроек инвентаря не найден', -1)
                finishScanningProcess()
                return
            end
        end
        if id == 734 or id == 1190 then
            local list_idx = -1
            local current_idx = 0
            local is_enabled = false
            local found = false
            for line in text:gmatch("[^\r\n]+") do
                local c_line = line:gsub("%[.-%]", ""):gsub("{.-}", ""):gsub("%s+", "")
                if c_line:find("Новыйинвентарь") or c_line:find("НовыйCEFинвентарь") then
                    list_idx = (style == 5 and current_idx - 1) or current_idx; found = true
                    if c_line:find("Включено") or c_line:find("Включен") then is_enabled = true end
                    break
                end
                current_idx = current_idx + 1
            end
            if not found then
                sampAddChatMessage('[RMarket] {ff0000}Ошибка: "Новый инвентарь" не найден', -1)
                finishScanningProcess()
                return
            end
            if is_enabled then
                sampAddChatMessage('[RMarket] {ffff00}Перезагрузка инвентаря...', -1)
                sampSendDialogResponse(id, 1, list_idx, "")
            else
                sampAddChatMessage('[RMarket] {00ff00}Включение инвентаря', -1)
                sampSendDialogResponse(id, 1, list_idx, "")
                State.inventory_scan.waiting_for_packets = true
                State.inventory_scan.has_received_data = false
                State.inventory_scan.start_wait_time = os.clock()
                State.inventory_scan.last_packet_time = os.clock()
                App.tasks.add("collect_inventory_data", function()
                    if not App.is_scanning then return end
                    local now = os.clock()
                    local time_since_last = now - State.inventory_scan.last_packet_time
                    local time_total = now - State.inventory_scan.start_wait_time
                    if State.inventory_scan.has_received_data and time_since_last > 0.6 then
                        finishScanningProcess()
                    elseif time_total > 6.0 then
                        if State.inventory_scan.has_received_data then finishScanningProcess()
                        else sampAddChatMessage('[RMarket] {ff0000}Таймаут инвентаря', -1) finishScanningProcess() end
                    else
                        App.tasks.add("collect_inventory_data", debug.getinfo(1).func, 100)
                    end
                end, 200)
            end
            return false
        end
    end

    -- [АВТО-НАЗВАНИЕ ЛАВКИ И АВТО-ЦВЕТ (RODINA & ARIZONA)]
    if title:find("Название лавки") or id == 8 or id == 3020 then
        if Buffers.settings.auto_name[0] then
            local name_utf8 = ffi.string(Buffers.settings.shop_name)
            if name_utf8 ~= "" then
                lua_thread.create(function()
                    wait(math.random(300, 500))
                    local name_cp1251 = u8:decode(name_utf8)
                    sampSendDialogResponse(id, 1, 0, name_cp1251)
                    sampAddChatMessage(string.format('[RMarket] {00ff00}Лавка: "%s"', name_cp1251), -1)
                end)
                return false
            end
        end
    end

    if State.buying.active then
        State.buying.waiting_for_alt = false
        local tasks_to_clear = {"wait_buy_start", "wait_buy_items_dialog", "wait_buy_name_dialog", "wait_buy_select_dialog", "wait_buy_price_dialog", "wait_buy_next_item", "wait_buy_finish"}
        for _, t in ipairs(tasks_to_clear) do App.tasks.remove_by_name(t) end
        
        local is_finished = State.buying.current_item_index > #State.buying.items_to_buy
        local user_delay = math.max(Data.settings.delay_placement or 10, 10)

        if id == 9 or title:find("Управление лавкой") then
            if is_finished then
                finishBuying()
                sampSendDialogResponse(id, 0, -1, "")
                sampAddChatMessage('[RMarket] {00ff00}Товары выставлены', -1)
            else
                lua_thread.create(function() wait(user_delay) sampSendDialogResponse(id, 1, 1, "") end)
            end
            return false
        end

        if (id == 10 or title:find("Скупка")) and text:find("Поиск предмета по названию") then
            lua_thread.create(function()
                wait(user_delay)
                if is_finished then sampSendDialogResponse(id, 0, -1, "")
                else sampSendDialogResponse(id, 1, 0, "") end
            end)
            return false
        end

        if id == 909 or (style == 1 and (title:find("Поиск") or title:find("Скупка") or text:find("введите") or text:find("название") or text:find("индекс"))) then
            if not text:find("цену") and not text:find("штук") and not text:find("количество") then
                lua_thread.create(function()
                    wait(user_delay)
                    if is_finished then
                        sampSendDialogResponse(id, 0, -1, "")
                    else
                        local item = State.buying.items_to_buy[State.buying.current_item_index]
                        if item and item.index and tonumber(item.index) > 0 then
                            -- Вводим строго ИНДЕКС
                            local query = tostring(item.index)
                            State.buying.last_search_name = query
                            sampSendDialogResponse(id, 1, -1, query)
                        else
                            sampAddChatMessage(string.format('[RMarket] {ff0000}Критическая ошибка: Нет ID у товара "%s"', item and u8:decode(item.name) or "Unknown"), -1)
                            State.buying.current_item_index = State.buying.current_item_index + 1
                            sampSendDialogResponse(id, 0, -1, "")
                        end
                    end
                end)
                return false
            end
        end

        if id == 910 or (style == 2 and not text:find("Поиск предмета по названию") and not title:find("Управление лавкой")) then
            local item = State.buying.items_to_buy[State.buying.current_item_index]
            local target_idx = -1
            
            if item and item.index then
                local search_id_str = "[" .. tostring(item.index) .. "]"
                local current_idx = 0
                
                -- Ищем строку, содержащую нужный нам ID в квадратных скобках
                for line in text:gmatch("[^\r\n]+") do
                    local clean_line = cleanTextColors(line)
                    if clean_line:find(search_id_str, 1, true) then
                        target_idx = current_idx
                        break
                    end
                    current_idx = current_idx + 1
                end
                
                -- Резервный вариант: если по ID не нашло (что странно), но список не пуст и не пишет об ошибке, берем 1-й элемент
                if target_idx == -1 and text ~= "" and not text:find("ничего не найдено", 1, true) then
                    target_idx = 0
                end
            end

            lua_thread.create(function()
                wait(user_delay)
                if target_idx ~= -1 then
                    sampSendDialogResponse(id, 1, target_idx, "")
                else
                    local msg = item and u8:decode(item.name) or "Unknown"
                    sampAddChatMessage('[RMarket] {ff0000}По ID товар не найден сервером: ' .. msg, -1)
                    State.buying.current_item_index = State.buying.current_item_index + 1
                    sampSendDialogResponse(id, 0, -1, "")
                end
            end)
            return false
        end

        if id == 11 or (style == 1 and (text:find("цену") or text:find("штук") or text:find("количество") or text:find("стаке"))) then
            local item = State.buying.items_to_buy[State.buying.current_item_index]
            if item then
                local input
                if isAccessory(item.name) then
                    local color = math.max(0, math.floor(item.amount))
                    input = string.format("%d,%d", item.price, color)
                else
                    input = string.format("%d,%d", math.floor(item.amount), math.floor(item.price))
                end
                
                lua_thread.create(function()
                    wait(user_delay)
                    sampSendDialogResponse(id, 1, -1, input)
                    State.buying.current_item_index = State.buying.current_item_index + 1
                end)
            end
            return false
        end
        return false
    end

    if is_modified then
        return {id, style, title, b1, b2, text}
    end
end

function events.onSendDialogResponse(id, button, list, input)
    -- [NEW] Скрываем оверлей при закрытии диалога продажи авто
    if id == 148 then
        App.show_car_sell_dialog_overlay = false
    end
    
    -- Скрываем оверлей средних цен при закрытии диалога
    if App.item_price_overlay.active then
        App.item_price_overlay.active = false
    end

    if id == 15 then
        Data.remote_shop_items = {}
        Data.last_remote_packet = os.clock()
    end

    if id == 9 and button == 1 then
        if list == State.dialog_9_line_count then
            lua_thread.create(function()
                if LOCAL_PLAYER_NICK == nil or LOCAL_ACCOUNT_ID == 0 then
                    sampAddChatMessage('[RMarket] {FFFF00}Авторизация...', -1)
                    Data.vip_checked = false 
                    State.stats_requested_by_script = true
                    App.pending_menu_open = true
                    sampSendChat("/stats")
                else
                    if not Data.vip_checked and Data.settings.telegram_token ~= "" then
                        checkVipStatus(Data.settings.telegram_token)
                    end
                    App.win_state[0] = not App.win_state[0]
                    sampAddChatMessage('[RMarket] {00ff00}Меню ' .. (App.win_state[0] and '{00ff00}открыто' or '{ff0000}закрыто'), -1)
                end
            end)
            return false 
        end
    end
    
    if id == 913 then
        if button == 1 then 
            State.restoration.waiting_confirmation = true
        else
            State.restoration.pending_sell = {}
            State.restoration.pending_buy = {}
            State.restoration.waiting_confirmation = false
        end
    end
end

local font_fa_big = nil

function loadSettingsSyncSafe()
    local path = PATHS.SETTINGS
    if not doesFileExist(path) then return nil end
    local f = io.open(path, "r")
    if not f then return nil end
    local content = f:read("*a")
    f:close()
    if not content or #content == 0 then return nil end
    local ok, res = pcall(json.decode, content)
    return ok and res or nil
end

local glyph_ranges_cyrillic = nil
local icon_ranges_fa = nil

-- ============================================================================
-- [ОПТИМИЗАЦИЯ КЭША] Выносим ВСЕ Си-объекты и конфигурации из тела функции.
-- Создаем их строго ОДИН раз при загрузке скрипта, предотвращая утечки памяти.
-- ============================================================================
local font_config       = imgui.ImFontConfig()
local icon_config       = imgui.ImFontConfig()
local large_config      = imgui.ImFontConfig()
local big_icon_config   = imgui.ImFontConfig()

-- Инициализируем общие статические параметры для всех конфигураций шрифтов
font_config.MergeMode,   font_config.PixelSnapH,   font_config.OversampleH,   font_config.OversampleV   = false, true, 1, 1
large_config.MergeMode,  large_config.PixelSnapH,  large_config.OversampleH,  large_config.OversampleV  = false, true, 1, 1
icon_config.MergeMode,   icon_config.PixelSnapH,   icon_config.OversampleH,   icon_config.OversampleV   = true,  true, 1, 1
big_icon_config.MergeMode, big_icon_config.PixelSnapH, big_icon_config.OversampleH, big_icon_config.OversampleV = true,  true, 1, 1

-- Смещение иконок (создаем ImVec2 один раз на всю сессию игры)
icon_config.GlyphOffset = imgui.ImVec2(0, 1)
big_icon_config.GlyphOffset = imgui.ImVec2(0, 2)

-- Кэшируем диапазоны символов и Base85 данные до инициализации
local cyrillic_ranges = nil
local icon_ranges_fa  = imgui.new.ImWchar[3](fa.min_range, fa.max_range, 0)
local fa_base85_data  = fa.get_font_data_base85('solid')

-- Пути к системным шрифтам Windows (выносим из функции, так как переменная окружения не меняется)
local windir = os.getenv("WINDIR") or "C:\\Windows"
local path_segoe_bold  = windir .. "\\Fonts\\segoeuib.ttf"
local path_arial_bold  = windir .. "\\Fonts\\arialbd.ttf"
local path_segoe_black = windir .. "\\Fonts\\seguibl.ttf"
local path_arial_black = windir .. "\\Fonts\\ariblk.ttf"

-- ============================================================================
-- ОПТИМИЗИРОВАННЫЙ ИНИЦИАЛИЗАТОР MIMGUI
-- ============================================================================
imgui.OnInitialize(function()
    local io = imgui.GetIO()
    io.IniFilename = nil
    
    -- Генерируем U32 цвета только если они еще не были сгенерированы
    for _, theme in pairs(THEME_COLORS) do
        for key, vec4 in pairs(theme) do
            if type(vec4) == "cdata" and not key:find("_u32") then
                local u32_key = key .. "_u32"
                if not theme[u32_key] then
                    theme[u32_key] = imgui.ColorConvertFloat4ToU32(vec4)
                end
            end
        end
    end
    
    -- Получаем текущий масштаб интерфейса
    local pre_settings = loadSettingsSyncSafe()
    local scale_mode = (pre_settings and pre_settings.ui_scale_mode) or 1
    local scale = SCALE_MODES[scale_mode] or 1.0
    CURRENT_SCALE = scale

    -- Полностью очищаем старые шрифты из памяти перед пересборкой атласа
    io.Fonts:Clear()
    
    -- Рассчитываем точные размеры шрифтов под текущее разрешение/масштаб
    local size_main  = math.max(18, math.floor(18 * scale + 0.5))
    local size_large = math.floor(30 * scale + 0.5)
    
    -- Получаем системный диапазон кириллицы (строго один раз за сессию)
    if not cyrillic_ranges then 
        cyrillic_ranges = io.Fonts:GetGlyphRangesCyrillic() 
    end

    -- === 1. ЗАГРУЗКА ОСНОВНОГО ШРИФТА И МЕЛКИХ ИКОНОК ===
    if doesFileExist(path_segoe_bold) then
        font_default = io.Fonts:AddFontFromFileTTF(path_segoe_bold, size_main, font_config, cyrillic_ranges)
    elseif doesFileExist(path_arial_bold) then
        font_default = io.Fonts:AddFontFromFileTTF(path_arial_bold, size_main, font_config, cyrillic_ranges)
    else
        font_default = io.Fonts:AddFontDefault()
    end
    
    -- Вшиваем FontAwesome иконки в основной шрифт (без повторного парсинга Base85)
    font_fa = io.Fonts:AddFontFromMemoryCompressedBase85TTF(fa_base85_data, size_main, icon_config, icon_ranges_fa)

    -- === 2. ЗАГРУЗКА БОЛЬШОГО ШРИФТА И БОЛЬШИХ ИКОНОК ===
    if doesFileExist(path_segoe_black) then
        font_fa_big = io.Fonts:AddFontFromFileTTF(path_segoe_black, size_large, large_config, cyrillic_ranges)
    elseif doesFileExist(path_arial_black) then
        font_fa_big = io.Fonts:AddFontFromFileTTF(path_arial_black, size_large, large_config, cyrillic_ranges)
    else
        font_fa_big = io.Fonts:AddFontDefault()
    end
    
    -- Вшиваем FontAwesome иконки в большой шрифт
    io.Fonts:AddFontFromMemoryCompressedBase85TTF(fa_base85_data, size_large, big_icon_config, icon_ranges_fa)
    
    -- Финализируем текстурный атлас (сжимает память и отправляет данные на GPU)
    io.Fonts:Build()
    
    -- Применяем стили интерфейса в безопасном режиме
    pcall(applyStrictStyle)
end)

local PADDING_LEFT = 12
local PADDING_TOP = 12
local PADDING_RIGHT = 12
local PADDING_BOTTOM = 12

function setLeftPadding()
    imgui.SetCursorPosX(S(PADDING_LEFT))
end

function setLeftPaddingLarge()
    imgui.SetCursorPosX(S(PADDING_LEFT + 8))
end

function pushPanelPadding()
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(PADDING_LEFT), S(PADDING_TOP)))
end

function pushElementPadding()
    imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(S(0), S(8)))
end

function getContentWidth()
    local w = imgui.GetContentRegionAvail().x
    return w - S(PADDING_LEFT + PADDING_RIGHT)
end

function centerText(text)
    local text_size = GetStaticTextSize(text)
    local avail = imgui.GetContentRegionAvail().x
    local offset = (avail - text_size.x) / 2
    if offset > 0 then
        imgui.SetCursorPosX(imgui.GetCursorPosX() + offset)
    end
    imgui.Text(text)
end

function centerX(width)
    local avail = imgui.GetContentRegionAvail().x
    local offset = (avail - width) / 2
    if offset > 0 then
        imgui.SetCursorPosX(imgui.GetCursorPosX() + offset)
    end
end

function beginContentSection()
    pushPanelPadding()
end

function endContentSection()
    imgui.PopStyleVar()
end

function renderPRMessageCard(index, msg, width)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    local height = S(55) 
    
    if msg.active == nil then msg.active = true end
    if not msg._uid then msg._uid = tostring(os.clock()) .. index end
    local uid = msg._uid
    
    -- Буферы
    if not Buffers.pr_input_buffers then Buffers.pr_input_buffers = {} end
    if not Buffers.pr_input_buffers["txt_"..uid] then
        Buffers.pr_input_buffers["txt_"..uid] = imgui.new.char[4096](u8(msg.text or ""))
    end
    if not Buffers.pr_input_buffers["del_"..uid] then
        Buffers.pr_input_buffers["del_"..uid] = imgui.new.char[32](tostring(msg.delay or 60))
    end

    -- === СТАТУС СООБЩЕНИЯ ===
    local timer_str = "STOP"
    local t_col = 0xFFAAAAAA -- Серый
    
    if Data.auto_pr.active and msg.active then
        if not msg.next_send then 
            timer_str = "..." 
        else
            local now = os.time()
            local left = math.max(0, math.floor(msg.next_send - now))
            
            -- Проверка VR Кулдауна (визуальная)
            local vr_cooldown = false
            if msg.channel == 1 and (now - (Data.auto_pr.last_vr_time or 0) < 305) then
                vr_cooldown = true
            end

            if left > 0 then
                timer_str = tostring(left) .. "s"
                t_col = 0xFF00FF00 -- Зеленый (таймер тикает)
            elseif vr_cooldown then
                local vr_left = 305 - (now - (Data.auto_pr.last_vr_time or 0))
                timer_str = "VR: " .. vr_left .. "s"
                t_col = 0xFF00AAFF -- Голубой (ждет кд VR)
            else
                timer_str = "READY" -- Готово к отправке, ждет глобальную очередь
                t_col = 0xFFFFAA00 -- Оранжевый
            end
        end
    else
        timer_str = tostring(msg.delay or 60) .. "s"
        t_col = 0xFF808080 
    end

    -- Фон карточки
    local bg_col = msg.active and CURRENT_THEME.bg_secondary or imgui.ImVec4(0.12, 0.12, 0.12, 0.5)
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
    
    -- Обводка
    local border_col = msg.active and CURRENT_THEME.border_light or imgui.ImVec4(1,1,1,0.05)
    -- Если сообщение готово к отправке (READY), подсветим рамку
    if timer_str == "READY" then border_col = CURRENT_THEME.accent_warning end
    
    draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + height), imgui.ColorConvertFloat4ToU32(border_col), S(8), 15, S(1))

    -- === 1. TOGGLE (ВКЛ/ВЫКЛ) ===
    local tog_w = S(48)
    local tog_h = S(26)
    local tog_x = p.x + S(12)
    local tog_y = p.y + (height - tog_h) / 2
    
    imgui.SetCursorScreenPos(imgui.ImVec2(tog_x, tog_y))
    if renderAAAToggle("##tog_"..uid, msg.active) then
        msg.active = not msg.active
        -- При включении ставим таймер "через 2 сек + индекс", чтобы разбросать старт
        if msg.active and Data.auto_pr.active then 
            msg.next_send = os.time() + 2 + index 
        end 
        saveSettings()
    end
    if imgui.IsItemHovered() then imgui.SetTooltip(msg.active and u8"Включено" or u8"Выключено") end

    -- === 2. КАНАЛ ===
    local ch_colors = { 
        [1] = 0xFF00AAFF, -- VR
        [2] = 0xFFCCCCCC, -- /b
        [3] = 0xFFFFFFFF, -- /s
        [4] = 0xFF66FF66, -- Chat
        [5] = 0xFFFFFF00, -- /fam (Желтый)
        [6] = 0xFF00FFFF  -- /al (Голубой/Бирюзовый)
    }
    local ch_names = {"VR", "/b", "/s", "Chat", "/fam", "/al"}
    local current_ch = msg.channel or 1
    
    local btn_ch_w = S(35)
    local btn_ch_h = S(24)
    local curs_x = tog_x + tog_w + S(12)
    local btn_y = p.y + (height - btn_ch_h) / 2
    
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, btn_y))
    if imgui.InvisibleButton("##ch_"..uid, imgui.ImVec2(btn_ch_w, btn_ch_h)) then
        msg.channel = (msg.channel % 6) + 1 -- ИЗМЕНЕНО с 4 на 6
        saveSettings()
    end
    
    local ch_col = ch_colors[current_ch] or 0xFFFFFFFF
    draw_list:AddRect(imgui.ImVec2(curs_x, btn_y), imgui.ImVec2(curs_x + btn_ch_w, btn_y + btn_ch_h), ch_col, S(6), 15, S(1.5))
    
    local ch_txt = ch_names[current_ch] or "?"
    local txt_sz = GetStaticTextSize(ch_txt)
    draw_list:AddText(imgui.ImVec2(curs_x + (btn_ch_w - txt_sz.x)/2, btn_y + (btn_ch_h - txt_sz.y)/2), ch_col, ch_txt)
    if imgui.IsItemHovered() then imgui.SetTooltip(u8"Канал отправки: " .. u8(ch_txt)) end

    -- === 3. ИНФО ТАЙМЕРА ===
    curs_x = curs_x + btn_ch_w + S(10)
    
    -- Выравнивание текста таймера
    local t_width_approx = S(50)
    local t_calc_sz = GetStaticTextSize(timer_str)
    draw_list:AddText(imgui.ImVec2(curs_x, p.y + (height - t_calc_sz.y)/2), t_col, timer_str)
    
    curs_x = curs_x + t_width_approx + S(5)

    -- === 4. ПОЛЕ ТЕКСТА (4096 символов) ===
    local right_zone_w = S(100)
    local input_w = width - (curs_x - p.x) - right_zone_w
    
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, p.y + (height - S(34))/2))
    imgui.SetNextItemWidth(input_w)
    
    imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.Text, msg.active and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary)
    
    -- [ВАЖНО] Здесь 4096 - это размер буфера для длинных сообщений
    if imgui.InputText("##t_"..uid, Buffers.pr_input_buffers["txt_"..uid], 4096) then
        msg.text = u8:decode(ffi.string(Buffers.pr_input_buffers["txt_"..uid]))
        saveSettings()
    end
    
    local line_y = p.y + (height + S(20))/2
    local line_col = imgui.IsItemActive() and CURRENT_THEME.accent_primary or CURRENT_THEME.border_light
    if not msg.active then line_col = imgui.ImVec4(1,1,1,0.1) end
    draw_list:AddLine(imgui.ImVec2(curs_x, line_y), imgui.ImVec2(curs_x + input_w, line_y), imgui.ColorConvertFloat4ToU32(line_col))
    
    imgui.PopStyleColor(2)

    -- === 5. ЗАДЕРЖКА И УДАЛЕНИЕ ===
    curs_x = curs_x + input_w + S(8)
    
    local del_w = S(45)
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, p.y + (height - S(26))/2))
    imgui.SetNextItemWidth(del_w)
    
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(5), S(4)))
    
    if imgui.InputText("##d_"..uid, Buffers.pr_input_buffers["del_"..uid], 32, imgui.InputTextFlags.CharsDecimal) then
        local val = tonumber(ffi.string(Buffers.pr_input_buffers["del_"..uid]))
        if val then 
            msg.delay = val 
            saveSettings() 
        end
    end
    imgui.PopStyleVar()
    imgui.PopStyleColor()
    if imgui.IsItemHovered() then imgui.SetTooltip(u8"Интервал (сек)") end
    
    curs_x = curs_x + del_w + S(10)
    
    local trash_sz = S(28)
    imgui.SetCursorScreenPos(imgui.ImVec2(curs_x, p.y + (height - trash_sz)/2))
    if imgui.InvisibleButton("##del_"..uid, imgui.ImVec2(trash_sz, trash_sz)) then
        table.remove(Data.auto_pr.messages, index)
        saveSettings()
    end
    
    local is_trash_hov = imgui.IsItemHovered()
    local trash_col = is_trash_hov and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
    if font_fa then
        imgui.PushFont(font_fa)
        local ti = fa('trash')
        local tsz = GetStaticTextSize(ti)
        draw_list:AddText(imgui.ImVec2(curs_x + (trash_sz-tsz.x)/2, p.y + (height-tsz.y)/2), imgui.ColorConvertFloat4ToU32(trash_col), ti)
        imgui.PopFont()
    end

    imgui.SetCursorScreenPos(p)
    imgui.Dummy(imgui.ImVec2(width, height))
end

function isShopTrulyActive()
    -- Лавка считается активной, если включен режим витрины, есть активная сессия и она не очищена
    return App.live_shop_active and Marketplace.enabled and not Marketplace.is_cleared
end

function renderPRItemNew(index, item, width, parent_list)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    local is_group = (item.type == "group")
    
    -- Инициализация настройки "Только лавка", если её нет (для старых конфигов)
    if item.shop_only == nil then item.shop_only = false end
    
    -- Размеры
    local base_height = S(50)
    local total_height = base_height
    
    -- Вычисление высоты для раскрытой группы
    if is_group and item.expanded then
        local inner_count = #(item.items or {})
        local inner_item_h = S(42)
        local inner_gap = S(4)
        local add_btn_h = S(28)
        total_height = total_height + (inner_count * (inner_item_h + inner_gap)) + add_btn_h + S(15)
    end

    if not item._uid then item._uid = tostring(os.clock()) .. "_" .. index .. (is_group and "g" or "s") end
    local uid = item._uid

    -- Инициализация буферов
    if not Buffers.pr_input_buffers then Buffers.pr_input_buffers = {} end
    
    local txt_key = "txt_" .. uid
    local val_text = is_group and (item.name or "Группа") or (item.text or "")
    if not Buffers.pr_input_buffers[txt_key] then
        Buffers.pr_input_buffers[txt_key] = imgui.new.char[4096](u8(val_text))
    end
    
    local del_key = "del_" .. uid
    if not Buffers.pr_input_buffers[del_key] then
        local delay_val = item.delay or (is_group and 10 or 60)
        Buffers.pr_input_buffers[del_key] = imgui.new.char[32](tostring(delay_val))
    end

    imgui.PushIDStr("pr_item_" .. uid)
    imgui.BeginGroup()

    -- 1. ФОН И ОБВОДКА [ОПТИМИЗИРОВАНО В U32]
    local bg_col_u32 = item.active and CURRENT_THEME.bg_secondary_u32 or 0x801F1F1F -- 0.5 Alpha Dark Gray
    local border_col_u32 = item.active and CURRENT_THEME.border_light_u32 or 0x0DFFFFFF -- 0.05 Alpha White
    
    -- Логика статуса для подсветки
    local status_border = false
    if Data.auto_pr.active and item.active then
        -- Если включен режим "Только лавка", но лавка не активна
        if item.shop_only and not isShopTrulyActive() then
             border_col_u32 = CURRENT_THEME.accent_warning_u32
             status_border = true
        elseif item.next_send then
            local now = os.time()
            local time_left = item.next_send - now
            if time_left < 2 and time_left >= 0 then 
                border_col_u32 = CURRENT_THEME.accent_warning_u32
                status_border = true
            end
        end
    end

    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + total_height), bg_col_u32, S(8))
    draw_list:AddRect(p, imgui.ImVec2(p.x + width, p.y + total_height), border_col_u32, S(8), 15, status_border and S(2.0) or S(1.2))

    -- 2. ВЕРХНЯЯ СТРОКА (ОСНОВНОЙ КОНТЕНТ)
    local row_y = p.y + (base_height - S(24)) / 2
    local center_y_abs = p.y + base_height / 2
    
    -- === ЛЕВАЯ ЧАСТЬ (Static Width) ===
    local cursor_x = p.x + S(12)

    -- [A] СТРЕЛКИ СОРТИРОВКИ
    local sort_btn_sz = S(20)
    
    -- Up
    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, center_y_abs - sort_btn_sz + S(2)))
    if index > 1 then
        if imgui.InvisibleButton("##up", imgui.ImVec2(sort_btn_sz, sort_btn_sz/2)) then
            moveItemInList(parent_list, index, -1)
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local icon_pos = imgui.GetItemRectMin()
            local col = imgui.IsItemHovered() and CURRENT_THEME.accent_primary or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(icon_pos.x + S(4), icon_pos.y - S(3)), imgui.ColorConvertFloat4ToU32(col), fa('caret_up'))
            imgui.PopFont()
        end
    end
    
    -- Down
    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, center_y_abs + S(2)))
    if index < #parent_list then
        if imgui.InvisibleButton("##down", imgui.ImVec2(sort_btn_sz, sort_btn_sz/2)) then
            moveItemInList(parent_list, index, 1)
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local icon_pos = imgui.GetItemRectMin()
            local col = imgui.IsItemHovered() and CURRENT_THEME.accent_primary or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(icon_pos.x + S(4), icon_pos.y - S(4)), imgui.ColorConvertFloat4ToU32(col), fa('caret_down'))
            imgui.PopFont()
        end
    end
    cursor_x = cursor_x + sort_btn_sz + S(8)

    -- [B] TOGGLE (Вкл/Выкл)
    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, row_y))
    if renderAAAToggle("##act_"..uid, item.active) then
        item.active = not item.active
        if item.active then item.next_send = os.time() + 2 end
        saveSettings()
    end
    cursor_x = cursor_x + S(50)

    -- [C] НАСТРОЙКИ (Канал и "Только лавка")
    if is_group then
        if font_fa then
            imgui.PushFont(font_fa)
            draw_list:AddText(imgui.ImVec2(cursor_x, row_y + S(2)), 0xFFFFAA00, fa('layer_group'))
            imgui.PopFont()
        end
        cursor_x = cursor_x + S(26)
    else
        -- [C.1] КНОПКА "ТОЛЬКО ЛАВКА"
        local shop_btn_sz = S(24)
        local shop_btn_x = cursor_x
        local shop_btn_y = p.y + (base_height - shop_btn_sz)/2
        
        imgui.SetCursorScreenPos(imgui.ImVec2(shop_btn_x, shop_btn_y))
        if imgui.InvisibleButton("##shop_only_"..uid, imgui.ImVec2(shop_btn_sz, shop_btn_sz)) then
            item.shop_only = not item.shop_only
            saveSettings()
        end
        
        -- Отрисовка иконки магазина
        local shop_icon_col = item.shop_only and CURRENT_THEME.accent_success or CURRENT_THEME.text_hint
        -- Если активно, но лавки нет - красим в оранжевый/желтый
        if item.shop_only and not App.live_shop_active and item.active and Data.auto_pr.active then
             shop_icon_col = CURRENT_THEME.accent_warning
        end
        
        if font_fa then
            imgui.PushFont(font_fa)
            local icon_store = fa('store')
            local isz = GetStaticTextSize(icon_store)
            draw_list:AddText(imgui.ImVec2(shop_btn_x + (shop_btn_sz-isz.x)/2, shop_btn_y + (shop_btn_sz-isz.y)/2), 
                imgui.ColorConvertFloat4ToU32(shop_icon_col), icon_store)
            imgui.PopFont()
        end
        
        if imgui.IsItemHovered() then
            if item.shop_only then
                imgui.SetTooltip(u8"Отправка: ТОЛЬКО когда лавка активна")
            else
                imgui.SetTooltip(u8"Отправка: ВСЕГДА (Нажмите, чтобы включить проверку лавки)")
            end
        end
        cursor_x = cursor_x + shop_btn_sz + S(8)

        -- [C.2] КНОПКА ВЫБОРА КАНАЛА
        local channels = {"VR", "/b", "/s", "Chat", "/fam", "/al"} 
        local ch_colors = {0xFF00AAFF, 0xFFCCCCCC, 0xFFFFFFFF, 0xFF66FF66, 0xFFFFFF00, 0xFF00FFFF}
        local curr_ch = (item.channel or 1)
        local ch_w = S(36)
        local ch_h = S(22)
        local ch_y = p.y + (base_height - ch_h)/2
        
        imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, ch_y))
        if imgui.InvisibleButton("##ch_"..uid, imgui.ImVec2(ch_w, ch_h)) then
            item.channel = (item.channel % 6) + 1 -- ИЗМЕНЕНО с 4 на 6
            saveSettings()
        end
        
        local r_min = imgui.GetItemRectMin()
        local r_max = imgui.GetItemRectMax()
        draw_list:AddRect(r_min, r_max, ch_colors[curr_ch], S(5), 15, S(1.5))
        
        local ch_txt = channels[curr_ch]
        local ch_txt_sz = GetStaticTextSize(ch_txt)
        draw_list:AddText(imgui.ImVec2(r_min.x + (ch_w - ch_txt_sz.x)/2, r_min.y + (ch_h - ch_txt_sz.y)/2), ch_colors[curr_ch], ch_txt)
        
        if imgui.IsItemHovered() then imgui.SetTooltip(u8"Канал отправки: " .. u8(ch_txt)) end
        cursor_x = cursor_x + ch_w + S(10)
    end

    -- === ПРАВАЯ ЧАСТЬ (Calculated from Right) ===
    local right_cursor = p.x + width - S(10)
    
    -- [Z] УДАЛЕНИЕ
    local del_size = S(28)
    right_cursor = right_cursor - del_size
    imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, center_y_abs - del_size/2))
    
    if imgui.InvisibleButton("##trash_"..uid, imgui.ImVec2(del_size, del_size)) then
        DragDropAction.active = true
        DragDropAction.type = "delete"
        DragDropAction.source_list = parent_list
        DragDropAction.from_idx = index
    end
    
    local trash_col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
    if font_fa then
        imgui.PushFont(font_fa)
        local tsz = GetStaticTextSize(fa('trash'))
        draw_list:AddText(imgui.ImVec2(right_cursor + (del_size-tsz.x)/2, center_y_abs - tsz.y/2), imgui.ColorConvertFloat4ToU32(trash_col), fa('trash'))
        imgui.PopFont()
    end
    right_cursor = right_cursor - S(5)

    -- [Y] EXPAND (Только для групп)
    if is_group then
        local exp_size = S(28)
        right_cursor = right_cursor - exp_size
        
        imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, center_y_abs - exp_size/2))
        if imgui.InvisibleButton("##exp_btn_"..uid, imgui.ImVec2(exp_size, exp_size)) then
            item.expanded = not item.expanded
        end
        
        -- Рисуем фон кнопки
        local exp_bg = imgui.IsItemHovered() and CURRENT_THEME.bg_main or CURRENT_THEME.bg_tertiary
        draw_list:AddRectFilled(imgui.GetItemRectMin(), imgui.GetItemRectMax(), imgui.ColorConvertFloat4ToU32(exp_bg), S(6))
        
        -- Рисуем иконку
        if font_fa then
            imgui.PushFont(font_fa)
            local exp_icon = item.expanded and fa('chevron_up') or fa('chevron_down')
            local esz = GetStaticTextSize(exp_icon)
            local e_center = imgui.GetItemRectMin()
            draw_list:AddText(imgui.ImVec2(e_center.x + (exp_size - esz.x)/2, e_center.y + (exp_size - esz.y)/2), 0xFFFFFFFF, exp_icon)
            imgui.PopFont()
        end
        right_cursor = right_cursor - S(10)
    else
        right_cursor = right_cursor - S(5)
    end
	
	if not is_group and Data.auto_pr.active and item.active then
        local force_size = S(28)
        right_cursor = right_cursor - force_size
        
        imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, center_y_abs - force_size/2))
        if imgui.InvisibleButton("##force_"..uid, imgui.ImVec2(force_size, force_size)) then
            item.next_send = os.time() -- Сбрасываем таймер в 0, отправится на следующем тике
            addToastNotification("Отправлено в очередь!", "info", 1.0)
        end
        
        local force_col = imgui.IsItemHovered() and CURRENT_THEME.accent_success or CURRENT_THEME.text_hint
        if font_fa then
            imgui.PushFont(font_fa)
            local f_sz = GetStaticTextSize(fa('paper_plane'))
            draw_list:AddText(imgui.ImVec2(right_cursor + (force_size-f_sz.x)/2, center_y_abs - f_sz.y/2), imgui.ColorConvertFloat4ToU32(force_col), fa('paper_plane'))
            imgui.PopFont()
        end
        
        if imgui.IsItemHovered() then imgui.SetTooltip(u8"Отправить сообщение прямо сейчас вне очереди") end
        right_cursor = right_cursor - S(5)
    end

    -- [X] ТАЙМЕР / ИНТЕРВАЛ (Input)
    local timer_w = S(45)
    right_cursor = right_cursor - timer_w
    
    imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, row_y - S(3)))
    imgui.SetNextItemWidth(timer_w)
    
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(5), S(4)))
    if imgui.InputText("##del_"..uid, Buffers.pr_input_buffers[del_key], 32, imgui.InputTextFlags.CharsDecimal) then
        item.delay = tonumber(ffi.string(Buffers.pr_input_buffers[del_key])) or 60
        saveSettings()
    end
    imgui.PopStyleVar()
    imgui.PopStyleColor()
    if imgui.IsItemHovered() then imgui.SetTooltip(u8"Задержка (сек)") end
    
    -- [W] ТЕКСТ "Интервал" (Только для групп, для одиночных - статус)
    right_cursor = right_cursor - S(5)
    
    if is_group then
        local lbl_txt = u8"Интервал:"
        local lbl_sz = GetStaticTextSize(lbl_txt)
        right_cursor = right_cursor - lbl_sz.x
        
        imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, center_y_abs - lbl_sz.y/2))
        imgui.TextColored(CURRENT_THEME.text_secondary, lbl_txt)
        right_cursor = right_cursor - S(10)
    else
        -- Для одиночных сообщений можно вывести статус таймера или "NO SHOP"
        local status_txt = ""
        local status_col = CURRENT_THEME.text_hint
        
        if Data.auto_pr.active and item.active then
            if item.shop_only and not isShopTrulyActive() then
                status_txt = "NO SHOP"
                status_col = CURRENT_THEME.accent_warning
            elseif item.next_send then
                local left = math.max(0, math.floor(item.next_send - os.time()))
                if left > 0 then status_txt = tostring(left).."s" end
            end
        end
        
        if status_txt ~= "" then
            local s_sz = GetStaticTextSize(status_txt)
            right_cursor = right_cursor - s_sz.x
            imgui.SetCursorScreenPos(imgui.ImVec2(right_cursor, center_y_abs - s_sz.y/2))
            imgui.TextColored(status_col, status_txt)
            right_cursor = right_cursor - S(10)
        end
    end

    -- === ЦЕНТРАЛЬНАЯ ЧАСТЬ (INPUT) ===
    -- Занимает всё место между cursor_x (конец левой части) и right_cursor (начало правой части)
    local input_width = right_cursor - cursor_x
    
    if input_width > S(50) then -- Рисуем, только если есть место
        imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, row_y - S(3)))
        
        if is_group then
            renderModernInput("##gname_"..uid, Buffers.pr_input_buffers[txt_key], input_width, "Название группы")
            if imgui.IsItemDeactivatedAfterEdit() then
                item.name = u8:decode(ffi.string(Buffers.pr_input_buffers[txt_key]))
                saveSettings()
            end
        else
            imgui.SetNextItemWidth(input_width)
            imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0,0,0,0)) -- Прозрачный фон
            if imgui.InputText("##txt_"..uid, Buffers.pr_input_buffers[txt_key], 4096) then
                item.text = u8:decode(ffi.string(Buffers.pr_input_buffers[txt_key]))
                saveSettings()
            end
            imgui.PopStyleColor()
            
            -- Линия подчеркивания
            local line_col = imgui.IsItemActive() and CURRENT_THEME.accent_primary or CURRENT_THEME.border_light
            draw_list:AddLine(
                imgui.ImVec2(cursor_x, row_y + S(20)), 
                imgui.ImVec2(cursor_x + input_width, row_y + S(20)), 
                imgui.ColorConvertFloat4ToU32(line_col)
            )
        end
    end

    -- === 3. ВЛОЖЕННЫЕ ЭЛЕМЕНТЫ (Для групп) ===
    if is_group and item.expanded then
        local inner_y = p.y + base_height
        local inner_w = width - S(30)
        local inner_x = p.x + S(20)
        
        draw_list:AddLine(
            imgui.ImVec2(p.x + S(15), p.y + base_height - S(10)), 
            imgui.ImVec2(p.x + S(15), p.y + total_height - S(20)), 
            0x40FFFFFF, 2
        )

        local sub_h = S(42)
        local sub_gap = S(4)

        for i, sub_item in ipairs(item.items) do
            local sub_pos_y = inner_y + (i - 1) * (sub_h + sub_gap)
            
            imgui.SetCursorScreenPos(imgui.ImVec2(inner_x, sub_pos_y))
            imgui.PushIDInt(index * 10000 + i)
            
            -- Фон подэлемента
            draw_list:AddRectFilled(
                imgui.ImVec2(inner_x, sub_pos_y), 
                imgui.ImVec2(inner_x + inner_w, sub_pos_y + sub_h), 
                imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), 
                S(6)
            )
            
            if Data.auto_pr.active and item.active and item.current_idx == i then
                draw_list:AddRect(
                    imgui.ImVec2(inner_x, sub_pos_y), 
                    imgui.ImVec2(inner_x + inner_w, sub_pos_y + sub_h), 
                    imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), 
                    S(6), 15, S(1.5)
                )
            end

            local sub_cy = sub_pos_y + sub_h / 2
            local sub_cx = inner_x + S(10)

            -- Сортировка внутри
            local sub_sort_sz = S(16)
            
            -- Up
            imgui.SetCursorScreenPos(imgui.ImVec2(sub_cx, sub_cy - sub_sort_sz + S(2)))
            if i > 1 then
                if imgui.InvisibleButton("##sup", imgui.ImVec2(sub_sort_sz, sub_sort_sz/2 + 2)) then
                    moveItemInList(item.items, i, -1)
                end
                if font_fa then
                    imgui.PushFont(font_fa)
                    draw_list:AddText(imgui.GetItemRectMin(), 0x80FFFFFF, fa('angle_up'))
                    imgui.PopFont()
                end
            end
            
            -- Down
            imgui.SetCursorScreenPos(imgui.ImVec2(sub_cx, sub_cy + S(2)))
            if i < #item.items then
                if imgui.InvisibleButton("##sdown", imgui.ImVec2(sub_sort_sz, sub_sort_sz/2 + 2)) then
                    moveItemInList(item.items, i, 1)
                end
                if font_fa then
                    imgui.PushFont(font_fa)
                    draw_list:AddText(imgui.GetItemRectMin(), 0x80FFFFFF, fa('angle_down'))
                    imgui.PopFont()
                end
            end
            sub_cx = sub_cx + S(20)

            -- Канал (вложенный)
            local ch_idx = sub_item.channel or 1
            local channels = {"VR", "/b", "/s", "Chat"}
            local ch_col = ({0xFF00AAFF, 0xFFCCCCCC, 0xFFFFFFFF, 0xFF66FF66})[ch_idx]
            
            imgui.SetCursorScreenPos(imgui.ImVec2(sub_cx, sub_cy - S(10)))
            if imgui.InvisibleButton("sub_ch", imgui.ImVec2(S(30), S(20))) then
                sub_item.channel = (sub_item.channel % 4) + 1
                saveSettings()
            end
            
            local btn_min = imgui.GetItemRectMin()
            local btn_max = imgui.GetItemRectMax()
            draw_list:AddRect(btn_min, btn_max, ch_col, S(4))
            
            local csz = GetStaticTextSize(channels[ch_idx])
            draw_list:AddText(
                imgui.ImVec2(btn_min.x + (S(30)-csz.x)/2, btn_min.y + (S(20)-csz.y)/2), 
                ch_col, channels[ch_idx]
            )
            sub_cx = sub_cx + S(38)

            -- Удаление (справа)
            local sub_del_x = inner_x + inner_w - S(25)
            imgui.SetCursorScreenPos(imgui.ImVec2(sub_del_x, sub_cy - S(10)))
            if imgui.InvisibleButton("##sdel", imgui.ImVec2(S(20), S(20))) then
                table.remove(item.items, i)
                saveSettings()
            end
            if font_fa then
                imgui.PushFont(font_fa)
                local col = imgui.IsItemHovered() and 0xFF4444FF or 0x80FFFFFF
                local tsz = GetStaticTextSize(fa('minus'))
                draw_list:AddText(imgui.ImVec2(sub_del_x+(S(20)-tsz.x)/2, sub_cy-S(10)+(S(20)-tsz.y)/2), col, fa('minus'))
                imgui.PopFont()
            end

            -- Input (посередине)
            local sub_txt_w = sub_del_x - sub_cx - S(10)
            local sub_uid = uid .. "_sub_" .. i
            if not Buffers.pr_input_buffers["s_"..sub_uid] then
                Buffers.pr_input_buffers["s_"..sub_uid] = imgui.new.char[4096](u8(sub_item.text or ""))
            end
            
            imgui.SetCursorScreenPos(imgui.ImVec2(sub_cx, sub_cy - S(9)))
            imgui.SetNextItemWidth(sub_txt_w)
            imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0,0,0,0))
            if imgui.InputText("##st_"..sub_uid, Buffers.pr_input_buffers["s_"..sub_uid], 4096) then
                sub_item.text = u8:decode(ffi.string(Buffers.pr_input_buffers["s_"..sub_uid]))
                saveSettings()
            end
            imgui.PopStyleColor()

            imgui.PopID()
        end
        
        -- Кнопка "Добавить"
        local add_y = inner_y + (#item.items) * (sub_h + sub_gap) + S(4)
        local add_h = S(28)
        
        imgui.SetCursorScreenPos(imgui.ImVec2(inner_x, add_y))
        if renderCustomButton(u8" Добавить в группу", inner_w, add_h, CURRENT_THEME.accent_primary, fa('plus')) then
            table.insert(item.items, { text = "", channel = 1 })
            saveSettings()
        end
    end

    imgui.EndGroup()
    imgui.PopID()
    
    -- [ФИКС СКРОЛЛА] Сообщаем движку ImGui реальные размеры отрисованного элемента,
    -- чтобы скроллбар рассчитывался правильно и список не мигал/прыгал.
    imgui.SetCursorScreenPos(p)
    imgui.Dummy(imgui.ImVec2(width, total_height))
    
    -- Правильный сдвиг курсора для следующего элемента
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + total_height + S(8)))
end

function moveItemInList(list, index, direction)
    if not list then return end
    local new_index = index + direction
    if new_index < 1 or new_index > #list then return end
    
    local item = table.remove(list, index)
    table.insert(list, new_index, item)
    saveSettings()
end

function toggleItemLock(item)
    if not item or not item.model_id or not item.slot then return end
    
    -- [FIX] Создаем уникальный ключ: IDМодели_НомерСлота
    -- Это позволяет различать одинаковые предметы в разных слотах (арендованные и нет)
    local unique_key = tostring(item.model_id) .. "_" .. tostring(item.slot)
    
    if Data.locked_items[unique_key] then
        Data.locked_items[unique_key] = nil
        addToastNotification("Предмет разблокирован", "info")
    else
        Data.locked_items[unique_key] = true
        addToastNotification("Предмет заблокирован (защита от продажи)", "warning")
    end
    
    saveJsonFile(FILES.LOCKED_ITEMS, Data.locked_items)
end

function renderAutoPRTab()
    -- Выполняем действия с таблицами до начала отрисовки
    resolveDragDropActions()

    local full_w = imgui.GetContentRegionAvail().x
    local full_h = imgui.GetContentRegionAvail().y
    
    -- === 1. СТАТУС БАР (ВЕРХНЯЯ ПАНЕЛЬ) ===
    local status_h = S(50)
    local draw = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local is_active = Data.auto_pr.active

    draw:AddRectFilled(p, imgui.ImVec2(p.x + full_w, p.y + status_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
    
    -- Текст статуса слева
    local text_x = p.x + S(15)
    local text_y = p.y + (status_h - imgui.GetFontSize())/2
    imgui.SetCursorScreenPos(imgui.ImVec2(text_x, text_y))
    
    if is_active then
        imgui.TextColored(CURRENT_THEME.accent_success, fa('bullhorn') .. " " .. u8("СИСТЕМА АКТИВНА"))
    else
        imgui.TextColored(CURRENT_THEME.text_hint, fa('pause') .. " " .. u8("ОСТАНОВЛЕНО"))
    end

    -- Кнопка "Запустить/Остановить" (Справа)
    local btn_w = S(120)
    local btn_h = S(32)
    local btn_x = p.x + full_w - btn_w - S(10)
    local btn_y = p.y + (status_h - btn_h) / 2

    -- [ИСПРАВЛЕНО] Кнопка "Справка по переменным" (Ручная отрисовка без текста)
    local help_sz = S(32) -- Квадратная кнопка
    local help_x = btn_x - help_sz - S(8)
    
    imgui.SetCursorScreenPos(imgui.ImVec2(help_x, btn_y))
    -- Используем InvisibleButton для логики клика и ID
    if imgui.InvisibleButton("##help_vars_btn", imgui.ImVec2(help_sz, btn_h)) then
        -- Действие при клике (если нужно)
    end
    
    local is_help_hovered = imgui.IsItemHovered()
    
    -- Рисуем фон (симулируем стиль кнопки)
    local help_col = CURRENT_THEME.bg_tertiary
    if is_help_hovered then 
        help_col = imgui.ImVec4(help_col.x*1.15, help_col.y*1.15, help_col.z*1.15, 1) 
    end
    draw:AddRectFilled(imgui.ImVec2(help_x, btn_y), imgui.ImVec2(help_x + help_sz, btn_y + btn_h), imgui.ColorConvertFloat4ToU32(help_col), S(6))
    
    -- Рисуем иконку по центру
    if font_fa then
        imgui.PushFont(font_fa)
        local icon = fa('tags')
        local isz = GetStaticTextSize(icon)
        draw:AddText(imgui.ImVec2(help_x + (help_sz - isz.x)/2, btn_y + (btn_h - isz.y)/2), 0xFFFFFFFF, icon)
        imgui.PopFont()
    end
    
    -- Тултип при наведении
    if is_help_hovered then
        imgui.BeginTooltip()
        imgui.TextColored(CURRENT_THEME.accent_primary, u8"Доступные переменные (вставьте в текст):")
        imgui.Separator()
        imgui.Text(u8"{id} - Ваш ID")
        imgui.Text(u8"{name} - Ник (Name_Surname)")
        imgui.Text(u8"{name_space} - Ник без _ (Name Surname)")
        imgui.Text(u8"{lvl} - Ваш уровень")
        imgui.Text(u8"{time} - Время (МСК)")
        imgui.EndTooltip()
    end

    -- Основная кнопка запуска
    imgui.SetCursorScreenPos(imgui.ImVec2(btn_x, btn_y))
    local btn_col = is_active and CURRENT_THEME.accent_danger or CURRENT_THEME.accent_success
    local btn_txt = is_active and u8"Остановить" or u8"Запустить"
    
    if renderCustomButton(btn_txt, btn_w, btn_h, btn_col, is_active and fa('power_off') or fa('play')) then
        Data.auto_pr.active = not Data.auto_pr.active
        if Data.auto_pr.active then
            local now = os.time()
            for i, item in ipairs(Data.auto_pr.items) do
                item.next_send = now + 2 + i 
                if item.type == "group" then item.current_idx = 1 end
            end
            addToastNotification("Авто-пиар запущен", "success")
        else
            Data.auto_pr.pending_vr_response = false
            addToastNotification("Авто-пиар остановлен", "warning")
        end
        saveSettings()
    end

    -- === 2. СПИСОК СООБЩЕНИЙ ===
    local footer_h = S(60)
    local list_h = full_h - status_h - footer_h - S(15)
    
    -- Сдвигаем курсор под статус бар
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + status_h + S(10)))
    
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    
    -- [ИЗМЕНЕНО] Используем стандартный BeginChild вместо renderSmoothScrollBox
    if imgui.BeginChild("PRListScroll", imgui.ImVec2(full_w, list_h), false) then
        
        -- Отступ от левого края (чтобы не прилипало)
        imgui.SetCursorPosX(S(10))
        
        if #Data.auto_pr.items == 0 then
            imgui.Dummy(imgui.ImVec2(0, S(40)))
            renderEmptyState(fa('list_ul'), "Список пуст", "Создайте сообщения или группы кнопками внизу.")
        else
            -- Ширина элемента списка (учитываем скроллбар)
            local item_width = full_w - S(25) 
            
            -- Небольшой отступ сверху списка
            imgui.Dummy(imgui.ImVec2(0, S(2))) 

            for i, item in ipairs(Data.auto_pr.items) do
                -- Важно: SetCursorPosX вызываем перед КАЖДЫМ элементом
                imgui.SetCursorPosX(S(10))
                
                renderPRItemNew(i, item, item_width, Data.auto_pr.items)
            end
        end
        
        -- Пустое место внизу списка
        imgui.Dummy(imgui.ImVec2(0, S(50)))
    end
    imgui.EndChild()
    
    imgui.PopStyleColor()

    -- === 3. ФУТЕР (КНОПКИ) ===
    local footer_y = p.y + full_h - footer_h
    draw:AddRectFilled(imgui.ImVec2(p.x, footer_y), imgui.ImVec2(p.x + full_w, footer_y + footer_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(10), 10)
    
    local btn_add_w = (full_w - S(45)) / 2
    local btn_add_y = footer_y + (footer_h - S(35))/2
    
    -- Кнопка "Добавить сообщение"
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + S(15), btn_add_y))
    if renderCustomButton(u8"Добавить сообщение", btn_add_w, S(35), CURRENT_THEME.accent_primary, fa('plus')) then
        table.insert(Data.auto_pr.items, {
            type = "single",
            text = "",
            channel = 1,
            delay = 60,
            active = true,
            next_send = 0,
            shop_only = false 
        })
        saveSettings()
        triggerScrollToBottom("PRListScroll")
    end
    
    -- Кнопка "Создать группу"
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + S(25) + btn_add_w, btn_add_y))
    if renderCustomButton(u8"Создать группу", btn_add_w, S(35), CURRENT_THEME.accent_secondary, fa('layer_group')) then
        table.insert(Data.auto_pr.items, {
            type = "group",
            name = "Новая группа",
            delay = 10,
            active = true,
            items = {},
            expanded = true,
            current_idx = 1,
            next_send = 0,
            shop_only = false
        })
        saveSettings()
        triggerScrollToBottom("PRListScroll")
    end
end

function renderInventoryStatusIndicator(draw_list, center, radius, state, is_hovered)
    local bg_col, border_col, icon, icon_col, border_thickness

    if state == "locked" then
        bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.3))
        border_col = CURRENT_THEME.text_secondary_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
        icon = fa('lock')
        icon_col = border_col
        border_thickness = S(1.5)
    elseif state == "rented" then
        bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_warning.x, CURRENT_THEME.accent_warning.y, CURRENT_THEME.accent_warning.z, 0.1))
        border_col = CURRENT_THEME.accent_warning_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning)
        icon = fa('clock')
        icon_col = border_col
        border_thickness = S(1.5)
    elseif state == "added" then
        bg_col = CURRENT_THEME.accent_primary_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
        -- Добавляем легкое свечение вокруг активного кружка
        border_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.4))
        icon = fa('check')
        
        -- [FIX CONTRAST] Делаем галочку черной, если тема использует светлый акцент
        local lum = CURRENT_THEME.accent_primary.x * 0.299 + CURRENT_THEME.accent_primary.y * 0.587 + CURRENT_THEME.accent_primary.z * 0.114
        icon_col = lum > 0.6 and 0xFF101010 or 0xFFFFFFFF
        
        border_thickness = S(2.5)
    elseif state == "has_avg" then
        -- Товар не добавлен, но на него есть средняя цена (рекомендация)
        bg_col = is_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.2)) or 0
        border_col = CURRENT_THEME.accent_warning_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning)
        icon = fa('plus')
        icon_col = border_col
        border_thickness = S(1.5)
    else 
        -- Обычное состояние (Можно добавить)
        bg_col = is_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.08)) or 0
        border_col = CURRENT_THEME.border_light_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light)
        icon = fa('plus')
        icon_col = CURRENT_THEME.text_hint_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint)
        border_thickness = S(1.5)
        
        -- Подсветка при наведении
        if is_hovered then
            border_col = CURRENT_THEME.accent_primary_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
            icon_col = CURRENT_THEME.text_primary_u32 or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary)
        end
    end

    -- 1. Фон индикатора
    if bg_col ~= 0 then
        draw_list:AddCircleFilled(center, radius, bg_col, 24)
    end
    
    -- 2. Обводка индикатора
    draw_list:AddCircle(center, radius, border_col, 24, border_thickness)

    -- 3. Иконка точно по центру
    if font_fa then
        imgui.PushFont(font_fa)
        local isz = GetStaticTextSize(icon)
        draw_list:AddText(imgui.ImVec2(center.x - isz.x/2, center.y - isz.y/2), icon_col, icon)
        imgui.PopFont()
    end
end

function renderUnifiedHeader(text, icon)
    local p = imgui.GetCursorScreenPos()
    local w = imgui.GetContentRegionAvail().x
    
    
    imgui.Dummy(imgui.ImVec2(0, S(2)))
    
    
    if icon then
        imgui.TextColored(CURRENT_THEME.accent_secondary, icon)
        imgui.SameLine()
    end
    
    imgui.TextColored(CURRENT_THEME.accent_secondary, text)
    
    
    imgui.Separator()
    imgui.Spacing()
end

-- Выделяем вектор 1 раз
local modern_input_vec = imgui.ImVec2(0, 0)

-- Инициализируем пул 1 раз
local VEC_POOL = {
    padding = imgui.ImVec2(0, 0),
    size = imgui.ImVec2(0, 0),
    pos = imgui.ImVec2(0, 0)
}

function renderModernInput(label_id, buffer, width, hint, is_secret, custom_size)
    imgui.SetNextItemWidth(width)
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    
    -- Используем вектор из пула, просто меняя значения
    VEC_POOL.padding.x = S(10)
    VEC_POOL.padding.y = (S(34) - imgui.GetFontSize()) / 2
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, VEC_POOL.padding)
    
    local flags = is_secret and imgui.InputTextFlags.Password or 0
    local changed = imgui.InputTextWithHint(label_id, u8(hint or ""), buffer, custom_size or 64, flags)
    
    imgui.PopStyleVar()
    imgui.PopStyleColor()
    return changed
end

function clearPriceCache()
    CacheSystem.prices.market = {}
    CacheSystem.prices.lower_map = nil
end

function getAveragePriceForItem(item, mode, strict)
    if not item or not item.name then return nil end
    mode = mode or "sell"
    local strict_key = strict and 1 or 0
    
    local clean_key_1 = item._clean_k1
    local clean_key_2 = item._clean_k2
    
    if not clean_key_1 then
        clean_key_1 = enhancedCleanItemName(item.name)
        clean_key_2 = cleanItemName(item.name)
        item._clean_k1 = clean_key_1
        item._clean_k2 = clean_key_2
    end
    
    if not CacheSystem.prices.market[clean_key_1] then CacheSystem.prices.market[clean_key_1] = {} end
    if not CacheSystem.prices.market[clean_key_1][mode] then CacheSystem.prices.market[clean_key_1][mode] = {} end
    
    local cached_value = CacheSystem.prices.market[clean_key_1][mode][strict_key]
    if cached_value ~= nil then
        return cached_value
    end

    local found_data = Data.average_prices[clean_key_1] or Data.average_prices[clean_key_2]

    -- [КРИТИЧЕСКИЙ ФИКС FPS] Мгновенный поиск O(1) вместо тяжелого цикла
    if not found_data then
        if not CacheSystem.prices.lower_map then
            CacheSystem.prices.lower_map = {}
            for db_name, db_data in pairs(Data.average_prices) do
                CacheSystem.prices.lower_map[db_name:lower()] = db_data
            end
        end
        found_data = CacheSystem.prices.lower_map[clean_key_2:lower()]
    end

    -- 4. Выбор цены
    local final_price = nil
    if found_data then
        if mode == "sell" then
            final_price = found_data.sell
            if (not final_price or final_price == 0) and not strict and found_data.buy and found_data.buy > 0 then
                final_price = math.floor(found_data.buy * 1.3)
            end
        elseif mode == "buy" then
            final_price = found_data.buy
            if (not final_price or final_price == 0) and not strict and found_data.sell and found_data.sell > 0 then
                final_price = math.floor(found_data.sell * 0.7)
            end
        end
        if (not final_price or final_price == 0) and not strict then
            final_price = found_data.price
        end
    end

    -- 5. Запись в кэш
    CacheSystem.prices.market[clean_key_1][mode][strict_key] = final_price or false
    return final_price
end

function addAccessoryWithAllColors(item)
    
    local color_count = 10 
    
    for color_id = 0, color_count - 1 do
        table.insert(Data.buy_list, {
            name = item.name, 
            price = 100, 
            amount = color_id,  
            index = item.index, 
            active = true
        })
    end
    
    saveListsConfig()
    calculateBuyTotal()
    sampAddChatMessage(string.format('[RMarket] {00ff00}Добавлено %s (%d)', item.name, color_count), -1)
end

function moveTableItem(tbl, from, to)
    if from == to or not tbl[from] then return end
    
    local item = table.remove(tbl, from)
    
    if to > from then 
        to = to - 1 
    end
    
    if to < 1 then to = 1 end
    if to > #tbl + 1 then to = #tbl + 1 end
    
    table.insert(tbl, to, item)
end

function renderMoneyTooltip(text_value)
    -- 1. Получаем состояние элемента (InputText)
    local is_active = imgui.IsItemActive()
    local is_hovered = imgui.IsItemHovered()
    
    -- Если мы не пишем и не навели мышку -- ничего не показываем
    if not is_active and not is_hovered then return end
    
    local val = tonumber(text_value)
    -- Показываем подсказку только для сумм от 1000, чтобы не мелькала на мелких числах
    if not val or val < 1000 then return end
    
    -- 2. Форматирование текста (сокращения) - ИСПРАВЛЕННАЯ ЛОГИКА
    local formatted = ""
    local num_val = 0
    local suffix = ""

    if val >= 1000000000 then
        num_val = val / 1000000000
        suffix = u8" млрд."
    elseif val >= 1000000 then
        num_val = val / 1000000
        suffix = u8" млн."
    elseif val >= 1000 then
        num_val = val / 1000
        suffix = u8" тыс."
    end

    if suffix ~= "" then
        -- Форматируем число отдельно от текста
        local clean_num = string.format("%.2f", num_val)
        -- Безопасно удаляем нули только с конца числа (1.50 -> 1.5, 231.06 -> 231.06)
        clean_num = clean_num:gsub("0+$", "")
        -- Удаляем точку, если она осталась последней (100. -> 100)
        clean_num = clean_num:gsub("%.$", "")
        
        formatted = clean_num .. suffix
    end
    
    -- Полное число с точками
    local money_str = formatMoney(val)
    
    -- 3. Отрисовка
    if is_hovered then
        -- ВАРИАНТ А: Мышь на поле. Используем стандартный Tooltip (следует за мышкой)
        imgui.BeginTooltip()
        imgui.TextColored(CURRENT_THEME.accent_success, formatted)
        imgui.SameLine()
        imgui.TextDisabled(string.format("(%s $)", money_str))
        imgui.EndTooltip()
        
    elseif is_active then
        -- ВАРИАНТ Б: Мы пишем, но мышь убрали. 
        -- Рисуем фиксированное окошко прямо НАД полем ввода.
        
        local p_min = imgui.GetItemRectMin()
        
        -- Стилизация мини-окна под тему
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(4)))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(6))
        imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.08, 0.08, 0.10, 0.95)) -- Темный фон
        imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)          -- Цветная рамка
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1))
        
        -- Позиция: X = начало поля, Y = над полем (с отступом S(32) вверх)
        local tooltip_pos = imgui.ImVec2(p_min.x, p_min.y - S(32))
        imgui.SetNextWindowPos(tooltip_pos)
        
        -- Флаги окна: Tooltip (поверх всего), без ввода, без заголовка, авто-размер
        local flags = imgui.WindowFlags.Tooltip + imgui.WindowFlags.NoInputs + 
                      imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoMove + 
                      imgui.WindowFlags.NoResize + imgui.WindowFlags.AlwaysAutoResize
        
        if imgui.Begin("##fixed_money_tooltip", nil, flags) then
            imgui.TextColored(CURRENT_THEME.accent_success, formatted)
            imgui.SameLine()
            imgui.TextDisabled(string.format("(%s $)", money_str))
            imgui.End()
        end
        
        imgui.PopStyleVar(3)
        imgui.PopStyleColor(2)
    end
end

function renderUnifiedConfigItem(index, item, mode)
    if not item then return end
    local height = S(85)
    local padding = S(10)
    
    local p = imgui.GetCursorScreenPos()
    local is_sell = (mode == "sell")
    local draw_list = imgui.GetWindowDrawList()
    
    local avail_width = imgui.GetContentRegionAvail().x - S(10) 
    
    local is_buy_accessory = (not is_sell) and isAccessory(item.name)
    
    -- [ОПТИМИЗАЦИЯ FPS] Генерируем строки-ключи строго ОДИН раз для предмета
    if not item._str_keys_cached then
        item._uid_cache = tostring(item):gsub("table: ", "") .. tostring(os.clock())
        local item_uid = item._uid_cache .. (mode == "sell" and "_s" or "_b")
        local prefix = mode == "sell" and "s" or "b"
        
        item._ui_id = "u_item_" .. item_uid
        item._buf_price = prefix .. "p_" .. item_uid
        item._buf_amount = prefix .. "a_" .. item_uid
        item._str_keys_cached = true
    end
    
    -- Используем уже готовые закешированные строки
    imgui.PushIDStr(item._ui_id)
    
    if item.active == nil then item.active = true end
    if is_sell and item.auto_max == nil then item.auto_max = true end
    
    local buf_key_price  = item._buf_price
    local buf_key_amount = item._buf_amount
    local buffer_table = is_sell and Buffers.sell_input_buffers or Buffers.buy_input_buffers
    if not buffer_table[buf_key_price] then 
        buffer_table[buf_key_price] = imgui.new.char[32](tostring(item.price or (is_sell and 0 or 100))) 
    end
    
    local max_inv_amount = 0
    if is_sell then
        max_inv_amount = getInventoryAmountForItem(item.model_id, item.slot)
        if item.auto_max then item.amount = max_inv_amount end
        if not item.auto_max and (item.amount or 0) > max_inv_amount and max_inv_amount > 0 then
            item.amount = max_inv_amount
        end
    end
    if not buffer_table[buf_key_amount] then 
        buffer_table[buf_key_amount] = imgui.new.char[32](tostring(item.amount or (is_buy_accessory and 0 or 1))) 
    end
    
    imgui.BeginGroup()
    imgui.SetCursorScreenPos(p)
    imgui.Dummy(imgui.ImVec2(avail_width, height))
    
    local is_card_hovered = imgui.IsMouseHoveringRect(p, imgui.ImVec2(p.x + avail_width, p.y + height))
    
    local bg_col_u32 = CURRENT_THEME.bg_secondary_u32
    -- Подсветка всей карточки при наведении мыши (важно для UX!)
    if is_card_hovered then
        bg_col_u32 = CURRENT_THEME.bg_tertiary_u32
    end
    
    if is_sell and item.missing then 
        bg_col_u32 = setAlphaU32(CURRENT_THEME.accent_danger_u32, is_card_hovered and 0.25 or 0.15)
    end
    
    -- Основной фон карточки
    draw_list:AddRectFilled(p, SetVec(REN_VEC_1, p.x + avail_width, p.y + height), bg_col_u32, S(8))
    
    -- [NEW] Эффект объема (светлая фаска сверху и тонкая обводка)
    local hl_alpha = is_card_hovered and 0.08 or 0.03
    local highlight_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, hl_alpha))
    draw_list:AddRect(p, REN_VEC_1, highlight_col, S(8), 15, S(1))
    
    if item.active then
        local accent_col = is_sell and CURRENT_THEME.accent_success_u32 or CURRENT_THEME.accent_primary_u32
        -- Полоска статуса слева (сделали чуть толще для контраста)
        draw_list:AddRectFilled(p, SetVec(REN_VEC_2, p.x + S(6), p.y + height), accent_col, S(8), 5)
    else
        -- Заштриховка неактивной карточки
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + avail_width, p.y + height), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0,0,0, 0.3)), S(8))
    end
    
	local now = os.clock()
    if not item._price_check_time or (now - item._price_check_time) > 2.0 then
        item._cached_avg_price = getAveragePriceForItem(item, mode)
        item._cached_strict_avg = getAveragePriceForItem(item, mode, true)
        
        -- [КРИТИЧЕСКИЙ ФИКС FPS] Кэшируем цены для тултипа здесь (раз в 2 сек), а не каждый кадр при движении мыши
        item._cached_stat_sell = (mode == "sell") and item._cached_strict_avg or getAveragePriceForItem(item, "sell", true)
        item._cached_stat_buy = (mode == "buy")  and item._cached_strict_avg or getAveragePriceForItem(item, "buy", true)
        
        item._cached_matches_count = 0
        if is_sell then
            for _, sit in ipairs(Data.sell_list) do
                if sit.name == item.name then item._cached_matches_count = item._cached_matches_count + 1 end
            end
        end
        
        local name_str = item.name:gsub("%s*%(x%d+%)", "")
        item._u8_display_name = u8(index .. ". " .. name_str)
        if (not is_sell) and isAccessory(item.name) then
            item._u8_display_name = u8(index .. ". " .. name_str .. " [Цвет: " .. (item.amount or 0) .. "]")
        end
        if is_sell and item.missing then 
            item._u8_display_name = u8(index .. ". " .. name_str .. " (НЕТ В ИНВЕНТАРЕ)") 
        end
        
        if is_sell then
            item._cached_inv_amount = getInventoryAmountForItem(item.model_id, item.slot)
        end
        item._price_check_time = now
    end
    
	local avg_price = item._cached_avg_price
	local strict_avg = item._cached_strict_avg
    local max_inv_amount = item._cached_inv_amount or 0

	if item.active and strict_avg and strict_avg > 0 and (item.price or 0) > 0 then
		local ratio = item.price / strict_avg
		local bar_w = avail_width * 0.8
		local bar_x = p.x + (avail_width - bar_w) / 2
		local bar_y = p.y + height - S(3)

		local fill_w = 0
		local bar_col = 0

		if is_sell then
			fill_w = math.min(math.abs(1.0 - ratio) * (bar_w/2), bar_w/2)
			bar_col = ratio >= 1.0 and (CURRENT_THEME.accent_success_u32 or 0xFF00FF00) or (CURRENT_THEME.accent_danger_u32 or 0xFF0000FF)
		else
			fill_w = math.min(math.abs(1.0 - ratio) * (bar_w/2), bar_w/2)
			bar_col = ratio <= 1.0 and (CURRENT_THEME.accent_success_u32 or 0xFF00FF00) or (CURRENT_THEME.accent_danger_u32 or 0xFF0000FF)
		end

		draw_list:AddRectFilled(
			imgui.ImVec2(bar_x, bar_y),
			imgui.ImVec2(bar_x + bar_w, bar_y + S(3)),
			setAlphaU32(CURRENT_THEME.text_primary_u32, 0.08), 
			S(2)
		)

		local center_x = bar_x + (bar_w/2)

		if ratio > 1.0 then
			draw_list:AddRectFilled(imgui.ImVec2(center_x, bar_y), imgui.ImVec2(center_x + fill_w, bar_y + S(3)), bar_col, S(2))
		else
			draw_list:AddRectFilled(imgui.ImVec2(center_x - fill_w, bar_y), imgui.ImVec2(center_x, bar_y + S(3)), bar_col, S(2))
		end

		draw_list:AddRectFilled(
			imgui.ImVec2(center_x - S(1), bar_y - S(1)),
			imgui.ImVec2(center_x + S(1), bar_y + S(4)),
			CURRENT_THEME.text_primary_u32
		)
	end
    
    local grip_width = S(28)
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + S(4), p.y + (height - S(24))/2))
    -- ОПТИМИЗАЦИЯ: Не склеиваем ID, так как мы внутри PushID
    imgui.InvisibleButton("##grip", imgui.ImVec2(grip_width, S(24)))
    local is_grip_hovered = imgui.IsItemHovered()

    if is_grip_hovered and imgui.IsMouseClicked(1) and not MagnetMove.active then
        MagnetMove.active = true
        MagnetMove.mode = mode
        MagnetMove.from_index = index
        MagnetMove.item_data = item
        MagnetMove.pickup_time = os.clock() 
        addToastNotification("Товар взят! Скролльте и нажмите ЛКМ для вставки.", "info", 3.0)
    end

    if font_fa then
        imgui.PushFont(font_fa)
        local is_magnetized = (MagnetMove.active and MagnetMove.mode == mode and MagnetMove.from_index == index)
        local grip_icon = is_magnetized and fa('magnet') or fa('grip_vertical')
        
        local grip_col = is_grip_hovered and CURRENT_THEME.accent_primary or CURRENT_THEME.text_hint
        if is_magnetized then grip_col = CURRENT_THEME.accent_warning end 
        
        local grip_pos_x = p.x + S(10)
        local grip_pos_y = p.y + (height - GetStaticTextSize(grip_icon).y)/2
        draw_list:AddText(imgui.ImVec2(grip_pos_x, grip_pos_y), imgui.ColorConvertFloat4ToU32(grip_col), grip_icon)
        imgui.PopFont()
    end

    if is_grip_hovered and not MagnetMove.active then 
        imgui.SetTooltip(u8"ЛКМ + Тянуть = Обычное перемещение\nПКМ = Магнитное (быстрое) перемещение") 
    end

    if not MagnetMove.active and imgui.BeginDragDropSource() then
        imgui.SetDragDropPayload(is_sell and "DND_SELL" or "DND_BUY", ffi.new('int[1]', index), ffi.sizeof('int'))
        imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.08, 0.08, 0.1, 0.95))
        imgui.BeginGroup()
            imgui.TextColored(CURRENT_THEME.text_primary, u8(item.name))
        imgui.EndGroup()
        imgui.PopStyleColor()
        imgui.EndDragDropSource()
    end
    
    local icon_box_sz = S(46) 
    local icon_box_x = p.x + grip_width + S(5)
    local icon_box_y = p.y + (height - icon_box_sz) / 2

    local box_min = imgui.ImVec2(icon_box_x, icon_box_y)
    local box_max = imgui.ImVec2(icon_box_x + icon_box_sz, icon_box_y + icon_box_sz)
    local box_rounding = S(10)

	local slot_bg_col = CURRENT_THEME.bg_main_u32
	draw_list:AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)

	local glow_base_u32 = item.active and CURRENT_THEME.accent_primary_u32 or CURRENT_THEME.text_hint_u32
	local glow_col = setAlphaU32(glow_base_u32, item.active and 0.20 or 0.05)
	draw_list:AddRectFilled(box_min, box_max, glow_col, box_rounding)

	local border_col = setAlphaU32(CURRENT_THEME.text_primary_u32, item.active and 0.20 or 0.08)
	draw_list:AddRect(box_min, box_max, border_col, box_rounding, 15, S(1.5))

    local texture = getItemIconTexture(tonumber(item.model_id))
    if texture then
        local pad = S(4)
        local uv0 = imgui.ImVec2(0, 0)
        local uv1 = imgui.ImVec2(1, 1)
        
        local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.8))
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(3)), imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(3)), uv0, uv1, shadow_col)
        
        local tex_col = item.active and 0xFFFFFFFF or imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.5))
        draw_list:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad), imgui.ImVec2(box_max.x - pad, box_max.y - pad), uv0, uv1, tex_col)
    else
        if font_fa then
            imgui.PushFont(font_fa)
            local ph_icon = fa('box_open')
            local p_sz = GetStaticTextSize(ph_icon)
            
            local pulse = (math.sin(os.clock() * 4) + 1) * 0.5
            local icon_alpha = 0.2 + (pulse * 0.3)
            local ph_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, icon_alpha))
            
            draw_list:AddText(imgui.ImVec2(icon_box_x + (icon_box_sz - p_sz.x)/2, icon_box_y + (icon_box_sz - p_sz.y)/2), ph_col, ph_icon)
            imgui.PopFont()
        end
    end

    imgui.SetCursorScreenPos(box_min)
    imgui.InvisibleButton("##img_hover_cfg", imgui.ImVec2(icon_box_sz, icon_box_sz))
    if texture and imgui.IsItemHovered() then
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(8)))
        imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.05, 0.05, 0.06, 0.98))
        imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
        
        imgui.BeginTooltip()
        imgui.Image(texture, imgui.ImVec2(S(130), S(130)))
        imgui.EndTooltip()
        
        imgui.PopStyleVar(2)
        imgui.PopStyleColor(2)
    end

    local content_offset_x = grip_width + icon_box_sz + S(22) 
    local cursor_x = p.x + content_offset_x
    
    local row1_y = p.y + S(13) 
    
    local toggle_radius = S(11)
    local toggle_w = toggle_radius * 2
    local toggle_h = toggle_w
    
    local toggle_draw_y = row1_y + (imgui.GetFontSize() - toggle_h) / 2
    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, toggle_draw_y))
    
    if is_sell and item.missing then
        if font_fa then
            imgui.PushFont(font_fa)
            local icon_ban = fa('ban')
            local isz = GetStaticTextSize(icon_ban)
            
            draw_list:AddCircleFilled(imgui.ImVec2(cursor_x + toggle_radius, toggle_draw_y + toggle_radius), toggle_radius, 0x99262626)
            
            draw_list:AddText(
                imgui.ImVec2(cursor_x + (toggle_w - isz.x)/2, toggle_draw_y + (toggle_h - isz.y)/2),
                imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_danger),
                icon_ban
            )
            imgui.PopFont()
        end
        imgui.InvisibleButton("##disabled_toggle", imgui.ImVec2(toggle_w, toggle_h))
        if imgui.IsItemHovered() then
            imgui.SetTooltip(u8"Товар отсутствует в инвентаре.\nАвтоматически исключен из продажи.")
        end
    else
        if renderAAAToggle("##act_toggle", item.active) then
            item.active = not item.active
            saveListsConfig()
            if is_sell then calculateSellTotal() else calculateBuyTotal() end
        end
    end
    
    cursor_x = cursor_x + toggle_w + S(12)
    local display_name = item._u8_display_name or u8(item.name)
    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, row1_y))
    
	local text_col = item.active and CURRENT_THEME.text_primary or CURRENT_THEME.text_hint
	
	local price_warning = false
	if is_sell and item.missing then 
		text_col = CURRENT_THEME.accent_danger
	else
		if strict_avg and strict_avg > 0 and (item.price or 0) > 0 then
			if is_sell then
				if item.price < strict_avg then 
					text_col = CURRENT_THEME.accent_danger 
					price_warning = true
				end
			else
				if item.price > strict_avg then 
					text_col = CURRENT_THEME.accent_danger 
					price_warning = true
				end
			end
		end
	end

	imgui.PushFont(font_default)
	imgui.TextColored(text_col, display_name)
    if (imgui.IsItemHovered() or (imgui.IsItemHovered(imgui.HoveredFlags.AllowWhenOverlapped))) then
        local stat_sell = item._cached_stat_sell
        local stat_buy  = item._cached_stat_buy
        
        if (stat_sell and stat_sell > 0) or (stat_buy and stat_buy > 0) then
            local is_right_mouse_down = imgui.IsMouseDown(1)
            if is_right_mouse_down then
                imgui.GetIO().WantCaptureMouse = true
            end
            imgui.BeginTooltip()
            imgui.TextColored(CURRENT_THEME.text_secondary, u8("Популярные цены на сервере:"))
            imgui.Separator()
            imgui.TextColored(CURRENT_THEME.text_hint, u8("ТЕКУЩИЕ:"))
            if stat_sell and stat_sell > 0 then
                local clean_k = cleanItemNameKey(item.name)
                local price_info = Data.average_prices[clean_k]
                local label = u8("Продажа:")
                if price_info and price_info.source == "daily" then
                    label = u8("Продажа:")
                end
                imgui.TextColored(CURRENT_THEME.accent_success, label)
                imgui.SameLine(S(120))
                imgui.TextColored(CURRENT_THEME.accent_success, formatMoney(stat_sell) .. " $")
            else
                imgui.TextDisabled(u8("Продажа: нет данных"))
            end
            if stat_buy and stat_buy > 0 then
                imgui.TextColored(CURRENT_THEME.accent_primary, u8("Скупка:"))
                imgui.SameLine(S(120))
                imgui.TextColored(CURRENT_THEME.accent_primary, formatMoney(stat_buy) .. " $")
            else
                imgui.TextDisabled(u8("Скупка: нет данных"))
            end
            if price_warning then
                imgui.Separator()
                if is_sell then
                    imgui.TextColored(CURRENT_THEME.accent_danger, fa("TRIANGLE_EXCLAMATION") .. u8(" Цена ниже рыночной!"))
                else
                    imgui.TextColored(CURRENT_THEME.accent_danger, fa("TRIANGLE_EXCLAMATION") .. u8(" Цена выше рыночной!"))
                end
                imgui.Text(u8("Ваша цена: ") .. formatMoney(item.price) .. u8(" $"))
            end
            if is_right_mouse_down then
                local tooltip_width = S(420)
                imgui.Separator()
                imgui.TextColored(CURRENT_THEME.text_secondary, fa("chart_line") .. u8(" История (последние 3 дня):"))
                if UIState.daily_price_tooltip.last_requested_item ~= item.name then
                    UIState.daily_price_tooltip.last_requested_item = item.name
                    UIState.daily_price_tooltip.daily_prices = nil
                    UIState.daily_price_tooltip.loading = true
                    api_GetDailyPricesForItem(item.name, function(prices)
                        if UIState.daily_price_tooltip.last_requested_item == item.name then
                            UIState.daily_price_tooltip.daily_prices = prices
                            UIState.daily_price_tooltip.loading = false
                        end
                    end)
                end
                local daily_prices = UIState.daily_price_tooltip.daily_prices
                if UIState.daily_price_tooltip.loading then
                    imgui.TextDisabled(u8("Загрузка данных..."))
                elseif daily_prices and #daily_prices > 0 then
                    imgui.Dummy(imgui.ImVec2(0, S(2)))
                    imgui.TextColored(CURRENT_THEME.text_hint, u8"Дата")
                    imgui.SameLine(S(90))
                    imgui.TextColored(CURRENT_THEME.text_hint, u8"Продажа")
                    imgui.SameLine(S(220))
                    imgui.TextColored(CURRENT_THEME.text_hint, u8"Скупка")
                    imgui.Separator()
                    local start_index = math.max(1, #daily_prices - 2)
                    for i = start_index, #daily_prices do
                        local price_data = daily_prices[i]
                        local date_str = price_data.date_str or "?"
                        if #date_str > 5 then date_str = date_str:sub(1, 5) end
                        local sell_price = tonumber(price_data.sell) or tonumber(price_data.avg_sell) or 0
                        local buy_price = tonumber(price_data.buy) or tonumber(price_data.avg_buy) or 0
                        imgui.TextColored(CURRENT_THEME.text_secondary, date_str)
                        imgui.SameLine(S(90))
                        if sell_price > 0 then
                            imgui.TextColored(CURRENT_THEME.accent_success, formatMoney(sell_price) .. " $")
                        else
                            imgui.TextDisabled("-")
                        end
                        imgui.SameLine(S(220))
                        if buy_price > 0 then
                            imgui.TextColored(CURRENT_THEME.accent_primary, formatMoney(buy_price) .. " $")
                        else
                            imgui.TextDisabled("-")
                        end
                    end
                else
                    imgui.TextDisabled(u8("Нет данных"))
                end
                imgui.Dummy(imgui.ImVec2(tooltip_width, S(2)))
            else
                imgui.Spacing()
                imgui.TextDisabled(u8("(Удерживайте ПКМ для истории)"))
            end
            if avg_price and avg_price > 0 then
                imgui.Separator()
                imgui.TextDisabled(u8("ЛКМ > установить: ") .. formatMoney(avg_price) .. u8(" $"))
            end
            imgui.EndTooltip()
        end
    end
    if imgui.IsItemClicked() and avg_price and avg_price > 0 then
        item.price = avg_price
        imgui.StrCopy(buffer_table[buf_key_price], tostring(avg_price))
