        item._price_pad_x = nil 
        if is_sell then calculateSellTotal() else calculateBuyTotal() end
        saveListsConfig()
    end
    imgui.PopFont()
    local row2_y = p.y + S(45)
    cursor_x = p.x + content_offset_x 
    local input_price_w = S(120)
    local input_h = S(30)
    
	-- Инпуты должны быть ТЕМНЕЕ карточки, создавая эффект "углубления"
	local bg_input_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.25))
	-- Рамка инпута - прозрачный белый
