    imgui.SetCursorScreenPos(imgui.ImVec2(cursor_x, row2_y))
    
    if not item._price_pad_x then
        local current_price_str = ffi.string(buffer_table[buf_key_price])
        local txt_width = GetStaticTextSize(current_price_str).x
