        item._last_price_str = new_str
        item._price_pad_x = nil 
        if is_sell then calculateSellTotal() else calculateBuyTotal() end
    end
    if imgui.IsItemDeactivatedAfterEdit() then
		local raw_text = ffi.string(buffer_table[buf_key_price])
		local smart_val = parseRodinaPrice(raw_text)

		if smart_val > 0 then
			item.price = smart_val
			imgui.StrCopy(buffer_table[buf_key_price], tostring(smart_val))
            item._last_price_str = tostring(smart_val)
            item._price_pad_x = nil
			addToastNotification("Цена конвертирована: " .. formatMoney(smart_val), "info", 1.0)
		else
			item.price = tonumber(raw_text) or 0
		end

		if is_sell then calculateSellTotal() else calculateBuyTotal() end
		saveListsConfig()
