    cursor_x = cursor_x + input_price_w + S(8)
    if font_fa then
        imgui.PushFont(font_fa)
        local rub_sz = GetStaticTextSize(fa('ruble_sign'))
        draw_list:AddText(imgui.ImVec2(cursor_x, row2_y + (S(30)-rub_sz.y)/2), CURRENT_THEME.text_hint_u32, fa('ruble_sign'))
        imgui.PopFont()
        cursor_x = cursor_x + rub_sz.x + S(8)
    else
        cursor_x = cursor_x + S(20)
    end
    
    if is_sell then
        local matches_count = item._cached_matches_count or 0
        if matches_count > 1 then
