        draw_list:AddRectFilled(imgui.ImVec2(cursor_x, row2_y), imgui.ImVec2(cursor_x + input_amt_w, row2_y + S(30)), max_bg_col, S(6))
        draw_list:AddRect(imgui.ImVec2(cursor_x, row2_y), imgui.ImVec2(cursor_x + input_amt_w, row2_y + S(30)), max_border_col, S(6), 15, S(1))
        
