        local txt_sz = GetStaticTextSize(txt_max)
        draw_list:AddText(imgui.ImVec2(cursor_x + (input_amt_w - txt_sz.x)/2, row2_y + (S(30) - txt_sz.y)/2), CURRENT_THEME.text_primary_u32, txt_max)
        
