                imgui.StrCopy(buffer_table[buf_key_amount], tostring(item.amount))
                item._last_sync_amount = item.amount
            end
        end
        
        local amt_sz = 0
        if imgui.IsItemActive() then
            amt_sz = GetStaticTextSize(ffi.string(buffer_table[buf_key_amount])).x
        else
            if not item._c_amt_sz_cfg or item._c_last_amt_cfg ~= item.amount then
                item._c_amt_sz_cfg = GetStaticTextSize(tostring(item.amount)).x
                item._c_last_amt_cfg = item.amount
            end
            amt_sz = item._c_amt_sz_cfg
        end

        local amt_pad = (input_amt_w - amt_sz) / 2
        if amt_pad < S(5) then amt_pad = S(5) end
        
		draw_list:AddRectFilled(imgui.ImVec2(cursor_x, row2_y), imgui.ImVec2(cursor_x + input_amt_w, row2_y + S(30)), bg_input_col_u32, S(6))
		draw_list:AddRect(imgui.ImVec2(cursor_x, row2_y), imgui.ImVec2(cursor_x + input_amt_w, row2_y + S(30)), 0x0FFFFFFF, S(6), 15, S(1))
		
		if is_buy_accessory then
			draw_list:AddRect(imgui.ImVec2(cursor_x, row2_y), imgui.ImVec2(cursor_x + input_amt_w, row2_y + S(30)), CURRENT_THEME.accent_primary_u32, S(6), 15, S(1.0))
		end
        
