                imgui.SetTooltip(u8"Сотрите текст или введите 0, чтобы вернуть режим MAX")
            end
        end
        imgui.PopStyleVar()
        imgui.PopStyleColor()
        if imgui.IsItemDeactivatedAfterEdit() then saveListsConfig() end
    end
    
    cursor_x = cursor_x + input_amt_w + S(8)
