        local ch_border_col = chart_hovered and setAlphaU32(CURRENT_THEME.accent_primary_u32, 0.5) or 0x0FFFFFFF
        draw_list:AddRectFilled(imgui.ImVec2(chart_x, row2_y), imgui.ImVec2(chart_x + chart_size, row2_y + S(30)), ch_bg_col, S(6))
        draw_list:AddRect(imgui.ImVec2(chart_x, row2_y), imgui.ImVec2(chart_x + chart_size, row2_y + S(30)), ch_border_col, S(6), 15, S(1))

