    local pl_border_col = play_hovered and setAlphaU32(CURRENT_THEME.accent_success_u32, 0.5) or 0x0FFFFFFF
    draw_list:AddRectFilled(imgui.ImVec2(play_x, row2_y), imgui.ImVec2(play_x + play_size, row2_y + S(30)), pl_bg_col, S(6))
    draw_list:AddRect(imgui.ImVec2(play_x, row2_y), imgui.ImVec2(play_x + play_size, row2_y + S(30)), pl_border_col, S(6), 15, S(1))

