        local p_col = play_hovered and CURRENT_THEME.accent_success_u32 or CURRENT_THEME.text_secondary_u32
        draw_list:AddText(imgui.ImVec2(play_x + (play_size - psz.x)/2, row2_y + (S(30) - psz.y)/2), p_col, icon_play)
