	local del_bg_col = is_del_hov and setAlphaU32(CURRENT_THEME.accent_danger_u32, 0.2) or 0x08FFFFFF
	local del_border_col = is_del_hov and setAlphaU32(CURRENT_THEME.accent_danger_u32, 0.5) or 0x0FFFFFFF

	draw_list:AddRectFilled(imgui.ImVec2(del_x, row2_y), imgui.ImVec2(del_x + del_size, row2_y + S(30)), del_bg_col, S(6))
	draw_list:AddRect(imgui.ImVec2(del_x, row2_y), imgui.ImVec2(del_x + del_size, row2_y + S(30)), del_border_col, S(6), 15, S(1))

