		for k,v in pairs(item) do deleted_copy[k] = v end

		table.insert(App.undo_stack,{
			list = mode,
			index = index,
			item = deleted_copy
		})

		App.undo_timer = os.clock() + 5.0

		table.remove(is_sell and Data.sell_list or Data.buy_list, index)
		rebuildLookupTables()
		saveListsConfig()
		if is_sell then 
            calculateSellTotal() 
            App.sell_ui_cache = nil 
        else 
            calculateBuyTotal() 
            App.buy_conf_ui_cache = nil 
        end
