		local tsz = GetStaticTextSize(icon_trash)
		draw_list:AddText(imgui.ImVec2(del_x + (del_size-tsz.x)/2, row2_y + (S(30)-tsz.y)/2), del_icon_col, icon_trash)
		imgui.PopFont()
	end
    imgui.EndGroup()
    
    if imgui.BeginDragDropTarget() then
