        if is_hovered_full then
            local mouse_y = imgui.GetMousePos().y
            local item_center_y = p.y + (height / 2)
            local is_bottom_half = mouse_y > item_center_y
            
            local line_y = is_bottom_half and (p.y + height + S(2)) or (p.y - S(2))
            draw_list:AddRectFilled(imgui.ImVec2(p.x, line_y - S(2)), imgui.ImVec2(p.x + avail_width, line_y + S(2)), CURRENT_THEME.accent_warning_u32, S(2))
            
            imgui.SetMouseCursor(imgui.MouseCursor.Hand)
            
            if imgui.IsMouseClicked(0) then
                local to_index = is_bottom_half and (index + 1) or index
                local target_list = (mode == "sell") and Data.sell_list or Data.buy_list
                
                moveTableItem(target_list, MagnetMove.from_index, to_index)
                saveListsConfig()
                if mode == "sell" then calculateSellTotal() else calculateBuyTotal() end
                
                App.sell_ui_cache = nil
                App.buy_conf_ui_cache = nil
                
                MagnetMove.active = false
                MagnetMove.item_data = nil
                addToastNotification("Товар успешно перемещен!", "success")
            end
        end
    end
    imgui.PopID()
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + height + padding))
end

function renderIconInButton(draw_list, icon, x, y, size, hovered, color_vec_u32, disabled)
    if not font_fa then return end
    
    -- Используем заранее сгенерированные U32 цвета из темы (0 C-Data аллокаций)
    local u32 = color_vec_u32 or CURRENT_THEME.text_secondary_u32
    if disabled then u32 = CURRENT_THEME.text_hint_u32 end
    if hovered and not disabled then u32 = CURRENT_THEME.text_primary_u32 end
    
    -- Мгновенно меняем альфа-канал через битовые сдвиги
    if disabled then u32 = setAlphaU32(u32, 0.3) end
    
    imgui.PushFont(font_fa)
    local sz = GetStaticTextSize(icon)
    draw_list:AddText(imgui.ImVec2(x + (size-sz.x)/2, y - sz.y/2), u32, icon)
    imgui.PopFont()
end

function startSingleItemSelling(item)
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active then return end
    
    if item.active == false then
        sampAddChatMessage('[RMarket] {ff0000}Товар отключен', -1)
        return
    end
    
    App.live_shop_active = true
    Marketplace.enabled = true
    Marketplace.is_cleared = false
    Marketplace.publish_sell = true
    
    MarketConfig.LAST_SYNC = 0 
    PrepareMarketplaceData() -- Сразу обновляем данные для отправки
    
    App.is_selling_cef = true
    App.current_sell_item_index = 0
    App.current_processing_item = nil -- Сброс текущего предмета
    Data.cef_slots_data = {}
    Data.cef_sell_queue = {}
    
    sampAddChatMessage('[RMarket] {ffff00}Выставление: ' .. item.name, -1)
    
    -- [FIX] Если диалог уже открыт, сразу жмем кнопку
    if sampIsDialogActive() and sampGetCurrentDialogId() == 9 then
        sampSendDialogResponse(9, 1, 0, "") -- Входим в меню "Выставить"
        
        -- Сразу запускаем подготовку после диалога
        App.tasks.add("cef_sell_single_wait_data", function()
            -- Проверка наличия данных инвентаря
            if countTable(Data.cef_slots_data) > 0 then
                prepareSingleItemQueue(item)
            else
                -- Если данных нет, пробуем еще пару раз
                App.tasks.add("cef_sell_single_retry", function()
                     if countTable(Data.cef_slots_data) > 0 then prepareSingleItemQueue(item) end
                end, 500)
            end
        end, 800)
    else
        -- Диалога нет, жмем ALT
        App.tasks.add("cef_sell_single_press_alt", function()
            setVirtualKeyDown(0x12, true)
            App.tasks.add("cef_sell_single_release_alt", function()
                setVirtualKeyDown(0x12, false)
            end, 50)
        end, 500)
        
        -- Ожидаем данные инвентаря и диалога
        App.tasks.add("cef_sell_single_prepare", function()
            if App.is_selling_cef then
                -- Ждем пока загрузятся слоты
                if countTable(Data.cef_slots_data) > 0 then
                    prepareSingleItemQueue(item)
                else
                    -- Если пусто, проверяем таймаут
                    if not App.current_processing_item then
                         -- Можно добавить ретрай, но обычно 2с хватает для открытия диалога
                    end
                end
            end
        end, 2000)
    end
    
    App.tasks.add("cef_sell_single_timeout", function()
        if App.is_selling_cef then
            stopSelling()
        end
    end, 15000)
end

-- Вспомогательная функция для формирования очереди одного предмета
function prepareSingleItemQueue(item)
    Data.cef_sell_queue = {}
    local used_slots = {}
    local target_model = tonumber(item.model_id)
    local found_slot = nil
    
    -- Принудительно берем цену
    local safe_price = tonumber(item.price) or 0
    
    if safe_price <= 0 then
        sampAddChatMessage('[RMarket] {ff0000}Ошибка: Цена товара 0 или некорректна!', -1)
        App.is_selling_cef = false
        sendCEF("inventoryClose")
        return
    end
    
    -- 1. Ищем слот (сначала проверяем сохраненный, потом ищем любой)
    if item.slot and Data.cef_slots_data[item.slot] and Data.cef_slots_data[item.slot].model_id == target_model then
        found_slot = item.slot
    else
        for slot, item_data in pairs(Data.cef_slots_data) do
            if item_data.model_id == target_model and item_data.available == 1 and not used_slots[slot] then
                found_slot = slot
                break
            end
        end
    end
    
    if found_slot then
        local final_amount = item.amount
        if item.auto_max then
            local max_inv = getInventoryAmountForItem(target_model, found_slot)
            if max_inv > 0 then 
                final_amount = max_inv
                item.amount = max_inv
            end
        end

        table.insert(Data.cef_sell_queue, {
            slot = found_slot,
            model = target_model,
            amount = final_amount,
            price = safe_price, -- Используем безопасную цену
            name = item.name,
            retry_count = 0
        })
        
        -- Запускаем процесс обработки очереди
        if not App.current_processing_item then
            processNextCEFSellItem()
        end
    else
        sampAddChatMessage('[RMarket] {ff0000}Товар не найден', -1)
        App.is_selling_cef = false
        sendCEF("inventoryClose")
    end
end

function startSingleItemBuying(item)
    if App.is_scanning or App.is_selling_cef or App.is_downloading_db or State.buying.active then return end
    
    if item.active == false then
