function recalculateInventoryTotals()
    Data.inventory_item_amounts = {}
    for slot, data in pairs(Data.cef_slots_data) do
        if data.model_id and data.amount then
            local s_id = tostring(data.model_id)
            Data.inventory_item_amounts[s_id] = (Data.inventory_item_amounts[s_id] or 0) + data.amount
        end
    end
end

function finishScanningProcess()
    App.is_scanning = false
    if State.inventory_scan then
        State.inventory_scan.active = false
        State.inventory_scan.waiting_for_packets = false
    end
    App.tasks.remove_by_name("scan_timeout")
    App.tasks.remove_by_name("collect_inventory_data") 
    
    if sampIsDialogActive() then
        sampCloseCurrentDialogWithButton(0)
    end
    
    Data.scanned_items = {}
    
    for _, item_data in pairs(Data.cef_inventory_items) do
        local is_money = (item_data.model_id == 3660)
        local has_name = Data.item_names[tostring(item_data.model_id)] ~= nil
        
        if (is_money or has_name) and not isItemUnsellable(item_data.model_id) then
            local original_n = is_money and "Деньги" or item_data.name
            local display_name = original_n
            
            if not is_money then
                if item_data.text and item_data.text ~= "" and item_data.text ~= tostring(item_data.amount) then
                    display_name = display_name .. " [" .. item_data.text .. "]"
                end
                
                if item_data.amount and item_data.amount > 1 then
                    display_name = display_name .. " (x" .. item_data.amount .. ")"
                end
            end

            table.insert(Data.scanned_items, {
                name = display_name, 
                original_name = original_n,
                model_id = item_data.model_id,
                amount = item_data.amount, 
                slot = item_data.slot,
                text = item_data.text,
                time = item_data.time,
                is_blocked = (item_data.blackout == 1) or (item_data.available == 0)
            })
        end
    end
    
    table.sort(Data.scanned_items, function(a, b) 
        return (tonumber(a.slot) or 0) < (tonumber(b.slot) or 0) 
    end)
    
    recalculateInventoryTotals()

    local new_locked_items = {}
    local inventory_map = {}
    local processed_slots = {}

    for _, item in ipairs(Data.scanned_items) do
        inventory_map[tonumber(item.slot)] = tonumber(item.model_id)
    end

    local locks_updated = false

    for lock_key, _ in pairs(Data.locked_items) do
        local model_str, slot_str = lock_key:match("^(%d+)_(%d+)$")
        if model_str and slot_str then
            local locked_model = tonumber(model_str)
            local locked_slot = tonumber(slot_str)
            
            if inventory_map[locked_slot] == locked_model then
                new_locked_items[lock_key] = true
                processed_slots[locked_slot] = true
            else
                local found_new_slot = nil
                
                for _, item in ipairs(Data.scanned_items) do
                    local current_slot = tonumber(item.slot)
                    local check_key = tostring(locked_model) .. "_" .. tostring(current_slot)
                    
                    if tonumber(item.model_id) == locked_model 
                       and not processed_slots[current_slot] 
                       and not Data.locked_items[check_key] then
                        
                        found_new_slot = current_slot
                        break
                    end
                end
                
                if found_new_slot then
                    local new_key = tostring(locked_model) .. "_" .. tostring(found_new_slot)
                    new_locked_items[new_key] = true
                    processed_slots[found_new_slot] = true
                    locks_updated = true
                else
                    locks_updated = true
                end
            end
        end
    end
    
    if locks_updated then
        Data.locked_items = new_locked_items
        saveJsonFile(FILES.LOCKED_ITEMS, Data.locked_items)
    end
    
    local pool_slots = {} 
    for _, scanned in ipairs(Data.scanned_items) do
        local mid = tonumber(scanned.model_id)
        if mid then
            if not pool_slots[mid] then pool_slots[mid] = {} end
            table.insert(pool_slots[mid], {
                slot = tonumber(scanned.slot),
                amount = tonumber(scanned.amount) or 0
            })
        end
    end
    
    for _, list in pairs(pool_slots) do
        table.sort(list, function(a, b) return a.slot < b.slot end)
    end

    for _, sell_item in ipairs(Data.sell_list) do
        if sell_item.model_id then
            local mid = tonumber(sell_item.model_id)
            local assigned_slot = nil
            local found_amount = 0
            
            if sell_item.slot and pool_slots[mid] then
                for i, data in ipairs(pool_slots[mid]) do
                    if data.slot == tonumber(sell_item.slot) then
                        assigned_slot = data.slot
                        found_amount = data.amount
                        table.remove(pool_slots[mid], i)
                        break
                    end
                end
            end
            
            if not assigned_slot and pool_slots[mid] and #pool_slots[mid] > 0 then
                local data = table.remove(pool_slots[mid], 1)
                assigned_slot = data.slot
                found_amount = data.amount
                sell_item.slot = assigned_slot
            end
            
            if assigned_slot then
                sell_item.missing = false
                
                if sell_item.auto_max then
                    sell_item.amount = found_amount
                else
                    if (sell_item.amount or 0) > found_amount then
                        sell_item.amount = found_amount
                    end
                end
            else
                sell_item.missing = true
            end
        end
    end
    
    saveJsonFile(PATHS.CACHE .. 'scanned_items.json', Data.scanned_items)
    saveJsonFile(PATHS.DATA .. 'item_amounts.json', Data.inventory_item_amounts)
    
    -- [CRITICAL FIX] Жестко пересобираем кэш после того, как слоты были перетасованы. 
    -- Это гарантирует 100% синхронизацию кнопок "Добавлено" с новым инвентарем.
    rebuildLookupTables()
    
    api_SyncInventory()
    api_SyncConfigsToMiniApp() 
    
    calculateSellTotal()
    saveListsConfig()
    
    Data.cached_sell_filtered = nil 
    App.inv_ui_cache = nil -- [FIX] Очищаем современный кэш UI инвентаря
    
    sampAddChatMessage('[RMarket] {00ff00}Сканирование товаров: ' .. #Data.scanned_items, -1)
    
    App.is_busy_remote = false
    updateInvCategories()
    App.win_state[0] = true
end

function parseCEFInventory(str)
    -- [ОПТИМИЗАЦИЯ] Быстрый выход, если строка пустая
    if not str or #str < 10 then return end
    
    if not string.find(str, "inventory", 1, true) and not string.find(str, "items", 1, true) then 
        return 
    end

    str = str:gsub("`", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if not (str:find("event%.inventory%.playerInventory") or str:find("items") or str:find("action")) then return end
    
    if State.inventory_scan and State.inventory_scan.waiting_for_packets then
        State.inventory_scan.last_packet_time = os.clock()
        State.inventory_scan.has_received_data = true
    end
    
    local json_start = str:find("%[")
    if not json_start then return end
    
    local bracket_count = 0
    local json_end = nil
    for i = json_start, #str do
        local char = str:sub(i, i)
        if char == "[" then bracket_count = bracket_count + 1
        elseif char == "]" then
            bracket_count = bracket_count - 1
            if bracket_count == 0 then json_end = i break end
        end
    end
    if not json_end then return end
    
    local json_str = str:sub(json_start, json_end):gsub("%c", "")
    local status, data = pcall(json.decode, json_str)
    if not status or not data then return end
    
    for _, event_data in ipairs(data) do
        local action = event_data.action 
        local d = event_data.data
        
        -- ============================================================
        -- [STEP 1] СБОР ТОВАРОВ (Action 0 или 2) - ЛАВКА (Тип 9 или 10)
        -- ============================================================
        if (action == 0 or action == 2) and d and (d.type == 9 or d.type == 10) and d.items then
            local now = os.clock()
            local time_since_last = now - (ScanCollector.last_packet_time or 0)
            
            -- Увеличенный таймаут (2.0 сек), чтобы все страницы успевали прийти одним куском
            local is_same_sequence = (time_since_last < 2.0) and (ScanCollector.last_updated_type == d.type)
            
            ScanCollector.last_packet_time = now
            ScanCollector.last_updated_type = d.type
            
            App.remote_shop_active = true

            if action == 0 and not is_same_sequence then
                if time_since_last > 15.0 then
                     ScanCollector.current_shop_owner = nil
                     Data.remote_shop_items = {}
                else
                    for i = #Data.remote_shop_items, 1, -1 do
                        if Data.remote_shop_items[i].shop_type == d.type then
                            table.remove(Data.remote_shop_items, i)
                        end
                    end
                end
            end
            
            -- Сохраняем пакеты в универсальный кэш просмотра
            for _, item in ipairs(d.items) do
                if item.item then
                    local model_id = tonumber(item.item)
                    local item_name = Data.item_names[tostring(model_id)] or ("Item_"..model_id)
                    
                    local raw_price_text = item.text or "0"
                    local real_price = parseRodinaPrice(raw_price_text)
                    local amount = item.amount or 1
                    
                    local new_item_data = {
                        name = item_name, 
                        model_id = model_id, 
                        slot = item.slot,
                        amount = amount, 
                        price_text = raw_price_text, 
                        raw_price = real_price, 
                        shop_type = d.type
                    }
                    
                    -- Upsert (защита от дублей)
                    local found_idx = nil
                    for i, existing in ipairs(Data.remote_shop_items) do
                        if existing.slot == item.slot and existing.shop_type == d.type then
                            found_idx = i
                            break
                        end
                    end
                    
                    if found_idx then
                        -- Если action == 2 (обновление) и available == 0, удаляем товар
                        if item.available == 0 then
                            table.remove(Data.remote_shop_items, found_idx)
                        else
                            Data.remote_shop_items[found_idx] = new_item_data
                        end
                    else
                        if item.available ~= 0 then
                            table.insert(Data.remote_shop_items, new_item_data)
                        end
                    end
                elseif item.available == 0 and item.slot then
                    -- Удаление пустого слота (кто-то купил)
                    for i = #Data.remote_shop_items, 1, -1 do
                        if Data.remote_shop_items[i].slot == item.slot and Data.remote_shop_items[i].shop_type == d.type then
                            table.remove(Data.remote_shop_items, i)
                            break
                        end
                    end
                end
            end
            
            table.sort(Data.remote_shop_items, function(a, b)
                if a.shop_type ~= b.shop_type then return a.shop_type < b.shop_type end
                return (a.slot or 0) < (b.slot or 0) 
            end)
            
            -- [КРИТИЧЕСКИЙ ФИКС БАГА С ЧУЖОЙ ЛАВКОЙ]
            -- Мы проверяем, чья это лавка, ТОЛЬКО ЕСЛИ:
            -- 1. Скрипт сам её автоматически редактирует (выставляет товары)
            -- 2. ИЛИ Владелец уже определен (action 1 пришел) И он совпадает с нашим ником
            local my_nick = getSafeLocalNickname():gsub(" ", "_")
            local is_my_shop = false
            
            if ScanCollector.current_shop_owner == my_nick then
                is_my_shop = true
            end
            if App.is_selling_cef or App.is_removing_sale or State.buying.active or App.is_removing_buy then
                is_my_shop = true
            end
            
            -- Если это НАША лавка, дублируем данные из универсального кэша (remote_shop_items) 
            -- в наш личный магазин (live_shop) для отправки в базу
            if is_my_shop then
                -- Активируем статус, чтобы лавка улетела в базу как Активная
                App.live_shop_active = true
                Marketplace.enabled = true
                Marketplace.is_cleared = false

                if not Data.live_shop then Data.live_shop = { sell = {}, buy = {} } end
                if not Data.live_shop.sell then Data.live_shop.sell = {} end
                if not Data.live_shop.buy then Data.live_shop.buy = {} end

                if action == 0 and not is_same_sequence then
                    if d.type == 9 then Data.live_shop.sell = {} end
                    if d.type == 10 then Data.live_shop.buy = {} end
                end

                local target_dict = (d.type == 9) and Data.live_shop.sell or Data.live_shop.buy

                for _, item in ipairs(d.items) do
                    if item.slot ~= nil then
                        local slot = tonumber(item.slot)
                        if item.available == 1 and item.item then
                            local model_id = tonumber(item.item)
                            local item_name = Data.item_names[tostring(model_id)] or ("Item_"..model_id)
                            
                            -- Подтягиваем правильное имя из списка продажи (с заточками и т.д.)
                            if d.type == 9 and Data.sell_list then
                                for _, s_item in ipairs(Data.sell_list) do
                                    if s_item.slot == slot and s_item.model_id == model_id then
                                        item_name = s_item.name
                                        break
                                    end
                                end
                            end
                            
                            local real_price = parseRodinaPrice(item.text)
                            local amount = item.amount or 1
                            target_dict[slot] = { name = item_name, price = real_price, amount = amount, model_id = model_id }
                        elseif item.available == 0 then
                            target_dict[slot] = nil
                        end
                    end
                end

                saveLiveShopState()
                
                -- Антифлуд отправки на сервер
                if not (App.is_selling_cef or App.is_removing_sale or State.buying.active or App.is_removing_buy) then
                    MarketConfig.SYNC_QUEUED_TIME = os.clock() + 1.5 
                end
            end
            
            -- Буферы снятия товаров
            if App.is_removing_sale and d.type == 9 then
                if not Data.removal_slots_buffer then Data.removal_slots_buffer = {} end
                for _, item in ipairs(d.items) do
                    if item.slot then
                         if item.available == 1 then Data.removal_slots_buffer[tonumber(item.slot)] = tonumber(item.item) or true
                         elseif item.available == 0 then Data.removal_slots_buffer[tonumber(item.slot)] = nil end
                    end
                end
            end

            if App.is_removing_buy and d.type == 10 then
                if not Data.removal_slots_buffer then Data.removal_slots_buffer = {} end
                for _, item in ipairs(d.items) do
                    if item.slot then
                         if item.available == 1 then 
                            Data.removal_slots_buffer[tonumber(item.slot)] = true
                         elseif item.available == 0 then 
                            Data.removal_slots_buffer[tonumber(item.slot)] = nil 
                         end
                    end
                end
            end
            
            RemoteShopState.needs_refresh = true
        end

        -- ============================================================
        -- [STEP 2] ПОЛУЧЕНИЕ ИМЕНИ ВЛАДЕЛЬЦА (Action 1)
        -- ============================================================
        if action == 1 and d and d.name then
            local raw_name = safe_decode(d.name)
            raw_name = cleanTextColors(raw_name)
            
            raw_name = raw_name:match("^%s*(.-)%s*$")
            
            local isValidNick = false
            if raw_name:find("_") then isValidNick = true end
            if #raw_name < 3 or #raw_name > 24 then isValidNick = false end
            if raw_name:find(" ") then isValidNick = false end
            if raw_name:match("^%d+$") then isValidNick = false end
            
            if isValidNick then
                local my_nick = getSafeLocalNickname():gsub(" ", "_") 
                
                if ScanCollector.current_shop_owner ~= raw_name then
                    ScanCollector.current_shop_owner = raw_name
                    ScanCollector.current_shop_id = -1
                    local cur_type = ScanCollector.last_updated_type
                    for i = #Data.remote_shop_items, 1, -1 do
                        if Data.remote_shop_items[i].shop_type ~= cur_type then
                            table.remove(Data.remote_shop_items, i)
                        end
                    end
                end
                
                -- [КРИТИЧЕСКИЙ ФИКС 2] 
                -- Теперь, когда мы точно знаем имя владельца, проверяем: А не наша ли это лавка?
                -- Если это наша лавка, и мы просто её смотрим, нужно обновить Data.live_shop
                if raw_name == my_nick then
                    if not Data.live_shop then Data.live_shop = { sell = {}, buy = {} } end
                    local cur_type = ScanCollector.last_updated_type
                    if cur_type == 9 then
                        Data.live_shop.sell = {}
                        for _, item in ipairs(Data.remote_shop_items) do
                            if item.shop_type == 9 then
                                Data.live_shop.sell[item.slot] = { name = item.name, price = item.raw_price, amount = item.amount, model_id = item.model_id }
                            end
                        end
                    elseif cur_type == 10 then
                        Data.live_shop.buy = {}
                        for _, item in ipairs(Data.remote_shop_items) do
                            if item.shop_type == 10 then
                                Data.live_shop.buy[item.slot] = { name = item.name, price = item.raw_price, amount = item.amount, model_id = item.model_id }
                            end
                        end
                    end
                    App.live_shop_active = true
                    Marketplace.enabled = true
                    Marketplace.is_cleared = false
                    saveLiveShopState()
                    MarketConfig.SYNC_QUEUED_TIME = os.clock() + 1.5
                else
                    -- Это чужая лавка -> Запускаем таймер отправки в пассивный маркет
                    App.tasks.remove_by_name("submit_passive_shop")
                    App.tasks.add("submit_passive_shop", function()
                        api_SubmitPassiveShop()
                    end, 2500)
                end
            end
        end

        -- ============================================================
        -- [NEW] БАГАЖНИК И ШКАФ В ДОМЕ (Типы 13 и 17)
        -- ============================================================
        if (action == 0 or action == 2) and d and (d.type == 13 or d.type == 17) and d.items then
            local storage_name = App.current_open_trunk
            if d.type == 17 and not storage_name then
                storage_name = "Шкаф (Квартира/Дом)"
            end

            if storage_name then
                if not Data.warehouses[storage_name] then
                    Data.warehouses[storage_name] = {}
                end

                local current_trunk = Data.warehouses[storage_name]
                local now = os.clock()
                
                local is_burst = (App.last_trunk_sync and (now - App.last_trunk_sync < 1.0))
                App.last_trunk_sync = now

                if action == 0 and not is_burst then
                    current_trunk = {}
                    Data.warehouses[storage_name] = current_trunk
                end

                for _, item in ipairs(d.items) do
                    if item.slot ~= nil then
                        local slot = tonumber(item.slot)
                        local has_item = item.item and item.item ~= json.null
                        
                        if has_item and tonumber(item.available) == 1 then
                            local model_id = tonumber(item.item)
                            local item_name = Data.item_names[tostring(model_id)] or ("Item_"..model_id)
                            local amount = tonumber(item.amount) or 1
                            
                            if item.text and item.text ~= "" and not item.text:match("^%d+$") then
                                item_name = item_name .. " [" .. item.text .. "]"
                            end
                            
                            current_trunk[slot] = {
                                name = item_name,
                                model_id = model_id,
                                amount = amount
                            }
                        elseif not has_item or tonumber(item.available) == 0 then
                            current_trunk[slot] = nil
                        end
                    end
                end
                SaveScheduler.lists_dirty = true 
            end
        end

        -- ============================================================
        -- === СВОЙ ИНВЕНТАРЬ (Тип 1) ===
        -- ============================================================
        if (action == 2 or action == 0) and d and d.type == 1 and d.items then
            for _, item in ipairs(d.items) do
                local slot = tonumber(item.slot)
                if slot and item.item then
                     local model_id = tonumber(item.item)
                     local final_amount = tonumber(item.amount)
                     if not final_amount then
                        if Data.cef_slots_data[slot] and Data.cef_slots_data[slot].model_id == model_id then
                            final_amount = Data.cef_slots_data[slot].amount
                        else final_amount = 1 end
                     end
                     Data.cef_slots_data[slot] = {
                        model_id = model_id,
                        slot = slot,
                        amount = final_amount,
                        available = item.available,
                        text = item.text,
                        time = item.time
                    }
                    
                    local fixed_name = (model_id == 3660) and "Деньги" or (Data.item_names[tostring(model_id)] or "Unknown_"..model_id)
                    
                    if App.cef_inventory_active or State.inventory_scan.active then
                        Data.cef_inventory_items[slot] = {
                            model_id = model_id,
                            name = fixed_name,
                            slot = slot,
                            amount = final_amount,
                            text = item.text,
                            time = item.time,
                            is_blocked = (item.blackout == 1) or (item.available == 0)
                        }
                    end
                    
                    -- [CORE FIX] Синхронизируем главный кэш (Scanned Items), чтобы он не "протухал"
                    for i = #Data.scanned_items, 1, -1 do
                        if tonumber(Data.scanned_items[i].slot) == slot then
                            table.remove(Data.scanned_items, i)
                            break
                        end
                    end
                    
                    -- [DATA INTEGRITY FIX] Строгая блокировка добавления неизвестных предметов.
                    -- Если предмета нет в Data.item_names, мы полностью игнорируем его обработку, 
                    -- исключая появление "Unknown" карточек в списке продажи.
                    local db_name = Data.item_names[tostring(model_id)]
                    local is_money = (model_id == 3660)
                    
                    if (is_money or db_name) and not isItemUnsellable(model_id) then
                        local base_name = is_money and "Деньги" or db_name
                        local fixed_name = base_name
                        
                        if item.text and item.text ~= "" and item.text ~= tostring(final_amount) and not is_money then
                            fixed_name = fixed_name .. " [" .. item.text .. "]"
                        end
                        
                        table.insert(Data.scanned_items, {
                            name = fixed_name,
                            original_name = base_name,
                            model_id = model_id,
                            amount = final_amount,
                            slot = slot,
                            text = item.text,
                            time = item.time,
                            is_blocked = (item.blackout == 1) or (item.available == 0)
                        })
                    end

                elseif slot and item.available == 0 and not item.blackout then 
                    if Data.cef_slots_data[slot] then Data.cef_slots_data[slot] = nil end
                    if Data.cef_inventory_items[slot] then Data.cef_inventory_items[slot] = nil end
                    
                    -- [CORE FIX] Удаляем из кэша при исчезновении вещи
                    for i = #Data.scanned_items, 1, -1 do
                        if tonumber(Data.scanned_items[i].slot) == slot then
                            table.remove(Data.scanned_items, i)
                            break
                        end
                    end
                end
            end
            
            -- [ОПТИМИЗАЦИЯ ИНВЕНТАРЯ И CEF]
            -- Сервер присылает инвентарь кусками и каждую секунду шлет обновления для арендованных предметов.
            -- Чтобы сетевой поток не "душился" и инвентарь открывался моментально, 
            -- откладываем тяжелую сортировку и пересчет на 150мс в основной поток игры.
            App.tasks.add("debounce_inv_update", function()
                table.sort(Data.scanned_items, function(a, b) 
                    return (tonumber(a.slot) or 0) < (tonumber(b.slot) or 0) 
                end)
                
                recalculateInventoryTotals()
                refreshSellListMissingStatus()
            end, 150)
        end
    end
end

function getInventoryAmountForItem(model_id, specific_slot)
    if specific_slot and Data.cef_slots_data and Data.cef_slots_data[specific_slot] then
        local item = Data.cef_slots_data[specific_slot]
        if tonumber(item.model_id) == tonumber(model_id) then
            return item.amount or 0
        end
    end

    local model_str = tostring(model_id)
    if Data.inventory_item_amounts and Data.inventory_item_amounts[model_str] then
        return Data.inventory_item_amounts[model_str]
    end

    return 0
end

function renderCustomHeader(window_size)
    local w = imgui.GetWindowWidth()
    local h = S(90)
    local draw_list = imgui.GetWindowDrawList()
    local p = imgui.GetWindowPos()
    
    -- ОПТИМИЗАЦИЯ FPS: Убраны imgui.Dummy и SetItemAllowOverlap. 
    -- Они создавали огромную невидимую зону поверх всего хедера, заставляя ImGui 
    -- просчитывать коллизии (hitbox) для каждого пикселя при движении мыши.
    
    -- Фон хедера
    local col_bg_top = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary)
    local col_bg_bot = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main)
    local header_rounding = S(12)
    
    draw_list:AddRectFilled(
        p, imgui.ImVec2(p.x + w, p.y + header_rounding), 
        col_bg_top, header_rounding, 3
    )
    
    draw_list:AddRectFilledMultiColor(
        imgui.ImVec2(p.x, p.y + header_rounding), imgui.ImVec2(p.x + w, p.y + h),
        col_bg_top, col_bg_top,
        col_bg_bot, col_bg_bot
    )

    -- Нижняя линия хедера (разделитель)
    draw_list:AddLine(
        imgui.ImVec2(p.x, p.y + h - 1), 
        imgui.ImVec2(p.x + w, p.y + h - 1), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 
        1.0
    )

    -- === ДАЛЕЕ ИДЕТ ОТРИСОВКА ИНТЕРФЕЙСА (ТЕКСТ, КНОПКИ) ===
    local text_y = p.y + (h - imgui.GetFontSize()) * 0.5

    -- Иконка слева
    if font_fa then imgui.PushFont(font_fa) end
    draw_list:AddText(
        imgui.ImVec2(p.x + S(20), text_y),
        -- Если нет VIP, делаем иконку чуть прозрачнее, но используем тот же мягкий цвет темы
        imgui.ColorConvertFloat4ToU32(Data.is_vip and CURRENT_THEME.accent_primary or imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.7)),
        fa('code')
    )
    if font_fa then imgui.PopFont() end

    -- ЗАГОЛОВОК
    local title_text = "RMARKET"
    local title_x = p.x + S(48) -- Выравнивание относительно иконки

    -- [AAA Style] Мягкая тень под текстом логотипа для объема
    draw_list:AddText(imgui.ImVec2(title_x + S(1), text_y + S(1.5)), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.6)), title_text)
    
    local title_color_u32 = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary)
    draw_list:AddText(imgui.ImVec2(title_x, text_y), title_color_u32, title_text)

    -- Сдвиг для бейджей / иконок
    local title_width = GetStaticTextSize(title_text).x
    local extra_offset = S(12) -- [FIX] Базовый отступ от текста, чтобы ничего не слипалось

    -- [VIP VISUAL] Премиальный бейдж Короны
    if Data.is_vip and font_fa then
        imgui.PushFont(font_fa)
        local crown_icon = fa('crown')
        local crown_sz = GetStaticTextSize(crown_icon)
        
        local vip_badge_x = title_x + title_width + extra_offset
        local vip_badge_y = text_y - S(2)
        local vip_badge_w = crown_sz.x + S(14)
        local vip_badge_h = crown_sz.y + S(4)

        -- Красивая золотая подложка (Pill) с прозрачностью
        local gold_col = imgui.ImVec4(1.0, 0.75, 0.1, 1.0)
        draw_list:AddRectFilled(
            imgui.ImVec2(vip_badge_x, vip_badge_y), 
            imgui.ImVec2(vip_badge_x + vip_badge_w, vip_badge_y + vip_badge_h), 
            imgui.ColorConvertFloat4ToU32(imgui.ImVec4(gold_col.x, gold_col.y, gold_col.z, 0.15)), 
            S(6)
        )
        
        -- Легкая золотая обводка для эффекта свечения
        draw_list:AddRect(
            imgui.ImVec2(vip_badge_x, vip_badge_y), 
            imgui.ImVec2(vip_badge_x + vip_badge_w, vip_badge_y + vip_badge_h), 
            imgui.ColorConvertFloat4ToU32(imgui.ImVec4(gold_col.x, gold_col.y, gold_col.z, 0.4)), 
            S(6), 15, S(1)
        )

        -- Коронка идеально по центру бейджа
        draw_list:AddText(
            imgui.ImVec2(vip_badge_x + S(7), text_y),
            imgui.ColorConvertFloat4ToU32(gold_col),
            crown_icon
        )

        extra_offset = extra_offset + vip_badge_w + S(10) -- Сдвигаем плашку версии правее
        imgui.PopFont()
    end
    
    -- ВЕРСИЯ
    local ver_str = "v" .. SCRIPT_CURRENT_VERSION
    if UpdateState.is_outdated then
        ver_str = u8"Обновить! (v" .. UpdateState.remote_version .. ")"
    end

    -- Убрали хардкод S(15), так как отступы теперь динамически считаются в extra_offset
    local badge_x = title_x + title_width + extra_offset
    local badge_y = text_y - S(2)
    
    imgui.PushFont(font_default)
    imgui.SetWindowFontScale(0.75)
    local ver_sz = GetStaticTextSize(ver_str)
    local badge_w = ver_sz.x + S(12)
    local badge_h = ver_sz.y + S(4)
    
    local badge_col_u32 = UpdateState.is_outdated and 0xFF0033DD or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary)
    local badge_text_col = 0xFFFFFFFF
    
    if Data.is_vip and not UpdateState.is_outdated then
        badge_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.15))
        badge_text_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
    end
    
    draw_list:AddRectFilled(imgui.ImVec2(badge_x, badge_y), imgui.ImVec2(badge_x + badge_w, badge_y + badge_h), badge_col_u32, S(6))
    draw_list:AddText(imgui.ImVec2(badge_x + S(6), badge_y + S(2)), badge_text_col, ver_str)
    
    imgui.SetWindowFontScale(1.0)
    imgui.PopFont()
    
    -- Социальные иконки
    local social_x = badge_x + badge_w + S(15)
    local social_icon_size = S(20)
    
    local drawSocialIcon = function(id, icon, x, y, color, url, tooltip)
        imgui.SetCursorScreenPos(imgui.ImVec2(x, y - S(2)))
        if imgui.InvisibleButton(id, imgui.ImVec2(social_icon_size, social_icon_size)) then
            os.execute("explorer " .. url)
        end
        local is_hovered = imgui.IsItemHovered()
        local final_color = is_hovered and CURRENT_THEME.text_primary or color
        final_color = imgui.ImVec4(final_color.x, final_color.y, final_color.z, final_color.w + (is_hovered and 0.2 or 0))
        
        if font_fa then imgui.PushFont(font_fa) end
        draw_list:AddText(imgui.ImVec2(x, y), imgui.ColorConvertFloat4ToU32(final_color), fa(icon))
        if font_fa then imgui.PopFont() end
        if is_hovered then imgui.SetTooltip(u8(tooltip)) end
    end

    drawSocialIcon("##tg_link", "paper_plane", social_x, text_y, imgui.ImVec4(0.24, 0.67, 0.89, 0.8), "https://t.me/rdnMarket", "Telegram канал")
    drawSocialIcon("##yt_link", "play", social_x + S(25), text_y, imgui.ImVec4(1.0, 0.0, 0.0, 0.8), "https://youtube.com/@feyzer", "YouTube канал")

    -- ПОИСК
    local search_hint = ""
    local search_buffer = nil
    local is_search_active = false

    if App.active_tab == 1 then search_hint = "Поиск (Продажа)" search_buffer = Buffers.sell_search is_search_active = true
    elseif App.active_tab == 2 then search_hint = "Поиск (Скупка)" search_buffer = Buffers.buy_search is_search_active = true
    elseif App.active_tab == 3 then search_hint = "Поиск по логам" search_buffer = Buffers.logs_search is_search_active = true
    elseif App.active_tab == 4 then search_hint = "Поиск товара" search_buffer = MarketData.search_buffer is_search_active = true
    elseif App.active_tab == 7 then search_hint = "Поиск в трендах" search_buffer = Buffers.trends_search is_search_active = true
    elseif App.active_tab == 9 then search_hint = "Поиск по складу" search_buffer = Buffers.warehouse_search is_search_active = true end

    if is_search_active and search_buffer then
        local search_w = S(300) 
        local search_h_real = S(40)
        
        -- Вычисляем координату X сразу после иконок социальных сетей
        -- (social_x + S(25) это отступ второй иконки YT, прибавляем её размер и общий отступ)
        local left_elements_end_x = social_x + S(25) + social_icon_size
        
        -- Привязываем поиск к левой части панели, а не к жесткому центру! 
        -- Это освобождает огромное пространство по центру для надписи и предотвращает наложение
        local search_x = left_elements_end_x + S(40) 
        local search_y = p.y + (h * 0.5) - (search_h_real * 0.5)
        
        imgui.SetCursorScreenPos(imgui.ImVec2(search_x, search_y))
        renderAnimatedSearchBar(search_buffer, search_hint, search_w)
    end
    
    -- Кнопки справа (Закрыть, VIP, Обновить и т.д.)
    local btn_size = S(32)
    local btn_spacing = S(8)
    local close_btn_x = p.x + w - btn_size - S(15)
    local close_btn_y = p.y + (h - btn_size) * 0.5
    local current_x = close_btn_x - btn_spacing
    
    local function drawHeaderBtn(icon, callback, color_active, tooltip, blink_alert)
        current_x = current_x - btn_size
        imgui.SetCursorScreenPos(imgui.ImVec2(current_x, close_btn_y))
        if imgui.InvisibleButton("##hbtn_"..icon, imgui.ImVec2(btn_size, btn_size)) then callback() end
        local is_hovered = imgui.IsItemHovered()
        
        local default_icon_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
        local icon_col = is_hovered and color_active or default_icon_col
        
        if blink_alert then
            local pulse = (math.sin(os.clock() * 6) + 1.0) * 0.5
            local r = 0.4 + (1.0 - 0.4) * pulse
            icon_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(r, 0.2, 0.2, 1.0))
        end

        if font_fa then imgui.PushFont(font_fa) end
        local txt_sz = GetStaticTextSize(icon)
        draw_list:AddText(imgui.ImVec2(current_x + (btn_size - txt_sz.x)/2, close_btn_y + (btn_size - txt_sz.y)/2), icon_col, icon)
        if font_fa then imgui.PopFont() end
        
        if is_hovered and tooltip then imgui.SetTooltip(u8(tooltip)) end
        current_x = current_x - btn_spacing
    end

    local is_real_vip = isVerifiedVip()
    local vip_color = is_real_vip and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary) or 0xFF808080
    local vip_tooltip = is_real_vip and "VIP Активирован! Спасибо за поддержку" or "Активировать VIP статус"
    
    drawHeaderBtn(fa('crown'), function() 
        os.execute('explorer "https://t.me/rdnMarket_bot?start=script"')
        addToastNotification("Перейдите в Telegram для управления VIP", "info", 4.0)
    end, vip_color, vip_tooltip, not is_real_vip) 
    
    if App.active_tab == 7 and is_real_vip then
        local icon = MarketData.is_loading and fa('spinner') or fa('arrows_rotate')
        drawHeaderBtn(icon, function() api_GetVipAnalytics('top_resale') MarketData.last_fetch = os.time() end, 0xFFFFFFFF, "Обновить список")
    end
	
	if App.active_tab == 3 then
        -- 1. КНОПКИ ФИЛЬТРОВ (Sale / Buy)
        -- Рисуем их справа налево, отступая от current_x
        
        local filter_btn_sz = S(32)
        local gap = S(8)
        
        -- Кнопка "Покупки" (Buy)
        current_x = current_x - filter_btn_sz
        imgui.SetCursorScreenPos(imgui.ImVec2(current_x, close_btn_y))
        
        if imgui.InvisibleButton("##header_filter_buy", imgui.ImVec2(filter_btn_sz, filter_btn_sz)) then
            Buffers.log_filters.show_purchases[0] = not Buffers.log_filters.show_purchases[0]
            LogsState.cached_income, LogsState.cached_expense = updateLogView() -- Обновляем список сразу
        end
        
        local is_buy_active = Buffers.log_filters.show_purchases[0]
        local buy_icon_col = is_buy_active and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
        local buy_bg = (is_buy_active or imgui.IsItemHovered()) and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_danger.x, CURRENT_THEME.accent_danger.y, CURRENT_THEME.accent_danger.z, 0.15)) or 0
        
        if buy_bg ~= 0 then draw_list:AddRectFilled(imgui.ImVec2(current_x, close_btn_y), imgui.ImVec2(current_x + filter_btn_sz, close_btn_y + filter_btn_sz), buy_bg, S(6)) end
        
        if font_fa then
            imgui.PushFont(font_fa)
            local b_icon = fa('arrow_down')
            local b_sz = GetStaticTextSize(b_icon)
            draw_list:AddText(imgui.ImVec2(current_x + (filter_btn_sz - b_sz.x)/2, close_btn_y + (filter_btn_sz - b_sz.y)/2), imgui.ColorConvertFloat4ToU32(buy_icon_col), b_icon)
            imgui.PopFont()
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(u8"Показать покупки") end
        
        current_x = current_x - gap

        -- Кнопка "Продажи" (Sell)
        current_x = current_x - filter_btn_sz
        imgui.SetCursorScreenPos(imgui.ImVec2(current_x, close_btn_y))
        
        if imgui.InvisibleButton("##header_filter_sell", imgui.ImVec2(filter_btn_sz, filter_btn_sz)) then
            Buffers.log_filters.show_sales[0] = not Buffers.log_filters.show_sales[0]
            LogsState.cached_income, LogsState.cached_expense = updateLogView()
        end
        
        local is_sell_active = Buffers.log_filters.show_sales[0]
        local sell_icon_col = is_sell_active and CURRENT_THEME.accent_success or CURRENT_THEME.text_hint
        local sell_bg = (is_sell_active or imgui.IsItemHovered()) and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_success.x, CURRENT_THEME.accent_success.y, CURRENT_THEME.accent_success.z, 0.15)) or 0
        
        if sell_bg ~= 0 then draw_list:AddRectFilled(imgui.ImVec2(current_x, close_btn_y), imgui.ImVec2(current_x + filter_btn_sz, close_btn_y + filter_btn_sz), sell_bg, S(6)) end
        
        if font_fa then
            imgui.PushFont(font_fa)
            local s_icon = fa('arrow_up')
            local s_sz = GetStaticTextSize(s_icon)
            draw_list:AddText(imgui.ImVec2(current_x + (filter_btn_sz - s_sz.x)/2, close_btn_y + (filter_btn_sz - s_sz.y)/2), imgui.ColorConvertFloat4ToU32(sell_icon_col), s_icon)
            imgui.PopFont()
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(u8"Показать продажи") end
        
        current_x = current_x - gap

        -- 2. ВЫБОР ДАТЫ (POPUP, КАК У СЕРВЕРОВ)
        local selector_w = S(155) 
        local selector_h = btn_size
        current_x = current_x - selector_w
        
        local sel_x = current_x
        local sel_y = close_btn_y
        
        -- Определяем текст даты
        if Buffers.logs_current_date_idx == 0 and #Buffers.logs_dates_cache > 0 then Buffers.logs_current_date_idx = 1 end
        local current_date_str = Buffers.logs_dates_cache[Buffers.logs_current_date_idx] or u8"Нет логов"
        
        imgui.SetCursorScreenPos(imgui.ImVec2(sel_x, sel_y))
        
        if imgui.InvisibleButton("##header_date_select", imgui.ImVec2(selector_w, selector_h)) then
            imgui.OpenPopup("HeaderDateSelectPopup")
        end
        
        local is_hov = imgui.IsItemHovered()
        local is_open = imgui.IsPopupOpen("HeaderDateSelectPopup")
        
        local d_bg = CURRENT_THEME.bg_tertiary
        local d_border = CURRENT_THEME.border_light
        if is_hov or is_open then 
            d_bg = imgui.ImVec4(d_bg.x + 0.1, d_bg.y + 0.1, d_bg.z + 0.1, 1.0)
            if is_open then d_border = CURRENT_THEME.accent_primary end
        end
        
        draw_list:AddRectFilled(imgui.ImVec2(sel_x, sel_y), imgui.ImVec2(sel_x + selector_w, sel_y + selector_h), imgui.ColorConvertFloat4ToU32(d_bg), S(8))
        draw_list:AddRect(imgui.ImVec2(sel_x, sel_y), imgui.ImVec2(sel_x + selector_w, sel_y + selector_h), imgui.ColorConvertFloat4ToU32(d_border), S(8), 15, is_open and S(1.5) or S(1.0))
        
        -- Иконка календаря и стрелка
        local left_icon_w = 0
        local right_icon_w = 0
        
        if font_fa then
            imgui.PushFont(font_fa)
            local c_icon = fa('calendar')
            local c_sz = GetStaticTextSize(c_icon)
            left_icon_w = c_sz.x + S(12) -- Отступ слева
            
            -- Рисуем календарь слева
            draw_list:AddText(imgui.ImVec2(sel_x + S(12), sel_y + (selector_h - c_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), c_icon)
            
            local arrow = is_open and fa('chevron_up') or fa('chevron_down')
            local a_sz = GetStaticTextSize(arrow)
            right_icon_w = a_sz.x + S(12) -- Отступ справа
            
            -- Рисуем стрелку справа
            draw_list:AddText(imgui.ImVec2(sel_x + selector_w - a_sz.x - S(10), sel_y + (selector_h - a_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), arrow)
            imgui.PopFont()
        end
        
        -- Текст даты по центру доступного пространства
        local date_sz = GetStaticTextSize(current_date_str)
        -- Вычисляем центр: начало кнопки + (ширина кнопки / 2) - (ширина текста / 2)
        -- [FIX] Слегка смещаем вправо, так как левая иконка шире правой
        local text_center_x = sel_x + (selector_w - date_sz.x) / 2 + S(2)
        
        draw_list:AddText(imgui.ImVec2(text_center_x, sel_y + (selector_h - date_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), current_date_str)
        
        -- POPUP ДАТ
        imgui.SetNextWindowPos(imgui.ImVec2(sel_x, sel_y + selector_h + S(6)))
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(6), S(6)))
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(12))
        imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_secondary)
        imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
        
        if imgui.BeginPopup("HeaderDateSelectPopup") then
            local popup_w = S(160)
            local item_h = S(32)
            
            if #Buffers.logs_dates_cache == 0 then
                imgui.TextDisabled(u8"Нет файлов логов")
            else
                local visible_count = math.min(#Buffers.logs_dates_cache, 8)
                local content_h = visible_count * S(32)
                
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
                if imgui.BeginChild("DateListScroll", imgui.ImVec2(popup_w, content_h), false) then
                    for i, date_val in ipairs(Buffers.logs_dates_cache) do
                        local is_selected = (Buffers.logs_current_date_idx == i)
                        local p_item = imgui.GetCursorScreenPos()
                        
                        if imgui.InvisibleButton("date_"..i, imgui.ImVec2(popup_w, item_h)) then
                            Buffers.logs_current_date_idx = i
                            LogsState.cached_income, LogsState.cached_expense = updateLogView()
                            imgui.CloseCurrentPopup()
                        end
                        
                        local hov = imgui.IsItemHovered()
                        local dl_pop = imgui.GetWindowDrawList()
                        
                        if is_selected then
                            dl_pop:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_w, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(6))
                            dl_pop:AddRectFilled(p_item, imgui.ImVec2(p_item.x + S(3), p_item.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(6), 5)
                        elseif hov then
                            dl_pop:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_w, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.05)), S(6))
                        end
                        
                        local col_txt = is_selected and CURRENT_THEME.accent_primary or CURRENT_THEME.text_primary
                        local txt_sz = GetStaticTextSize(date_val)
                        dl_pop:AddText(imgui.ImVec2(p_item.x + S(15), p_item.y + (item_h - txt_sz.y)/2), imgui.ColorConvertFloat4ToU32(col_txt), date_val)
                    end
                end
                imgui.EndChild()
                imgui.PopStyleColor()
            end
            imgui.EndPopup()
        end
        imgui.PopStyleVar(2)
        imgui.PopStyleColor(2)
    end
    
    if App.active_tab == 4 then
        -- === НОВЫЙ ВЫПАДАЮЩИЙ СПИСОК СЕРВЕРОВ ===
        -- [FIX] Увеличили ширину с S(140) до S(170) чтобы "Центральный" и "Приморский" влезали
        local selector_w = S(170)
        local selector_h = btn_size
        
        -- Сдвигаем текущую позицию X влево для кнопки обновления
        local refresh_btn_pos_x = current_x 
        
        -- Позиция селектора (слева от будущей кнопки обновления)
        current_x = current_x - btn_size - btn_spacing - selector_w
        
        local sel_x = current_x
        local sel_y = close_btn_y
        
        imgui.SetCursorScreenPos(imgui.ImVec2(sel_x, sel_y))
        
        -- Получаем имя текущего выбранного сервера
        local current_srv_name = u8"Все серверы"
        if server_filter_idx > 0 and server_name_list[server_filter_idx + 1] then
            current_srv_name = u8(server_name_list[server_filter_idx + 1])
        end
        
        -- Рисуем кнопку-селектор
        if imgui.InvisibleButton("##header_server_select", imgui.ImVec2(selector_w, selector_h)) then
            imgui.OpenPopup("HeaderServerSelectPopup")
        end
        
        local is_sel_hovered = imgui.IsItemHovered()
        local is_popup_open = imgui.IsPopupOpen("HeaderServerSelectPopup")
        
        local sel_bg = CURRENT_THEME.bg_tertiary
        local sel_border = CURRENT_THEME.border_light
        
        if is_sel_hovered or is_popup_open then 
            sel_bg = imgui.ImVec4(sel_bg.x + 0.1, sel_bg.y + 0.1, sel_bg.z + 0.1, 1.0)
            if is_popup_open then
                sel_border = CURRENT_THEME.accent_primary
            end
        end
        
        -- Фон селектора
        draw_list:AddRectFilled(imgui.ImVec2(sel_x, sel_y), imgui.ImVec2(sel_x + selector_w, sel_y + selector_h), imgui.ColorConvertFloat4ToU32(sel_bg), S(8))
        draw_list:AddRect(imgui.ImVec2(sel_x, sel_y), imgui.ImVec2(sel_x + selector_w, sel_y + selector_h), imgui.ColorConvertFloat4ToU32(sel_border), S(8), 15, is_popup_open and S(1.5) or S(1.0))
        
        -- Текст и иконка внутри селектора
        local left_offset = S(12)
        local right_offset = S(30) -- Место под стрелку справа
        
        if font_fa then
            imgui.PushFont(font_fa)
            local globe_icon = fa('globe')
            -- Ищем иконку выбранного сервера для отображения в кнопке
            if server_filter_idx > 0 then
                local srv_name_raw = server_name_list[server_filter_idx + 1]
                for _, data in ipairs(RODINA_SERVERS_DATA) do
                    if data.name == srv_name_raw then globe_icon = data.icon break end
                end
            end
            
            local g_sz = GetStaticTextSize(globe_icon)
            draw_list:AddText(imgui.ImVec2(sel_x + left_offset, sel_y + (selector_h - g_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), globe_icon)
            
            -- Смещаем начало текста правее иконки
            left_offset = left_offset + g_sz.x + S(8)
            
            local chev_icon = is_popup_open and fa('chevron_up') or fa('chevron_down')
            local c_sz = GetStaticTextSize(chev_icon)
            -- Рисуем стрелку справа
            draw_list:AddText(imgui.ImVec2(sel_x + selector_w - c_sz.x - S(10), sel_y + (selector_h - c_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), chev_icon)
            imgui.PopFont()
        end
        
        -- [FIX] Клиппинг текста, чтобы он не залезал на стрелку справа
        -- Область текста: от (иконки слева) до (стрелки справа - отступ)
        imgui.PushClipRect(imgui.ImVec2(sel_x + left_offset, sel_y), imgui.ImVec2(sel_x + selector_w - right_offset, sel_y + selector_h), true)
        
        local txt_sz = GetStaticTextSize(current_srv_name)
        -- Рисуем текст
        draw_list:AddText(imgui.ImVec2(sel_x + left_offset, sel_y + (selector_h - txt_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), current_srv_name)
        imgui.PopClipRect()
        
        -- === POPUP МЕНЮ СЕРВЕРОВ (КРАСИВОЕ) ===
        imgui.SetNextWindowPos(imgui.ImVec2(sel_x, sel_y + selector_h + S(6)))
        
        -- Стилизация самого окна Popup
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(6), S(6)))
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(12))
        imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_secondary)
        imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
        
        if imgui.BeginPopup("HeaderServerSelectPopup") then
            local popup_width = S(200)
            
            -- Вспомогательная функция для отрисовки элемента списка
            local function DrawServerItem(label, idx, icon)
                local is_selected = (server_filter_idx == idx)
                local p_item = imgui.GetCursorScreenPos()
                local item_h = S(38)
                
                -- Невидимая кнопка во всю ширину
                local clicked = imgui.InvisibleButton("srv_item_"..idx, imgui.ImVec2(popup_width, item_h))
                local is_hovered = imgui.IsItemHovered()
                local dl = imgui.GetWindowDrawList()
                
                -- Цвета
                local bg_col = imgui.ImVec4(0,0,0,0)
                local text_col = CURRENT_THEME.text_primary
                local icon_col = CURRENT_THEME.text_secondary
                
                if is_selected then
                    bg_col = CURRENT_THEME.bg_tertiary -- Фон активного
                    text_col = CURRENT_THEME.accent_primary
                    icon_col = CURRENT_THEME.accent_primary
                elseif is_hovered then
                    bg_col = imgui.ImVec4(1, 1, 1, 0.05) -- Легкий ховер
                    text_col = CURRENT_THEME.text_primary
                    icon_col = CURRENT_THEME.text_primary
                end
                
                -- Отрисовка фона
                if is_selected or is_hovered then
                    dl:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_width, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
                end
                
                -- Активная полоска слева
                if is_selected then
                     dl:AddRectFilled(p_item, imgui.ImVec2(p_item.x + S(3), p_item.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)
                end
                
                -- Иконка
                local content_x = p_item.x + S(12)
                local cy = p_item.y + item_h / 2
                
                if icon and font_fa then
                    imgui.PushFont(font_fa)
                    local isz = GetStaticTextSize(icon)
                    dl:AddText(imgui.ImVec2(content_x, cy - isz.y/2), imgui.ColorConvertFloat4ToU32(icon_col), icon)
                    imgui.PopFont()
                    content_x = content_x + isz.x + S(10)
                end
                
                -- Текст
                local tsz = GetStaticTextSize(label)
                dl:AddText(imgui.ImVec2(content_x, cy - tsz.y/2), imgui.ColorConvertFloat4ToU32(text_col), label)
                
                -- Галочка справа если выбран
                if is_selected and font_fa then
                    imgui.PushFont(font_fa)
                    local check = fa('check')
                    local csz = GetStaticTextSize(check)
                    dl:AddText(imgui.ImVec2(p_item.x + popup_width - csz.x - S(10), cy - csz.y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), check)
                    imgui.PopFont()
                end
                
                return clicked
            end

            -- 1. Пункт "Все серверы"
            if DrawServerItem(u8"Все серверы", 0, fa('earth_europe')) then
                server_filter_idx = 0
                PassiveChecker.active = false 
                PassiveChecker.queue = {}
                -- [ФИКС МАРКЕТА] Обновляем поиск при смене фильтра сервера
                MarketData.last_executed_search = ""
                imgui.CloseCurrentPopup()
            end
            
            -- Разделитель
            imgui.Dummy(imgui.ImVec2(0, S(2)))
            local sep_p = imgui.GetCursorScreenPos()
            imgui.GetWindowDrawList():AddLine(imgui.ImVec2(sep_p.x, sep_p.y), imgui.ImVec2(sep_p.x + popup_width, sep_p.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
            imgui.Dummy(imgui.ImVec2(0, S(2)))
            
            -- 2. Остальные серверы
            for i = 2, #server_name_list do
                local srv_name_raw = server_name_list[i]
                local srv_icon = fa('server')
                
                -- Ищем красивую иконку из конфига
                for _, data in ipairs(RODINA_SERVERS_DATA) do
                    if data.name == srv_name_raw then
                        srv_icon = data.icon
                        break
                    end
                end
                
                -- server_filter_idx: 0 = ALL, 1 = Server[2], 2 = Server[3]...
                -- i - 1 конвертирует индекс массива (начинается с 2) в индекс фильтра
                if DrawServerItem(u8(srv_name_raw), i - 1, srv_icon) then
                    server_filter_idx = i - 1
                    PassiveChecker.active = false
                    PassiveChecker.queue = {}
                    -- [ФИКС МАРКЕТА] Обновляем поиск при смене фильтра сервера
                    MarketData.last_executed_search = ""
                    imgui.CloseCurrentPopup()
                end
            end
            
            imgui.EndPopup()
        end
        imgui.PopStyleColor(2)
        imgui.PopStyleVar(2)

        -- === КНОПКА ОБНОВЛЕНИЯ ===
        current_x = refresh_btn_pos_x 
        
        local icon = (MarketData.is_loading or PassiveChecker.active) and fa('spinner') or fa('arrows_rotate')
        drawHeaderBtn(icon, function() 
            PassiveChecker.active = false
            PassiveChecker.queue = {}
            App.tasks.remove_by_name("passive_check_timeout")
            MarketData.shops_list = {}
            api_FetchMarketList()
        end, 0xFFFFFFFF, "Обновить список (с полной проверкой)")
    end
	
	if App.active_tab == 5 then
        -- Кнопка переключения Радиуса Лавок
        local radius_active = App.render_radius
        -- Зеленый если включено, серый если выключено
        local radius_col = radius_active and 0xFF66CC66 or 0xFF808080 
        local radius_tooltip = radius_active and "Скрыть зоны лавок (Радиус)" or "Показать зоны лавок (Радиус)"
        
        drawHeaderBtn(fa('bullseye'), function() 
            App.render_radius = not App.render_radius
            if App.render_radius then
                addToastNotification("Отображение зон включено", "success")
                lastUpdate = 0 -- Форсируем мгновенное обновление
                updateLavkas()
            else
                addToastNotification("Отображение зон выключено", "info")
            end
        end, radius_col, radius_tooltip)
    end
    
    if App.active_tab == 2 then
        local db_empty = isItemDbEmpty()
        
        -- Кнопка генерации ТОП конфига
        local gen_tooltip = "Сгенерировать 'ТОП Конфиг'\nАвтоматически соберет самые популярные\nтовары по рыночным ценам скупки."
        if db_empty then gen_tooltip = "База пуста! Сначала просканируйте товары." end
        
        drawHeaderBtn(fa('wand_magic_sparkles'), function()
            if db_empty then
                addToastNotification("Сначала просканируйте базу товаров!", "error")
            else
                App.show_gen_config_modal = true -- Открываем окно настройки вместо прямой отправки
            end
        end, 0xFF00FF99, gen_tooltip, db_empty) -- Бирюзовый цвет (Магия)

        local scan_tooltip = db_empty and "ВНИМАНИЕ: База пуста! Нажмите для скачивания" or "Обновить базу предметов"
        drawHeaderBtn(fa('cloud_arrow_down'), function() api_CheckAndDownloadItemsDB(true) end, 0xFF66CCFF, scan_tooltip, db_empty)
        
        drawHeaderBtn(fa('sliders'), function() 
            if db_empty then
                addToastNotification("Сначала просканируйте товары (кнопка левее)!", "error")
            else
                App.show_config_manager = true 
            end
        end, 0xFFFFAA00, "Управление конфигами")
    end
    
    if App.active_tab == 1 then
        local db_empty = isItemDbEmpty()
        drawHeaderBtn(fa('cloud_arrow_down'), function() api_DownloadAveragePrices() end, 0xFF00A5FF, "Скачать средние цены")
        drawHeaderBtn(fa('sliders'), function() 
            if db_empty then
                addToastNotification("Сначала просканируйте базу товаров во вкладке 'Скупка'!", "error")
            else
                App.show_sell_config_manager = true 
            end
        end, 0xFFFFAA00, "Конфиги продажи")
        
        local has_db = not db_empty
        local scan_color = has_db and 0xFF66CC66 or 0xFF808080 
        drawHeaderBtn(fa('magnifying_glass'), function() 
            if has_db then startScanning() else addToastNotification("Ошибка: База предметов пуста!", "error") end
        end, scan_color, "Сканировать инвентарь")
    end
    
    -- Кнопка закрытия
    imgui.SetCursorScreenPos(imgui.ImVec2(close_btn_x, close_btn_y))
    if imgui.InvisibleButton("##close_header", imgui.ImVec2(btn_size, btn_size)) then 
        App.win_state[0] = false 
        -- [FIX] Принудительно закрываем все дочерние окна, чтобы они невидимо не удерживали курсор
        App.show_config_selector = false
        App.show_config_manager = false
        App.show_sell_config_manager = false
        App.show_gen_config_modal = false
        VipData.show_graph_modal = false
        ShareState.modal_active = false
        App.undo_stack = {} -- Сбрасываем удаленные предметы, чтобы сразу скрыть снекбар
    end
    local h_close = imgui.IsItemHovered()
    
    draw_list:AddRectFilled(imgui.ImVec2(close_btn_x, close_btn_y), imgui.ImVec2(close_btn_x+btn_size, close_btn_y+btn_size), h_close and 0x40FF0000 or 0, S(6))
    if font_fa then imgui.PushFont(font_fa) end
    local x_sz = GetStaticTextSize(fa('xmark'))
    draw_list:AddText(imgui.ImVec2(close_btn_x + (btn_size - x_sz.x)/2, close_btn_y + (btn_size - x_sz.y)/2), h_close and 0xFFFFFFFF or 0xB0FFFFFF, fa('xmark'))
    if font_fa then imgui.PopFont() end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + h))
end

function renderRemoteShopHeader(w, h)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    
    -- Статичный красивый градиент вместо тяжелых частиц
    draw_list:AddRectFilledMultiColor(
        p, 
        imgui.ImVec2(p.x + w, p.y + h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.15, 0.08, 1.0)),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.08, 0.20, 0.12, 1.0)),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.15, 0.08, 1.0)),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.08, 0.20, 0.12, 1.0))
    )

    -- Декоративная линия снизу
    draw_list:AddLine(
        imgui.ImVec2(p.x, p.y + h), 
        imgui.ImVec2(p.x + w, p.y + h), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), 
        1.5
    )
    
    local text_y = p.y + (h - imgui.GetFontSize()) * 0.5
    if font_fa then imgui.PushFont(font_fa) end
    draw_list:AddText(imgui.ImVec2(p.x + S(15), text_y), 
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.4, 1.0, 0.6, 1.0)), 
        fa('shop'))
    if font_fa then imgui.PopFont() end
    
    draw_list:AddText(imgui.ImVec2(p.x + S(40), text_y), 
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 1.0)), 
        u8"ПРОСМОТР ТОВАРОВ")
    
    -- Кнопка копирования конфига
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + w - S(50), text_y - S(15)))
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0, 0, 0, 0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.4, 1.0, 0.6, 0.2))
    imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.4, 1.0, 0.6, 0.4))
    
    if font_fa then imgui.PushFont(font_fa) end
    if imgui.Button(fa('copy') .. "##copy_remote", imgui.ImVec2(S(45), S(45))) then
        copyRemoteShopConfig()
    end
    if imgui.IsItemHovered() then imgui.SetTooltip(u8"Скопировать товары в конфиг") end
    if font_fa then imgui.PopFont() end
    
    imgui.PopStyleColor(3)
    
    -- Зона перетаскивания окна (ОПТИМИЗАЦИЯ FPS: Высота зоны теперь равна высоте хедера `h`, а не 500px)
    imgui.SetCursorScreenPos(p)
    if imgui.InvisibleButton("##drag_remote", imgui.ImVec2(w - S(100), h)) then end
    
    if imgui.IsItemActive() and imgui.IsMouseDragging(0) then
        local delta = imgui.GetMouseDragDelta(0)
        local wp = imgui.GetWindowPos()
        imgui.SetWindowPosVec2(imgui.ImVec2(wp.x + delta.x, wp.y + delta.y))
        imgui.ResetMouseDragDelta(0)
    end
    
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + h))
end

function parseShopPrice(price_text)
    if not price_text or price_text == "" then return 0 end
    
    local text = tostring(price_text):gsub(" р.", ""):gsub(" р", ""):gsub("^%s+", ""):gsub("%s+$", "")
    local num_str = text:match("([0-9.]+)")
    if not num_str then return 0 end
    
    local num = tonumber(num_str) or 0
    
    if text:find("ккк") then
        num = num * 1000000000
    elseif text:find("кк") then
        num = num * 1000000
    elseif text:find("к") then
        num = num * 1000
    end
    
    return math.floor(num)
end

function createBuyConfig(name)
    local new_config = { 
        name = name or "Новый конфиг", 
        items = {} 
    }
    -- Генерируем имя файла сразу, чтобы сохранить структуру
    local safe_name = tostring(new_config.name):gsub("[^%w%s%-_]", ""):gsub("%s+", "_")
    if safe_name == "" then safe_name = "config_" .. os.time() end
    new_config._filename = safe_name .. ".json"

    -- Сохраняем на диск
    saveSingleConfig(PATHS.PROFILES_BUY, new_config)
    
    -- Добавляем в память БЕЗ перезагрузки всего списка, чтобы не сбить индексы
    table.insert(Data.buy_configs, new_config)
    
    return #Data.buy_configs
end

function deleteBuyConfig(index)
    if index < 1 or index > #Data.buy_configs then return end
    
    -- Не даем удалить последний конфиг, чтобы не сломать логику
    if #Data.buy_configs <= 1 then
        addToastNotification("Нельзя удалить последний конфиг!", "error")
        return
    end

    local config = Data.buy_configs[index]
    deleteConfigFile(PATHS.PROFILES_BUY, config._filename)
    
    table.remove(Data.buy_configs, index)
    
    -- Корректируем активный индекс, если удалили что-то перед ним или его самого
    if Data.active_buy_config == index then
        -- [КРИТИЧЕСКОЕ ИСПРАВЛЕНИЕ]
        -- Сбрасываем активный индекс перед переключением, чтобы selectBuyConfig
        -- не сохранил текущий (удаленный) список в Конфиг №1 и не стер его!
        Data.active_buy_config = nil 
        selectBuyConfig(1)
    elseif Data.active_buy_config > index then
        -- Если удалили конфиг выше по списку, сдвигаем указатель
        Data.active_buy_config = Data.active_buy_config - 1
    end
    
    addToastNotification("Конфиг удален", "success", 2.0)
end

function renameBuyConfig(index, new_name)
    if index < 1 or index > #Data.buy_configs then return end
    if new_name and new_name ~= "" then
        local config = Data.buy_configs[index]
        local old_filename = config._filename
        
        config.name = new_name
        config._filename = nil -- Триггер генерации нового уникального имени
        
        -- [ИННОВАЦИЯ] Удаляем старый файл ТОЛЬКО если новый успешно записан
        local success = saveSingleConfig(PATHS.PROFILES_BUY, config)
        
        if success and old_filename and old_filename ~= config._filename then
            deleteConfigFile(PATHS.PROFILES_BUY, old_filename)
        end
        
        addToastNotification("Конфиг переименован", "success", 2.0)
    end
end

function selectBuyConfig(index)
    if index < 1 or index > #Data.buy_configs then return end
    
    -- 1. Сохраняем состояние ТЕКУЩЕГО (старого) конфига перед переключением
    if Data.active_buy_config and Data.buy_configs[Data.active_buy_config] then
        -- Синхронизация UI списка в структуру конфига
        saveBuyConfigState() 
    end

    -- 2. Переключаемся
    Data.active_buy_config = index
    Data.buy_list = {}
    
    -- 3. Загружаем новый список (Deep Copy во избежание ссылочных связей)
    for _, item in ipairs(Data.buy_configs[index].items) do
        local item_copy = sanitizeItemData(item) -- Берем только чистые данные
        
        -- Инициализируем UI-поля для нового сеанса
        item_copy._uid_cache = tostring(os.clock()) .. "_" .. math.random(1000,9999) 
        
        table.insert(Data.buy_list, item_copy)
    end
    
    -- 4. Пересчет и сохранение указателя активного конфига
    calculateBuyTotal()
    saveListsConfig() 
    addToastNotification("Загружен конфиг: " .. Data.buy_configs[index].name, "info", 2.0)
end

function copyRemoteShopConfig()
    if #Data.remote_shop_items == 0 then
        addToastNotification("Список товаров пуст", "warning", 2.0)
        return
    end
    
    local has_sell = false
    local has_buy = false
    for _, item in ipairs(Data.remote_shop_items) do
        if item.shop_type == 9 then has_sell = true end
        if item.shop_type == 10 then has_buy = true end
    end
    
    if has_sell and not has_buy then App.config_selector_mode = "sell"
    elseif has_buy and not has_sell then App.config_selector_mode = "buy"
    else App.config_selector_mode = "sell" end
    
    App.show_config_selector = true
    App.config_copy_pending = true
end

function performRemoteShopCopy(config_idx, target_mode)
    if #Data.remote_shop_items == 0 then
        addToastNotification("Список товаров для копирования пуст", "warning", 2.0)
        return
    end
    
    local is_sell = (target_mode == "sell")
    local target_configs = is_sell and Data.sell_configs or Data.buy_configs
    local active_idx = is_sell and Data.active_sell_config or Data.active_buy_config
    
    if config_idx < 1 or config_idx > #target_configs then return end
    
    local target_config = target_configs[config_idx]
    local is_active_config = (config_idx == active_idx)
    
    if is_active_config then
        if is_sell then saveSellConfigState() else saveBuyConfigState() end
    end

    local added_count = 0
    local modified = false
    
    local existing_map = {}
    for _, item in ipairs(target_config.items) do
        if item.name then existing_map[cleanItemNameKey(item.name):lower()] = true end
    end

    local valid_indexes = {}
    if Data.buyable_items then
        for _, b_item in ipairs(Data.buyable_items) do
            if b_item.name then valid_indexes[cleanItemNameKey(b_item.name):lower()] = b_item.index end
        end
    end
    
    for _, remote_item in ipairs(Data.remote_shop_items) do
        local item_type_match = (is_sell and remote_item.shop_type == 9) or (not is_sell and remote_item.shop_type == 10)
        
        if item_type_match then
            local clean_name = enhancedCleanItemName(remote_item.name)
            local lower_name = clean_name:lower()
            
            if not existing_map[lower_name] then
                local parsed_price = remote_item.raw_price or parseShopPrice(remote_item.price_text)
                local correct_index = valid_indexes[lower_name] or -1
                
                if correct_index == -1 and Data.item_names_reversed then
                    local db_id = Data.item_names_reversed[clean_name] or Data.item_names_reversed[lower_name]
                    if db_id then correct_index = db_id end
                end

                local is_acc = isAccessory(clean_name)
                local amount = is_acc and 0 or (remote_item.amount or 1)
                
                local new_item = {
                    name = clean_name,
                    price = parsed_price,
                    amount = amount,
                    active = true,
                    model_id = remote_item.model_id or correct_index or -1,
                    index = correct_index
                }
                
                if is_sell then
                    new_item.auto_max = true
                end
                
                table.insert(target_config.items, new_item)
                
                if is_active_config then
                    local live_item = {}
                    for k,v in pairs(new_item) do live_item[k] = v end
                    live_item._uid_cache = tostring(os.clock()) .. "_" .. math.random(1000, 9999) .. "_import"
                    if is_sell then
                        table.insert(Data.sell_list, live_item)
                    else
                        table.insert(Data.buy_list, live_item)
                    end
                end
                
                existing_map[lower_name] = true
                added_count = added_count + 1
                modified = true
            end
        end
    end
    
    if modified then
        if is_sell then
            saveSingleConfig(PATHS.PROFILES_SELL, target_config)
        else
            saveSingleConfig(PATHS.PROFILES_BUY, target_config)
        end
        
        if is_active_config then
            if is_sell then calculateSellTotal() else calculateBuyTotal() end
            saveListsConfig(true)
            addToastNotification("Добавлено " .. added_count .. " товаров в текущий список", "success", 3.0)
        else
            addToastNotification(string.format("Добавлено %d товаров в конфиг '%s'", added_count, target_config.name), "success", 3.0)
        end
    else
        addToastNotification("Новых товаров не найдено (или нет товаров нужного типа)", "info", 2.0)
    end
end

function renderRemoteShopWindow()
    local sw, sh = getScreenResolution()
    local w, h = 350, 500
    
    imgui.SetNextWindowPos(imgui.ImVec2(20, (sh - h) / 2), imgui.Cond.Appearing)
    imgui.SetNextWindowSize(imgui.ImVec2(w, h), imgui.Cond.FirstUseEver)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 10)
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.08, 0.09, 0.11, 0.98))
    
    if imgui.Begin("##RemoteShopViewer", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize) then
        local win_w = imgui.GetWindowWidth()
        
        imgui.BeginChild("RemoteHeader", imgui.ImVec2(win_w, S(50)), false, imgui.WindowFlags.NoScrollbar)
            renderRemoteShopHeader(win_w, S(50))
        imgui.EndChild()
        
        imgui.SetCursorPos(imgui.ImVec2(S(10), S(60)))
        if renderAnimatedSearchBar(Buffers.remote_shop_search, "Поиск товара...", win_w - S(20)) then
            -- Если текст изменился, требуем пересчет списка
            RemoteShopState.needs_refresh = true
        end
        
        imgui.SetCursorPosY(S(110))
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(10), S(10)))
        
        imgui.BeginChild("RemoteItems", imgui.ImVec2(0, 0), true)
            
            local search_raw = ffi.string(Buffers.remote_shop_search)
            
            -- [OPTIMIZATION] Проверяем, изменились ли данные или запрос поиска
            if RemoteShopState.needs_refresh or search_raw ~= RemoteShopState.last_search or #Data.remote_shop_items ~= RemoteShopState.last_data_count then
                
                RemoteShopState.filtered_list = {}
                local temp_list = {}
                
                -- 1. Фильтрация
                if search_raw == "" then
                    for _, item in ipairs(Data.remote_shop_items) do table.insert(temp_list, item) end
                else
                    local query = u8:decode(search_raw)
                    local results_with_score = {}
                    for _, item in ipairs(Data.remote_shop_items) do
                        local clean_name = enhancedCleanItemName(item.name)
                        local score = SmartSearch.getMatchScore(query, clean_name)
                        if score > 0 then
                            table.insert(results_with_score, {data = item, score = score})
                        end
                    end
                    table.sort(results_with_score, function(a, b) return a.score > b.score end)
                    for _, entry in ipairs(results_with_score) do table.insert(temp_list, entry.data) end
                end
                
                -- 2. Сортировка (Тяжелая операция - делаем один раз!)
                table.sort(temp_list, function(a, b)
                    local function isProfitable(item)
                        local p = parseShopPrice(item.price_text)
                        -- Кэшируем получение средней цены во время сортировки, если это возможно, 
                        -- но здесь вызываем функцию, так как она уже оптимизирована через CacheSystem
                        local avg = getAveragePriceForItem({name = item.name}, "sell")
                        if not avg or avg <= 0 or p <= 0 then return false end
                        
                        if item.shop_type == 10 then -- Лавка скупает
                            return p > avg
                        else -- Лавка продает
                            return p < avg
                        end
                    end
                    
                    local profit_a = isProfitable(a)
                    local profit_b = isProfitable(b)
                    
                    if profit_a and not profit_b then return true end
                    if not profit_a and profit_b then return false end
                    
                    return (a.slot or 0) < (b.slot or 0)
                end)
                
                RemoteShopState.filtered_list = temp_list
                RemoteShopState.last_search = search_raw
                RemoteShopState.last_data_count = #Data.remote_shop_items
                RemoteShopState.needs_refresh = false
            end
            
            -- Используем готовый кэшированный список
            local filtered = RemoteShopState.filtered_list
            
            if #filtered == 0 then
                imgui.Spacing()
                imgui.Indent(S(10))
                local msg = (search_raw ~= "") and u8("Ничего не найдено") or u8("Загрузка или пусто...")
                imgui.TextColored(CURRENT_THEME.text_hint, msg)
                imgui.Unindent(S(10))
            else
                local draw_list = imgui.GetWindowDrawList()
                local item_h = S(55) 
                local spacing_y = S(5)
                local item_full_h = item_h + spacing_y
                
                -- Виртуальный скроллинг
                local total_items = #filtered
                local current_scroll = imgui.GetScrollY()
                local visible_height = imgui.GetWindowHeight()
                
                local start_idx = math.floor(current_scroll / item_full_h) + 1
                local end_idx = start_idx + math.ceil(visible_height / item_full_h) + 1
                
                start_idx = math.max(1, start_idx)
                end_idx = math.min(total_items, end_idx)
                
                imgui.SetCursorPosY((start_idx - 1) * item_full_h)
                
                for i = start_idx, end_idx do
                    local item = filtered[i]
                    if item then
                        local p = imgui.GetCursorScreenPos()
                        local avail_w = imgui.GetContentRegionAvail().x
                        
                        -- Расчеты цветов и цен выполняем только для видимых элементов
                        local numeric_price = parseShopPrice(item.price_text)
                        local avg_price = getAveragePriceForItem({name = item.name}, "sell") 
                        
                        local is_shop_buying = (item.shop_type == 10)
                        local is_good_deal = false
                        
                        if numeric_price > 0 and avg_price and avg_price > 0 then
                            if is_shop_buying then
                                if numeric_price > avg_price then is_good_deal = true end
                            else
                                if numeric_price < avg_price then is_good_deal = true end
                            end
                        end
                        
                        local bg_col_u32
                        local hover_col_u32
                        
                        if is_good_deal then
                            bg_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.15, 0.35, 0.15, 0.7))
                            hover_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.20, 0.45, 0.20, 0.9))
                        else
                            bg_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.12, 0.13, 0.16, 0.5))
                            hover_col_u32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.15, 0.16, 0.20, 0.8))
                        end
                        
                        imgui.PushIDInt(item.slot or i)
                        if imgui.InvisibleButton("##ritem"..i, imgui.ImVec2(avail_w, item_h)) then
                            if item.slot then
                                local payload = string.format('clickOnBlock|{"slot": %d, "type": %d}', item.slot, item.shop_type or 9)
                                sendCEF(payload)
                            end
                        end
                        
                        local is_hovered = imgui.IsItemHovered()
                        if is_hovered then
                             local tooltip = u8("Нажмите, чтобы показать в лавке")
                             if avg_price and avg_price > 0 then
                                local profit_label = is_good_deal and u8"ВЫГОДА" or u8"Разница"
                                local diff = 0
                                if is_shop_buying then diff = numeric_price - avg_price else diff = avg_price - numeric_price end
                                tooltip = tooltip .. (string.format("\n%s: %s%s $", profit_label, diff > 0 and "+" or "", formatMoney(math.abs(diff))))
                                tooltip = tooltip .. u8("\nСредняя цена: " .. formatMoney(avg_price) .. " $")
                             end
                            imgui.SetTooltip(tooltip)
                        end
                        imgui.PopID()
                        
                        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + avail_w, p.y + item_h), is_hovered and hover_col_u32 or bg_col_u32, S(6))
                        if is_good_deal then
                            draw_list:AddRect(p, imgui.ImVec2(p.x + avail_w, p.y + item_h), 0xFF66FF66, S(6), 15, S(1))
                        end

                        local safe_name = item.name or "???"
                        draw_list:AddText(imgui.ImVec2(p.x + S(10), p.y + S(5)), 0xFFFFFFFF, u8(safe_name))
                        
                        local price_text = u8(item.price_text or "0")
                        local price_color = is_good_deal and 0xFF66FF66 or 0xFF6666FF
                        draw_list:AddText(imgui.ImVec2(p.x + S(10), p.y + S(23)), price_color, price_text)
                        
                        if avg_price and avg_price > 0 then
                            local avg_text = u8("(Рынок: " .. formatMoney(avg_price) .. ")")
                            local price_width = GetStaticTextSize(price_text).x
                            draw_list:AddText(imgui.ImVec2(p.x + S(15) + price_width, p.y + S(23)), 0xFFAAAAAA, avg_text)
                        end
                        
                        local amount_text = u8("x" .. (item.amount or 1))
                        local amount_size = GetStaticTextSize(amount_text)
                        draw_list:AddText(imgui.ImVec2(p.x + avail_w - amount_size.x - S(10), p.y + (item_h - amount_size.y)/2), 0xFFAAAAAA, amount_text)
                        
                        imgui.SetCursorPosY(imgui.GetCursorPosY() + spacing_y)
                    end
                end
                
                if end_idx < total_items then
                    local remaining = total_items - end_idx
                    imgui.SetCursorPosY(imgui.GetCursorPosY() + (remaining * item_full_h))
                end
            end
            
        imgui.EndChild()
        imgui.PopStyleVar()
    end
    imgui.End()
    imgui.PopStyleColor()
    imgui.PopStyleVar(2)
end

function renderMiniProcessWindow(title, status_text, progress_text, stop_callback)
    local io = imgui.GetIO()
    imgui.SetNextWindowPos(imgui.ImVec2(io.DisplaySize.x / 2, io.DisplaySize.y / 2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_secondary)
    
    if imgui.Begin("##MiniProcess", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.AlwaysAutoResize) then
        imgui.TextColored(CURRENT_THEME.accent_primary, u8(title))
        imgui.Separator()
        imgui.Text(u8(status_text))
        if progress_text then imgui.TextDisabled(u8(progress_text)) end
        imgui.Spacing()
        if imgui.Button(u8"ПРЕРВАТЬ", imgui.ImVec2(200, S(30))) and stop_callback then
            stop_callback()
        end
    end
    imgui.End()
    imgui.PopStyleColor()
end

function renderAAAToggle(str_id, v)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    
    local radius = S(11)
    local size = radius * 2
    
    local clicked = imgui.InvisibleButton(str_id, imgui.ImVec2(size, size))
    local is_hovered = imgui.IsItemHovered()
    
    local center = imgui.ImVec2(p.x + radius, p.y + radius)
    
    local bg_col = 0
    local border_col = CURRENT_THEME.border_light_u32
    local icon_col = 0
    local icon = ""
    local border_thickness = S(1.5)
    
    if v then 
        bg_col = CURRENT_THEME.accent_primary_u32
        -- ОПТИМИЗАЦИЯ: Избегаем создания ImVec4 каждый кадр
        border_col = setAlphaU32(CURRENT_THEME.accent_primary_u32, 0.4)
        border_thickness = S(2.5)
        icon = fa('check')
        
        local lum = CURRENT_THEME.accent_primary.x * 0.299 + CURRENT_THEME.accent_primary.y * 0.587 + CURRENT_THEME.accent_primary.z * 0.114
        icon_col = lum > 0.6 and 0xFF101010 or 0xFFFFFFFF
    else 
        if is_hovered then
            bg_col = 0x14FFFFFF 
            border_col = CURRENT_THEME.accent_primary_u32
        end
    end
    
    if bg_col ~= 0 then 
        draw_list:AddCircleFilled(center, radius, bg_col, 24) 
    end
    
    draw_list:AddCircle(center, radius, border_col, 24, border_thickness)
    
    if v and font_fa then
        imgui.PushFont(font_fa)
        local isz = GetStaticTextSize(icon)
        draw_list:AddText(imgui.ImVec2(center.x - isz.x/2, center.y - isz.y/2), icon_col, icon)
        imgui.PopFont()
    end
    
    return clicked
end

function api_SubmitPassiveShop()
    if not ScanCollector.current_shop_owner then return end
    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    local owner_id = ScanCollector.current_shop_id
    if not owner_id or owner_id == -1 then
        owner_id = findPlayerIdByNickname(ScanCollector.current_shop_owner)
    end
    local s_names, s_counts, s_prices = {}, {}, {}
    local b_names, b_counts, b_prices = {}, {}, {}
    for _, item in ipairs(Data.remote_shop_items) do
        if item.model_id and item.amount and item.raw_price then
            if item.shop_type == 9 then
                table.insert(s_names, tonumber(item.model_id))
                table.insert(s_counts, item.amount)
                table.insert(s_prices, item.raw_price)
            elseif item.shop_type == 10 then
                table.insert(b_names, tonumber(item.model_id))
                table.insert(b_counts, item.amount)
                table.insert(b_prices, item.raw_price)
            end
        end
    end
    local payload = {
        username     = u8(ScanCollector.current_shop_owner),
        enabled      = true,
        serverId     = server_id,
        token        = "",
        playerId     = owner_id, 
        LavkaUid     = 0,
        vip          = false,
        items_sell   = s_names,
        count_sell   = s_counts,
        price_sell   = s_prices,
        items_buy    = b_names,
        count_buy    = b_counts,
        price_buy    = b_prices
    }
    signed_request(
        "POST",
        MarketConfig.HOST .. "/marketplace?action=insert_passive", 
        payload,
        function(response)
            if response.status_code == 200 then
                print("[RMarket] Passive shop updated: " .. ScanCollector.current_shop_owner .. " (ID: " .. owner_id .. ")")
            end
        end
    )
end

function startPassiveShopsCheck()
    -- [FIX] Механизм полностью отключен во избежание спама /id в чат и киков от анти-флуда
    PassiveChecker.active = false
    PassiveChecker.queue = {}
end

function processNextPassiveCheck()
    if #PassiveChecker.queue == 0 then
        App.tasks.remove_by_name("passive_check_timeout")
        
        App.tasks.add("passive_finish_grace", function()
            if PassiveChecker.active then
                PassiveChecker.active = false
                PassiveChecker.current_nick = nil
                addToastNotification("Проверка пассивных лавок завершена.", "success")
            end
        end, 2500)
        return
    end
    
    App.tasks.remove_by_name("passive_finish_grace")
    
    local current_data = table.remove(PassiveChecker.queue, 1)
    
    PassiveChecker.current_nick = current_data.nick
    PassiveChecker.current_expected_id = current_data.expected_id
    PassiveChecker.current_shop_obj = current_data.shop_data
    
    local cmd_nick = PassiveChecker.current_nick:gsub(" ", "_")
    
    PassiveChecker.waiting_for_id = true
    App.tasks.remove_by_name("passive_id_timeout")
    App.tasks.add("passive_id_timeout", function()
        if PassiveChecker.waiting_for_id then
            PassiveChecker.waiting_for_id = false
        end
    end, 3000)
    
    sampSendChat("/id " .. cmd_nick)
    
    App.tasks.add("passive_check_timeout", function()
        if PassiveChecker.active and PassiveChecker.current_nick then
            PassiveChecker.waiting_for_id = false
            deletePassiveShop(PassiveChecker.current_nick)
            processNextPassiveCheck()
        end
    end, 2000)
end

