function api_FetchMods()
    if ModsData.is_loading then return end
    ModsData.is_loading = true
    
    asyncHttpRequest('GET', MarketConfig.HOST .. '/get_mods', {},
        function(response)
            ModsData.is_loading = false
            if response.status_code == 200 then
                local ok, data = pcall(json.decode, response.text)
                if ok and data then
                    ModsData.list = {}
                    for _, mod in ipairs(data) do
                        -- Обработка списка файлов
                        local files_list = {}
                        if mod.files and type(mod.files) == "table" then
                            for _, f in ipairs(mod.files) do
                                table.insert(files_list, {
                                    url = f.url,
                                    name = safe_decode(f.name),
                                    folder = f.folder or "moonloader"
                                })
                            end
                        end

                        table.insert(ModsData.list, {
                            id = mod.id,
                            title = safe_decode(mod.title),
                            desc = safe_decode(mod.description),
                            cmd = safe_decode(mod.activation_cmd),
                            image_url = mod.image_url,
                            author = safe_decode(mod.author or "Unknown"),
                            downloads = tonumber(mod.downloads) or 0, 
                            is_vip = mod.is_vip == 1 or mod.is_vip == true, -- [NEW] Считываем VIP статус
                            files = files_list
                        })
                    end
                end
            end
        end,
        function(err) ModsData.is_loading = false end
    )
end

function installModFiles(files)
    if not files or #files == 0 then 
        addToastNotification("Нет файлов для установки", "error")
        return 
    end

    local workDir = getWorkingDirectory()
    local gameRoot = workDir .. "\\..\\" -- Корень игры
    
    -- Карта путей
    local paths = {
        moonloader = workDir .. "\\",
        moonloader_lib = workDir .. "\\lib\\",
        moonloader_config = workDir .. "\\config\\",
        cleo = gameRoot .. "cleo\\",
        sampfuncs = gameRoot .. "SAMPFUNCS\\",
        root = gameRoot
    }

    local downloaded_count = 0
    local total_files = #files
    local errors = 0
    
    -- Флаги для определения типа перезагрузки
    local needs_game_restart = false
    local needs_script_reload = false

    addToastNotification("Начало установки (" .. total_files .. " файлов)...", "info", 3.0)

    for i, file in ipairs(files) do
        local target_folder = paths[file.folder] or paths.moonloader
        -- Создаем папку если нет
        if not doesDirectoryExist(target_folder) then createDirectory(target_folder) end
        
        local final_path = target_folder .. file.name
        
        -- Определение типа файла для уведомления
        local ext = file.name:match("^.+(%.[^%.]+)$")
        if ext then ext = ext:lower() end

        -- Если это ASI, CLEO, SF или файл в корне - нужен рестарт игры
        if file.folder == "root" or file.folder == "cleo" or file.folder == "sampfuncs" or (ext == ".asi" or ext == ".cs" or ext == ".sf" or ext == ".dll") then
            needs_game_restart = true
        -- Если это Lua в папке moonloader - нужен релоад скрипта
        elseif file.folder:find("moonloader") and (ext == ".lua" or ext == ".luac") then
            needs_script_reload = true
        end

        asyncHttpRequest('GET', file.url, {}, 
            function(response)
                if response.status_code == 200 then
                    local f = io.open(final_path, "wb")
                    if f then
                        f:write(response.text)
                        f:close()
                        downloaded_count = downloaded_count + 1
                        print("[RMarket] File installed: " .. file.name .. " -> " .. file.folder)
                    else
                        print("[RMarket] Write error: " .. final_path)
                        errors = errors + 1
                    end
                else
                    print("[RMarket] Download error: " .. response.status_code .. " for " .. file.name)
                    errors = errors + 1
                end

                -- Если это последний файл (или все обработаны)
                if (downloaded_count + errors) >= total_files then
                    if errors == 0 then
                        if needs_game_restart then
                            -- Приоритет 1: Если есть файлы требующие рестарта игры
                            addToastNotification("Успешно! Для работы ПЕРЕЗАЙДИТЕ в игру.", "warning", 10.0)
                            sampAddChatMessage("[RMarket] {ffff00}Установлены файлы, требующие перезапуска игры (ASI/CLEO/Root).", -1)
                        elseif needs_script_reload then
                            -- Приоритет 2: Только Lua скрипты
                            addToastNotification("Установлено! Перезагружаю скрипты...", "success")
                            reloadScripts()
                        else
                            -- Приоритет 3: Конфиги или ресурсы
                            addToastNotification("Все файлы установлены! (" .. total_files .. " шт.)", "success", 5.0)
                        end
                    else
                        addToastNotification("Установка завершена с ошибками (" .. errors .. ")", "warning")
                    end
                end
            end
        )
        -- Небольшая задержка между запросами
        wait(50) 
    end
end

function roundPriceToClean(price)
    if not price then return 0 end
    price = tonumber(price) or 0
    
    if price < 1000 then return math.floor(price / 10 + 0.5) * 10 end 
    
    local step = 100
    if price >= 100000000 then step = 100000   -- 100кк+ -> 100к
    elseif price >= 10000000 then step = 10000 -- 10кк+ -> 10к
    elseif price >= 1000000 then step = 5000   -- 1кк+  -> 5к
    elseif price >= 100000 then step = 1000    -- 100к+ -> 1к
    else step = 100 end                        -- <100к -> 100
    
    return math.floor(price / step + 0.5) * step
end

-- [[ ЗАМЕНИТЬ ЭТУ ФУНКЦИЮ ПОЛНОСТЬЮ ]]
function api_DownloadAveragePrices()
    if App.is_downloading_prices then 
        addToastNotification("Загрузка уже выполняется...", "warning")
        return 
    end

    local ip, port = sampGetCurrentServerAddress()
    local server_raw = ip .. ":" .. port
    
    local server_config = findServerConfig(server_raw)
    if not server_config then server_config = findServerConfig(nil) end
    
    if not server_config then
        print("[RMarket ERROR] Не удалось определить сервер. IP: " .. server_raw)
        addToastNotification("Ошибка: Неизвестный сервер Родины", "error")
        return
    end
    
    local server_id = server_config.id
    
    print("[RMarket] Запрос цен для сервера: " .. server_config.name .. " (ID: " .. server_id .. ")")
    
    App.is_downloading_prices = true
    addToastNotification("Загрузка базы цен (вкл. графики)...", "info", 3.0)
    
    local url = MarketConfig.HOST .. "/get_prices?server=" .. url_encode(server_id)
    
    asyncHttpRequest("GET", url, { verify = false, timeout = 45 },
        function(response)
            lua_thread.create(function()
                if response.status_code == 200 then
                    if not response.text or #response.text < 2 then
                        addToastNotification("База данных сервера пуста или недоступна", "warning")
                        App.is_downloading_prices = false
                        return
                    end

                    local ok, data = pcall(json.decode, response.text)
                    if not ok then
                        addToastNotification("Ошибка обработки данных от сервера", "error")
                        App.is_downloading_prices = false
                        return
                    end
                    
                    if data and next(data) ~= nil then
                        local count = 0
                        local new_prices = {}
                        local new_history = {} -- Хранилище для истории
                        local markdown_percent = Data.settings.price_download_percent or 10
                        local multiplier = (100 - markdown_percent) / 100
                        
                        collectgarbage("stop")
                        
                        for name_utf8, info in pairs(data) do
                            local name_cp1251 = safe_decode(name_utf8)
                            local clean_key = cleanItemName(name_cp1251)
                            
                            local daily_sell = tonumber(info.s) or 0
                            local daily_buy = tonumber(info.b) or 0
                            
                            if daily_sell > 0 or daily_buy > 0 then
                                local adjusted_sell = daily_sell
                                if daily_sell > 0 then
                                    adjusted_sell = math.floor(daily_sell * multiplier)
                                end
                                
                                new_prices[clean_key] = {
                                    sell = roundPriceToClean(adjusted_sell),
                                    buy = roundPriceToClean(daily_buy),
                                    price = daily_sell, 
                                    source = "logs"
                                }
                                count = count + 1
                            end
                            
                            -- Парсинг истории (графиков)
                            if info.h and type(info.h) == "table" and #info.h > 0 then
                                local hist = {}
                                for _, pt in ipairs(info.h) do
                                    table.insert(hist, {
                                        date_str = pt.d,
                                        sell = pt.s,
                                        buy = pt.b
                                    })
                                end
                                new_history[clean_key] = hist
                            end
                        end
                        
                        collectgarbage("restart")
                        
                        if count > 0 then
                            Data.average_prices = new_prices
                            Data.daily_item_prices = new_history -- Обновляем кэш истории
                            
                            saveJsonFile(FILES.CACHE_PRICES, Data.average_prices)
                            saveJsonFile(FILES.CACHE_DAILY, Data.daily_item_prices)
                            saveJsonFile(FILES.PRICE_META, { last_update = os.time() })
                            
                            if clearPriceCache then clearPriceCache() end
                            if CacheSystem and CacheSystem.prices then CacheSystem.prices.market = {} end
                            
                            addToastNotification("Успешно обновлено цен: " .. count, "success", 4.0)
                        else
                            addToastNotification("Сервер вернул пустой список цен", "warning")
                        end
                    else
                        addToastNotification("Нет данных о сделках на этом сервере", "warning")
                    end
                else
                    addToastNotification("Ошибка соединения: HTTP " .. response.status_code, "error")
                end
                App.is_downloading_prices = false
            end)
        end,
        function(err)
            addToastNotification("Ошибка сети. Попробуйте позже.", "error")
            App.is_downloading_prices = false
        end
    )
end

function api_GetDailyPricesForItem(item_name, callback)
    if not callback then return end
    if not item_name or item_name == "" then 
        callback({})
        return 
    end
    
    local clean_name = cleanItemName(item_name)
    if not Data.daily_item_prices then Data.daily_item_prices = {} end

    -- Теперь мы НЕ делаем HTTP запрос, а отдаем данные из кэша МГНОВЕННО.
    -- (Они скачиваются вместе с кнопкой "Скачать средние цены")
    if Data.daily_item_prices[clean_name] then
        callback(Data.daily_item_prices[clean_name])
    else
        callback({}) -- Данных нет (или еще не скачали базу)
    end
end

