-- ===== ФУНКЦИИ ДЛЯ ОВЕРЛЕЯ ЦЕНЫ ТОВАРА =====

function parseItemNameFromModal(text)
    if not text then return "" end
    
    -- 1. Сначала извлекаем ПЕРВУЮ строку из СЫРОГО текста (до того, как удалятся переносы строк \n)
    local raw_first_line = text:match("([^\r\n]+)")
    if not raw_first_line then return "" end
    
    -- 2. Очищаем от цветовых кодов ТОЛЬКО первую строку (чтобы не склеилось с описанием)
    local clean_line = cleanTextColors(raw_first_line)
    
    -- 3. Пытаемся извлечь название по разным паттернам оформления диалогов Родины
    local item_name = nil
    
    -- Формат 1: "Название товара - описание..." (Паттерн кейсов, ларцов и новых предметов)
    item_name = clean_line:match("^(.-)%s+%-%s+")
    
    -- Формат 2: "Категория: Название товара" (Паттерн аксессуаров, скинов)
    if not item_name then
        item_name = clean_line:match(":%s*(.+)")
    end
    
    -- Формат 3: Резервный фоллбэк для очень старых типов
    if not item_name then
        item_name = clean_line:match("Предмет:%s*(.+)")
    end
    
    -- 4. Финальная очистка пробелов по краям
    if item_name then
        item_name = item_name:match("^%s*(.-)%s*$")
        if item_name ~= "" then 
            return item_name 
        end
    end
    
    return ""
end

function showItemPriceOverlay(item_name)
    if not item_name or item_name == "" then return end
    
    App.item_price_overlay.active = true
    App.item_price_overlay.item_name = item_name
    App.item_price_overlay.created_at = os.time()
    
    -- Добавляем флаги сброса состояния
    App.item_price_overlay.loading = true
    App.item_price_overlay.price_history = {}
    
    -- Получаем среднюю цену из кэша
    local clean_name = enhancedCleanItemName(item_name)
    local price_data = Data.average_prices[clean_name]
    
    if price_data then
        App.item_price_overlay.avg_buy_price = price_data.buy or 0
        App.item_price_overlay.avg_sell_price = price_data.sell or 0
    else
        App.item_price_overlay.avg_buy_price = 0
        App.item_price_overlay.avg_sell_price = 0
    end
    
    -- Получаем историю цен за 30 дней (асинхронно)
    api_GetDailyPricesForItem(item_name, function(data)
        App.item_price_overlay.loading = false
        if data and type(data) == "table" then
            App.item_price_overlay.price_history = data
        end
    end)
end

function renderItemPriceOverlay()
    if not App.item_price_overlay.active then return end
    
    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local overlay_w = S(350)
    local overlay_h = S(300)
    
    -- Позиция: слева монитора, по центру по вертикали
    local overlay_x = S(15)
    local overlay_y = (sh - overlay_h) / 2
    
    -- Рисуем фон оверлея
    imgui.SetNextWindowPos(imgui.ImVec2(overlay_x, overlay_y), imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(overlay_w, overlay_h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(12), S(12)))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(10))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1.5)) -- Добавлено S()
    
    if imgui.Begin("##ItemPriceOverlay", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove) then
        -- Заголовок
        imgui.TextColored(CURRENT_THEME.accent_primary, fa('chart_line'))
        imgui.SameLine()
        imgui.TextColored(CURRENT_THEME.text_primary, u8"Анализ цены")
        imgui.Spacing()
        
        -- Название товара
        local item_name_display = App.item_price_overlay.item_name
        if #item_name_display > 38 then
            item_name_display = item_name_display:sub(1, 35) .. "..."
        end
        imgui.TextWrapped(u8(item_name_display))
        imgui.Spacing()
        imgui.Separator()
        imgui.Spacing()
        
        -- Средние цены
        imgui.TextColored(CURRENT_THEME.accent_success, u8"Покупка: " .. formatMoney(App.item_price_overlay.avg_buy_price))
        imgui.TextColored(CURRENT_THEME.accent_danger, u8"Продажа: " .. formatMoney(App.item_price_overlay.avg_sell_price))
        imgui.Spacing()
        
        -- Разница в процентах
        if App.item_price_overlay.avg_buy_price > 0 then
            local percent_diff = ((App.item_price_overlay.avg_sell_price - App.item_price_overlay.avg_buy_price) / App.item_price_overlay.avg_buy_price) * 100
            local color = percent_diff >= 0 and CURRENT_THEME.accent_success or CURRENT_THEME.accent_danger
            imgui.TextColored(color, u8"Маржа: " .. string.format("%.1f%%", percent_diff))
        end
        
        imgui.Spacing()
        imgui.Separator()
        imgui.Spacing()
        
        -- История цен
        if App.item_price_overlay.loading then
            imgui.TextColored(CURRENT_THEME.text_secondary, u8"Загрузка данных...")
        elseif App.item_price_overlay.price_history and #App.item_price_overlay.price_history > 0 then
            local min_price = math.huge
            local max_price = 0
            
            for _, price_entry in ipairs(App.item_price_overlay.price_history) do
                if price_entry.sell and price_entry.sell > 0 then
                    min_price = math.min(min_price, price_entry.sell)
                    max_price = math.max(max_price, price_entry.sell)
                end
            end
            
            if min_price ~= math.huge then
                imgui.TextColored(CURRENT_THEME.text_secondary, u8"Min: " .. formatMoney(min_price) .. " | Max: " .. formatMoney(max_price))
            end
        else
            imgui.TextColored(CURRENT_THEME.text_hint, u8"История цен отсутствует")
        end
    end
    
    imgui.End()
    imgui.PopStyleVar(3)
    imgui.PopStyleColor(2)
end

function api_ShareConfig(config_index)
    local config = Data.buy_configs[config_index]
    if not config or #config.items == 0 then
        addToastNotification("Пустой конфиг нельзя отправить", "warning")
        return
    end

    local payload = {
        name = u8(config.name), 
        items = {}
    }

    -- Собираем чистые данные
    for _, item in ipairs(config.items) do
        table.insert(payload.items, {
            name = u8(item.name),
            price = tonumber(item.price) or 0,
            amount = tonumber(item.amount) or 1,
            model_id = tonumber(item.model_id) or 0,
            index = tonumber(item.index) or tonumber(item.model_id) or -1, -- ФИКС: сохраняем индекс!
            active = item.active
        })
    end

    addToastNotification("Загрузка конфига на сервер...", "info")

    -- [СЕКЬЮРИТИ ФИКС] Отправка конфига с токеном авторизации
    signed_request("POST", MarketConfig.HOST .. "/shareConfig", payload,
        function(response)
            if response.status_code == 200 then
                local ok, res = pcall(json.decode, response.text)
                if ok and res.status == 'success' and res.code then
                    ShareState.generated_code = res.code
                    ShareState.config_name = config.name
                    ShareState.modal_active = true
                    setClipboardText(res.code)
                    addToastNotification("Код скопирован в буфер!", "success")
                else
                    addToastNotification("Ошибка обработки ответа", "error")
                end
            else
                -- Если все еще ошибка 500, то в консоли сервера будет причина
                addToastNotification("Ошибка сервера: " .. response.status_code, "error")
            end
        end,
        function(err)
            addToastNotification("Ошибка соединения", "error")
        end
    )
end

-- Глобальный кэш для мгновенного доступа O(1)
local GLOBAL_NAME_TO_ID_CACHE = nil

function findRealIndexByName(name)
    if not name then return nil end
    
    -- Инициализируем хэш-таблицу один раз при первом обращении
    if not GLOBAL_NAME_TO_ID_CACHE then
        GLOBAL_NAME_TO_ID_CACHE = {}
        if Data.item_names_reversed then
            for k, v in pairs(Data.item_names_reversed) do
                GLOBAL_NAME_TO_ID_CACHE[k] = v
            end
        end
        if Data.buyable_items then
            for _, item in ipairs(Data.buyable_items) do
                if item.name and item.index then
                    GLOBAL_NAME_TO_ID_CACHE[cleanItemNameKey(item.name):lower()] = item.index
                    GLOBAL_NAME_TO_ID_CACHE[cleanItemName(item.name):lower()] = item.index
                end
            end
        end
        for id, db_name in pairs(Data.item_names) do
            if type(db_name) == "string" then
                GLOBAL_NAME_TO_ID_CACHE[cleanItemName(db_name):lower()] = tonumber(id)
            end
        end
    end
    
    local clean_target = cleanItemNameKey(name):lower()
    local result = GLOBAL_NAME_TO_ID_CACHE[clean_target]
    if result then return result end
    
    local stripped_target = cleanItemName(name):lower()
    return GLOBAL_NAME_TO_ID_CACHE[stripped_target]
end

function api_ImportConfig()
    local code = ffi.string(Buffers.import_code)
    if code == "" then
        addToastNotification("Введите код конфига", "warning")
        return
    end

    addToastNotification("Поиск конфига...", "info")

    asyncHttpRequest("GET", MarketConfig.HOST .. "/getConfig/" .. code, {}, 
        function(response)
            if response.status_code == 200 then
                local ok, res = pcall(json.decode, response.text)
                if ok and res.status == 'found' and res.config then
                    local imported = res.config
                    
                    local new_items = {}
                    for _, item in ipairs(imported.items) do
                        local item_name = u8:decode(item.name)
                        
                        -- Берем ID напрямую из импортированных данных (поддержка новых и старых конфигов)
                        local resolved_index = tonumber(item.index) or -1
                        local resolved_model = tonumber(item.model_id) or -1
                        
                        -- Если индекс потерян, но есть model_id - синхронизируем их
                        if resolved_model > 0 and resolved_index <= 0 then resolved_index = resolved_model end
                        if resolved_index > 0 and resolved_model <= 0 then resolved_model = resolved_index end

                        -- Если у нас до сих пор нет нормального ID, пытаемся найти по имени
                        if resolved_index <= 0 then
                            local real_idx = findRealIndexByName(item_name)
                            if real_idx then
                                resolved_index = real_idx
                                resolved_model = real_idx
                            end
                        end

                        -- ФИКС: Если мы успешно определили ID, берем ПРАВИЛЬНОЕ название из нашей базы,
                        -- чтобы в меню писало "Ларец почтальона", а не обрубок "почтальона"
                        if resolved_index > 0 and Data.item_names[tostring(resolved_index)] then
                            item_name = Data.item_names[tostring(resolved_index)]
                        end

                        table.insert(new_items, {
                            name = item_name,
                            price = tonumber(item.price) or 0,
                            amount = tonumber(item.amount) or 1,
                            model_id = resolved_model,
                            active = item.active,
                            index = resolved_index 
                        })
                    end

                    local new_name = u8:decode(imported.name or "Imported") .. " (Import)"
                    table.insert(Data.buy_configs, {
                        name = new_name,
                        items = new_items
                    })
                    
                    local last_idx = #Data.buy_configs
                    if last_idx > 0 then
                        -- Генерируем безопасное имя файла, если его нет
                        local new_cfg = Data.buy_configs[last_idx]
                        if not new_cfg._filename then
                            new_cfg._filename = "import_" .. os.time() .. ".json"
                        end
                        
                        saveSingleConfig(PATHS.PROFILES_BUY, new_cfg)
                        
                        -- Если мы случайно перезаписали активный конфиг (маловероятно при append, но для надежности):
                        if last_idx == Data.active_buy_config then
                            saveActiveBuyProfile()
                        end
                    end
                    addToastNotification("Конфиг успешно импортирован! (" .. #new_items .. " товаров)", "success")
                    imgui.StrCopy(Buffers.import_code, "") 
                else
                    addToastNotification("Некорректные данные сервера", "error")
                end
            elseif response.status_code == 404 then
                addToastNotification("Конфиг с таким кодом не найден", "error")
            else
                addToastNotification("Ошибка сервера", "error")
            end
        end,
        function(err)
            addToastNotification("Ошибка соединения", "error")
        end
    )
end

function buildTopBuyConfig(api_items)
    local new_items = {}
    
    -- МГНОВЕННЫЙ КЭШ: Поиск O(1) вместо тяжелого O(N). Исключает зависание игры.
    local fast_id_cache = {}
    if Data.item_names_reversed then
        for k, v in pairs(Data.item_names_reversed) do
            fast_id_cache[k:lower()] = v
        end
    end
    
    -- Обработка готового ответа от сервера
    for _, item in ipairs(api_items) do
        local name = u8:decode(item.name)
        local price = tonumber(item.price) or 100
        local amount = tonumber(item.amount) or 1
        
        -- Мгновенное получение ID предмета за 0.0001 сек
        local clean_key = cleanItemNameKey(name):lower()
        local real_idx = fast_id_cache[clean_key] or -1
        
        table.insert(new_items, {
            name = name,
            price = price,
            amount = amount,
            model_id = real_idx,
            index = real_idx,
            active = true
        })
    end
    
    if #new_items > 0 then
        -- Создаем новый конфиг
        local cfg_name = "Топ Скупка " .. os.date("%d.%m")
        local new_idx = createBuyConfig(cfg_name)
        
        -- Заполняем и сохраняем
        Data.buy_configs[new_idx].items = new_items
        saveSingleConfig(PATHS.PROFILES_BUY, Data.buy_configs[new_idx])
        
        -- Переключаемся на него
        selectBuyConfig(new_idx)
        
        addToastNotification("Сгенерирован конфиг под ваш бюджет! (" .. #new_items .. " слотов)", "success", 6.0)
    else
        addToastNotification("Под указанный бюджет не найдено подходящих товаров.", "warning", 5.0)
    end
end

function api_GenerateTopBuyConfig(budget, include_accs)
    if Data.settings.telegram_token == "" then
        addToastNotification("Для этой функции требуется привязка Telegram ключа!", "error", 4.0)
        return
    end

    local ip, port = sampGetCurrentServerAddress()
    local server_id = normalizeServerId(ip .. ":" .. port)
    
    local payload = {
        secret_key = Data.settings.telegram_token,
        server = server_id,
        budget = budget,
        include_accs = include_accs
    }
    
    addToastNotification("Анализ рынка и загрузка конфига...", "info", 3.0)
    
    signed_request("POST", MarketConfig.HOST .. "/generate_top_buy", payload, function(response)
        if response.status_code == 200 then
            local ok, res = pcall(json.decode, response.text)
            if ok and res.status == 'success' and res.items then
                -- Убираем lua_thread, т.к. благодаря кэшу это выполняется мгновенно без фризов
                buildTopBuyConfig(res.items)
            elseif ok and res.status == 'error' and res.msg == 'limit_reached' then
                addToastNotification("Лимит исчерпан (3 раза в месяц). Приобретите VIP!", "error", 6.0)
            else
                addToastNotification("Не удалось получить конфиг от сервера", "error")
            end
        else
            addToastNotification("Ошибка сервера: " .. response.status_code, "error")
        end
    end)
end

function renderGenConfigModal()
    if not App.show_gen_config_modal then return end

    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local w, h = S(400), S(350)
    
    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(w, h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
    
    if imgui.Begin("GenConfigModal", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse) then
        local p = imgui.GetCursorScreenPos()
        local draw_list = imgui.GetWindowDrawList()
        
        -- Header
        local header_h = S(50)
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 3)
        draw_list:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1.0)
        
        imgui.SetCursorPos(imgui.ImVec2(S(20), (header_h - imgui.GetFontSize()) / 2))
        if font_fa then 
            imgui.PushFont(font_fa)
            imgui.TextColored(CURRENT_THEME.accent_primary, fa('wand_magic_sparkles'))
            imgui.PopFont()
            imgui.SameLine()
        end
        imgui.TextColored(CURRENT_THEME.text_primary, u8"Генерация ТОП конфига")
        
        -- Close button
        local close_sz = S(30)
        imgui.SetCursorPos(imgui.ImVec2(w - close_sz - S(10), (header_h - close_sz)/2))
        if imgui.InvisibleButton("##close_gen", imgui.ImVec2(close_sz, close_sz)) then
            App.show_gen_config_modal = false
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local icon_col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(p.x + w - close_sz - S(10) + S(6), p.y + (header_h - close_sz)/2 + S(6)), imgui.ColorConvertFloat4ToU32(icon_col), fa('xmark'))
            imgui.PopFont()
        end

        -- Content
        imgui.SetCursorPos(imgui.ImVec2(S(20), header_h + S(20)))
        imgui.BeginGroup()
        
        imgui.TextColored(CURRENT_THEME.text_secondary, u8"Ваш бюджет на скупку ($):")
        imgui.Dummy(imgui.ImVec2(0, S(5)))
        renderModernInput("##gen_budget", Buffers.gen_budget, w - S(40), "Например: 50000000", false)
        renderMoneyTooltip(ffi.string(Buffers.gen_budget))
        
        imgui.Dummy(imgui.ImVec2(0, S(20)))
        
        if renderAAAToggle("##inc_accs", Buffers.gen_include_accs[0]) then
            Buffers.gen_include_accs[0] = not Buffers.gen_include_accs[0]
        end
        imgui.SameLine()
        imgui.BeginGroup()
            imgui.TextColored(CURRENT_THEME.text_primary, u8"Включать аксессуары")
            imgui.TextColored(CURRENT_THEME.text_hint, u8"Займут много слотов (под разные цвета)")
        imgui.EndGroup()

        imgui.EndGroup()
        
        -- Footer buttons
        local btn_h = S(40)
        imgui.SetCursorPos(imgui.ImVec2(S(20), h - btn_h - S(20)))
        if renderCustomButton(u8"Сгенерировать", w - S(40), btn_h, CURRENT_THEME.accent_primary, fa('bolt')) then
            local budget_val = tonumber(ffi.string(Buffers.gen_budget)) or 0
            if budget_val < 1000000 then
                addToastNotification("Минимальный бюджет: 1.000.000 $", "error")
            else
                App.show_gen_config_modal = false
                api_GenerateTopBuyConfig(budget_val, Buffers.gen_include_accs[0])
            end
        end
    end
    imgui.End()
    imgui.PopStyleColor(2)
    imgui.PopStyleVar(2)
end

function renderModDetailsWindow()
    local mod = ModsData.selected_mod
    if not mod then return end

    local w = imgui.GetContentRegionAvail().x
    local h = imgui.GetContentRegionAvail().y
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    
    -- === ХЕДЕР (Верхняя шапка) ===
    local header_h = S(60)
    
    -- Рисуем фон хедера
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 5)
    draw_list:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
    
    -- 1. Кнопка НАЗАД (Слева)
    local btn_sz = S(36)
    local padding = S(15)
    local back_x = p.x + padding
    local center_y = p.y + (header_h - btn_sz) / 2
    
    imgui.SetCursorScreenPos(imgui.ImVec2(back_x, center_y))
    if imgui.InvisibleButton("##mod_back_btn", imgui.ImVec2(btn_sz, btn_sz)) then
        ModsData.selected_mod = nil
    end
    
    local back_hovered = imgui.IsItemHovered()
    local back_bg = back_hovered and imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary) or 0
    
    if back_bg ~= 0 then
        draw_list:AddRectFilled(imgui.ImVec2(back_x, center_y), imgui.ImVec2(back_x + btn_sz, center_y + btn_sz), back_bg, S(8))
    end
    
    if font_fa then
        imgui.PushFont(font_fa)
        local icon = fa('arrow_left')
        local isz = GetStaticTextSize(icon)
        local arrow_col = back_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary
        draw_list:AddText(imgui.ImVec2(back_x + (btn_sz - isz.x)/2, center_y + (btn_sz - isz.y)/2), 
            imgui.ColorConvertFloat4ToU32(arrow_col), icon)
        imgui.PopFont()
    end

    -- 2. Кнопка УСТАНОВИТЬ (Справа)
    local install_w = mod.is_vip and not isVerifiedVip() and S(200) or S(140)
    local install_x = p.x + w - install_w - padding
    
    imgui.SetCursorScreenPos(imgui.ImVec2(install_x, center_y))
    if imgui.InvisibleButton("##mod_install_header", imgui.ImVec2(install_w, btn_sz)) then
        if mod.is_vip and not isVerifiedVip() then
            addToastNotification("Для скачивания нужен VIP статус!", "error", 4.0)
            -- Предлагаем купить
            os.execute('explorer "https://t.me/rdnMarket_bot"')
        else
            if mod.files and #mod.files > 0 then
                api_IncrementModDownloads(mod.id)
                lua_thread.create(function()
                    installModFiles(mod.files)
                end)
                ModsData.selected_mod = nil
            else
                addToastNotification("Ошибка: Файлы отсутствуют", "error")
            end
        end
    end
    
    local install_hovered = imgui.IsItemHovered()
    -- Если это VIP мод и у юзера нет випки, делаем кнопку золотой
    local btn_base_col = (mod.is_vip and not isVerifiedVip()) and imgui.ImVec4(0.85, 0.70, 0.20, 1.0) or CURRENT_THEME.accent_primary
    local btn_hover_col = (mod.is_vip and not isVerifiedVip()) and imgui.ImVec4(0.95, 0.80, 0.30, 1.0) or CURRENT_THEME.accent_hover
    
    local install_bg_col = install_hovered and btn_hover_col or btn_base_col
    
    draw_list:AddRectFilled(imgui.ImVec2(install_x, center_y), imgui.ImVec2(install_x + install_w, center_y + btn_sz), 
        imgui.ColorConvertFloat4ToU32(install_bg_col), S(8))
        
    local btn_label = (mod.is_vip and not isVerifiedVip()) and u8"Купить VIP" or u8"Установить"
    local btn_icon = (mod.is_vip and not isVerifiedVip()) and fa('gem') or fa('download')
    
    local install_hovered = imgui.IsItemHovered()
    local install_bg_col = install_hovered and CURRENT_THEME.accent_hover or CURRENT_THEME.accent_primary
    
    draw_list:AddRectFilled(imgui.ImVec2(install_x, center_y), imgui.ImVec2(install_x + install_w, center_y + btn_sz), 
        imgui.ColorConvertFloat4ToU32(install_bg_col), S(8))
        
    local btn_label = u8"Установить"
    local btn_icon = fa('download')
    
    if font_fa then
        imgui.PushFont(font_fa)
        local isz = GetStaticTextSize(btn_icon)
        imgui.PushFont(font_default)
        local tsz = GetStaticTextSize(btn_label)
        
        local content_w_btn = isz.x + S(8) + tsz.x
        local start_x = install_x + (install_w - content_w_btn) / 2
        local icon_y = center_y + (btn_sz - isz.y) / 2
        local text_y = center_y + (btn_sz - tsz.y) / 2
        
        imgui.PopFont() 
        draw_list:AddText(imgui.ImVec2(start_x, icon_y), 0xFFFFFFFF, btn_icon)
        imgui.PopFont()
        
        imgui.PushFont(font_default)
        draw_list:AddText(imgui.ImVec2(start_x + isz.x + S(8), text_y), 0xFFFFFFFF, btn_label)
        imgui.PopFont()
    end
    
    -- 3. ТЕКСТ ЗАГОЛОВКА
    local title_area_x = back_x + btn_sz + S(15)
    local title_area_w = install_x - title_area_x - S(15)
    
    local title_str = u8(mod.title or "Unknown Mod")
    imgui.PushFont(font_default)
    local title_sz = GetStaticTextSize(title_str)
    
    if title_sz.x > title_area_w then 
        title_str = title_str:sub(1, 25) .. "..." 
    end
    
    local title_draw_y = p.y + (header_h - title_sz.y) / 2
    if mod.desc and mod.desc ~= "" then title_draw_y = title_draw_y - S(8) end
    
    draw_list:AddText(imgui.ImVec2(title_area_x, title_draw_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), title_str)
    
    if mod.desc and mod.desc ~= "" then
        local safe_desc_short = (mod.desc or ""):gsub("\n", " "):sub(1, 60)
        if #safe_desc_short >= 60 then safe_desc_short = safe_desc_short .. "..." end
        
        imgui.SetWindowFontScale(0.85)
        draw_list:AddText(imgui.ImVec2(title_area_x, title_draw_y + title_sz.y + S(2)), 
            imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), u8(safe_desc_short))
        imgui.SetWindowFontScale(1.0)
    end
    imgui.PopFont()
    
    -- === ОСНОВНОЙ КОНТЕНТ (СКРОЛЛ) ===
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + header_h))
    
    -- [FIX] Важно: Фон ChildBg должен быть непрозрачным, чтобы перекрывать контент под ним при скролле (если бы он был)
    -- Но в данном случае мы просто отделяем зону скролла от хедера
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    if imgui.BeginChild("ModDetailsScroll", imgui.ImVec2(w, h - header_h), false) then
        local content_w = w - (padding * 2)
        
        imgui.SetCursorPos(imgui.ImVec2(padding, padding))
        
        -- == БЛОК ИНФОРМАЦИИ (Переписан на Child для исправления бага скролла) ==
        local info_bg_col = CURRENT_THEME.bg_secondary
        -- Добавляем прозрачность в стиль, чтобы использовать BeginChild
        local final_bg = imgui.ImVec4(info_bg_col.x, info_bg_col.y, info_bg_col.z, 0.4) 
        
        imgui.PushStyleColor(imgui.Col.ChildBg, final_bg)
        imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, S(8))
        
        -- Вычисляем высоту блока информации примерно
        local info_rows_count = 5 
        if mod.cmd and mod.cmd ~= "" then info_rows_count = 6 end
        local info_h = S(40) + (info_rows_count * S(24)) + S(10)
        
        if imgui.BeginChild("ModInfoBlock", imgui.ImVec2(content_w, info_h), true, imgui.WindowFlags.NoScrollbar) then
            -- Рамка вокруг
            local dl_info = imgui.GetWindowDrawList()
            local ip = imgui.GetWindowPos()
            local isz = imgui.GetWindowSize()
            dl_info:AddRect(ip, imgui.ImVec2(ip.x+isz.x, ip.y+isz.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8))
            
            imgui.SetCursorPos(imgui.ImVec2(S(10), S(10)))
            
            -- Заголовок блока
            if font_fa then imgui.PushFont(font_fa) end
            imgui.TextColored(CURRENT_THEME.accent_primary, fa('circle_info'))
            if font_fa then imgui.PopFont() end
            imgui.SameLine()
            imgui.TextColored(CURRENT_THEME.text_primary, u8"Информация о моде")
            
            imgui.Dummy(imgui.ImVec2(0, S(5)))
            
            imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(S(10), S(8)))
            
            local info_rows = {
                { u8"Автор", u8(mod.author or "Unknown"), CURRENT_THEME.text_primary },
            }
            
            -- [NEW] Счетчик скачиваний
            table.insert(info_rows, { u8"Скачиваний", formatNumber(mod.downloads or 0), CURRENT_THEME.accent_success })
            
            local file_info = "Unknown"
            if mod.files and #mod.files > 0 then
                if #mod.files > 1 then 
                    file_info = u8"Пак файлов ("..#mod.files..u8" шт.)"
                else 
                    file_info = u8(mod.files[1].name) 
                end
            end
            table.insert(info_rows, { u8"Файл", file_info, CURRENT_THEME.text_primary })
            
            local install_type = "MoonLoader"
            if mod.files and #mod.files == 1 then
                local f = mod.files[1]
                if f.folder == "root" then install_type = "Root (Папка игры)"
                elseif f.folder == "cleo" then install_type = "CLEO"
                elseif f.folder == "sampfuncs" then install_type = "SAMPFUNCS"
                end
            elseif mod.files and #mod.files > 1 then
                install_type = "Multi-Folder"
            end
            table.insert(info_rows, { u8"Тип", u8(install_type), CURRENT_THEME.text_hint })
            
            if mod.cmd and mod.cmd ~= "" then
                table.insert(info_rows, { u8"Активация", u8(mod.cmd), CURRENT_THEME.accent_warning })
            end
            
            for _, row in ipairs(info_rows) do
                local label = row[1]
                local value = row[2]
                local val_col = row[3]
                
                -- Выравниваем "Автор:", "Файл:" и т.д.
                imgui.TextColored(CURRENT_THEME.text_secondary, label .. ":")
                imgui.SameLine(S(120)) 
                imgui.TextColored(val_col, value)
            end
            
            imgui.PopStyleVar()
        end
        imgui.EndChild() -- Конец блока Info
        imgui.PopStyleVar() -- ChildRounding
        imgui.PopStyleColor() -- ChildBg
        
        imgui.Dummy(imgui.ImVec2(0, S(25)))
        
        -- == БЛОК ОПИСАНИЯ ==
        imgui.Separator()
        imgui.Dummy(imgui.ImVec2(0, S(10)))
        
        imgui.SetCursorPosX(padding)
        imgui.TextColored(CURRENT_THEME.accent_primary, u8"ОПИСАНИЕ")
        
        imgui.Dummy(imgui.ImVec2(0, S(5)))
        
        imgui.SetCursorPosX(padding)
        imgui.PushTextWrapPos(padding + content_w)
        imgui.TextWrapped(u8(mod.desc or "Описание отсутствует."))
        imgui.PopTextWrapPos()
        
        imgui.Dummy(imgui.ImVec2(0, S(30)))
        
    imgui.EndChild()
    end
    imgui.PopStyleColor()
end

function renderModsTab()
    local avail_w = imgui.GetContentRegionAvail().x
    local avail_h = imgui.GetContentRegionAvail().y
    
    -- Если выбран мод, показываем окно деталей
    if ModsData.selected_mod then
        renderModDetailsWindow()
        return
    end
    
    -- LOADING STATE
    if ModsData.is_loading then
        imgui.Dummy(imgui.ImVec2(0, (avail_h - S(40)) / 2))
        imgui.SetCursorPosX((avail_w - S(40)) / 2)
        if font_fa then
            imgui.PushFont(font_fa)
            imgui.TextColored(CURRENT_THEME.accent_primary, fa('spinner'))
            imgui.PopFont()
        else
            imgui.Text("Загрузка...")
        end
        return
    end
    
    -- EMPTY STATE
    if #ModsData.list == 0 then
        if not ModsData.tried_load then
            ModsData.tried_load = true
            api_FetchMods()
        end
        imgui.Dummy(imgui.ImVec2(0, (avail_h - S(120)) / 2))
        renderEmptyState(fa('puzzle_piece'), "Каталог пуст", 
            "В данный момент нет доступных модов", 
            "Обновить", function() api_FetchMods() end)
        return
    end
    
    -- === HEADER BAR ===
    local header_h = S(50)
    local pad = S(15)
    local draw_list = imgui.GetWindowDrawList()
    local header_p = imgui.GetCursorScreenPos()
    
    -- Фон шапки
    draw_list:AddRectFilled(header_p, imgui.ImVec2(header_p.x + avail_w, header_p.y + header_h), 
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
    
    -- Заголовок слева
    local text_y = header_p.y + (header_h - imgui.GetFontSize()) / 2
    imgui.SetCursorScreenPos(imgui.ImVec2(header_p.x + pad, text_y))
    imgui.TextColored(CURRENT_THEME.accent_primary, fa('puzzle_piece') .. u8" КАТАЛОГ МОДОВ")
    
    -- Кнопка обновления справа
    local btn_sz = S(32)
    local btn_x = header_p.x + avail_w - btn_sz - pad
    local btn_y = header_p.y + (header_h - btn_sz) / 2
    
    imgui.SetCursorScreenPos(imgui.ImVec2(btn_x, btn_y))
    if imgui.InvisibleButton("##refresh_mods_btn", imgui.ImVec2(btn_sz, btn_sz)) then
        api_FetchMods()
    end
    
    local refresh_hovered = imgui.IsItemHovered()
    if refresh_hovered then
        draw_list:AddCircleFilled(imgui.ImVec2(btn_x + btn_sz/2, btn_y + btn_sz/2), btn_sz/2 + S(2), 
            imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.08)))
    end
    
    if font_fa then
        imgui.PushFont(font_fa)
        local icon = fa('arrows_rotate')
        local isz = GetStaticTextSize(icon)
        draw_list:AddText(imgui.ImVec2(btn_x + (btn_sz - isz.x)/2, btn_y + (btn_sz - isz.y)/2),
            imgui.ColorConvertFloat4ToU32(refresh_hovered and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary), icon)
        imgui.PopFont()
    end
    
    -- Отступ от шапки
    imgui.SetCursorScreenPos(imgui.ImVec2(header_p.x, header_p.y + header_h))
    imgui.Dummy(imgui.ImVec2(0, S(5)))
    
    -- LIST
    local list_h = avail_h - header_h - S(5)
    
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
    renderSmoothScrollBox("ModsListScroll", imgui.ImVec2(avail_w, list_h), function()
        local item_pad = S(10)
        local gap = S(6)
        
        for i, mod in ipairs(ModsData.list) do
            local safe_filename = mod.filename
            if (not safe_filename or safe_filename == "") and mod.files and #mod.files > 0 then
                safe_filename = mod.files[1].name
            end
            if not safe_filename then safe_filename = "script.lua" end

            local ext = safe_filename:match("^.+(%.[^%.]+)$") or ".lua"
            local type_str = "LUA"
            local type_col = CURRENT_THEME.accent_primary 
            
            if mod.files and #mod.files > 1 then
                type_str = "PACK"
                type_col = imgui.ImVec4(0.8, 0.3, 0.8, 1.0) 
            elseif ext == ".asi" then
                type_str = "ASI"
                type_col = imgui.ImVec4(0.9, 0.4, 0.1, 1.0) 
            elseif ext == ".cs" then
                type_str = "CLEO"
                type_col = imgui.ImVec4(0.2, 0.7, 0.3, 1.0) 
            end

            local item_w = avail_w - (item_pad * 2) - S(5)
            local item_h = S(75) 
            local item_rounding = S(10)
            
            imgui.SetCursorPosX(item_pad)
            local item_p = imgui.GetCursorScreenPos()
            
            if imgui.InvisibleButton("mod_item_" .. i, imgui.ImVec2(item_w, item_h)) then
                ModsData.selected_mod = mod
            end
            
            local is_hovered = imgui.IsItemHovered()
            local draw_list = imgui.GetWindowDrawList()
            
            -- Фон
            local bg_col = CURRENT_THEME.bg_secondary
            if mod.is_vip then
                -- Премиальный темный золотой фон для VIP модов
                bg_col = imgui.ImVec4(0.15, 0.12, 0.05, 1.0)
            end
            
            if is_hovered then
                bg_col = imgui.ImVec4(bg_col.x + 0.05, bg_col.y + 0.05, bg_col.z + 0.05, 1.0)
            end
            
            draw_list:AddRectFilled(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), 
                imgui.ColorConvertFloat4ToU32(bg_col), item_rounding)
            
            local border_col = CURRENT_THEME.accent_primary
            if mod.is_vip then border_col = imgui.ImVec4(0.85, 0.70, 0.20, 1.0) end -- Золотая рамка
            
            if is_hovered or mod.is_vip then
                draw_list:AddRect(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), 
                    imgui.ColorConvertFloat4ToU32(border_col), item_rounding, 15, (is_hovered and S(2.0) or S(1.0)))
            end
            
            -- Цветная полоса слева
            draw_list:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + item_h), 
                imgui.ColorConvertFloat4ToU32(type_col), item_rounding, 5)
            
            -- Иконка (слева)
            local icon_size = S(45)
            local icon_offset = S(15)
            local icon_x = item_p.x + icon_offset
            local icon_y = item_p.y + (item_h - icon_size) / 2
            
            draw_list:AddRectFilled(imgui.ImVec2(icon_x, icon_y), imgui.ImVec2(icon_x + icon_size, icon_y + icon_size),
                imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary), S(8))
            
            if font_fa then
                imgui.PushFont(font_fa)
                local mod_icon = fa('code')
                if type_str == "PACK" then mod_icon = fa('box_archive')
                elseif ext == ".asi" then mod_icon = fa('microchip')
                elseif ext == ".cs" then mod_icon = fa('scroll') end
                
                local icon_sz = GetStaticTextSize(mod_icon)
                draw_list:AddText(imgui.ImVec2(icon_x + (icon_size - icon_sz.x) / 2, icon_y + (icon_size - icon_sz.y) / 2),
                    imgui.ColorConvertFloat4ToU32(type_col), mod_icon)
                imgui.PopFont()
            end
            
            -- === ТЕКСТОВАЯ ЧАСТЬ (ОБНОВЛЕННАЯ ВЕРСТКА) ===
            local text_start_x = icon_x + icon_size + S(14)
            local dl_btn_w = S(40) -- Ширина кнопки скачивания справа
            local max_text_w = item_w - (text_start_x - item_p.x) - dl_btn_w - S(20)
            
            -- СТРОКА 1: Название + Автор
            local line1_y = item_p.y + S(12)
            local title_str = u8(mod.title or "Unknown Mod")
            
            if mod.is_vip and font_fa then
                imgui.PushFont(font_fa)
                local crown = fa('crown')
                local c_sz = GetStaticTextSize(crown)
                draw_list:AddText(imgui.ImVec2(text_start_x, line1_y + S(1)), 0xFF40C0FF, crown) -- Золотой цвет ABGR
                imgui.PopFont()
                text_start_x = text_start_x + c_sz.x + S(6)
                max_text_w = max_text_w - c_sz.x - S(6)
            end
            
            imgui.PushFont(font_default)
            local title_sz = GetStaticTextSize(title_str)
            
            -- Если название слишком длинное, обрезаем
            if title_sz.x > max_text_w then 
                 title_str = title_str:sub(1, 30).."..." 
                 title_sz = GetStaticTextSize(title_str)
            end
            
            draw_list:AddText(imgui.ImVec2(text_start_x, line1_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), title_str)
            
            -- Автор (серым, справа от названия)
            if mod.author and mod.author ~= "" and mod.author ~= "Unknown" then
                 local auth_str = u8(" by " .. mod.author)
                 imgui.SetWindowFontScale(0.85)
                 draw_list:AddText(imgui.ImVec2(text_start_x + title_sz.x + S(5), line1_y + S(2)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), auth_str)
                 imgui.SetWindowFontScale(1.0)
            end
            imgui.PopFont()
            
            -- СТРОКА 2: Бейджи (Тип + Скачивания)
            local line2_y = line1_y + title_sz.y + S(6)
            local badge_h = S(20)
            local current_badge_x = text_start_x
            
            -- 1. Бейдж ТИПА
            imgui.PushFont(font_default)
            imgui.SetWindowFontScale(0.8)
            local type_sz = GetStaticTextSize(type_str)
            local type_badge_w = type_sz.x + S(12)
            
            -- Фон бейджа
            draw_list:AddRectFilled(
                imgui.ImVec2(current_badge_x, line2_y), 
                imgui.ImVec2(current_badge_x + type_badge_w, line2_y + badge_h), 
                imgui.ColorConvertFloat4ToU32(imgui.ImVec4(type_col.x, type_col.y, type_col.z, 0.15)), 
                S(4)
            )
            -- Текст бейджа
            draw_list:AddText(
                imgui.ImVec2(current_badge_x + S(6), line2_y + (badge_h - type_sz.y)/2), 
                imgui.ColorConvertFloat4ToU32(type_col), 
                type_str
            )
            current_badge_x = current_badge_x + type_badge_w + S(6)
            
            -- 2. Бейдж СКАЧИВАНИЙ
            if font_fa then
                local dl_str = formatNumber(mod.downloads or 0)
                local dl_icon = fa('download')
                
                imgui.PushFont(font_fa)
                local dli_sz = GetStaticTextSize(dl_icon)
                imgui.PopFont() -- Вернуть default для текста
                
                local dlt_sz = GetStaticTextSize(dl_str)
                local dl_badge_w = dli_sz.x + dlt_sz.x + S(14)
                
                -- Фон бейджа (серый)
                draw_list:AddRectFilled(
                    imgui.ImVec2(current_badge_x, line2_y), 
                    imgui.ImVec2(current_badge_x + dl_badge_w, line2_y + badge_h), 
                    imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.05)), 
                    S(4)
                )
                
                -- Иконка
                imgui.PushFont(font_fa)
                draw_list:AddText(
                    imgui.ImVec2(current_badge_x + S(6), line2_y + (badge_h - dli_sz.y)/2), 
                    imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), 
                    dl_icon
                )
                imgui.PopFont()
                
                -- Число
                draw_list:AddText(
                    imgui.ImVec2(current_badge_x + S(6) + dli_sz.x + S(4), line2_y + (badge_h - dlt_sz.y)/2), 
                    imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), 
                    dl_str
                )
            end
            
            imgui.SetWindowFontScale(1.0)
            imgui.PopFont()
            
            -- Кнопка скачивания (Справа, для красоты)
            local dl_x = item_p.x + item_w - dl_btn_w - S(15)
            local dl_y = item_p.y + (item_h - dl_btn_w) / 2
            
            if is_hovered then
                draw_list:AddRectFilled(imgui.ImVec2(dl_x, dl_y), imgui.ImVec2(dl_x + dl_btn_w, dl_y + dl_btn_w),
                    imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8))
                if font_fa then
                    imgui.PushFont(font_fa)
                    local dl_icon = fa('chevron_right')
                    local dl_sz = GetStaticTextSize(dl_icon)
                    draw_list:AddText(imgui.ImVec2(dl_x + (dl_btn_w - dl_sz.x)/2, dl_y + (dl_btn_w - dl_sz.y)/2),
                        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), dl_icon)
                    imgui.PopFont()
                end
            end
            
            imgui.SetCursorPosY(item_p.y + item_h + gap - imgui.GetWindowPos().y)
        end
        
        imgui.Dummy(imgui.ImVec2(0, S(5)))
    end)
    imgui.PopStyleColor()
end

function renderShareResultModal()
    if not ShareState.modal_active then return end

    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local w, h = S(350), S(220)
    
    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(w, h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(20)))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 10)
    
    if imgui.Begin("##ShareResult", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize) then
        
        local icon_sz = S(40)
        local center_x = w / 2
        
        centerText(u8"Конфиг опубликован!")
        imgui.Dummy(imgui.ImVec2(0, S(10)))
        
        local code = ShareState.generated_code or "ERROR"
        
        imgui.PushStyleColor(imgui.Col.Button, CURRENT_THEME.bg_tertiary)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, CURRENT_THEME.bg_tertiary)
        imgui.PushStyleColor(imgui.Col.ButtonActive, CURRENT_THEME.bg_tertiary)
        imgui.Button(code, imgui.ImVec2(w - S(40), S(40)))
        imgui.PopStyleColor(3)
        
        if imgui.IsItemHovered() then
            imgui.SetTooltip(u8"Нажмите, чтобы скопировать снова")
        end
        if imgui.IsItemClicked() then
            setClipboardText(code)
            addToastNotification("Скопировано!", "success")
        end

        imgui.Dummy(imgui.ImVec2(0, S(20)))
        
        if imgui.Button(u8"Закрыть", imgui.ImVec2(-1, S(35))) then
            ShareState.modal_active = false
        end
    end
    imgui.End()
    imgui.PopStyleVar(2)
end

function saveSellConfigs()
    saveSellConfigState()
end

function createSellConfig(name)
    local new_config = { 
        name = name or "Новый конфиг", 
        items = {} 
    }
    
    local safe_name = tostring(new_config.name):gsub("[^%w%s%-_]", ""):gsub("%s+", "_")
    if safe_name == "" then safe_name = "config_" .. os.time() end
    new_config._filename = safe_name .. ".json"

    saveSingleConfig(PATHS.PROFILES_SELL, new_config)
    table.insert(Data.sell_configs, new_config)
    
    return #Data.sell_configs
end

function deleteSellConfig(index)
    if index < 1 or index > #Data.sell_configs then return end
    local config = Data.sell_configs[index]
    deleteConfigFile(PATHS.PROFILES_SELL, config._filename)
    table.remove(Data.sell_configs, index)
    
    -- [КРИТИЧЕСКОЕ ИСПРАВЛЕНИЕ] Аналогичная защита от стирания конфигов
    if Data.active_sell_config == index then
        Data.active_sell_config = nil
        if #Data.sell_configs == 0 then
            createSellConfig("Основная")
        end
        selectSellConfig(1)
    elseif Data.active_sell_config > index then
        Data.active_sell_config = Data.active_sell_config - 1
    end
    
    addToastNotification("Конфиг удален", "success", 2.0)
end

function renameSellConfig(index, new_name)
    if index < 1 or index > #Data.sell_configs then return end
    if new_name and new_name ~= "" then
        local config = Data.sell_configs[index]
        local old_filename = config._filename
        
        config.name = new_name
        config._filename = nil 
        
        local success = saveSingleConfig(PATHS.PROFILES_SELL, config)
        
        if success and old_filename and old_filename ~= config._filename then
            deleteConfigFile(PATHS.PROFILES_SELL, old_filename)
        end
        
        addToastNotification("Конфиг переименован", "success", 2.0)
    end
end

function selectSellConfig(index)
    if index < 1 or index > #Data.sell_configs then return end
    
    -- 1. Сохраняем состояние ТЕКУЩЕГО (старого) конфига
    if Data.active_sell_config and Data.sell_configs[Data.active_sell_config] then
        saveSellConfigState()
    end

    -- 2. Переключаемся
    Data.active_sell_config = index
    Data.sell_list = {}
    
    -- 3. Загружаем новый список (Deep Copy)
    for _, item in ipairs(Data.sell_configs[index].items) do
        local item_copy = {}
        for k,v in pairs(item) do item_copy[k] = v end
        table.insert(Data.sell_list, item_copy)
    end
    
    saveListsConfig()
    addToastNotification("Загружен конфиг: " .. Data.sell_configs[index].name, "success")
end

