                    App.sell_config_sort.asc = true
                end
            end
            
            local is_hovered = imgui.IsItemHovered()
            
            local bg_col
            local text_col
            local border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light)
            
            if is_active then
                bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.2))
                text_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
                border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
            else
                bg_col = imgui.ColorConvertFloat4ToU32(is_hovered and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary)
                text_col = imgui.ColorConvertFloat4ToU32(is_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary)
            end
            
            draw_list:AddRectFilled(pos, imgui.ImVec2(pos.x + btn_w, pos.y + btn_h), bg_col, S(6))
            draw_list:AddRect(pos, imgui.ImVec2(pos.x + btn_w, pos.y + btn_h), border_col, S(6))
            
            local label_sz = GetStaticTextSize(label)
            local icon_w = 0
            local sort_icon = ""
            if is_active and font_fa then
                sort_icon = App.sell_config_sort.asc and fa('arrow_down_a_z') or fa('arrow_up_a_z') 
                if mode_idx > 0 then sort_icon = App.sell_config_sort.asc and fa('arrow_down_1_9') or fa('arrow_up_1_9') end
                imgui.PushFont(font_fa)
                icon_w = GetStaticTextSize(sort_icon).x + S(6)
                imgui.PopFont()
            elseif icon and font_fa then
                 sort_icon = icon
                 imgui.PushFont(font_fa)
                 icon_w = GetStaticTextSize(sort_icon).x + S(6)
                 imgui.PopFont()
            end
            
            local content_w = label_sz.x + icon_w
            local start_x = pos.x + (btn_w - content_w) / 2
            local center_y = pos.y + btn_h / 2
            
            if sort_icon ~= "" and font_fa then
                imgui.PushFont(font_fa)
                draw_list:AddText(imgui.ImVec2(start_x, center_y - GetStaticTextSize(sort_icon).y/2), text_col, sort_icon)
                imgui.PopFont()
            end
            
            draw_list:AddText(imgui.ImVec2(start_x + icon_w, center_y - label_sz.y/2), text_col, label)
        end

        imgui.SetCursorPos(imgui.ImVec2(margin_x, header_h + (sort_bar_h - btn_h)/2))
        
        renderCustomSortButton(u8"Имя", fa('font'), 0)
        imgui.SameLine(0, gap)
        renderCustomSortButton(u8"Кол-во", fa('list_ol'), 1)
        imgui.SameLine(0, gap)
        renderCustomSortButton(u8"Цена", fa('coins'), 2)
        
        imgui.SetCursorPos(imgui.ImVec2(0, header_h + sort_bar_h))
        imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(0, S(6)))
        imgui.BeginChild("##SellConfigList", imgui.ImVec2(win_w, content_h), false)
        imgui.Dummy(imgui.ImVec2(0, S(6)))

        local item_w = win_w - margin_x*2 - S(5)
        local item_h = S(50)

        if not App.sell_cfg_cache then App.sell_cfg_cache = { time = 0, list = {} } end
        
        if os.clock() - App.sell_cfg_cache.time > 0.5 then
            local display_list = {}
            for i, v in ipairs(Data.sell_configs) do
                local total_price = 0
                if App.sell_config_sort.mode == 2 then
                    for _, item in ipairs(v.items or {}) do
                        total_price = total_price + (tonumber(item.price) or 0) * (tonumber(item.amount) or 1)
                    end
                end
                table.insert(display_list, { 
                    real_idx = i, 
                    data = v, 
                    count = #(v.items or {}),
                    price = total_price,
                    name_l = v.name:lower() 
                })
            end

            table.sort(display_list, function(a, b)
                local val_a, val_b
                
                if App.sell_config_sort.mode == 0 then 
                    val_a, val_b = a.name_l, b.name_l
                elseif App.sell_config_sort.mode == 1 then 
                    val_a, val_b = a.count, b.count
                elseif App.sell_config_sort.mode == 2 then 
                    val_a, val_b = a.price, b.price
                end
                
                if val_a == val_b then return a.real_idx < b.real_idx end
                if App.sell_config_sort.asc then return val_a < val_b else return val_a > val_b end
            end)
            
            App.sell_cfg_cache.list = display_list
            App.sell_cfg_cache.time = os.clock()
        end

        local display_list = App.sell_cfg_cache.list
        -- Удалите старый table.sort(display_list, function(a, b) ... end), мы вшили его в кэш!
        for _, entry in ipairs(display_list) do
            local i = entry.real_idx
            local config = entry.data
            local is_active = (Data.active_sell_config == i)
            local is_renaming = (App.rename_sell_config_idx == i)

            imgui.SetCursorPosX(margin_x)
            local item_p = imgui.GetCursorScreenPos()
            local dl = imgui.GetWindowDrawList()

            local bg = is_active and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary
            dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(bg), S(8))
            if is_active then dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), S(8), 5) end

            imgui.BeginGroup()

            if is_renaming then
                local btn_sz = S(28)
                local input_w = item_w - btn_sz*2 - S(25)
                imgui.SetCursorPosY(imgui.GetCursorPosY() + (item_h - S(32))/2)
                
                renderModernInput("##ren_sell_"..i, Buffers.new_sell_config_name, input_w, "Имя...")
                
                imgui.SameLine()
                local save_pos = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##sv_sell_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                    local name = u8:decode(ffi.string(Buffers.new_sell_config_name))
                    if name ~= "" then renameSellConfig(i,name) end
                    App.rename_sell_config_idx = nil
                end
                if font_fa then
                    imgui.PushFont(font_fa)
                    local col = imgui.IsItemHovered() and CURRENT_THEME.accent_success or CURRENT_THEME.text_hint
                    dl:AddText(imgui.ImVec2(save_pos.x + S(6), save_pos.y + S(6)), imgui.ColorConvertFloat4ToU32(col), fa('check'))
                    imgui.PopFont()
                end

                imgui.SameLine()
                local cancel_pos = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##cn_sell_"..i, imgui.ImVec2(btn_sz, btn_sz)) then App.rename_sell_config_idx = nil end
                if font_fa then
                    imgui.PushFont(font_fa)
                    local col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
                    dl:AddText(imgui.ImVec2(cancel_pos.x + S(6), cancel_pos.y + S(6)), imgui.ColorConvertFloat4ToU32(col), fa('xmark'))
                    imgui.PopFont()
                end
            else
                local buttons_zone = S(90)
                if imgui.InvisibleButton("##sel_sell_"..i, imgui.ImVec2(item_w - buttons_zone, item_h)) then selectSellConfig(i) end

                local cy = item_p.y + item_h/2
                local icon_x = item_p.x + S(20)
                if font_fa then
                    imgui.PushFont(font_fa)
                    dl:AddText(imgui.ImVec2(icon_x, cy - S(7)), imgui.ColorConvertFloat4ToU32(is_active and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary), is_active and fa('folder_open') or fa('folder'))
                    imgui.PopFont()
                end

                local txt_x = icon_x + S(30)
                dl:AddText(imgui.ImVec2(txt_x, cy - S(10)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8(config.name))
                
                -- [CLOUD] Отрисовка статуса синхронизации
                if is_active and Data.settings.telegram_token ~= "" and font_fa then
                    local name_w = GetStaticTextSize(u8(config.name)).x
                    local cloud_x = txt_x + name_w + S(10)
                    
                    local cloud_icon = fa('cloud')
                    local cloud_col = CURRENT_THEME.text_secondary
                    
                    if CloudSync.status == "synced" then 
                        cloud_col = CURRENT_THEME.accent_success
                    elseif CloudSync.status == "syncing" then 
                        cloud_icon = fa('arrow_up_from_bracket')
                        cloud_col = CURRENT_THEME.accent_warning
                    elseif CloudSync.status == "error" then 
                        cloud_icon = fa('triangle_exclamation')
                        cloud_col = CURRENT_THEME.accent_danger
                    end
                    
                    imgui.PushFont(font_fa)
                    dl:AddText(imgui.ImVec2(cloud_x, cy - S(8)), imgui.ColorConvertFloat4ToU32(cloud_col), cloud_icon)
                    imgui.PopFont()
                    
                    -- Хитбокс для тултипа облака
                    if imgui.IsMouseHoveringRect(imgui.ImVec2(cloud_x, cy - S(8)), imgui.ImVec2(cloud_x + S(15), cy + S(8))) then
                        if CloudSync.status == "synced" then imgui.SetTooltip(u8"Синхронизировано с облаком")
                        elseif CloudSync.status == "syncing" then imgui.SetTooltip(u8"Выгрузка в облако...")
                        else imgui.SetTooltip(u8"Ошибка синхронизации") end
                    end
                end
                
                local info_text = tostring(#(config.items or {}))..u8(" шт.")
                if entry.price > 0 then
                    info_text = info_text .. " | " .. formatMoney(entry.price) .. " $"
                end
                
                dl:AddText(imgui.ImVec2(txt_x, cy + S(5)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), info_text)

                local btn_sz = S(28)
                local right = item_p.x + item_w - S(10)
                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz, cy - btn_sz/2))
                if imgui.InvisibleButton("##del_sell_"..i, imgui.ImVec2(btn_sz, btn_sz)) then deleteSellConfig(i) end

                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz*2 - S(5), cy - btn_sz/2))
                if imgui.InvisibleButton("##ren_sell_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                    App.rename_sell_config_idx = i
                    imgui.StrCopy(Buffers.new_sell_config_name, u8(config.name))
                end

                if font_fa then
                    imgui.PushFont(font_fa)
                    local iy = cy - S(7)
                    dl:AddText(imgui.ImVec2(right - btn_sz + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('trash'))
                    dl:AddText(imgui.ImVec2(right - btn_sz*2 - S(5) + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('pen'))
                    imgui.PopFont()
                end
            end

            imgui.EndGroup()
        end

        imgui.EndChild()
        imgui.PopStyleVar()

        imgui.SetCursorPos(imgui.ImVec2(0, h - footer_h))
        local fp = imgui.GetCursorScreenPos()
        draw_list:AddRectFilled(fp, imgui.ImVec2(fp.x + win_w, fp.y + footer_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(10), 10)
        draw_list:AddLine(fp, imgui.ImVec2(fp.x + win_w, fp.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1)

        imgui.SetCursorPos(imgui.ImVec2(S(15), h - footer_h + S(25)))
        renderModernInput("##new_sell_name", Buffers.new_sell_config_name, win_w - S(140), "Новое название...")
        imgui.SameLine()
        if renderCustomButton(u8"Создать", S(100), S(32), CURRENT_THEME.accent_primary) then
            local name = u8:decode(ffi.string(Buffers.new_sell_config_name))
            if name ~= "" then
                createSellConfig(name)
                imgui.StrCopy(Buffers.new_sell_config_name, "")
            end
        end
    end

    imgui.End()
    imgui.PopStyleColor(2)
    imgui.PopStyleVar()
end

function renderConfigManagerWindow()
    if ShareState.modal_active then renderShareResultModal() end

    local sw, sh = getScreenResolution()
    local w, h = S(450), S(600)
    
    if not App.buy_config_sort then 
        App.buy_config_sort = { mode = 0, asc = true } 
    end

    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5,0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(w,h), imgui.Cond.Always)

    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0,0))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_secondary)

    if imgui.Begin("ConfigManager", nil,
        imgui.WindowFlags.NoTitleBar +
        imgui.WindowFlags.NoCollapse +
        imgui.WindowFlags.NoResize
    ) then
        local draw_list = imgui.GetWindowDrawList()
        local p = imgui.GetCursorScreenPos()
        local win_w = imgui.GetWindowWidth()

        local header_h = S(50)
        local footer_h = S(120)
        local sort_bar_h = S(45)
        local content_h = h - header_h - footer_h - sort_bar_h

        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + win_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(10),5)
        draw_list:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + win_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1)

        imgui.SetCursorPos(imgui.ImVec2(S(15), (header_h - S(20))/2))
        if font_fa then imgui.PushFont(font_fa) imgui.TextColored(CURRENT_THEME.accent_warning, fa('sliders')) imgui.PopFont() imgui.SameLine() end
        imgui.SetCursorPosY((header_h - imgui.GetFontSize())/2)
        imgui.TextColored(CURRENT_THEME.text_primary, u8"Управление конфигами (Скупка)")

        local btn_size = S(30)
        local btn_x = win_w - btn_size - S(10)
        imgui.SetCursorPos(imgui.ImVec2(btn_x, (header_h - btn_size)/2))
        if imgui.InvisibleButton("##close_cfg_mgr", imgui.ImVec2(btn_size, btn_size)) then
            App.show_config_manager = false
            App.rename_config_idx = nil
        end

        local close_center = imgui.ImVec2(p.x + btn_x + btn_size/2, p.y + (header_h - btn_size)/2 + btn_size/2)
        if imgui.IsItemHovered() then
            draw_list:AddCircleFilled(close_center, btn_size/2, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,0.3,0.3,0.2)))
        end
        if font_fa then
            imgui.PushFont(font_fa)
            local col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_secondary
            local sz = GetStaticTextSize(fa('xmark'))
            draw_list:AddText(imgui.ImVec2(close_center.x - sz.x/2, close_center.y - sz.y/2), imgui.ColorConvertFloat4ToU32(col), fa('xmark'))
            imgui.PopFont()
        end

        imgui.SetCursorPos(imgui.ImVec2(0, header_h))
        local margin_x = S(15)
        local sort_area_w = win_w - margin_x * 2
        local gap = S(6)
        local btn_w = (sort_area_w - gap*2) / 3
        local btn_h = S(30)
        
        local function renderCustomSortButton(label, icon, mode_idx)
            local is_active = (App.buy_config_sort.mode == mode_idx)
            local pos = imgui.GetCursorScreenPos()
            
            if imgui.InvisibleButton("##sort_buy_"..mode_idx, imgui.ImVec2(btn_w, btn_h)) then
                if is_active then
                    App.buy_config_sort.asc = not App.buy_config_sort.asc
                else
                    App.buy_config_sort.mode = mode_idx
                    App.buy_config_sort.asc = true
                end
            end
            
            local is_hovered = imgui.IsItemHovered()
            
            local bg_col
            local text_col
            local border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light)
            
            if is_active then
                bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.2))
                text_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
                border_col = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
            else
                bg_col = imgui.ColorConvertFloat4ToU32(is_hovered and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary)
                text_col = imgui.ColorConvertFloat4ToU32(is_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary)
            end
            
            draw_list:AddRectFilled(pos, imgui.ImVec2(pos.x + btn_w, pos.y + btn_h), bg_col, S(6))
            draw_list:AddRect(pos, imgui.ImVec2(pos.x + btn_w, pos.y + btn_h), border_col, S(6))
            
            local label_sz = GetStaticTextSize(label)
            local icon_w = 0
            local sort_icon = ""
            if is_active and font_fa then
                sort_icon = App.buy_config_sort.asc and fa('arrow_down_a_z') or fa('arrow_up_a_z')
                if mode_idx > 0 then sort_icon = App.buy_config_sort.asc and fa('arrow_down_1_9') or fa('arrow_up_1_9') end
                imgui.PushFont(font_fa)
                icon_w = GetStaticTextSize(sort_icon).x + S(6)
                imgui.PopFont()
            elseif icon and font_fa then
                 sort_icon = icon
                 imgui.PushFont(font_fa)
                 icon_w = GetStaticTextSize(sort_icon).x + S(6)
                 imgui.PopFont()
            end
            
            local content_w = label_sz.x + icon_w
            local start_x = pos.x + (btn_w - content_w) / 2
            local center_y = pos.y + btn_h / 2
            
            if sort_icon ~= "" and font_fa then
                imgui.PushFont(font_fa)
                draw_list:AddText(imgui.ImVec2(start_x, center_y - GetStaticTextSize(sort_icon).y/2), text_col, sort_icon)
                imgui.PopFont()
            end
            
            draw_list:AddText(imgui.ImVec2(start_x + icon_w, center_y - label_sz.y/2), text_col, label)
        end

        imgui.SetCursorPos(imgui.ImVec2(margin_x, header_h + (sort_bar_h - btn_h)/2))
        
        renderCustomSortButton(u8"Имя", fa('font'), 0)
        imgui.SameLine(0, gap)
        renderCustomSortButton(u8"Кол-во", fa('list_ol'), 1)
        imgui.SameLine(0, gap)
        renderCustomSortButton(u8"Цена", fa('coins'), 2)

        imgui.SetCursorPos(imgui.ImVec2(0, header_h + sort_bar_h))
        imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing, imgui.ImVec2(0, S(6)))
        imgui.BeginChild("##ConfigManagerList", imgui.ImVec2(win_w, content_h), false)
        imgui.Dummy(imgui.ImVec2(0, S(6)))

        local item_w = win_w - margin_x*2 - S(5)
        local item_h = S(50)

        if not App.buy_cfg_cache then App.buy_cfg_cache = { time = 0, list = {} } end
        
        if os.clock() - App.buy_cfg_cache.time > 0.5 then
            local display_list = {}
            for i, v in ipairs(Data.buy_configs) do
                local total_price = 0
                if App.buy_config_sort.mode == 2 then
                    for _, item in ipairs(v.items or {}) do
                        total_price = total_price + (tonumber(item.price) or 0) * (tonumber(item.amount) or 1)
                    end
                end
                table.insert(display_list, { 
                    real_idx = i, 
                    data = v, 
                    count = #(v.items or {}),
                    price = total_price,
                    name_l = v.name:lower()
                })
            end

            table.sort(display_list, function(a, b)
                local val_a, val_b
                if App.buy_config_sort.mode == 0 then val_a, val_b = a.name_l, b.name_l
                elseif App.buy_config_sort.mode == 1 then val_a, val_b = a.count, b.count
                elseif App.buy_config_sort.mode == 2 then val_a, val_b = a.price, b.price end
                
                if val_a == val_b then return a.real_idx < b.real_idx end
                if App.buy_config_sort.asc then return val_a < val_b else return val_a > val_b end
            end)
            
            App.buy_cfg_cache.list = display_list
            App.buy_cfg_cache.time = os.clock()
        end

        local display_list = App.buy_cfg_cache.list
        -- И здесь тоже убедитесь, что удалили старый table.sort(display_list, ...) ниже
        for _, entry in ipairs(display_list) do
            local i = entry.real_idx
            local config = entry.data
            local is_active = (Data.active_buy_config == i)
            local is_renaming = (App.rename_config_idx == i)

            imgui.SetCursorPosX(margin_x)
            local item_p = imgui.GetCursorScreenPos()
            local dl = imgui.GetWindowDrawList()

            local bg_col = is_active and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary
            dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
            if is_active then dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), S(8),5) end

            imgui.BeginGroup()

            if is_renaming then
                local btn_sz = S(28)
                local input_w = item_w - btn_sz*2 - S(25)
                imgui.SetCursorPosY(imgui.GetCursorPosY() + (item_h - S(32))/2)
                
                renderModernInput("##ren_inp_"..i, Buffers.new_config_name, input_w, "Имя...")
                
                imgui.SameLine()
                local save_pos = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##sv_rn_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                    local new_name = u8:decode(ffi.string(Buffers.new_config_name))
                    if new_name ~= "" then renameBuyConfig(i,new_name) end
                    App.rename_config_idx = nil
                end
                if font_fa then
                    imgui.PushFont(font_fa)
                    local col = imgui.IsItemHovered() and CURRENT_THEME.accent_success or CURRENT_THEME.text_hint
                    dl:AddText(imgui.ImVec2(save_pos.x + S(6), save_pos.y + S(6)), imgui.ColorConvertFloat4ToU32(col), fa('check'))
                    imgui.PopFont()
                end

                imgui.SameLine()
                local cancel_pos = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##cn_rn_"..i, imgui.ImVec2(btn_sz, btn_sz)) then App.rename_config_idx = nil end
                if font_fa then
                    imgui.PushFont(font_fa)
                    local col = imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
                    dl:AddText(imgui.ImVec2(cancel_pos.x + S(6), cancel_pos.y + S(6)), imgui.ColorConvertFloat4ToU32(col), fa('xmark'))
                    imgui.PopFont()
                end
            else
                local buttons_zone = S(100) 
                if imgui.InvisibleButton("##sel_cfg_"..i, imgui.ImVec2(item_w - buttons_zone, item_h)) then selectBuyConfig(i) end

                local cy = item_p.y + item_h/2
                local icon_x = item_p.x + S(20)

                if font_fa then
                    imgui.PushFont(font_fa)
                    dl:AddText(imgui.ImVec2(icon_x, cy - S(7)), imgui.ColorConvertFloat4ToU32(is_active and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary), is_active and fa('folder_open') or fa('folder'))
                    imgui.PopFont()
                end

                local txt_x = icon_x + S(30)
                dl:AddText(imgui.ImVec2(txt_x, cy - S(10)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8(config.name))
                
                -- [CLOUD] Отрисовка статуса синхронизации
                if is_active and Data.settings.telegram_token ~= "" and font_fa then
                    local name_w = GetStaticTextSize(u8(config.name)).x
                    local cloud_x = txt_x + name_w + S(10)
                    
                    local cloud_icon = fa('cloud')
                    local cloud_col = CURRENT_THEME.text_secondary
                    
                    if CloudSync.status == "synced" then 
                        cloud_col = CURRENT_THEME.accent_success
                    elseif CloudSync.status == "syncing" then 
                        cloud_icon = fa('arrow_up_from_bracket')
                        cloud_col = CURRENT_THEME.accent_warning
                    elseif CloudSync.status == "error" then 
                        cloud_icon = fa('triangle_exclamation')
                        cloud_col = CURRENT_THEME.accent_danger
                    end
                    
                    imgui.PushFont(font_fa)
                    dl:AddText(imgui.ImVec2(cloud_x, cy - S(8)), imgui.ColorConvertFloat4ToU32(cloud_col), cloud_icon)
                    imgui.PopFont()
                    
                    if imgui.IsMouseHoveringRect(imgui.ImVec2(cloud_x, cy - S(8)), imgui.ImVec2(cloud_x + S(15), cy + S(8))) then
                        if CloudSync.status == "synced" then imgui.SetTooltip(u8"Синхронизировано с облаком")
                        elseif CloudSync.status == "syncing" then imgui.SetTooltip(u8"Выгрузка в облако...")
                        else imgui.SetTooltip(u8"Ошибка синхронизации") end
                    end
                end
                
                local info_text = tostring(#(config.items or {}))..u8(" шт.")
                if entry.price > 0 then
                    info_text = info_text .. " | " .. formatMoney(entry.price) .. " $"
                end
                
                dl:AddText(imgui.ImVec2(txt_x, cy + S(5)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), info_text)

                local btn_sz = S(28)
                local right = item_p.x + item_w - S(10)

                -- Удалить
                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz, cy - btn_sz/2))
                if imgui.InvisibleButton("##del_"..i, imgui.ImVec2(btn_sz, btn_sz)) then deleteBuyConfig(i) end

                -- Переименовать
                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz*2 - S(5), cy - btn_sz/2))
                if imgui.InvisibleButton("##ren_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                    App.rename_config_idx = i
                    imgui.StrCopy(Buffers.new_config_name, u8(config.name))
                end

                -- [NEW] Дублировать
                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz*3 - S(10), cy - btn_sz/2))
                if imgui.InvisibleButton("##clone_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                    local new_idx = createBuyConfig(config.name .. " (Копия)")
                    -- Копируем товары
                    local cloned_items = {}
                    for _, it in ipairs(config.items) do
                        local copy = {}
                        for k, v in pairs(it) do copy[k] = v end
                        table.insert(cloned_items, copy)
                    end
                    Data.buy_configs[new_idx].items = cloned_items
                    saveSingleConfig(PATHS.PROFILES_BUY, Data.buy_configs[new_idx])
                    addToastNotification("Конфиг продублирован!", "success")
                end

                -- Поделиться (Share)
                imgui.SetCursorScreenPos(imgui.ImVec2(right - btn_sz*4 - S(15), cy - btn_sz/2))
                if imgui.InvisibleButton("##share_"..i, imgui.ImVec2(btn_sz, btn_sz)) then api_ShareConfig(i) end

                if font_fa then
                    imgui.PushFont(font_fa)
                    local iy = cy - S(7)
                    dl:AddText(imgui.ImVec2(right - btn_sz + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('trash'))
                    dl:AddText(imgui.ImVec2(right - btn_sz*2 - S(5) + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('pen'))
                    dl:AddText(imgui.ImVec2(right - btn_sz*3 - S(10) + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('copy')) -- Иконка дубликата
                    dl:AddText(imgui.ImVec2(right - btn_sz*4 - S(15) + S(6), iy), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), fa('share'))
                    imgui.PopFont()
                end
            end

            imgui.EndGroup()
        end

        imgui.EndChild()
        imgui.PopStyleVar()

        imgui.SetCursorPos(imgui.ImVec2(0, h - footer_h))
        local footer_p = imgui.GetCursorScreenPos()
        draw_list:AddRectFilled(footer_p, imgui.ImVec2(footer_p.x + win_w, footer_p.y + footer_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(10),10)
        draw_list:AddLine(footer_p, imgui.ImVec2(footer_p.x + win_w, footer_p.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light),1)

        local input_w = win_w - S(140)
        imgui.SetCursorPos(imgui.ImVec2(S(15), h - footer_h + S(15)))
        renderModernInput("##new_cfg_name", Buffers.new_config_name, input_w, "Новое название...")
        imgui.SameLine()
        if renderCustomButton(u8"Создать", S(100), S(32), CURRENT_THEME.accent_primary) then
            local name = u8:decode(ffi.string(Buffers.new_config_name))
            if name ~= "" then
                createBuyConfig(name)
                imgui.StrCopy(Buffers.new_config_name, "")
            end
        end

        imgui.SetCursorPos(imgui.ImVec2(S(15), h - footer_h + S(60)))
        renderModernInput("##import_code", Buffers.import_code, input_w, "Код для импорта...")
        imgui.SameLine()
        if renderCustomButton(u8"Импорт", S(100), S(32), CURRENT_THEME.accent_secondary) then api_ImportConfig() end
    end

    imgui.End()
    imgui.PopStyleColor(2)
    imgui.PopStyleVar()
end

function pushComboStyles()
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(S(10), S(8)))
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, imgui.ImVec4(CURRENT_THEME.bg_tertiary.x * 1.1, CURRENT_THEME.bg_tertiary.y * 1.1, CURRENT_THEME.bg_tertiary.z * 1.1, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive, imgui.ImVec4(CURRENT_THEME.bg_tertiary.x * 1.2, CURRENT_THEME.bg_tertiary.y * 1.2, CURRENT_THEME.bg_tertiary.z * 1.2, 1.0))
    imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.Header, imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.3))
    imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.5))
    imgui.PushStyleColor(imgui.Col.HeaderActive, imgui.ImVec4(CURRENT_THEME.accent_primary.x, CURRENT_THEME.accent_primary.y, CURRENT_THEME.accent_primary.z, 0.8))
    imgui.PushStyleColor(imgui.Col.Text, CURRENT_THEME.text_primary)
end

function popComboStyles()
    imgui.PopStyleColor(8) 
    imgui.PopStyleVar()
end


function applyThemeTextColors()
    imgui.PushStyleColor(imgui.Col.Text, CURRENT_THEME.text_primary)
    imgui.PushStyleColor(imgui.Col.TextDisabled, CURRENT_THEME.text_hint)
    imgui.PushStyleColor(imgui.Col.FrameBg, CURRENT_THEME.bg_tertiary)
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, imgui.ImVec4(CURRENT_THEME.bg_tertiary.x * 1.1, CURRENT_THEME.bg_tertiary.y * 1.1, CURRENT_THEME.bg_tertiary.z * 1.1, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive, imgui.ImVec4(CURRENT_THEME.bg_tertiary.x * 1.2, CURRENT_THEME.bg_tertiary.y * 1.2, CURRENT_THEME.bg_tertiary.z * 1.2, 1.0))
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
end

function revertThemeTextColors()
    imgui.PopStyleColor(6)
end

function renderAAASection(icon, name)
    imgui.Spacing()
    imgui.Spacing()
    
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    local w = imgui.GetContentRegionAvail().x
    
    
    if font_fa then imgui.PushFont(font_fa) end
    imgui.TextColored(CURRENT_THEME.accent_primary, icon)
    if font_fa then imgui.PopFont() end
    
    imgui.SameLine(nil, S(10))
    imgui.PushStyleColor(imgui.Col.Text, CURRENT_THEME.text_primary)
    imgui.Text(name:upper()) 
    imgui.PopStyleColor()
    
    
    local line_y = imgui.GetCursorScreenPos().y - S(5)
    draw_list:AddRectFilledMultiColor(
        imgui.ImVec2(p.x, line_y),
        imgui.ImVec2(p.x + w, line_y + S(2)),
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), 
        imgui.ColorConvertFloat4ToU32(lerpColor(CURRENT_THEME.accent_primary, CURRENT_THEME.bg_main, 0.5)), 
        imgui.ColorConvertFloat4ToU32(lerpColor(CURRENT_THEME.accent_primary, CURRENT_THEME.bg_main, 0.5)),
        imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary)
    )
    
    imgui.Spacing()
end

function renderConfigSelectorModal()
    local sw, sh = getScreenResolution()
    local w, h = S(480), S(580)
    
    if not App.config_selector_mode then App.config_selector_mode = "buy" end
    local is_sell_mode = (App.config_selector_mode == "sell")
    
    local target_configs = is_sell_mode and Data.sell_configs or Data.buy_configs

    imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(w, h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_secondary)
    
    if imgui.Begin("ConfigSelector", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse) then
        local p = imgui.GetCursorScreenPos()
        local draw_list = imgui.GetWindowDrawList()
        local win_w = imgui.GetContentRegionAvail().x
        
        local header_h = S(50)
        
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + win_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 5)
        draw_list:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + win_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1.0)
        
        local title_icon = fa('file_import')
        local title_text = u8"Копирование товаров"
        
        imgui.SetCursorPos(imgui.ImVec2(S(20), (header_h - imgui.GetFontSize()) / 2))
        if font_fa then 
            imgui.PushFont(font_fa)
            imgui.TextColored(CURRENT_THEME.accent_primary, title_icon)
            imgui.PopFont()
            imgui.SameLine()
        end
        imgui.TextColored(CURRENT_THEME.text_primary, title_text)
        
        local close_sz = S(30)
        local close_x = win_w - close_sz - S(10)
        local close_y = (header_h - close_sz) / 2
        
        imgui.SetCursorPos(imgui.ImVec2(close_x, close_y))
        if imgui.InvisibleButton("##close_modal", imgui.ImVec2(close_sz, close_sz)) then
            App.show_config_selector = false
            imgui.StrCopy(Buffers.new_config_name, "")
        end
        
        local is_close_hovered = imgui.IsItemHovered()
        if font_fa then
            local icon_center = imgui.ImVec2(p.x + close_x + close_sz/2, p.y + close_y + close_sz/2)
            if is_close_hovered then
                draw_list:AddCircleFilled(icon_center, close_sz/2, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 0.3, 0.3, 0.2)))
            end
            
            imgui.PushFont(font_fa)
            local x_icon = fa('xmark')
            local x_sz = GetStaticTextSize(x_icon)
            local x_col = is_close_hovered and CURRENT_THEME.accent_danger or CURRENT_THEME.text_hint
            draw_list:AddText(imgui.ImVec2(icon_center.x - x_sz.x/2, icon_center.y - x_sz.y/2), imgui.ColorConvertFloat4ToU32(x_col), x_icon)
            imgui.PopFont()
        end

        imgui.SetCursorPos(imgui.ImVec2(0, header_h))
        local tabs_h = S(40)
        local tab_w = win_w / 2
        
        imgui.SetCursorPos(imgui.ImVec2(0, header_h))
        if imgui.InvisibleButton("##tab_sell", imgui.ImVec2(tab_w, tabs_h)) then
            App.config_selector_mode = "sell"
            Buffers.config_selected[0] = 0
        end
        local sell_active = App.config_selector_mode == "sell"
        local sell_col = sell_active and CURRENT_THEME.accent_success or CURRENT_THEME.text_secondary
        local sell_bg = sell_active and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_main
        draw_list:AddRectFilled(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + tab_w, p.y + header_h + tabs_h), imgui.ColorConvertFloat4ToU32(sell_bg))
        local sell_txt = u8"В конфиги Продажи"
        local s_sz = GetStaticTextSize(sell_txt)
        draw_list:AddText(imgui.ImVec2(p.x + (tab_w - s_sz.x)/2, p.y + header_h + (tabs_h - s_sz.y)/2), imgui.ColorConvertFloat4ToU32(sell_col), sell_txt)
        if sell_active then
            draw_list:AddRectFilled(imgui.ImVec2(p.x, p.y + header_h + tabs_h - S(2)), imgui.ImVec2(p.x + tab_w, p.y + header_h + tabs_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success))
        end

        imgui.SetCursorPos(imgui.ImVec2(tab_w, header_h))
        if imgui.InvisibleButton("##tab_buy", imgui.ImVec2(tab_w, tabs_h)) then
            App.config_selector_mode = "buy"
            Buffers.config_selected[0] = 0
        end
        local buy_active = App.config_selector_mode == "buy"
        local buy_col = buy_active and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
        local buy_bg = buy_active and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_main
        draw_list:AddRectFilled(imgui.ImVec2(p.x + tab_w, p.y + header_h), imgui.ImVec2(p.x + win_w, p.y + header_h + tabs_h), imgui.ColorConvertFloat4ToU32(buy_bg))
        local buy_txt = u8"В конфиги Скупки"
        local b_sz = GetStaticTextSize(buy_txt)
        draw_list:AddText(imgui.ImVec2(p.x + tab_w + (tab_w - b_sz.x)/2, p.y + header_h + (tabs_h - b_sz.y)/2), imgui.ColorConvertFloat4ToU32(buy_col), buy_txt)
        if buy_active then
            draw_list:AddRectFilled(imgui.ImVec2(p.x + tab_w, p.y + header_h + tabs_h - S(2)), imgui.ImVec2(p.x + win_w, p.y + header_h + tabs_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary))
        end

        local footer_h = S(140)
        local list_h = h - header_h - tabs_h - footer_h
        
        imgui.SetCursorPos(imgui.ImVec2(0, header_h + tabs_h))
        
        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
        
        renderSmoothScrollBox("SelectorList", imgui.ImVec2(win_w, list_h), function()
            imgui.Dummy(imgui.ImVec2(0, S(10)))
            
            local item_h = S(50)
            local margin_x = S(15)
            local item_w = win_w - (margin_x * 2) - S(5) 
            
            for i, config in ipairs(target_configs) do
                local is_selected = (Buffers.config_selected[0] == i - 1)
                
                imgui.SetCursorPosX(margin_x)
                local item_p = imgui.GetCursorScreenPos()
                
                local bg_col = CURRENT_THEME.bg_tertiary
                local border_col = CURRENT_THEME.border_light
                local border_thick = S(1)
                
                local accent = is_sell_mode and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary

                if is_selected then
                    bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(accent.x, accent.y, accent.z, 0.15))
                    border_col = imgui.ColorConvertFloat4ToU32(accent)
                    border_thick = S(2)
                else
                    bg_col = imgui.ColorConvertFloat4ToU32(bg_col)
                    border_col = imgui.ColorConvertFloat4ToU32(border_col)
                end
                
                draw_list:AddRectFilled(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), bg_col, S(8))
                draw_list:AddRect(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), border_col, S(8), 15, border_thick)
                
                if imgui.InvisibleButton("##sel_item_"..i, imgui.ImVec2(item_w, item_h)) then
                    Buffers.config_selected[0] = i - 1
                end
                
                if imgui.IsItemHovered() and not is_selected then
                    draw_list:AddRect(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(8), 15, S(1))
                end
                
                local cy = item_p.y + item_h / 2
                local icon_x = item_p.x + S(15)
                if font_fa then
                    imgui.PushFont(font_fa)
                    local f_icon = is_selected and fa('folder_open') or fa('folder')
                    local f_col = is_selected and accent or CURRENT_THEME.text_secondary
                    local f_sz = GetStaticTextSize(f_icon)
                    draw_list:AddText(imgui.ImVec2(icon_x, cy - f_sz.y/2), imgui.ColorConvertFloat4ToU32(f_col), f_icon)
                    imgui.PopFont()
                end
                
                local txt_x = icon_x + S(30)
                local name_col = is_selected and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary
                draw_list:AddText(imgui.ImVec2(txt_x, cy - imgui.GetFontSize()/2), imgui.ColorConvertFloat4ToU32(name_col), u8(config.name))
                
                local count_str = tostring(#config.items) .. u8" шт."
                local count_sz = GetStaticTextSize(count_str)
                draw_list:AddText(imgui.ImVec2(item_p.x + item_w - count_sz.x - S(15), cy - count_sz.y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), count_str)
                
                if is_selected and font_fa then
                    imgui.PushFont(font_fa)
                    local check_icon = fa('check')
                    local c_sz = GetStaticTextSize(check_icon)
                    local c_x = item_p.x + item_w - count_sz.x - S(40)
                    draw_list:AddText(imgui.ImVec2(c_x, cy - c_sz.y/2), imgui.ColorConvertFloat4ToU32(accent), check_icon)
                    imgui.PopFont()
                end
                
                imgui.Dummy(imgui.ImVec2(0, S(2))) 
            end
            imgui.Dummy(imgui.ImVec2(0, S(10)))
        end)
        imgui.PopStyleColor()

        local footer_y = p.y + h - footer_h
        
        draw_list:AddLine(imgui.ImVec2(p.x, footer_y), imgui.ImVec2(p.x + win_w, footer_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1.0)
        draw_list:AddRectFilled(imgui.ImVec2(p.x, footer_y), imgui.ImVec2(p.x + win_w, p.y + h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 10)
        
        imgui.SetCursorPos(imgui.ImVec2(S(15), h - footer_h + S(15)))
        imgui.TextColored(CURRENT_THEME.text_secondary, u8"Или создайте новый конфиг:")
        
        imgui.SetCursorPos(imgui.ImVec2(S(15), h - footer_h + S(35)))
        
        local create_btn_w = S(40)
        local input_w = win_w - (S(15) * 2) - create_btn_w - S(8)
        
        renderModernInput("##new_cfg_name_modal", Buffers.new_config_name, input_w, "Название нового конфига...")
        
        imgui.SameLine()
        
        local accent = is_sell_mode and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary

        if renderCustomButton("", create_btn_w, S(34), accent, fa('plus')) then
            local new_name_utf8 = ffi.string(Buffers.new_config_name)
            local new_name = u8:decode(new_name_utf8)
            
            if new_name and new_name ~= "" then
                local new_idx
                if is_sell_mode then
                    new_idx = createSellConfig(new_name)
                else
                    new_idx = createBuyConfig(new_name)
                end
                Buffers.config_selected[0] = new_idx - 1
                imgui.StrCopy(Buffers.new_config_name, "")
                triggerScrollToBottom("SelectorList")
            else
                 addToastNotification("Введите название!", "error")
            end
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(u8"Создать новый пустой конфиг") end
        
        local btn_area_y = h - S(50)
        local gap = S(10)
        local action_btn_w = (win_w - (S(15) * 2) - gap) / 2
        local btn_h = S(35)
        
        imgui.SetCursorPos(imgui.ImVec2(S(15), btn_area_y))
        local selected_idx = Buffers.config_selected[0] + 1
        local target_name = (target_configs[selected_idx]) and target_configs[selected_idx].name or "..."
        if #target_name > 15 then target_name = target_name:sub(1, 15) .. "..." end
        
        local copy_label = u8("Вставить в: " .. target_name)
        
        if renderCustomButton(copy_label, action_btn_w, btn_h, CURRENT_THEME.accent_success, fa('check')) then
            if selected_idx >= 1 and selected_idx <= #target_configs then
                performRemoteShopCopy(selected_idx, App.config_selector_mode)
                App.show_config_selector = false
                imgui.StrCopy(Buffers.new_config_name, "")
            end
        end
        
        imgui.SetCursorPos(imgui.ImVec2(S(15) + action_btn_w + gap, btn_area_y))
        if renderCustomButton(u8"Отмена", action_btn_w, btn_h, imgui.ImVec4(0.3, 0.3, 0.35, 1.0)) then
            App.show_config_selector = false
            imgui.StrCopy(Buffers.new_config_name, "")
        end
    end
    imgui.End()
    
    imgui.PopStyleColor(2)
    imgui.PopStyleVar(2)
end

local button_color_cache = {}
-- Создаем статический ImVec2, чтобы не плодить мусор в памяти
local btn_size_vec = imgui.ImVec2(0, 0)

function renderCustomButton(label, w, h, col, icon)
    local full_label = icon and (icon .. " " .. label) or label
    local is_vec4 = type(col) == "cdata"
    
    if is_vec4 then
        -- ИСТИННАЯ ОПТИМИЗАЦИЯ: Формируем числовой хэш, исключая аллокацию строк каждый кадр
        local c_key = math.floor(col.x*100) + math.floor(col.y*100)*1000 + math.floor(col.z*100)*1000000
        
        if not button_color_cache[c_key] then
            button_color_cache[c_key] = {
                hover = imgui.ImVec4(math.min(col.x+0.1, 1), math.min(col.y+0.1, 1), math.min(col.z+0.1, 1), col.w),
                active = imgui.ImVec4(math.max(col.x-0.1, 0), math.max(col.y-0.1, 0), math.max(col.z-0.1, 0), col.w),
                text = (col.x * 0.299 + col.y * 0.587 + col.z * 0.114) > 0.6 and imgui.ImVec4(0.05, 0.05, 0.05, 1.0) or imgui.ImVec4(0.95, 0.95, 0.95, 1.0)
            }
        end
        
        local cached = button_color_cache[c_key]
        imgui.PushStyleColor(imgui.Col.Button, col)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, cached.hover)
        imgui.PushStyleColor(imgui.Col.ButtonActive, cached.active)
        imgui.PushStyleColor(imgui.Col.Text, cached.text)
    end

    if icon and font_fa then imgui.PushFont(font_fa) end
    
    btn_size_vec.x = w
    btn_size_vec.y = h
    local clicked = imgui.Button(full_label, btn_size_vec)
    
    if icon and font_fa then imgui.PopFont() end
    if is_vec4 then imgui.PopStyleColor(4) end
    
    return clicked
end

function renderEmptyState(icon, title, description, button_text, button_callback)
    local w = imgui.GetContentRegionAvail().x
    local h = imgui.GetContentRegionAvail().y
    
    local total_h = S(120)
    if button_text then total_h = total_h + S(50) end
    
    imgui.SetCursorPosY(math.max(S(10), (h - total_h) / 2))
    
    if font_fa then
        imgui.PushFont(font_fa)
        local isz = GetStaticTextSize(icon)
        imgui.SetCursorPosX((w - isz.x) / 2)
        imgui.TextColored(CURRENT_THEME.accent_primary, icon)
        imgui.PopFont()
    end
    
    local t_sz = GetStaticTextSize(u8(title))
    imgui.SetCursorPosX((w - t_sz.x) / 2)
    imgui.TextColored(CURRENT_THEME.text_primary, u8(title))
    
    imgui.PushTextWrapPos(w - S(20))
    local d_sz = GetStaticTextSize(u8(description))
    imgui.SetCursorPosX((w - math.min(d_sz.x, w - S(40))) / 2)
    imgui.TextColored(CURRENT_THEME.text_secondary, u8(description))
    imgui.PopTextWrapPos()
    
    if button_text and button_callback then
        imgui.Dummy(imgui.ImVec2(0, S(15)))
        local bw = S(180)
        imgui.SetCursorPosX((w - bw) / 2)
        if imgui.Button(u8(button_text), imgui.ImVec2(bw, S(35))) then
            button_callback()
        end
    end
end

function applyAveragePrices(list, mode, strategy)
    -- strategy: "normal" (средние), "fast_sell" (-5% от рынка), "max_profit" (скупка +1%, продажа +5%)
    local count = 0
    local is_sell = (mode == "sell")
    local buffer_table = is_sell and Buffers.sell_input_buffers or Buffers.buy_input_buffers
    local prefix = is_sell and "s" or "b"
    local suffix = is_sell and "_s" or "_b"

    for _, item in ipairs(list) do
        if item.active then
            local avg = getAveragePriceForItem(item, mode, true)
            if not avg or avg == 0 then avg = getAveragePriceForItem(item, mode, false) end
            
            if avg and avg > 0 then
                local new_price = avg
                local current = tonumber(item.price) or 0
                local should_update = false

                -- Инновационная логика стратегий
                if strategy == "normal" then
                    should_update = true
                elseif strategy == "fix_bad" then
                    if is_sell and current < avg then should_update = true end
                    if not is_sell and current > 0 and current > avg then should_update = true end
                elseif strategy == "fast_sell" and is_sell then
                    -- Демпинг для быстрой продажи (на 1-5% дешевле рынка)
                    new_price = math.floor(avg * 0.96)
                    should_update = true
                elseif strategy == "max_profit" then
                    -- Максимальная прибыль (Продаем дороже, скупаем чуть выше конкурентов)
                    if is_sell then new_price = math.floor(avg * 1.05) 
                    else new_price = math.floor(avg * 1.02) end
                    should_update = true
                end

                if should_update then
                    -- Округляем для красоты (без копеек)
                    new_price = roundPriceToClean(new_price)
                    item.price = new_price
                    
                    local uid = item._uid_cache or (tostring(item):gsub("table: ", "") .. tostring(os.clock()))
                    item._uid_cache = uid
                    local key = prefix .. "p_" .. uid .. suffix
                    
                    -- [FPS FIX] Перезаписываем без утечки
                    if buffer_table[key] then
                        imgui.StrCopy(buffer_table[key], tostring(new_price))
                    else
                        buffer_table[key] = imgui.new.char[32](tostring(new_price))
                    end
                    item._last_price_str = tostring(new_price)
                    item._price_pad_x = nil
                    
                    count = count + 1
                end
            end
        end
    end
    
    if count > 0 then
        saveListsConfig()
        if is_sell then calculateSellTotal() else calculateBuyTotal() end
        local strat_names = {normal = "Средние цены", fix_bad = "Цены исправлены", fast_sell = "Быстрая продажа", max_profit = "Макс. прибыль"}
        addToastNotification("Стратегия [" .. (strat_names[strategy] or "Применено") .. "]: обновлено " .. count .. " товаров", "success", 4.0)
    else
        addToastNotification("Нет данных для оптимизации цен", "info")
    end
end

function renderRadialMenuOverlay()
    if not App.radial_menu_active then return end

    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    
    -- Позиция: по центру, снизу (20% от низа экрана, как в оригинале)
    imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh * 0.80), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
    
    -- Убираем фон окна, оставляем только кнопки
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(10, 10))
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 0)) 
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0)

    -- Окно поверх всего, без возможности взаимодействия с ним самим (только с его кнопками)
    local flags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + 
                  imgui.WindowFlags.NoMove + imgui.WindowFlags.AlwaysAutoResize + 
                  imgui.WindowFlags.NoSavedSettings

    if imgui.Begin("RadialMenuOverlay", nil, flags) then
        local btn_w = S(160)
        local btn_h = S(45)

        -- Кнопка RMarket (Фиолетовая)
        local color_rmarket = imgui.ImVec4(0.58, 0.45, 0.95, 1.0) -- Под цвет оригинальной кнопки
        if renderCustomButton(u8"RMarket", btn_w, btn_h, color_rmarket, fa('gear')) then
            App.radial_menu_active = false
            
            -- [NEW] Штатно закрываем серверное CEF меню
            sendCEF("radialMenu.closeMenu")
            
            lua_thread.create(function()
                wait(50) -- Ждем долю секунды, чтобы интерфейс CEF успел пропасть
                -- Открываем меню скрипта (Курсор покажется автоматически через State Manager)
                sampProcessChatInput("/rmenu")
            end)
        end

        imgui.SameLine(0, S(15))

        -- Кнопка Радиус (Красная)
        if renderCustomButton(u8"Радиус", btn_w, btn_h, CURRENT_THEME.accent_danger, fa('bullseye')) then
            App.radial_menu_active = false
            
            -- [NEW] Штатно закрываем серверное CEF меню
            sendCEF("radialMenu.closeMenu")
            
            lua_thread.create(function()
                wait(50)
                -- Переключаем радиус
                App.render_radius = not App.render_radius
                if App.render_radius then
                    lastUpdate = 0
                    updateLavkas()
                    addToastNotification("Отображение зон включено", "success")
                else
                    addToastNotification("Отображение зон выключено", "info")
                end
            end)
        end
    end
    imgui.End()
    imgui.PopStyleColor()
    imgui.PopStyleVar(2)
end

function renderLiveProfitHUD()
    if not Buffers.settings.show_live_hud[0] then return end 
    if Buffers.settings.live_hud_only_in_shop[0] and not App.live_shop_active then return end
    if not App.script_loaded then return end
    if isGamePaused() then return end

    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local is_cursor = isCursorVisible()
    
    if Data.settings.hud_pos_x == nil or Data.settings.hud_pos_x == -1 then
        imgui.SetNextWindowPos(imgui.ImVec2(sw - S(20), sh - S(80)), imgui.Cond.FirstUseEver, imgui.ImVec2(1.0, 1.0))
    else
        imgui.SetNextWindowPos(imgui.ImVec2(Data.settings.hud_pos_x, Data.settings.hud_pos_y), imgui.Cond.FirstUseEver)
    end
    
    local pad_x, pad_y = S(18), S(16)
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(pad_x, pad_y))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
    
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.06, 0.07, 0.09, 0.95)) 
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1.5))

    local flags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + 
                  imgui.WindowFlags.AlwaysAutoResize + imgui.WindowFlags.NoFocusOnAppearing + 
                  imgui.WindowFlags.NoSavedSettings
                  
    if not is_cursor then
        flags = flags + imgui.WindowFlags.NoInputs + imgui.WindowFlags.NoMove
    end

    if imgui.Begin("##LiveProfitHUD", nil, flags) then
        local dl = imgui.GetWindowDrawList()
        local p = imgui.GetWindowPos()
        local win_w = imgui.GetWindowWidth()
        
        if is_cursor then
            local pos = imgui.GetWindowPos()
            if imgui.IsWindowHovered() and imgui.IsMouseReleased(0) then
                if pos.x ~= Data.settings.hud_pos_x or pos.y ~= Data.settings.hud_pos_y then
                    Data.settings.hud_pos_x = pos.x
                    Data.settings.hud_pos_y = pos.y
                    App.hud_saved_pos_x = pos.x
                    App.hud_saved_pos_y = pos.y
                    scheduleSaveSettings()
                end
            end
        end
        
        local content_min_w = S(240)
        imgui.Dummy(imgui.ImVec2(content_min_w, 0))
        local content_w = math.max(content_min_w, win_w - (pad_x * 2))

        local now = os.clock()
        if not App.hud_date_check or (now - App.hud_date_check > 1.0) then
            local current_date = os.date("%Y-%m-%d")
            if not LogsState.today or LogsState.today.date ~= current_date then
                calculateTodayStats()
            end
            App.hud_date_check = now
        end

        local earned = LogsState.today.earned or 0
        local spent = LogsState.today.spent or 0
        local profit = earned - spent
        local trades_count = LogsState.today.trades or 0

        if not App.hud_anim then App.hud_anim = { e = earned, s = spent } end
        local dt = io.DeltaTime
        App.hud_anim.e = App.hud_anim.e + (earned - App.hud_anim.e) * dt * 8.0
        App.hud_anim.s = App.hud_anim.s + (spent - App.hud_anim.s) * dt * 8.0

        if font_fa then
            imgui.PushFont(font_fa)
            imgui.TextColored(CURRENT_THEME.accent_primary, fa('chart_pie'))
            imgui.PopFont()
            imgui.SameLine(0, S(8))
        end
        
        imgui.TextColored(imgui.ImVec4(1, 1, 1, 0.95), u8"RMarket Live")
        
        if is_cursor and font_fa then
            imgui.SameLine(0, S(8))
            imgui.PushFont(font_fa)
            imgui.TextColored(imgui.ImVec4(1, 1, 1, 0.2), fa('up_down_left_right'))
            if imgui.IsItemHovered() then imgui.SetTooltip(u8"Окно можно перемещать") end
            imgui.PopFont()
        end
        
        local dot_center = imgui.ImVec2(p.x + win_w - pad_x - S(2), p.y + pad_y + S(6))
        
        if App.live_shop_active then
            local t = os.clock() * 1.5
            local fract = t % 1.0
            
            local pulse_r = S(4) + (fract * S(10))
            local pulse_a = 1.0 - (fract * fract)
            dl:AddCircleFilled(dot_center, pulse_r, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.2, 0.8, 0.3, pulse_a * 0.5)))
            
            local inner_a = 0.6 + (math.sin(os.clock() * 6) + 1) * 0.2
            dl:AddCircleFilled(dot_center, S(4), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.2, 0.9, 0.3, inner_a)))
        else
            dl:AddCircleFilled(dot_center, S(4), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.4, 0.4, 0.4, 0.8)))
        end
        
        imgui.Dummy(imgui.ImVec2(0, S(8)))
        
        local function DrawRowAligned(label, val_str, val_col, icon)
            if font_fa then
                imgui.PushFont(font_fa)
                imgui.TextColored(CURRENT_THEME.text_hint, icon)
                imgui.PopFont()
                imgui.SameLine(0, S(8))
            end
            imgui.TextColored(CURRENT_THEME.text_hint, label)
            
            local v_sz = GetStaticTextSize(val_str)
            imgui.SameLine(pad_x + content_w - v_sz.x)
            imgui.TextColored(val_col, val_str)
        end

        DrawRowAligned(u8"Сделок:", tostring(trades_count), CURRENT_THEME.text_primary, fa('handshake'))
        DrawRowAligned(u8"Доход:", "+" .. formatMoney(math.floor(App.hud_anim.e)) .. " $", CURRENT_THEME.accent_success, fa('arrow_trend_up'))
        DrawRowAligned(u8"Расход:", "-" .. formatMoney(math.floor(App.hud_anim.s)) .. " $", CURRENT_THEME.accent_danger, fa('arrow_trend_down'))
        
        local roi = 0
        if spent > 0 then roi = ((earned - spent) / spent) * 100 end
        local roi_str = string.format("%s%.1f%%", roi > 0 and "+" or "", roi)
        local roi_col = roi >= 0 and CURRENT_THEME.accent_primary or CURRENT_THEME.accent_danger
        DrawRowAligned(u8"Маржа (ROI):", roi_str, roi_col, fa('percent'))
        
        imgui.Dummy(imgui.ImVec2(0, S(6)))
        
        local sep_y = imgui.GetCursorScreenPos().y
        local c_clear = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.border_light.x, CURRENT_THEME.border_light.y, CURRENT_THEME.border_light.z, 0.0))
        local c_solid = imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light)
        
        dl:AddRectFilledMultiColor(imgui.ImVec2(p.x, sep_y), imgui.ImVec2(p.x + win_w/2, sep_y + S(1)), c_clear, c_solid, c_solid, c_clear)
        dl:AddRectFilledMultiColor(imgui.ImVec2(p.x + win_w/2, sep_y), imgui.ImVec2(p.x + win_w, sep_y + S(1)), c_solid, c_clear, c_clear, c_solid)
        
        imgui.Dummy(imgui.ImVec2(0, S(8)))
        
        local profit_anim = math.floor(App.hud_anim.e) - math.floor(App.hud_anim.s)
        local p_str = (profit_anim > 0 and "+" or "") .. formatMoney(profit_anim) .. " $"
        local p_col = profit_anim >= 0 and CURRENT_THEME.accent_success or CURRENT_THEME.accent_danger
        
        local base_u32 = profit_anim >= 0 and CURRENT_THEME.accent_success_u32 or CURRENT_THEME.accent_danger_u32
        local profit_bg = setAlphaU32(base_u32, 0.15)
        
        local cur_y = imgui.GetCursorScreenPos().y
        dl:AddRectFilled(SetVec(REN_VEC_1, p.x, cur_y - S(4)), SetVec(REN_VEC_2, p.x + win_w, cur_y + imgui.GetFontSize() + S(4)), profit_bg)

        imgui.TextColored(CURRENT_THEME.text_primary, u8"ЧИСТАЯ ПРИБЫЛЬ:")
        
        if font_default then imgui.PushFont(font_default) end
        local p_sz = GetStaticTextSize(p_str)
        imgui.SameLine(pad_x + content_w - p_sz.x)
        imgui.TextColored(p_col, p_str)
        if font_default then imgui.PopFont() end
        
    end
    imgui.End()
    
    imgui.PopStyleColor(2)
    imgui.PopStyleVar(3)
end

function renderWarehouseTab()
    local avail_w = imgui.GetContentRegionAvail().x
    local avail_h = imgui.GetContentRegionAvail().y
    local main_draw_list = imgui.GetWindowDrawList()

    imgui.Dummy(imgui.ImVec2(0, S(8)))
    avail_h = imgui.GetContentRegionAvail().y 

    -- Считываем глобальный поиск
    local is_searching = Buffers.warehouse_search[0] ~= 0
    local search_q = ""
    if is_searching then 
        search_q = u8:decode(ffi.string(Buffers.warehouse_search)):lower() 
    end

    -- === ЕСЛИ ПОИСК АКТИВЕН (ГЛОБАЛЬНЫЙ ПОИСК) ===
    if is_searching then
        -- [FPS BOOST] Кэшируем результаты поиска по складам
        if not App.wh_search_cache then App.wh_search_cache = { query = nil, results = {} } end
        
        -- Выполняем тяжелый поиск и сортировку только если текст изменился
        if App.wh_search_cache.query ~= search_q or SaveScheduler.lists_dirty then
            local new_results = {}
            for car_name, items in pairs(Data.warehouses) do
                if type(items) == "table" then
                    for slot, item in pairs(items) do
                        if type(item) == "table" and item.name then
                            if item.name:lower():find(search_q, 1, true) then
                                table.insert(new_results, {
                                    car_name = car_name,
                                    name = item.name,
                                    amount = item.amount,
                                    slot = slot,
                                    data = item
                                })
                            end
                        end
                    end
                end
            end

            table.sort(new_results, function(a, b)
                if a.name == b.name then return a.car_name < b.car_name end
                return a.name < b.name
            end)
            
            App.wh_search_cache.query = search_q
            App.wh_search_cache.results = new_results
        end
        
        local search_results = App.wh_search_cache.results

        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
        imgui.BeginChild("WarehouseGlobalSearch", imgui.ImVec2(0, avail_h - S(5)), true, imgui.WindowFlags.NoScrollbar)
            local panel_w = imgui.GetContentRegionAvail().x

            -- Хедер поиска
            local hp = imgui.GetCursorScreenPos()
            local head_h = S(45)
            -- Фон шапки закругляем только сверху (3)
			main_draw_list:AddRectFilled(hp, imgui.ImVec2(hp.x + panel_w, hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8), 3)
			-- Левую полоску закругляем только сверху слева (1)
			main_draw_list:AddRectFilled(hp, imgui.ImVec2(hp.x + S(4), hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), S(8), 1)
            main_draw_list:AddLine(imgui.ImVec2(hp.x, hp.y + head_h), imgui.ImVec2(hp.x + panel_w, hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
            
            if font_fa then
                imgui.PushFont(font_fa)
                main_draw_list:AddText(imgui.ImVec2(hp.x + S(15), hp.y + (head_h - GetStaticTextSize(fa('magnifying_glass')).y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), fa('magnifying_glass'))
                imgui.PopFont()
            end
            local res_txt = u8"Результаты поиска: " .. #search_results .. u8" совпадений"
            main_draw_list:AddText(imgui.ImVec2(hp.x + S(45), hp.y + (head_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), res_txt)
            
            imgui.Dummy(imgui.ImVec2(0, head_h))

            if #search_results == 0 then
                imgui.Dummy(imgui.ImVec2(0, imgui.GetContentRegionAvail().y / 2 - S(40)))
                renderEmptyState(fa('ghost'), "Ничего не найдено", "Товар не найден ни в одном из сохраненных хранилищ.")
            else
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
                renderSmoothScrollBox("WhGlobalSearchScroll", imgui.ImVec2(panel_w, imgui.GetContentRegionAvail().y), function()
                    local dl = imgui.GetWindowDrawList() -- [FIX] Локальный DrawList для клиппинга скролла
                    imgui.Dummy(imgui.ImVec2(0, S(8)))
                    local iw = panel_w - S(24)
                    local ih = S(55) 
                    
                    local total_items = #search_results
                    local current_scroll = imgui.GetScrollY()
                    local visible_height = imgui.GetWindowHeight()
                    local start_idx = math.floor(current_scroll / (ih + S(6))) + 1
                    local end_idx = start_idx + math.ceil(visible_height / (ih + S(6))) + 1
                    
                    start_idx = math.max(1, start_idx)
                    end_idx = math.min(total_items, end_idx)
                    
                    imgui.SetCursorPosY((start_idx - 1) * (ih + S(6)) + S(8))
                    
                    for i = start_idx, end_idx do
                        local res = search_results[i]
                        if res then
                            imgui.SetCursorPosX(S(12))
                            local ip = imgui.GetCursorScreenPos()
                            
                            if imgui.InvisibleButton("##wh_gsearch_"..i, imgui.ImVec2(iw, ih)) then
                                App.selected_warehouse_car = res.car_name
                                imgui.StrCopy(Buffers.warehouse_search, "")
                            end
                            imgui.SetItemAllowOverlap() -- [FIX] Разрешаем наведение на картинку поверх карточки
                            
                            local is_hov = imgui.IsItemHovered()
                            local bg_c = is_hov and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.bg_tertiary.x+0.05, CURRENT_THEME.bg_tertiary.y+0.05, CURRENT_THEME.bg_tertiary.z+0.05, 1)) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary)
                            dl:AddRectFilled(ip, imgui.ImVec2(ip.x + iw, ip.y + ih), bg_c, S(8))
                            
                            if is_hov then
                                dl:AddRect(ip, imgui.ImVec2(ip.x + iw, ip.y + ih), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(8), 15, S(1))
                            end
                            
                            local target_model_id = res.data.model_id or findRealIndexByName(res.name)
                            local img_box_sz = S(36)
                            local img_box_x = ip.x + S(12)
                            local img_box_y = ip.y + (ih - img_box_sz)/2

                            local box_min = imgui.ImVec2(img_box_x, img_box_y)
                            local box_max = imgui.ImVec2(img_box_x + img_box_sz, img_box_y + img_box_sz)
                            local box_rounding = S(8)

                            -- Темный слот
                            local slot_bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.05, 0.06, 1.0))
                            dl:AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)
                            
                            -- Свечение
                            local glow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_warning.x, CURRENT_THEME.accent_warning.y, CURRENT_THEME.accent_warning.z, 0.15))
                            dl:AddRectFilled(box_min, box_max, glow_col, box_rounding)
                            dl:AddRect(box_min, box_max, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.12)), box_rounding, 15, S(1.5))

                            local texture = getItemIconTexture(tonumber(target_model_id))

                            if texture then
                                local pad = S(3)
                                local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.8))
                                dl:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(2)), imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(2)), imgui.ImVec2(0,0), imgui.ImVec2(1,1), shadow_col)
                                dl:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad), imgui.ImVec2(box_max.x - pad, box_max.y - pad))
                            else
                                if font_fa then
                                    imgui.PushFont(font_fa)
                                    local isz = GetStaticTextSize(fa('box'))
                                    dl:AddText(imgui.ImVec2(img_box_x + (img_box_sz - isz.x)/2, img_box_y + (img_box_sz - isz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), fa('box'))
                                    imgui.PopFont()
                                end
                            end

                            -- [NEW] Увеличенная иконка при наведении (Tooltip)
                            imgui.SetCursorScreenPos(box_min)
                            imgui.InvisibleButton("##img_hover_whg_" .. i, imgui.ImVec2(img_box_sz, img_box_sz))
                            if texture and imgui.IsItemHovered() then
                                imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(8)))
                                imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.05, 0.05, 0.06, 0.98))
                                imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_warning)
                                imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
                                
                                imgui.BeginTooltip()
                                imgui.Image(texture, imgui.ImVec2(S(130), S(130)))
                                imgui.EndTooltip()
                                
                                imgui.PopStyleVar(2)
                                imgui.PopStyleColor(2)
                            end
                            
                            local text_x_offset = ip.x + S(55)
                            local safe_name = u8(res.name)
                            dl:AddText(imgui.ImVec2(text_x_offset, ip.y + S(8)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), safe_name)
                            
                            -- [FIX] Иконка машины или шкафа в поиске
                            local storage_icon = res.car_name:find("Шкаф") and fa('box_archive') or fa('car_side')
                            if font_fa then
                                imgui.PushFont(font_fa)
                                dl:AddText(imgui.ImVec2(ip.x + S(45), ip.y + S(29)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_warning), storage_icon)
                                imgui.PopFont()
                            end
                            
                            -- [FIX] Применяем кастомное имя в поиске, если оно есть
                            if not Data.settings.warehouse_names then Data.settings.warehouse_names = {} end
                            local display_car_name = Data.settings.warehouse_names[res.car_name] or res.car_name
                            dl:AddText(imgui.ImVec2(ip.x + S(65), ip.y + S(28)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), u8(display_car_name .. " (Слот: " .. res.slot .. ")"))
                            
                            local amt_str = formatNumber(res.amount) .. u8" шт."
                            local asz = GetStaticTextSize(amt_str)
                            local badge_w = asz.x + S(16)
                            local badge_h = S(24)
                            local badge_x = ip.x + iw - badge_w - S(10)
                            local badge_y = ip.y + (ih - badge_h) / 2
                            
                            dl:AddRectFilled(imgui.ImVec2(badge_x, badge_y), imgui.ImVec2(badge_x + badge_w, badge_y + badge_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main), S(12))
                            dl:AddText(imgui.ImVec2(badge_x + S(8), badge_y + (badge_h - asz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), amt_str)
                            
                            if is_hov then imgui.SetTooltip(u8"Кликните, чтобы перейти к " .. res.car_name) end
                            
                            imgui.SetCursorScreenPos(imgui.ImVec2(0, ip.y + ih + S(6)))
                        end
                    end
                    if end_idx < total_items then
                        local remaining = total_items - end_idx
                        imgui.SetCursorPosY(imgui.GetCursorPosY() + (remaining * (ih + S(6))))
                    end
                    imgui.Dummy(imgui.ImVec2(0, S(10)))
                end)
                imgui.PopStyleColor()
            end
        imgui.EndChild()
        imgui.PopStyleVar()

    -- === ЕСЛИ ПОИСК ПУСТОЙ (ОБЫЧНЫЙ РЕЖИМ 2 КОЛОНКИ) ===
    else
        imgui.Columns(2, "##warehouse_cols", false) 
        imgui.SetColumnWidth(0, avail_w * 0.35)

        -- ==========================================
        -- ЛЕВАЯ КОЛОНКА: СПИСОК ХРАНИЛИЩ
        -- ==========================================
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
        imgui.BeginChild("WarehouseCarsPanel", imgui.ImVec2(0, avail_h - S(5)), true, imgui.WindowFlags.NoScrollbar)
            local panel_w = imgui.GetContentRegionAvail().x

            local p_head = imgui.GetCursorScreenPos()
            local head_h = S(45)
            
            main_draw_list:AddRectFilled(p_head, imgui.ImVec2(p_head.x + panel_w, p_head.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8), 5)
            main_draw_list:AddRectFilled(p_head, imgui.ImVec2(p_head.x + S(4), p_head.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)
            main_draw_list:AddLine(imgui.ImVec2(p_head.x, p_head.y + head_h), imgui.ImVec2(p_head.x + panel_w, p_head.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
            
            if font_fa then
                imgui.PushFont(font_fa)
                main_draw_list:AddText(imgui.ImVec2(p_head.x + S(15), p_head.y + (head_h - GetStaticTextSize(fa('car')).y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), fa('car'))
                imgui.PopFont()
            end
            main_draw_list:AddText(imgui.ImVec2(p_head.x + S(45), p_head.y + (head_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), u8"Мои хранилища")
            
            imgui.Dummy(imgui.ImVec2(0, head_h))

            local cars = {}
            for car_name, items in pairs(Data.warehouses) do
                local count = 0
                if type(items) == "table" then
                    for _, item in pairs(items) do 
                        if type(item) == "table" and item.name then count = count + 1 end
                    end
                end
                table.insert(cars, {name = car_name, count = count})
            end
            table.sort(cars, function(a, b) return a.name < b.name end)

            if #cars == 0 then
                imgui.Dummy(imgui.ImVec2(0, S(40)))
                local txt = u8"Пусто. Откройте багажник или шкаф."
                local txt_sz = GetStaticTextSize(txt).x
                imgui.SetCursorPosX((panel_w - txt_sz) / 2)
                imgui.TextColored(CURRENT_THEME.text_hint, txt)
            else
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
                renderSmoothScrollBox("CarsScroll", imgui.ImVec2(panel_w, imgui.GetContentRegionAvail().y), function()
                    local dl = imgui.GetWindowDrawList() -- [FIX] Локальный DrawList
                    imgui.Dummy(imgui.ImVec2(0, S(8))) 
                    local list_w = panel_w - S(24) 
                    
                    for i, car in ipairs(cars) do
                        imgui.SetCursorPosX(S(12)) 
                        
                        local is_selected = (App.selected_warehouse_car == car.name)
                        local cp = imgui.GetCursorScreenPos()
                        local ch = S(55)
                        
                        if not Data.settings.warehouse_names then Data.settings.warehouse_names = {} end
                        local is_renaming = (App.rename_warehouse_key == car.name)
                        
                        -- [FIX] Скрываем кнопку выбора во время переименования, чтобы она не "съедала" клики
                        if not is_renaming then
                            if imgui.InvisibleButton("##car_"..i, imgui.ImVec2(list_w, ch)) then
                                App.selected_warehouse_car = car.name
                                imgui.StrCopy(Buffers.warehouse_search, "") -- Сброс поиска
                            end
                            imgui.SetItemAllowOverlap() -- [FIX] Разрешаем кликать по кнопкам (карандаш, корзина) поверх этого блока
                        else
                            imgui.Dummy(imgui.ImVec2(list_w, ch))
                            imgui.SetCursorScreenPos(cp)
                        end
                        
                        local hov = not is_renaming and imgui.IsItemHovered()
                        local bg_col = is_selected and CURRENT_THEME.bg_tertiary or (hov and imgui.ImVec4(1,1,1,0.05) or CURRENT_THEME.bg_secondary)
                        
                        dl:AddRectFilled(cp, imgui.ImVec2(cp.x + list_w, cp.y + ch), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
                        if is_selected then
                            dl:AddRectFilled(cp, imgui.ImVec2(cp.x + S(4), cp.y + ch), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)
                        end

                        local icon_sz = S(32)
                        local icon_y = cp.y + (ch - icon_sz) / 2
                        dl:AddCircleFilled(imgui.ImVec2(cp.x + S(25), icon_y + icon_sz/2), icon_sz/2, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main))
                        if font_fa then
                            imgui.PushFont(font_fa)
                            local icol = is_selected and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
                            -- [FIX] Меняем иконку, если это шкаф
                            local car_icon = car.name:find("Шкаф") and fa('box_archive') or fa('car_side')
                            local isz = GetStaticTextSize(car_icon)
                            dl:AddText(imgui.ImVec2(cp.x + S(25) - isz.x/2, icon_y + (icon_sz - isz.y)/2), imgui.ColorConvertFloat4ToU32(icol), car_icon)
                            imgui.PopFont()
                        end
                        
                        if is_renaming then
                            local input_w = list_w - S(115)
                            imgui.SetCursorScreenPos(imgui.ImVec2(cp.x + S(45), cp.y + (ch - S(28)) / 2))
                            
                            -- [FIX] Используем красивый кастомный InputText
                            renderModernInput("##ren_wh_"..i, Buffers.new_warehouse_name, input_w, "Новое название...")
                            
                            local btn_sz = S(28)
                            
                            -- Сохранить
                            imgui.SetCursorScreenPos(imgui.ImVec2(cp.x + S(50) + input_w, cp.y + (ch - btn_sz) / 2))
                            if imgui.InvisibleButton("##sv_wh_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                                local new_n = u8:decode(ffi.string(Buffers.new_warehouse_name))
                                if new_n == "" or new_n == car.name then
                                    Data.settings.warehouse_names[car.name] = nil
                                else
                                    Data.settings.warehouse_names[car.name] = new_n
                                end
                                saveSettings()
                                App.rename_warehouse_key = nil
                            end
                            if font_fa then
                                imgui.PushFont(font_fa)
                                dl:AddText(imgui.ImVec2(cp.x + S(50) + input_w + S(6), cp.y + (ch - GetStaticTextSize(fa('check')).y) / 2), imgui.ColorConvertFloat4ToU32(imgui.IsItemHovered() and CURRENT_THEME.accent_success or CURRENT_THEME.text_secondary), fa('check'))
                                imgui.PopFont()
                            end
                            
                            -- Отменить
                            imgui.SetCursorScreenPos(imgui.ImVec2(cp.x + S(55) + input_w + btn_sz, cp.y + (ch - btn_sz) / 2))
                            if imgui.InvisibleButton("##cn_wh_"..i, imgui.ImVec2(btn_sz, btn_sz)) then App.rename_warehouse_key = nil end
                            if font_fa then
                                imgui.PushFont(font_fa)
                                dl:AddText(imgui.ImVec2(cp.x + S(55) + input_w + btn_sz + S(8), cp.y + (ch - GetStaticTextSize(fa('xmark')).y) / 2), imgui.ColorConvertFloat4ToU32(imgui.IsItemHovered() and CURRENT_THEME.accent_danger or CURRENT_THEME.text_secondary), fa('xmark'))
                                imgui.PopFont()
                            end
                        else
                            local display_name = Data.settings.warehouse_names[car.name] or car.name
                            local name_u8 = u8(display_name)
                            local max_name_w = list_w - S(100)
                            local n_sz = GetStaticTextSize(name_u8)
                            if n_sz.x > max_name_w then name_u8 = name_u8:sub(1, 18) .. "..." end
                            
                            dl:AddText(imgui.ImVec2(cp.x + S(50), cp.y + S(10)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), name_u8)
                            dl:AddText(imgui.ImVec2(cp.x + S(50), cp.y + S(30)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), u8"Занято слотов: " .. car.count)
                            
                            local btn_sz = S(28)
                            local del_x = cp.x + list_w - btn_sz - S(10)
                            local ren_x = del_x - btn_sz - S(5)
                            local btn_y = cp.y + (ch - btn_sz) / 2
                            
                            -- Кнопка Удалить
                            imgui.SetCursorScreenPos(imgui.ImVec2(del_x, btn_y))
                            if imgui.InvisibleButton("##del_car_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                                Data.warehouses[car.name] = nil
                                if Data.settings.warehouse_names then Data.settings.warehouse_names[car.name] = nil; saveSettings() end
                                if App.selected_warehouse_car == car.name then App.selected_warehouse_car = nil end
                                SaveScheduler.lists_dirty = true
                                addToastNotification("Хранилище удалено из памяти", "info")
                            end
                            local is_del_hov = imgui.IsItemHovered()
                            if is_del_hov then
                                dl:AddRectFilled(imgui.ImVec2(del_x, btn_y), imgui.ImVec2(del_x + btn_sz, btn_y + btn_sz), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,0,0,0.15)), S(6))
                                imgui.SetTooltip(u8"Забыть содержимое этого хранилища")
                            end
                            
                            -- Кнопка Переименовать
                            imgui.SetCursorScreenPos(imgui.ImVec2(ren_x, btn_y))
                            if imgui.InvisibleButton("##ren_car_"..i, imgui.ImVec2(btn_sz, btn_sz)) then
                                App.rename_warehouse_key = car.name
                                imgui.StrCopy(Buffers.new_warehouse_name, u8(Data.settings.warehouse_names[car.name] or car.name))
                            end
                            local is_ren_hov = imgui.IsItemHovered()
                            if is_ren_hov then
                                dl:AddRectFilled(imgui.ImVec2(ren_x, btn_y), imgui.ImVec2(ren_x + btn_sz, btn_y + btn_sz), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(6))
                                imgui.SetTooltip(u8"Изменить отображаемое название (Например: Дом 1337)")
                            end
                            
                            if font_fa then
                                imgui.PushFont(font_fa)
                                local tsz = GetStaticTextSize(fa('trash'))
                                local dcol = is_del_hov and CURRENT_THEME.accent_danger or CURRENT_THEME.text_secondary
                                dl:AddText(imgui.ImVec2(del_x + (btn_sz-tsz.x)/2, btn_y + (btn_sz-tsz.y)/2), imgui.ColorConvertFloat4ToU32(dcol), fa('trash'))
                                
                                local psz = GetStaticTextSize(fa('pen'))
                                local pcol = is_ren_hov and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
                                dl:AddText(imgui.ImVec2(ren_x + (btn_sz-psz.x)/2, btn_y + (btn_sz-psz.y)/2), imgui.ColorConvertFloat4ToU32(pcol), fa('pen'))
                                imgui.PopFont()
                            end
                        end
                        
                        imgui.SetCursorScreenPos(imgui.ImVec2(0, cp.y + ch + S(6)))
                    end
                    imgui.Dummy(imgui.ImVec2(0, S(10)))
                end)
                imgui.PopStyleColor()
            end
        imgui.EndChild()
        imgui.PopStyleVar()

        imgui.NextColumn()

        -- ==========================================
        -- ПРАВАЯ КОЛОНКА: ВЕЩИ В ХРАНИЛИЩЕ
        -- ==========================================
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
        imgui.BeginChild("WarehouseItemsPanel", imgui.ImVec2(0, avail_h - S(5)), true, imgui.WindowFlags.NoScrollbar)
            local panel_w = imgui.GetContentRegionAvail().x

            if not App.selected_warehouse_car or not Data.warehouses[App.selected_warehouse_car] then
                imgui.Dummy(imgui.ImVec2(0, avail_h / 2 - S(40)))
                renderEmptyState(fa('box_open'), "Выберите хранилище", "Слева выберите багажник или шкаф, чтобы просмотреть, что в нём лежит.")
            else
                local car_name = App.selected_warehouse_car
                local items = Data.warehouses[car_name]
                
                local hp = imgui.GetCursorScreenPos()
                local head_h = S(45)
                
                main_draw_list:AddRectFilled(hp, imgui.ImVec2(hp.x + panel_w, hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8), 5)
                main_draw_list:AddRectFilled(hp, imgui.ImVec2(hp.x + S(4), hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), S(8), 5)
                main_draw_list:AddLine(imgui.ImVec2(hp.x, hp.y + head_h), imgui.ImVec2(hp.x + panel_w, hp.y + head_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
                
                if font_fa then
                    imgui.PushFont(font_fa)
                    main_draw_list:AddText(imgui.ImVec2(hp.x + S(15), hp.y + (head_h - GetStaticTextSize(fa('boxes_stacked')).y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), fa('boxes_stacked'))
                    imgui.PopFont()
                end
                
                local display_car_name = Data.settings.warehouse_names and Data.settings.warehouse_names[car_name] or car_name
                local title_base = u8"Содержимое: "
                local cn_u8 = u8(display_car_name)
                main_draw_list:AddText(imgui.ImVec2(hp.x + S(45), hp.y + (head_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), title_base)
                main_draw_list:AddText(imgui.ImVec2(hp.x + S(45) + GetStaticTextSize(title_base).x, hp.y + (head_h - imgui.GetFontSize())/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), cn_u8)
                
                imgui.Dummy(imgui.ImVec2(0, head_h))
                
                local display_items = {}
                if type(items) == "table" then
                    for slot, item in pairs(items) do
                        if type(item) == "table" and item.name then
                            table.insert(display_items, {slot = slot, data = item})
                        end
                    end
                end
                
                table.sort(display_items, function(a,b) return (tonumber(a.slot) or 0) < (tonumber(b.slot) or 0) end)
                
                if #display_items == 0 then
                    imgui.Dummy(imgui.ImVec2(0, imgui.GetContentRegionAvail().y / 2 - S(40)))
                    renderEmptyState(fa('ghost'), "Пусто", "В этом хранилище нет вещей.")
                else
                    imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
                    renderSmoothScrollBox("WhItemsScroll", imgui.ImVec2(panel_w, imgui.GetContentRegionAvail().y), function()
                        local dl = imgui.GetWindowDrawList() -- [FIX] Локальный DrawList
                        imgui.Dummy(imgui.ImVec2(0, S(8)))
                        local iw = panel_w - S(24)
                        local ih = S(50) 
                        
                        local total_items = #display_items
                        local current_scroll = imgui.GetScrollY()
                        local visible_height = imgui.GetWindowHeight()
                        local start_idx = math.floor(current_scroll / (ih + S(6))) + 1
                        local end_idx = start_idx + math.ceil(visible_height / (ih + S(6))) + 1
                        
                        start_idx = math.max(1, start_idx)
                        end_idx = math.min(total_items, end_idx)
                        
                        imgui.SetCursorPosY((start_idx - 1) * (ih + S(6)) + S(8))
                        
                        for i = start_idx, end_idx do
                            local entry = display_items[i]
                            if entry then
                                imgui.SetCursorPosX(S(12))
                                local ip = imgui.GetCursorScreenPos()
                                
                                imgui.InvisibleButton("##wh_item_"..entry.slot, imgui.ImVec2(iw, ih))
                                local is_hov = imgui.IsItemHovered()
                                imgui.SetItemAllowOverlap() -- [FIX] Разрешаем наведение на картинку поверх карточки
                                
                                local bg_c = is_hov and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.bg_tertiary.x+0.05, CURRENT_THEME.bg_tertiary.y+0.05, CURRENT_THEME.bg_tertiary.z+0.05, 1)) or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary)
                                dl:AddRectFilled(ip, imgui.ImVec2(ip.x + iw, ip.y + ih), bg_c, S(8))
                                
                                if is_hov then
                                    dl:AddRect(ip, imgui.ImVec2(ip.x + iw, ip.y + ih), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(8), 15, S(1))
                                end
                                
                                local target_name = res and res.name or entry.data.name
                                local target_model_id = (res and res.data and res.data.model_id) or (entry and entry.data and entry.data.model_id) or findRealIndexByName(target_name)

                                -- ААА Иконка Склада
                                local img_box_sz = S(36)
                                local img_box_x = ip.x + S(12)
                                local img_box_y = ip.y + (ih - img_box_sz)/2

                                local box_min = imgui.ImVec2(img_box_x, img_box_y)
                                local box_max = imgui.ImVec2(img_box_x + img_box_sz, img_box_y + img_box_sz)
                                local box_rounding = S(8)

                                local slot_bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.05, 0.06, 1.0))
                                dl:AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)
                                
                                -- Для склада делаем мягкое зеленоватое свечение или в цвет темы
                                local glow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_success.x, CURRENT_THEME.accent_success.y, CURRENT_THEME.accent_success.z, 0.15))
                                dl:AddRectFilled(box_min, box_max, glow_col, box_rounding)
                                dl:AddRect(box_min, box_max, imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 0.12)), box_rounding, 15, S(1.5))

                                local texture = getItemIconTexture(tonumber(target_model_id))

                                if texture then
                                    local pad = S(3)
                                    local uv0, uv1 = imgui.ImVec2(0, 0), imgui.ImVec2(1, 1)
                                    local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.8))
                                    
                                    dl:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(2)), imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(2)), uv0, uv1, shadow_col)
                                    dl:AddImage(texture, imgui.ImVec2(box_min.x + pad, box_min.y + pad), imgui.ImVec2(box_max.x - pad, box_max.y - pad), uv0, uv1, 0xFFFFFFFF)
                                else
                                    if font_fa then
                                        imgui.PushFont(font_fa)
                                        local isz = GetStaticTextSize(fa('box'))
                                        local pulse = (math.sin(os.clock() * 4) + 1) * 0.5
                                        local icon_alpha = 0.2 + (pulse * 0.3)
                                        local ph_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(CURRENT_THEME.accent_success.x, CURRENT_THEME.accent_success.y, CURRENT_THEME.accent_success.z, icon_alpha))
                                        dl:AddText(imgui.ImVec2(img_box_x + (img_box_sz - isz.x)/2, img_box_y + (img_box_sz - isz.y)/2), ph_col, fa('box'))
                                        imgui.PopFont()
                                    end
                                end
                                
                                -- [NEW] Увеличенная иконка при наведении (Tooltip)
                                imgui.SetCursorScreenPos(box_min)
                                imgui.InvisibleButton("##img_hover_wh_" .. entry.slot, imgui.ImVec2(img_box_sz, img_box_sz))
                                if texture and imgui.IsItemHovered() then
                                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(8), S(8)))
                                    imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.05, 0.05, 0.06, 0.98))
                                    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_success)
                                    imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(8))
                                    
                                    imgui.BeginTooltip()
                                    imgui.Image(texture, imgui.ImVec2(S(130), S(130)))
                                    imgui.EndTooltip()
                                    
                                    imgui.PopStyleVar(2)
                                    imgui.PopStyleColor(2)
                                end
                                
                                local text_x_offset = ip.x + S(60) -- [FIX] Отодвигаем текст, чтобы он не нализал на иконку
                                local safe_name = u8(target_name)
                                local max_text_w = iw - S(145)
                                local txt_sz = GetStaticTextSize(safe_name)
                                if txt_sz.x > max_text_w then safe_name = safe_name:sub(1, 35) .. "..." end
                                
                                dl:AddText(imgui.ImVec2(text_x_offset, ip.y + S(9)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), safe_name)
                                dl:AddText(imgui.ImVec2(text_x_offset, ip.y + S(27)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), u8("Слот: " .. entry.slot))
                                
                                local amt_str = formatNumber(entry.data.amount) .. u8" шт."
                                local asz = GetStaticTextSize(amt_str)
                                local badge_w = asz.x + S(16)
                                local badge_h = S(24)
                                local badge_x = ip.x + iw - badge_w - S(10)
                                local badge_y = ip.y + (ih - badge_h) / 2
                                
                                dl:AddRectFilled(imgui.ImVec2(badge_x, badge_y), imgui.ImVec2(badge_x + badge_w, badge_y + badge_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main), S(12))
                                dl:AddText(imgui.ImVec2(badge_x + S(8), badge_y + (badge_h - asz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), amt_str)
                                
                                if is_hov then
                                    local avg = getAveragePriceForItem(entry.data, "sell")
                                    if avg and avg > 0 then
                                        imgui.SetTooltip(u8"Примерная рыночная цена: " .. formatMoney(avg) .. " $")
                                    else
                                        imgui.SetTooltip(u8"Нет данных о цене")
                                    end
                                end
                                
                                imgui.SetCursorScreenPos(imgui.ImVec2(0, ip.y + ih + S(6)))
                            end
                        end
                        
                        if end_idx < total_items then
                            local remaining = total_items - end_idx
                            imgui.SetCursorPosY(imgui.GetCursorPosY() + (remaining * (ih + S(6))))
                        end
                        imgui.Dummy(imgui.ImVec2(0, S(10)))
                    end)
                    imgui.PopStyleColor()
                end
            end
        imgui.EndChild()
        imgui.PopStyleVar()

        imgui.Columns(1)
    end
end

imgui.OnFrame(
    function()
        return App.script_loaded and isSampAvailable() and sampIsLocalPlayerSpawned() and not isGamePaused()
    end,
    function(this)
        GLOBAL_FRAME_TIME = os.clock()
        processImageLoaderQueue() -- Убран pcall, он здесь не нужен и вызывает оверхед
        
        local is_interactive_menu = App.win_state[0] or App.show_tutorial or App.show_config_manager or App.show_sell_config_manager or App.show_config_selector or ShareState.modal_active or App.show_gen_config_modal or App.show_update_alert or VipData.show_graph_modal or App.show_car_sell_dialog_overlay

        -- Стабильный механизм mimgui для управления курсором (без ручных if-проверок)
        this.HideCursor = not is_interactive_menu

        -- === ФОНОВЫЙ РЕНДЕР ===
        pcall(drawRadiusGraphics)
        pcall(renderToastNotifications)
        pcall(renderItemPriceOverlay)
        pcall(renderMagnetOverlay)
        pcall(renderUndoSnackbar)
        pcall(renderRadialMenuOverlay) 
        pcall(renderLiveProfitHUD)

        -- Объединяем флаги фоновых процессов и активного меню
        local is_ui_active = is_interactive_menu or State.buying.active or App.is_selling_cef or (App.remote_shop_active and Data.settings.show_remote_shop_menu) or App.is_removing_sale or App.is_removing_buy

        -- Если ничего не требует отрисовки (ни меню, ни процессы), прерываем рендер
        if not is_ui_active then return end
        
        -- [NEW] Окно критического обновления
        if App.show_update_alert then
            renderUpdateAlertWindow()
            return
        end

        -- [NEW] Окно помощника при выставлении авто на АБ
        if App.show_car_sell_dialog_overlay then
            renderCarSellOverlay()
            -- Мы не делаем return, так как меню может работать поверх других
        end

        -- [NEW] ПРИОРИТЕТНОЕ ОТОБРАЖЕНИЕ ТУТОРИАЛА
        if App.show_tutorial then
            renderTutorialWindow()
            -- Если идет туториал, мы НЕ рисуем основное окно и другие окна
            -- Поэтому делаем return, чтобы прервать выполнение функции OnFrame для других окон
            return 
        end
		
        if App.show_config_selector then
            renderConfigSelectorModal()
        end
        
        if App.show_config_manager then
            renderConfigManagerWindow()
        end
		
		if App.show_sell_config_manager then
			renderSellConfigManager()
		end

        if App.show_gen_config_modal then
            renderGenConfigModal()
        end
        
        -- Глобальный вызов окна графика (поверх всего)
        if VipData.show_graph_modal then
            renderPriceGraphModal()
        end
        
        if App.remote_shop_active and Data.settings.show_remote_shop_menu then
            renderRemoteShopWindow()

            
            if not App.win_state[0] then
                return
            end
        end

        
        
        if App.is_removing_sale then
            local left = Data.removal_queue and #Data.removal_queue or 0
            
            renderMiniProcessWindow(
                "СНЯТИЕ ТОВАРОВ",
                "Очищаю витрину...",
                "В очереди: " .. left,
                function()
                    stopSaleRemoval()
                end
            )
            return
        end

		if App.is_removing_buy then
            local left = Data.removal_queue and #Data.removal_queue or 0
            renderMiniProcessWindow(
                "СНЯТИЕ СКУПКИ",
                "Очищаю список скупки...",
                "Осталось слотов: " .. left,
                function()
                    stopBuyRemoval()
                end
            )
            return
        end
        
        if State.buying.active then
            local title = "ВЫСТАВЛЕНИЕ СКУПКИ"
            local status = "Выставляю товары..."
            local current_idx = State.buying.current_item_index or 0
            local total = State.buying.items_to_buy and #State.buying.items_to_buy or 0
            
            local progress = string.format(
                "Товар: %d / %d",
                current_idx,
                total
            )

            if State.buying.waiting_for_alt then
                title = "ОЖИДАНИЕ ЛАВКИ"
                status = "Подойдите к лавке и нажмите ALT!"
                progress = "Ожидание диалога..."
            end

            renderMiniProcessWindow(
                title,
                status,
                progress,
                function()
                    stopBuying()
                    App.win_state[0] = true
                end
            )
            return
        end

        
        if App.is_selling_cef then
            local current_idx = App.current_sell_item_index or 0
            local queue_size = (Data.cef_sell_queue and #Data.cef_sell_queue) or 0
            local total = queue_size + (App.current_processing_item and 1 or 0)

            renderMiniProcessWindow(
                "ВЫСТАВЛЕНИЕ ПРОДАЖИ",
                "Выставляю товары...",
                string.format("Товар: %d / %d", current_idx, total),
                function()
                    stopSelling()
                    App.win_state[0] = true
                end
            )
            return
        end

        
        
        
        if not App.win_state[0] then
            return
        end

        
        
        
        local io = imgui.GetIO()
        local sw, sh = io.DisplaySize.x, io.DisplaySize.y

        
        local base_w, base_h = 1000, 650

        local scaled_w = math.floor(base_w * CURRENT_SCALE)
        local scaled_h = math.floor(base_h * CURRENT_SCALE)

        
        if scaled_w > sw * 0.95 then scaled_w = math.floor(sw * 0.95) end
        if scaled_h > sh * 0.95 then scaled_h = math.floor(sh * 0.95) end

        
        if scaled_w < 800 then scaled_w = 800 end
        if scaled_h < 500 then scaled_h = 500 end

        
        local size_cond = imgui.Cond.FirstUseEver
        if Data.force_window_resize then
            size_cond = imgui.Cond.Always
            Data.force_window_resize = false
        end

        imgui.SetNextWindowSize(
            imgui.ImVec2(scaled_w, scaled_h),
            size_cond
        )

        -- [ОПТИМИЗАЦИЯ FPS] Удалена ручная калькуляция перетаскивания окна.
        -- Постоянный вызов imgui.SetNextWindowPos с Cond.Always вызывал лаги 
        -- и перестройку геометрии каждый кадр (просадки со 120 до 70 фпс).

        -- Анимация для выезжающего меню автобазара
        local target_car_anim = App.show_car_menu and 1.0 or 0.0
        local last_anim_state = App.car_menu_anim
        App.car_menu_anim = App.car_menu_anim + (target_car_anim - App.car_menu_anim) * imgui.GetIO().DeltaTime * 12.0

        -- Базовая позиция окна (устанавливается только при первом открытии)
        local base_window_pos = imgui.ImVec2(
            (sw - scaled_w) * 0.5,
            (sh - scaled_h) * 0.5
        )
        imgui.SetNextWindowPos(base_window_pos, imgui.Cond.FirstUseEver)

        local main_rounding = S(12) -- Задаем степень скругления окна
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, main_rounding) -- Скругляем само окно
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0)
        imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, 0)

        imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
        imgui.PushStyleColor(imgui.Col.Text, CURRENT_THEME.text_primary)
        imgui.PushStyleColor(imgui.Col.TextDisabled, CURRENT_THEME.text_hint)

        -- Окно БЕЗ флага NoMove, чтобы встроенный механизм ImGui мог управлять движением
        if imgui.Begin("Rodina Market", App.win_state,
        imgui.WindowFlags.NoCollapse + 
        imgui.WindowFlags.NoTitleBar + 
        imgui.WindowFlags.NoResize) then
        
        -- [ОПТИМИЗАЦИЯ FPS] Сдвигаем окно только во время анимации бокового меню
        if math.abs(App.car_menu_anim - last_anim_state) > 0.001 then
            local shift_diff = (App.car_menu_anim - last_anim_state) * S(440) / 2
            local cur_pos = imgui.GetWindowPos()
            imgui.SetWindowPosVec2(imgui.ImVec2(cur_pos.x - shift_diff, cur_pos.y))
        end

        local window_pos = imgui.GetWindowPos()
        local window_size = imgui.GetWindowSize()
        
        renderCustomHeader(window_size)
        
        -- Минималистичная панель вкладок (Высота всего S(36))
        local tab_h = S(36)
        
        -- [ИСПРАВЛЕНИЕ] Выносим PushStyleColor ПЕРЕД BeginChild, чтобы фон применился к панели
        imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
        imgui.BeginChild("Tabs", imgui.ImVec2(window_size.x, tab_h), false, imgui.WindowFlags.NoScrollbar)
            
            local visible_tabs = {}
            for _, t in ipairs(tabs) do
                if t.id ~= 7 or Data.is_vip then table.insert(visible_tabs, t) end
            end

            local tab_count = #visible_tabs
            local draw_list = imgui.GetWindowDrawList()
            local p = imgui.GetCursorScreenPos()
            
            -- Выравнивание вкладок по центру
            local padding_x = S(24)
            local item_spacing_x = S(4)
            local tabs_area_w = window_size.x - (padding_x * 2)
            local tab_w = (tabs_area_w - (item_spacing_x * (tab_count - 1))) / tab_count
            
            imgui.SetCursorPos(imgui.ImVec2(padding_x, 0))
            
            for i, tab in ipairs(visible_tabs) do
                local is_active = (App.active_tab == tab.id)
                local tab_p = imgui.GetCursorScreenPos()
                
                -- Прозрачная невидимая кнопка
                local clicked = imgui.InvisibleButton("##tab_"..i, imgui.ImVec2(tab_w, tab_h))
                local hovered = imgui.IsItemHovered()
                if clicked then App.active_tab = tab.id end
                
                -- [ОПТИМИЗАЦИЯ FPS] Используем предрассчитанные U32 цвета вместо генерации ImVec4
                local u32_col = is_active and CURRENT_THEME.text_primary_u32 or CURRENT_THEME.text_secondary_u32
                
                if hovered and not is_active then 
                    -- Если навели мышь, просто используем белый цвет с небольшой прозрачностью поверх основного
                    -- Это дает эффект осветления без тяжелой математики
                    u32_col = CURRENT_THEME.text_primary_u32
                end
                
                -- Отрисовка фона при наведении (адаптивно)
                if hovered and not is_active then
                    -- Если фон светлый, делаем ховер темнее, если темный - светлее
                    local h_alpha = (CURRENT_THEME.bg_main.x > 0.5) and 0.05 or 0.08
                    local h_color = (CURRENT_THEME.bg_main.x > 0.5) and 0 or 1
                    draw_list:AddRectFilled(tab_p, imgui.ImVec2(tab_p.x + tab_w, tab_p.y + tab_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(h_color, h_color, h_color, h_alpha)), S(4))
                end

                -- Отрисовка полоски снизу для активной вкладки
                if is_active then
                    draw_list:AddRectFilled(imgui.ImVec2(tab_p.x + S(10), tab_p.y + tab_h - S(2)), imgui.ImVec2(tab_p.x + tab_w - S(10), tab_p.y + tab_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary))
                end
                
                -- Отрисовка контента по центру
                local icon_str = tab.icon or ""
                local name_str = u8(tab.name)
                
                local icon_sz = {x=0, y=0}
                if font_fa then
                    imgui.PushFont(font_fa)
                    icon_sz = GetStaticTextSize(icon_str)
                    imgui.PopFont()
                end
                local text_sz = GetStaticTextSize(name_str)
                
                local content_w = icon_sz.x + (icon_sz.x > 0 and S(8) or 0) + text_sz.x
                local content_x = tab_p.x + (tab_w - content_w) / 2
                
                if font_fa and icon_sz.x > 0 then
                    imgui.PushFont(font_fa)
                    draw_list:AddText(imgui.ImVec2(content_x, tab_p.y + (tab_h - icon_sz.y)/2), u32_col, icon_str)
                    imgui.PopFont()
                    content_x = content_x + icon_sz.x + S(8)
                end
                draw_list:AddText(imgui.ImVec2(content_x, tab_p.y + (tab_h - text_sz.y)/2), u32_col, name_str)
                
                if i < tab_count then imgui.SameLine(0, item_spacing_x) end
            end
            
        imgui.EndChild()
        imgui.PopStyleColor() -- Возвращаем вынесенный PopStyleColor
        
        -- Тонкий разделитель на всю ширину окна под вкладками
        local dl_sep = imgui.GetWindowDrawList()
        local p_sep = imgui.GetCursorScreenPos()
        dl_sep:AddLine(imgui.ImVec2(p_sep.x, p_sep.y), imgui.ImVec2(p_sep.x + window_size.x, p_sep.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
        imgui.Dummy(imgui.ImVec2(0, S(2))) -- Микро-отступ
        
        -- Убираем зазор между вкладками и контентом, но сохраняем нормальные отступы для контента
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(10)))
        imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
        
        local content_size = imgui.GetContentRegionAvail()
        if content_size.y < 1 then content_size.y = 1 end
        
        imgui.BeginChild("Content", content_size, false, imgui.WindowFlags.NoScrollbar)
            
            if App.active_tab == 1 then
                
                if countTable(Data.item_names) < 10 then
                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
                    
                    imgui.BeginChild("EmptyDBFullOverlay", imgui.GetContentRegionAvail(), false)
                        
                        renderEmptyState(
                            fa('triangle_exclamation'), 
                            "База предметов пуста", 
                            "Скрипту нужно узнать ID предметов.\n1. Арендуйте СВОБОДНУЮ лавку.\n2. Нажмите кнопку ниже.\n3. Дождитесь конца сканирования.",
                            "Начать сканирование", 
                            function() App.active_tab = 2 end 
                        )
                        
                    imgui.EndChild()
                    imgui.PopStyleVar()
                else
                    local avail_w = imgui.GetContentRegionAvail().x
                    local avail_h = imgui.GetContentRegionAvail().y

                    if not Data.cached_sell_filtered or ffi.string(Buffers.sell_search) ~= Data.last_sell_search_str then
                        Data.last_sell_search_str = ffi.string(Buffers.sell_search)
                        Data.cached_sell_filtered = filterList(Data.scanned_items, Buffers.sell_search)
                    end
                    local filtered_items = Data.cached_sell_filtered
                    local sell_total = calculateSellTotal()

                    imgui.Spacing()
                    imgui.Columns(2, "##sale_content", true)
                    imgui.SetColumnWidth(0, avail_w * 0.4)

                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(12), S(12)))
                    local left_panel_height = avail_h - S(25)
                    
                    imgui.BeginChild("ScannedItemsPanel", imgui.ImVec2(0, left_panel_height), true, imgui.WindowFlags.NoScrollbar)
						imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
						
						-- === НОВЫЙ ХЕДЕР ИНВЕНТАРЯ (MINIMAL) ===
						local p = imgui.GetCursorScreenPos()
						local panel_w = imgui.GetContentRegionAvail().x
						local header_h = S(40) -- Чуть тоньше
						local dl = imgui.GetWindowDrawList()

						-- 1. Чистый темный фон заголовка (Никаких цветных плашек)
						dl:AddRectFilled(p, imgui.ImVec2(p.x + panel_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(6))

						-- 2. Иконка и Текст (Слева)
						local center_y = p.y + header_h / 2
						local left_padding = S(15)
						local title_icon = fa('box_open')
						local icon_sz = S(0)
						
						if font_fa then
							imgui.PushFont(font_fa)
							icon_sz = GetStaticTextSize(title_icon).x
							local i_sz_y = GetStaticTextSize(title_icon).y
							dl:AddText(imgui.ImVec2(p.x + left_padding, center_y - i_sz_y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), title_icon)
							imgui.PopFont()
						end

						local current_cat_name = inv_category_list_ui[inv_category_filter_idx + 1] or u8"Мой инвентарь"
						if inv_category_filter_idx == 0 then current_cat_name = u8"Мой инвентарь" end

						local t_sz_y = GetStaticTextSize(current_cat_name).y
						dl:AddText(imgui.ImVec2(p.x + left_padding + icon_sz + S(8), center_y - t_sz_y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), current_cat_name)

						-- 3. КНОПКИ СПРАВА (Строгие, монохромные)
						local btn_sz = S(28)
						local right_padding = S(10)
                        local gap = S(4)
                        
                        -- == Кнопка ФИЛЬТРА ==
						local filter_btn_x = p.x + panel_w - btn_sz - right_padding
						local filter_btn_y = center_y - btn_sz / 2
						
						imgui.SetCursorScreenPos(imgui.ImVec2(filter_btn_x, filter_btn_y))
						if imgui.InvisibleButton("##inv_filter_toggle", imgui.ImVec2(btn_sz, btn_sz)) then
							imgui.OpenPopup("InvCategoryFilterPopup")
						end

						local is_filter_hovered = imgui.IsItemHovered()
						local is_active_filter = (inv_category_filter_idx ~= 0)
						-- Активный фильтр подсвечиваем белым, неактивный - серым
						local filter_icon_col = is_active_filter and CURRENT_THEME.text_primary or CURRENT_THEME.text_hint
						local filter_bg_col = is_filter_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.08)) or 0
						
						if filter_bg_col ~= 0 then dl:AddRectFilled(imgui.ImVec2(filter_btn_x, filter_btn_y), imgui.ImVec2(filter_btn_x + btn_sz, filter_btn_y + btn_sz), filter_bg_col, S(6)) end

						if font_fa then
							imgui.PushFont(font_fa)
							local filter_icon = is_active_filter and fa('filter_circle_xmark') or fa('filter')
							local f_sz = GetStaticTextSize(filter_icon)
							dl:AddText(imgui.ImVec2(filter_btn_x + (btn_sz - f_sz.x)/2, filter_btn_y + (btn_sz - f_sz.y)/2), imgui.ColorConvertFloat4ToU32(filter_icon_col), filter_icon)
							imgui.PopFont()
						end
                        
                        -- == Кнопка ДОБАВИТЬ ВСЁ ==
                        local add_all_x = filter_btn_x - btn_sz - gap
                        imgui.SetCursorScreenPos(imgui.ImVec2(add_all_x, filter_btn_y))
                        if imgui.InvisibleButton("##add_all_btn", imgui.ImVec2(btn_sz, btn_sz)) then addAllToSell() end
                        
                        local is_add_hovered = imgui.IsItemHovered()
                        local add_bg_col = is_add_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.08)) or 0
                        local add_icon_col = is_add_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_hint
                        
                        if add_bg_col ~= 0 then dl:AddRectFilled(imgui.ImVec2(add_all_x, filter_btn_y), imgui.ImVec2(add_all_x + btn_sz, filter_btn_y + btn_sz), add_bg_col, S(6)) end
                        
                        if font_fa then
                            imgui.PushFont(font_fa)
                            local add_icon = fa('angles_right')
                            local a_sz = GetStaticTextSize(add_icon)
                            dl:AddText(imgui.ImVec2(add_all_x + (btn_sz - a_sz.x)/2, filter_btn_y + (btn_sz - a_sz.y)/2), imgui.ColorConvertFloat4ToU32(add_icon_col), add_icon)
                            imgui.PopFont()
                        end

						-- == MAGIC AUTO-SETUP (Минимализм) ==
                        local magic_w = S(140)
                        local magic_x = add_all_x - magic_w - gap
                        
                        imgui.SetCursorScreenPos(imgui.ImVec2(magic_x, filter_btn_y))
                        if imgui.InvisibleButton("##magic_setup_btn", imgui.ImVec2(magic_w, btn_sz)) then addAllToSell() end
                        
                        local is_magic_hovered = imgui.IsItemHovered()
                        local magic_bg = is_magic_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.08)) or 0
                        if magic_bg ~= 0 then dl:AddRectFilled(imgui.ImVec2(magic_x, filter_btn_y), imgui.ImVec2(magic_x + magic_w, filter_btn_y + btn_sz), magic_bg, S(6)) end
                        
                        if font_fa then
                            imgui.PushFont(font_fa)
                            local m_icon = fa('wand_magic_sparkles')
                            local i_sz = GetStaticTextSize(m_icon)
                            imgui.PopFont()
                            
                            local m_txt = u8"Авто-сборка"
                            local t_sz = GetStaticTextSize(m_txt)
                            local icon_spacing = S(8)
                            local total_cw = i_sz.x + icon_spacing + t_sz.x
                            local start_cx = magic_x + (magic_w - total_cw) / 2
                            
                            local text_col = imgui.ColorConvertFloat4ToU32(is_magic_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary)
                            
                            imgui.PushFont(font_fa)
                            dl:AddText(imgui.ImVec2(start_cx, filter_btn_y + (btn_sz - i_sz.y)/2), text_col, m_icon)
                            imgui.PopFont()
                            dl:AddText(imgui.ImVec2(start_cx + i_sz.x + icon_spacing, filter_btn_y + (btn_sz - t_sz.y)/2), text_col, m_txt)
                        end

						-- 4. ВЫПАДАЮЩЕЕ МЕНЮ (Категории)
						imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
						imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_secondary)
						imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
						imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(6))
						
						if imgui.BeginPopup("InvCategoryFilterPopup") then
							local popup_width = S(240)
							local function DrawInvFilterItem(label_utf8, is_selected)
								local p_item = imgui.GetCursorScreenPos()
								local item_h = S(36)
								local clicked = imgui.InvisibleButton("##inv_"..label_utf8, imgui.ImVec2(popup_width, item_h))
								local is_hov = imgui.IsItemHovered()
								local dl_item = imgui.GetWindowDrawList()
								
								if is_selected then
									dl_item:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_width, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.08)))
								elseif is_hov then
									dl_item:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_width, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.03)))
								end
								
								local text_col = is_selected and CURRENT_THEME.text_primary or CURRENT_THEME.text_secondary
								local t_sz = GetStaticTextSize(label_utf8)
								dl_item:AddText(imgui.ImVec2(p_item.x + S(15), p_item.y + (item_h - t_sz.y)/2), imgui.ColorConvertFloat4ToU32(text_col), label_utf8)
								return clicked
							end

							if DrawInvFilterItem(u8"Все категории", (inv_category_filter_idx == 0)) then
								inv_category_filter_idx = 0
								refresh_inventory_display = true
								imgui.CloseCurrentPopup()
							end
							
							local p_sep = imgui.GetCursorScreenPos()
							imgui.GetWindowDrawList():AddLine(imgui.ImVec2(p_sep.x, p_sep.y), imgui.ImVec2(p_sep.x + popup_width, p_sep.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
							imgui.Dummy(imgui.ImVec2(0, 1))
							
							imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0)) 
							local content_h = math.min(#inv_category_list_ui * S(36), S(350))
							
							if imgui.BeginChild("InvFilterListInner", imgui.ImVec2(popup_width, content_h), false) then
								for i, cat_name_utf8 in ipairs(inv_category_list_ui) do
									if i > 1 then
										if DrawInvFilterItem(cat_name_utf8, (inv_category_filter_idx == i - 1)) then
											inv_category_filter_idx = i - 1
											refresh_inventory_display = true
											imgui.CloseCurrentPopup()
										end
									end
								end
							end
							imgui.EndChild()
							imgui.PopStyleColor()
							imgui.EndPopup()
						end
						imgui.PopStyleVar(2)
						imgui.PopStyleColor(2)

						imgui.SetCursorPosY(header_h) -- Сдвиг контента под хедер

						-- ... Далее идет рендер списка инвентаря ...
						if #Data.scanned_items == 0 then
                            renderEmptyState(
                                fa('box_open'),
                                "Инвентарь не загружен",
                                "Скрипт должен прочитать ваш инвентарь.\nНажмите кнопку ниже - он сам откроет и считает предметы.",
                                "Сканировать инвентарь",
                                function() startScanning() end
                            )
                        else
                            -- [FIX] 2. Устанавливаем темный (bg_main) фон для самого списка товаров
                            imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
							renderSmoothScrollBox("ScannedItemsScroll", imgui.ImVec2(0, 0), function()
								-- [INNOVATION] КЭШИРОВАНИЕ ИНВЕНТАРЯ (УБИВАЕТ ЛАГИ)
								if not App.inv_ui_cache then App.inv_ui_cache = { search = nil, cat = nil, list = {}, locks = 0 } end
								
								local selected_cat_raw = inv_category_list_raw[inv_category_filter_idx + 1]
								local is_all_cats = (inv_category_filter_idx == 0)
								
								local search_q = ffi.string(Buffers.sell_search)
								local search_decoded = (search_q ~= "") and to_lower(u8:decode(search_q)) or ""
                                
                                -- Генерируем хэш блокировок для обновления, если замок был снят/навешен
                                local current_locks = countTable(Data.locked_items)

                                -- Проверяем, нужно ли делать тяжелую фильтрацию и сортировку (добавлен UIFilters.refresh_inventory_display)
                                if UIFilters.refresh_inventory_display or App.inv_ui_cache.search ~= search_decoded or App.inv_ui_cache.cat ~= inv_category_filter_idx or App.inv_ui_cache.locks ~= current_locks then
                                    UIFilters.refresh_inventory_display = false -- Сбрасываем триггер
    								local filtered_inv = {}
    								for _, item in ipairs(Data.scanned_items) do
                                        -- [FPS ОПТИМИЗАЦИЯ] Предрасчет тяжелых строк
                                        if not item._unique_key then
                                            item._unique_key = tostring(item.model_id) .. "_" .. tostring(item.slot)
                                            item._model_str = tostring(item.model_id)
                                            item._is_rented = (item.time and tonumber(item.time) > 0)
                                            
                                            local n, q = (item.name or ""):match("^(.-)%s*(%(x%d+%))$")
                                            local name_part = n or item.name or ""
                                            item._u8_qty_part = q and u8(" " .. q) or ""
                                            
                                            item._u8_base_name = u8(name_part)
                                            item._u8_locked_name = u8("[LOCK] " .. name_part)
                                        end

    									-- 1. Фильтр по категории
    									local cat_match = is_all_cats
    									if not cat_match then
    										local item_cat = "Предмет"
    										if item.model_id and Data.item_categories[tostring(item.model_id)] then
    											item_cat = Data.item_categories[tostring(item.model_id)]
    										elseif item.name then
    											item_cat = extractCategory(item.name)
    										end
    										cat_match = (item_cat == selected_cat_raw)
    									end
    									
    									-- 2. Фильтр по поиску
    									local name_match = true
    									if search_decoded ~= "" then
    										name_match = to_lower(item.name):find(search_decoded, 1, true)
    									end
    									
    									if cat_match and name_match then
    										table.insert(filtered_inv, item)
    									end
    								end
    								
                                    -- СОРТИРОВКА (Выполняется только 1 раз при смене поиска!)
                                    table.sort(filtered_inv, function(a, b)
                                        local key_a = tostring(a.model_id) .. "_" .. tostring(a.slot)
                                        local key_b = tostring(b.model_id) .. "_" .. tostring(b.slot)
                                        
                                        local locked_a = Data.locked_items[key_a] and 1 or 0
                                        local locked_b = Data.locked_items[key_b] and 1 or 0
                                        
                                        if locked_a ~= locked_b then return locked_a < locked_b end
                                        return (tonumber(a.slot) or 0) < (tonumber(b.slot) or 0)
                                    end)
                                    
                                    App.inv_ui_cache.search = search_decoded
                                    App.inv_ui_cache.cat = inv_category_filter_idx
                                    App.inv_ui_cache.list = filtered_inv
                                    App.inv_ui_cache.locks = current_locks
                                end
								
                                local filtered_inv = App.inv_ui_cache.list
                                
                                imgui.Dummy(imgui.ImVec2(0, S(5))) -- [FIX] Добавляем отступ от хедера
                                
								-- РЕНДЕР СПИСКА (ПРОФЕССИОНАЛЬНЫЙ C++ CLIPPER)
								local item_h_real = S(42) + S(6)
								imgui.SetCursorPosY(imgui.GetCursorPosY() + S(5))

								local clipper = imgui.ImGuiListClipper(#filtered_inv)
								while clipper:Step() do
									for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
										local item = filtered_inv[i]
										if item then
											imgui.PushIDInt(i)
											
											-- [ОПТИМИЗАЦИЯ] Кэшируем вызов цены инвентаря на 2 секунды
											local now_inv = os.clock()
											if not item._inv_price_check or (now_inv - item._inv_price_check > 2.0) then
												item._cached_has_avg = getAveragePriceForItem(item, "sell")
												item._inv_price_check = now_inv
											end
											
											-- [FAST CHECK] Проверка через прямой доступ к хэш-таблице (мгновенно, 0 аллокаций)
											local is_added = Data.sell_lookup and Data.sell_lookup[item._unique_key] == true
											
											local count_in_sell = Data.sell_count_lookup and Data.sell_count_lookup[item._model_str] or 0
											local is_rented = item._is_rented
											local has_avg = item._cached_has_avg
											
											local is_locked = Data.locked_items[item._unique_key]

											local p = imgui.GetCursorScreenPos()
											local w = imgui.GetContentRegionAvail().x
											local h = S(42)

											imgui.SetCursorScreenPos(p)
											
											-- === ЛОГИКА КЛИКА (OPTIMIZED) ===
											if imgui.InvisibleButton("##scan_btn_" .. i, imgui.ImVec2(w, h)) then
												if is_rented then
													addToastNotification("Нельзя продать арендованный товар!", "warning")
												elseif is_locked then
													addToastNotification("Предмет заблокирован! (ПКМ для разблокировки)", "error")
												else
													local current_added_status = isSlotInSellList(item.slot, item.model_id)
													
													if current_added_status then
														-- УДАЛЕНИЕ: Ищем с конца для безопасного удаления
														for k = #Data.sell_list, 1, -1 do
															local v = Data.sell_list[k]
															if tonumber(v.model_id) == tonumber(item.model_id) and tonumber(v.slot) == tonumber(item.slot) then
																table.remove(Data.sell_list, k)
																break -- Удаляем строго один дубликат за клик
															end
														end
														addToastNotification("Товар убран из списка", "info", 1.0)
													else
														-- ДОБАВЛЕНИЕ
														table.insert(Data.sell_list, {
															name = item.original_name or item.name,
															price = 0,
															amount = item.amount or 1,
															model_id = item.model_id, 
															slot = item.slot, 
															missing = false, 
															active = true,
															auto_max = true
														})
														addToastNotification("Товар добавлен к продаже", "success", 1.0)
														triggerScrollToBottom("SellItemsScroll")
													end
													
													-- [CRITICAL FIX] СИНХРОННОЕ ОБНОВЛЕНИЕ КЭША!
													rebuildLookupTables() 
													calculateSellTotal()
													App.sell_ui_cache = nil -- Очистка визуального кэша списка конфига
													
													saveListsConfig()
												end
											end
											
											-- ПКМ: Блокировка/Разблокировка
											if imgui.IsItemClicked(1) then
												toggleItemLock(item)
											end
											-- ===================================================

											local is_hovered = imgui.IsItemHovered()
											
											-- Тултипы
											if is_rented and is_hovered then
												imgui.SetTooltip(u8("Товар находится в аренде.\nЕго невозможно выставить на продажу."))
											elseif is_locked and is_hovered then
												imgui.SetTooltip(u8("ЗАБЛОКИРОВАНО.\nНажмите ПКМ, чтобы снять замок."))
											elseif not is_added and has_avg and is_hovered then
												 imgui.SetTooltip(u8("Доступна средняя цена: ") .. formatMoney(has_avg) .. " $\n" .. u8("Нажмите ПКМ, чтобы заблокировать."))
											elseif is_hovered then
												 imgui.SetTooltip(u8("Нажмите ПКМ, чтобы заблокировать предмет."))
											end

											local bg_col = 0
											
											if is_locked then
												-- Используем danger цвет с очень сильной прозрачностью для блока
												bg_col = setAlphaU32(CURRENT_THEME.accent_danger_u32, 0.15)
											elseif is_added then
												bg_col = setAlphaU32(CURRENT_THEME.accent_success_u32, 0.2)
											elseif is_rented then
												bg_col = setAlphaU32(CURRENT_THEME.accent_warning_u32, 0.15)
											elseif is_hovered then
												bg_col = CURRENT_THEME.bg_tertiary_u32
											else 
												bg_col = CURRENT_THEME.bg_secondary_u32
											end

											if bg_col ~= 0 then
												imgui.GetWindowDrawList():AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + h), bg_col, S(6))
											end

											local item_center_y = p.y + h / 2

											-- 1. Рендерим новый круговой индикатор статуса
											local item_state = "idle"
											if is_locked then item_state = "locked"
											elseif is_rented then item_state = "rented"
											elseif is_added then item_state = "added"
											elseif has_avg then item_state = "has_avg"
											end

											local indicator_radius = S(11)
											local indicator_center = imgui.ImVec2(p.x + S(14) + indicator_radius, item_center_y)
											
											renderInventoryStatusIndicator(imgui.GetWindowDrawList(), indicator_center, indicator_radius, item_state, is_hovered)

											-- 2. Рендерим контейнер для 3D/WEB Иконки предмета (AAA Style)
											local img_box_sz = S(34) -- Слегка увеличим для идеальных пропорций с кружком
											local img_box_x = indicator_center.x + indicator_radius + S(14)
											local img_box_y = item_center_y - img_box_sz / 2

											local box_min = imgui.ImVec2(img_box_x, img_box_y)
											local box_max = imgui.ImVec2(img_box_x + img_box_sz, img_box_y + img_box_sz)
											local box_rounding = S(8)

											local slot_bg_col = CURRENT_THEME.bg_main_u32
											imgui.GetWindowDrawList():AddRectFilled(box_min, box_max, slot_bg_col, box_rounding)

											local glow_col = setAlphaU32(CURRENT_THEME.accent_primary_u32, 0.15)
											imgui.GetWindowDrawList():AddRectFilled(box_min, box_max, glow_col, box_rounding)
											imgui.GetWindowDrawList():AddRect(box_min, box_max, CURRENT_THEME.border_light_u32, box_rounding, 15, S(1.5))

											-- Пытаемся получить текстуру с сервера
											local texture = getItemIconTexture(tonumber(item.model_id))

											if texture then
												local pad = S(3)
												local uv0 = imgui.ImVec2(0, 0)
												local uv1 = imgui.ImVec2(1, 1)
												
												local shadow_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0, 0, 0, 0.7))
												imgui.GetWindowDrawList():AddImage(
													texture, 
													imgui.ImVec2(box_min.x + pad, box_min.y + pad + S(2)), 
													imgui.ImVec2(box_max.x - pad, box_max.y - pad + S(2)),
													uv0, uv1, shadow_col
												)
												
												imgui.GetWindowDrawList():AddImage(
													texture, 
													imgui.ImVec2(box_min.x + pad, box_min.y + pad), 
													imgui.ImVec2(box_max.x - pad, box_max.y - pad)
												)
											else
												-- Skeleton Loading (Пульсирующая загрузка)
												local pulse = (math.sin(os.clock() * 6) + 1) * 0.5
												local alpha = 0.05 + (pulse * 0.15)
												imgui.GetWindowDrawList():AddRectFilled(
													imgui.ImVec2(box_min.x + S(4), box_min.y + S(4)), 
													imgui.ImVec2(box_max.x - S(4), box_max.y - S(4)), 
													imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, alpha)), S(6)
												)
											end

											-- 3. Смещаем текст правее иконки
											local label_x = img_box_x + img_box_sz + S(12)
											local text_y = item_center_y - imgui.GetFontSize() / 2

											local text_color = CURRENT_THEME.text_primary_u32
											if is_added then text_color = CURRENT_THEME.text_secondary_u32 end
											if is_rented or is_locked then text_color = CURRENT_THEME.text_hint_u32 end

											-- [CRASH FIX] Защита от nil: Гарантируем, что строки сгенерированы, 
											-- даже если предмет обновился в обход цикла фильтрации.
											if not item._u8_base_name then
												item._unique_key = tostring(item.model_id) .. "_" .. tostring(item.slot)
												item._model_str = tostring(item.model_id)
												item._is_rented = (item.time and tonumber(item.time) > 0)
												
												local n, q = (item.name or ""):match("^(.-)%s*(%(x%d+%))$")
												local name_part = n or item.name or ""
												item._u8_qty_part = q and u8(" " .. q) or ""
												
												item._u8_base_name = u8(name_part)
												item._u8_locked_name = u8("[LOCK] " .. name_part)
											end

											local final_name_u8 = is_locked and item._u8_locked_name or item._u8_base_name
											
											-- Рисуем ИМЯ товара
											imgui.GetWindowDrawList():AddText(imgui.ImVec2(label_x, text_y), text_color, final_name_u8)
											
											local current_x = label_x + GetStaticTextSize(final_name_u8).x
											
											-- Рисуем КОЛИЧЕСТВО (x...) приглушенным цветом (добавлена защита от nil)
											if item._u8_qty_part and item._u8_qty_part ~= "" then
												local qty_col = (is_added or is_rented or is_locked) and text_color or CURRENT_THEME.text_hint_u32
												imgui.GetWindowDrawList():AddText(imgui.ImVec2(current_x, text_y), qty_col, item._u8_qty_part)
												current_x = current_x + GetStaticTextSize(item._u8_qty_part).x
											end

											if count_in_sell > 0 and not is_added then 
                                                -- Кэшируем на лету
                                                if not item["_u8_suf_"..count_in_sell] then item["_u8_suf_"..count_in_sell] = u8(" (еще " .. count_in_sell .. ")") end
                                                imgui.GetWindowDrawList():AddText(imgui.ImVec2(current_x, text_y), CURRENT_THEME.text_hint_u32, item["_u8_suf_"..count_in_sell])
                                                current_x = current_x + GetStaticTextSize(item["_u8_suf_"..count_in_sell]).x
                                            end
                                            
											if is_rented then 
                                                if not item._u8_rent_suf then item._u8_rent_suf = u8(" (Аренда)") end
                                                imgui.GetWindowDrawList():AddText(imgui.ImVec2(current_x, text_y), CURRENT_THEME.text_hint_u32, item._u8_rent_suf)
                                            end

											imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + h + S(6)))
											imgui.PopID()
										end
									end
								end
							end)
							imgui.PopStyleColor()
						end
						imgui.PopStyleColor()
					imgui.EndChild()
                    imgui.PopStyleVar()

                    imgui.NextColumn()

                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(12), S(12)))
                    local button_h = S(45) -- Увеличиваем высоту кнопок
                    local spacing_h = S(10)
                    local bottom_padding = S(20)
                    local button_area_h = button_h + spacing_h + bottom_padding
                    local right_panel_height = avail_h - button_area_h

                    imgui.BeginChild("SellListPanel", imgui.ImVec2(0, right_panel_height), true, imgui.WindowFlags.NoScrollbar)
                        -- [FIX] Прозрачный фон контейнера
