                        -- 1. ЛОГИКА ПОДСЧЕТА ПЛОХИХ ЦЕН
                        local bad_price_count = 0
                        
                        for i, it in ipairs(Data.sell_list) do
                            if it.active then
                                local p = tonumber(it.price) or 0
                                local avg = getAveragePriceForItem(it, "sell", true)
                                
                                -- Условие проблемы: Цена 0 ИЛИ Цена ниже рынка
                                local is_zero = (p == 0)
                                local is_low = (avg and avg > 0 and p > 0 and p < avg)
                                
                                if is_zero or is_low then
                                    bad_price_count = bad_price_count + 1
                                end
                            end
                        end
                        
                        -- Данные о деньгах
                        local current_player_money = getPlayerMoney()
                        local predicted_balance = current_player_money + sell_total

-- 2. ОТРИСОВКА ЗАГОЛОВКА (MINIMAL)
                        local p = imgui.GetCursorScreenPos()
                        local panel_w = imgui.GetContentRegionAvail().x
                        local header_h = S(40) 
                        local dl = imgui.GetWindowDrawList()

                        -- Фон заголовка (чистый)
