                        if imgui.InvisibleButton("##sell_tools_menu", imgui.ImVec2(btn_sz, btn_sz)) then imgui.OpenPopup("SellToolsPopup") end

                        local is_menu_hovered = imgui.IsItemHovered()
                        local menu_icon = bad_price_count > 0 and fa('triangle_exclamation') or fa('ellipsis_vertical')
                        local menu_col = bad_price_count > 0 and CURRENT_THEME.accent_danger or (is_menu_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_hint)
                        local menu_bg = is_menu_hovered and imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.08)) or 0
