                        local bal_x = div_x - bal_sz.x - S(10)
                        local bal_y = center_y + S(2) 
                        dl:AddText(imgui.ImVec2(bal_x, bal_y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), bal_str)
                        imgui.SetWindowFontScale(1.0)
                        imgui.PopFont()

                        -- 3. ВЫПАДАЮЩЕЕ МЕНЮ
                        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(10), S(10)))
                        imgui.PushStyleColor(imgui.Col.PopupBg, CURRENT_THEME.bg_secondary)
                        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding, S(6))
                        
                        if imgui.BeginPopup("SellToolsPopup") then
                            imgui.TextColored(CURRENT_THEME.text_secondary, u8"Управление списком")
                            imgui.Separator()
                            
                            local missing_count = 0
                            for _, it in ipairs(Data.sell_list) do if it.missing then missing_count = missing_count + 1 end end
                            
                            local trash_col = (missing_count > 0) and CURRENT_THEME.accent_danger or CURRENT_THEME.text_primary
                            imgui.PushStyleColor(imgui.Col.Text, trash_col)
                            if imgui.Selectable(u8"  " .. fa('ghost') .. u8"  Удалить отсутствующие (" .. missing_count .. ")") then
                                if missing_count > 0 then
                                    for i = #Data.sell_list, 1, -1 do
                                        if Data.sell_list[i].missing then
                                            setSlotAddedStatus(Data.sell_list[i].slot, Data.sell_list[i].model_id, false)
                                            table.remove(Data.sell_list, i)
                                        end
                                    end
                                    saveListsConfig()
                                    calculateSellTotal()
                                end
                            end
                            imgui.PopStyleColor()
                            
                            imgui.Dummy(imgui.ImVec2(0, S(5)))
                            imgui.TextColored(CURRENT_THEME.text_secondary, u8"Управление ценами")
                            imgui.Separator()

                            if imgui.Selectable(u8"  " .. fa('tags') .. u8"  Рыночные цены (Стандарт)") then applyAveragePrices(Data.sell_list, "sell", "normal") end
                            if imgui.Selectable(u8"  " .. fa('bolt') .. u8"  Быстрая продажа (Демпинг)") then applyAveragePrices(Data.sell_list, "sell", "fast_sell") end
                            if imgui.Selectable(u8"  " .. fa('gem') .. u8"  Максимальная прибыль") then applyAveragePrices(Data.sell_list, "sell", "max_profit") end
                            
                            imgui.Separator()

                            local fix_label = u8"  " .. fa('wrench') .. u8"  Исправить низкие"
                            local fix_col = CURRENT_THEME.text_primary
                            if bad_price_count > 0 then
                                fix_label = fix_label .. " (" .. bad_price_count .. ")"
                                fix_col = CURRENT_THEME.accent_warning
                            end
                            
                            imgui.PushStyleColor(imgui.Col.Text, fix_col)
                            if imgui.Selectable(fix_label) then applyAveragePrices(Data.sell_list, "sell", "fix_bad") end
                            imgui.PopStyleColor()

                            imgui.EndPopup()
                        end
                        imgui.PopStyleVar()
                        imgui.PopStyleColor()

                        -- 4. СДВИГ КУРСОРА ВНИЗ ДЛЯ СПИСКА
                        imgui.SetCursorPosY(header_h) 

                        -- 5. СПИСОК ТОВАРОВ
                        local list_height_avail = right_panel_height - header_h
                        
                        imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
                        renderSmoothScrollBox("SellItemsScroll", imgui.ImVec2(0, list_height_avail), function()
                            -- [FPS BOOST FIX] Кэшируем результаты поиска, чтобы не сжигать FPS каждый кадр
                            if not App.sell_ui_cache then App.sell_ui_cache = { hash = "", list = {} } end
                            
                            local search_q = ffi.string(Buffers.sell_search)
                            local current_hash = tostring(#Data.sell_list) .. "_" .. search_q
                            
                            if App.sell_ui_cache.hash ~= current_hash then
                                local new_display_list = {}
                                local is_searching = search_q ~= ""
                                
                                if is_searching then
                                    local decoded_q = to_lower(u8:decode(search_q))
                                    for i, item in ipairs(Data.sell_list) do
                                        if SmartSearch.getMatchScore(decoded_q, item.name) > 0 then
                                            table.insert(new_display_list, { data = item, real_idx = i })
                                        end
                                    end
                                else
                                    for i, item in ipairs(Data.sell_list) do
                                        table.insert(new_display_list, { data = item, real_idx = i })
                                    end
                                end
                                
                                App.sell_ui_cache.hash = current_hash
                                App.sell_ui_cache.list = new_display_list
                            end
                            
                            local display_list = App.sell_ui_cache.list
                            local is_searching = search_q ~= ""
                            
                            imgui.Dummy(imgui.ImVec2(0, S(5)))

                            if #display_list == 0 then
                                if is_searching then
                                    renderEmptyState(fa('magnifying_glass'), "Ничего не найдено", "Попробуйте изменить поисковый запрос.")
                                else
                                    renderEmptyState(
                                        fa('inbox'),
                                        "Список продажи пуст",
                                        "Нажмите на предметы в левой панели (Инвентарь), чтобы добавить их сюда."
                                    )
                                end
                            else
                                -- [FPS BOOST FIX] Заменяем тяжелый Lua-пересчет позиций на C++ ImGuiListClipper.
                                -- Это устраняет нагрузку на процессор и просадки FPS при скроллинге длинных списков.
                                -- [FIX] Убрали дублирующийся imgui.Dummy, чтобы отступ был нормальным
                                
                                local clipper = imgui.ImGuiListClipper(#display_list)
                                while clipper:Step() do
                                    for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
                                        local entry = display_list[i]
                                        if entry then
                                            renderUnifiedConfigItem(entry.real_idx, entry.data, "sell")
                                        end
                                    end
                                end
                            end
                            imgui.Dummy(imgui.ImVec2(0, S(5)))
                        end)
                        imgui.PopStyleColor(2) 

                    imgui.EndChild()
                    imgui.PopStyleVar()

                    local spacing = S(10)
