                local current_search = ffi.string(Buffers.buy_search)
                
                -- [NEW] Проверяем изменение поиска ИЛИ категории или первоначальное заполнение
                if BuyableItems.needs_refresh or current_search ~= BuyableItems.last_search_query or BuyableItems.force_refresh then 
                    BuyableItems.force_refresh = false
                    BuyableItems.needs_refresh = false
                    BuyableItems.last_search_query = current_search
                    BuyableItems.items = {}
                    
                    local query_utf8 = current_search
                    local query = ""
                    -- [FIX] Используем to_lower вместо :lower()
                    if query_utf8 ~= "" then query = to_lower(u8:decode(query_utf8)) end
                    
                    -- [NEW] Получаем выбранную категорию
                    local selected_cat_raw = buy_category_list_raw[buy_category_filter_idx + 1]
                    local is_all_cats = (buy_category_filter_idx == 0)
                    
                    for _, item in ipairs(Data.buyable_items) do 
                        -- 1. Фильтр по названию (Используем to_lower для имени предмета)
                        local name_match = (query == "") or to_lower(item.name):find(query, 1, true)
                        
                        -- 2. Фильтр по категории
                        local cat_match = is_all_cats
                        if not cat_match and item.category then
                            cat_match = (item.category == selected_cat_raw)
                        end
                        
                        if name_match and cat_match then 
                            table.insert(BuyableItems.items, item) 
                        end 
                    end
                end
                
