                    -- 1. Фон заголовка
                    dl:AddRectFilled(p, imgui.ImVec2(p.x + panel_w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(8))
                    dl:AddRectFilled(p, imgui.ImVec2(p.x + S(4), p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)

