                        local i_sz_y = GetStaticTextSize(title_icon).y
                        dl:AddText(imgui.ImVec2(p.x + left_padding, center_y - i_sz_y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), title_icon)
