                    dl:AddText(imgui.ImVec2(p.x + left_padding + icon_sz + S(10), center_y - t_sz_y/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), current_cat_name)

                    -- 3. Кнопка ФИЛЬТРА (Справа)
                    local btn_sz = S(28)
                    local right_padding = S(10)
                    local btn_x = p.x + panel_w - btn_sz - right_padding
                    local btn_y = center_y - btn_sz / 2
                    
