                    if imgui.InvisibleButton("##cat_filter_toggle", imgui.ImVec2(btn_sz, btn_sz)) then
                        imgui.OpenPopup("CategoryFilterPopup")
                    end

                    local is_hovered = imgui.IsItemHovered()
                    local is_active_filter = (buy_category_filter_idx ~= 0) -- Активен ли какой-то фильтр?

                    -- Цвет кнопки: Если фильтр включен - акцентный, иначе серый
                    local icon_col = is_active_filter and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
                    local bg_col = 0
                    
