                        -- Функция отрисовки элемента
                        local function DrawFilterItem(label_utf8, is_selected, icon)
                            local p_item = imgui.GetCursorScreenPos()
                            local item_h = S(36)
                            
                            local clicked = imgui.InvisibleButton("##"..label_utf8, imgui.ImVec2(popup_width, item_h))
                            
                            local is_hovered = imgui.IsItemHovered()
                            local dl_item = imgui.GetWindowDrawList()
                            
                            -- Фон
                            if is_selected then
                                dl_item:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_width, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_tertiary))
                                dl_item:AddRectFilled(p_item, imgui.ImVec2(p_item.x + S(3), p_item.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary))
                            elseif is_hovered then
                                dl_item:AddRectFilled(p_item, imgui.ImVec2(p_item.x + popup_width, p_item.y + item_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.05)))
                            end
                            
                            -- Иконка
                            local text_offset_x = S(15)
                            if icon and font_fa then
                                imgui.PushFont(font_fa)
                                local icon_col = is_selected and CURRENT_THEME.accent_primary or (is_hovered and CURRENT_THEME.text_primary or CURRENT_THEME.text_hint)
                                local isz = GetStaticTextSize(icon)
                                -- Центрируем иконку в квадрате 30x36 слева
                                dl_item:AddText(imgui.ImVec2(p_item.x + S(12), p_item.y + (item_h - isz.y)/2), imgui.ColorConvertFloat4ToU32(icon_col), icon)
                                imgui.PopFont()
                                text_offset_x = S(40)
                            end
                            
                            -- Текст (УЖЕ В UTF-8, НЕ ИСПОЛЬЗУЕМ u8())
                            local text_col = is_selected and CURRENT_THEME.accent_primary or CURRENT_THEME.text_primary
                            local t_sz = GetStaticTextSize(label_utf8)
                            dl_item:AddText(imgui.ImVec2(p_item.x + text_offset_x, p_item.y + (item_h - t_sz.y)/2), imgui.ColorConvertFloat4ToU32(text_col), label_utf8)
                            
                            return clicked
                        end

