                    renderSmoothScrollBox("BuyItemsList", imgui.ImVec2(0, list_height_avail), function()
                         -- [FPS BOOST FIX] Кэшируем результаты поиска списка скупки
                         if not App.buy_conf_ui_cache then App.buy_conf_ui_cache = { hash = "", list = {} } end
                         
                         local search_q = ffi.string(Buffers.buy_search)
                         local current_hash = tostring(#Data.buy_list) .. "_" .. search_q
                         
                         if App.buy_conf_ui_cache.hash ~= current_hash then
                             local new_display_list = {}
                             local is_searching = search_q ~= ""
                             
                             if is_searching then
                                 local decoded_q = to_lower(u8:decode(search_q))
                                 for i, item in ipairs(Data.buy_list) do
                                     if SmartSearch.getMatchScore(decoded_q, item.name) > 0 then
                                         table.insert(new_display_list, { data = item, real_idx = i })
                                     end
                                 end
                             else
                                 for i, item in ipairs(Data.buy_list) do
                                     table.insert(new_display_list, { data = item, real_idx = i })
                                 end
                             end
                             
                             App.buy_conf_ui_cache.hash = current_hash
                             App.buy_conf_ui_cache.list = new_display_list
                         end
                         
                         local display_list = App.buy_conf_ui_cache.list
                         local is_searching = search_q ~= ""
                         
                         imgui.Dummy(imgui.ImVec2(0, S(5)))

                         if #display_list == 0 then
                            if is_searching then
                                renderEmptyState(fa('magnifying_glass'), "Ничего не найдено", "Попробуйте изменить поисковый запрос.")
                            else
                                renderEmptyState(
                                    fa('basket_shopping'),
                                    "Список скупки пуст",
                                    "Найдите товары в левой панели и нажмите на них, чтобы добавить в этот список.\nЗатем укажите цены и нажмите кнопку внизу."
                                )
                            end
                        else
                            -- [FPS BOOST FIX] C++ ImGuiListClipper для вкладки Скупка.
                            -- [FIX] Убрали дублирующийся imgui.Dummy для правильного отступа сверху
                            
                            local clipper = imgui.ImGuiListClipper(#display_list)
                            while clipper:Step() do
                                for i = clipper.DisplayStart + 1, clipper.DisplayEnd do
                                    local entry = display_list[i]
                                    if entry then
                                        renderUnifiedConfigItem(entry.real_idx, entry.data, "buy")
                                    end
                                end
                            end
                        end
                        imgui.Dummy(imgui.ImVec2(0, S(5)))
                    end)
                    imgui.PopStyleColor(2)
                    
                imgui.EndChild()
                imgui.PopStyleVar()
                
                -- Вычисляем ширину для двух кнопок
                local total_w = imgui.GetContentRegionAvail().x
                local spacing = S(10)
                local remove_btn_w = S(160) -- Ширина кнопки удаления
                local buy_btn_w = total_w - remove_btn_w - spacing
                
                -- Кнопка ВЫСТАВИТЬ
                if renderCustomButton(u8"Выставить всё на скуп", buy_btn_w, button_h, CURRENT_THEME.accent_primary, fa('shop')) then
                    saveBuyConfigState()
                    startBuying()
                end
                
                imgui.SameLine(nil, spacing)
                
                -- Кнопка СНЯТЬ ВСЁ
                if renderCustomButton(u8"Снять всё", remove_btn_w, button_h, CURRENT_THEME.accent_danger, fa('trash_can')) then
                    startBuyRemoval()
                end
                if imgui.IsItemHovered() then
                    imgui.SetTooltip(u8"Удаляет ВСЕ товары из списка скупки в лавке")
                end
                
                imgui.Columns(1)

            elseif App.active_tab == 3 then
                
                
                imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(25), S(25)))
                imgui.BeginChild("LogsContent", imgui.ImVec2(0, 0), true)
                    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_secondary)
                    renderLogsTab()
                    imgui.PopStyleColor()
                imgui.EndChild()
                imgui.PopStyleVar()
            
            
            elseif App.active_tab == 4 then
                
                imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(25), S(25)))
                imgui.BeginChild("GlobalMarket", imgui.ImVec2(0, 0), true)
                    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_secondary)
                    renderGlobalMarketTab()
                    imgui.PopStyleColor()
                imgui.EndChild()
                imgui.PopStyleVar()

			elseif App.active_tab == 5 then
				imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
				imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_secondary)
				
				if imgui.BeginChild("SettingsContent", imgui.ImVec2(0, 0), true) then
					renderEnhancedSettingsTab()
				end
				imgui.EndChild()
				imgui.PopStyleColor()
				imgui.PopStyleVar()
				
			elseif App.active_tab == 6 then
                imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
                imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main) 
                
                if imgui.BeginChild("AutoPRContent", imgui.ImVec2(0, 0), true) then
                    renderAutoPRTab() -- Функционал доступен всем!
                end
                imgui.EndChild()
                
                imgui.PopStyleColor()
                imgui.PopStyleVar()
            elseif App.active_tab == 7 then
                -- Инновационная защита: если каким-то чудом (эксплойт памяти/сбой) активна вкладка 7 без VIP, блокируем
                if not Data.is_vip then
                    App.active_tab = 1 -- Принудительный сброс на главную вкладку
                else
                    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(20)))
                    imgui.BeginChild("VipAnalyticsContent", imgui.ImVec2(0, 0), true)
                        imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
                        renderVipAnalyticsTab()
                        imgui.PopStyleColor()
                    imgui.EndChild()
                    imgui.PopStyleVar()
                end
			elseif App.active_tab == 8 then
				-- Обновляем моды при первом открытии
				if #ModsData.list == 0 and not ModsData.tried_load then
					api_FetchMods()
					ModsData.tried_load = true
				end

				imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(20)))
				imgui.BeginChild("ModsContent", imgui.ImVec2(0, 0), true)
					imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
					renderModsTab()
					imgui.PopStyleColor()
				imgui.EndChild()
				imgui.PopStyleVar()
				
            elseif App.active_tab == 9 then
                -- [NEW] Вкладка Склад
                imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(20)))
                imgui.BeginChild("WarehouseContent", imgui.ImVec2(0, 0), true)
                    imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main)
                    renderWarehouseTab()
                    imgui.PopStyleColor()
                imgui.EndChild()
                imgui.PopStyleVar()
			end
		
		imgui.EndChild() 
        imgui.PopStyleColor() 
        imgui.PopStyleVar()   -- Закрываем WindowPadding
        
    end
    imgui.End()
    imgui.PopStyleVar(4)
    imgui.PopStyleColor(3)

    -- ==================== ВЫЕЗЖАЮЩАЯ КНОПКА И ОКНО АВТОБАЗАРА ====================
    if App.win_state[0] then
        local arrow_w = S(34) 
        local arrow_h = S(80)
        local car_menu_w = S(420)
        
        -- Кнопка прижата к правой стороне (или к выехавшему окну)
        local arrow_x = sw - arrow_w - (App.car_menu_anim * (car_menu_w + S(20)))
        local arrow_y = (sh - arrow_h) / 2
        
        imgui.SetNextWindowPos(imgui.ImVec2(arrow_x, arrow_y), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(arrow_w, arrow_h), imgui.Cond.Always)
        
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
        imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 0))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0)
        
        if imgui.Begin("##CarMenuToggleBtn", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove) then
            local p = imgui.GetWindowPos()
            local dl = imgui.GetWindowDrawList()
            
            if imgui.InvisibleButton("##car_toggle_act", imgui.ImVec2(arrow_w, arrow_h)) then
                App.show_car_menu = not App.show_car_menu
            end
            
            local hov = imgui.IsItemHovered()
            local bg_col = hov and CURRENT_THEME.accent_primary or CURRENT_THEME.bg_secondary
            
            -- Рисуем плашку (язычок) со скругленными левыми углами
            dl:AddRectFilled(p, imgui.ImVec2(p.x + arrow_w, p.y + arrow_h), imgui.ColorConvertFloat4ToU32(bg_col), S(8), 1 + 8) 
            dl:AddRect(p, imgui.ImVec2(p.x + arrow_w + 5, p.y + arrow_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8), 1 + 8, S(1))
            
            if font_fa then
                imgui.PushFont(font_fa)
                local icon = App.show_car_menu and fa('chevron_right') or fa('car_side')
                local isz = GetStaticTextSize(icon)
                local text_col = hov and 0xFFFFFFFF or imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary)
                -- Идеальное центрирование без костылей
                local center_x = p.x + (arrow_w - isz.x) / 2
                local center_y = p.y + (arrow_h - isz.y) / 2
                dl:AddText(imgui.ImVec2(center_x, center_y), text_col, icon)
                imgui.PopFont()
            end
            
            if hov then imgui.SetTooltip(u8"База Автобазара") end
        end
        imgui.End()
        imgui.PopStyleColor()
        imgui.PopStyleVar(2)

        -- САМО ОКНО АВТОБАЗАРА
        if App.car_menu_anim > 0.01 then
            local car_h = scaled_h
            local car_x = sw + S(20) - (App.car_menu_anim * (car_menu_w + S(20)))
            -- Берем актуальную позицию окна без костылей
            local current_main_pos = imgui.GetWindowPos()
            local car_y = current_main_pos.y
            
            imgui.SetNextWindowPos(imgui.ImVec2(car_x, car_y), imgui.Cond.Always)
            imgui.SetNextWindowSize(imgui.ImVec2(car_menu_w, car_h), imgui.Cond.Always)
            
            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(S(20), S(20)))
            imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
            imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.border_light)
            imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1))
            imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
            imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, App.car_menu_anim)

            if imgui.Begin("##CarPricesWindow", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove) then
                local w = imgui.GetContentRegionAvail().x
                local dl = imgui.GetWindowDrawList()
                local p = imgui.GetCursorScreenPos()
                
                -- Шапка
                if font_fa then imgui.PushFont(font_fa) imgui.TextColored(CURRENT_THEME.accent_primary, fa('car')) imgui.PopFont() imgui.SameLine() end
                imgui.TextColored(CURRENT_THEME.text_primary, u8"БАЗА АВТОБАЗАРА")
                
                -- Инициализация настроек подсказок
                if Data.settings.car_hints == nil then Data.settings.car_hints = false end

                -- Блок кнопок справа
                local btn_sz = S(26)
                local gap = S(8)
                
                -- Динамическая ширина кнопок: теперь всегда 2
                local btn_count = 2
                local right_btns_w = (btn_sz * btn_count) + (gap * (btn_count - 1))
                
                imgui.SameLine(w - right_btns_w)
                imgui.SetCursorPosY(imgui.GetCursorPosY() - S(3))
                
                -- 1. Кнопка "Умные подсказки" (CEF Цены АБ)
                local hint_p = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##hints_tog", imgui.ImVec2(btn_sz, btn_sz)) then
                    Data.settings.car_hints = not Data.settings.car_hints
                    saveSettings()
                end
                
                local is_hint_hov = imgui.IsItemHovered()
                local hint_bg = Data.settings.car_hints and CURRENT_THEME.accent_success or imgui.ImVec4(0,0,0,0)
                local hint_col = Data.settings.car_hints and imgui.ImVec4(1,1,1,1) or CURRENT_THEME.text_secondary
                
                if is_hint_hov then 
                    hint_bg = Data.settings.car_hints and imgui.ImVec4(CURRENT_THEME.accent_success.x*1.1, CURRENT_THEME.accent_success.y*1.1, CURRENT_THEME.accent_success.z*1.1, 1) or imgui.ImVec4(1,1,1,0.1) 
                end
                
                if hint_bg.w ~= 0 or is_hint_hov then
                    dl:AddRectFilled(hint_p, imgui.ImVec2(hint_p.x + btn_sz, hint_p.y + btn_sz), imgui.ColorConvertFloat4ToU32(hint_bg), S(6))
                end
                
                if font_fa then
                    imgui.PushFont(font_fa)
                    local t_icon = fa('eye')
                    local t_sz = GetStaticTextSize(t_icon)
                    dl:AddText(imgui.ImVec2(hint_p.x + (btn_sz-t_sz.x)/2, hint_p.y + (btn_sz-t_sz.y)/2), imgui.ColorConvertFloat4ToU32(hint_col), t_icon)
                    imgui.PopFont()
                end
                
                if is_hint_hov then 
                    imgui.SetTooltip(Data.settings.car_hints and u8"Цены в CEF окне покупки авто: ВКЛ\n(Скрипт будет выводить средние цены автобазара)" or u8"Цены в CEF окне покупки авто: ВЫКЛ") 
                end
                
                imgui.SameLine(0, gap)
                
                -- 2. Кнопка "Обновить базу"
                local ref_p = imgui.GetCursorScreenPos()
                if imgui.InvisibleButton("##refresh_cars_btn", imgui.ImVec2(btn_sz, btn_sz)) then
                    api_FetchCarPrices()
                end
                
                local is_ref_hov = imgui.IsItemHovered()
                if is_ref_hov then
                    dl:AddRectFilled(ref_p, imgui.ImVec2(ref_p.x + btn_sz, ref_p.y + btn_sz), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1)), S(6))
                    imgui.SetTooltip(u8"Обновить базу с сервера")
                end
                
                if font_fa then 
                    imgui.PushFont(font_fa) 
                    local r_col = is_ref_hov and CURRENT_THEME.accent_primary or CURRENT_THEME.text_secondary
                    local r_icon = fa('arrows_rotate')
                    local r_isz = GetStaticTextSize(r_icon)
                    dl:AddText(imgui.ImVec2(ref_p.x + (btn_sz - r_isz.x)/2, ref_p.y + (btn_sz - r_isz.y)/2), imgui.ColorConvertFloat4ToU32(r_col), r_icon)
                    imgui.PopFont() 
                end
                
                imgui.Dummy(imgui.ImVec2(0, S(15)))
                
                -- Поиск (теперь во всю ширину окна)
                imgui.SetCursorPosX(S(20))
                renderAnimatedSearchBar(CarMarket.search_buf, "Поиск автомобиля...", w)

                imgui.Dummy(imgui.ImVec2(0, S(15)))
                
                local list_h = imgui.GetContentRegionAvail().y
                imgui.PushStyleColor(imgui.Col.ChildBg, CURRENT_THEME.bg_main) -- Фон прозрачный/темный
                
                -- Используем стандартный BeginChild вместо SmoothScrollBox для устранения бага с высотой
                if imgui.BeginChild("CarListScroll", imgui.ImVec2(w, list_h), false) then
                    
                    -- [INNOVATION] Инициализация кэша Автобазара
                    if not CarMarket.ui_cache then CarMarket.ui_cache = { query = nil, list = {} } end
                    
                    local search_q = ""
                    local raw_s = ffi.string(CarMarket.search_buf)
                    if raw_s ~= "" then search_q = u8:decode(raw_s):lower() end
                    
                    -- Проверяем, нужно ли пересчитывать список (если поиск изменился или пришли новые цены)
                    if CarMarket.ui_cache.query ~= search_q or SaveScheduler.cars_dirty then
                        local display_cars = {}
                        local srv_db, _ = CarMarket.getCurrentServerDB()
                        
                        for name, data in pairs(srv_db) do
                            if search_q == "" or name:lower():find(search_q, 1, true) then
                                -- ПРЕДРАСЧЕТ: Ищем самую частую цену (Моду) 1 раз
                                local counts = {}
                                local max_count = 0
                                local mode_price = 0
                                
                                for _, price in ipairs(data.p) do
                                    counts[price] = (counts[price] or 0) + 1
                                    if counts[price] > max_count or (counts[price] == max_count and price > mode_price) then
                                        max_count = counts[price]
                                        mode_price = price
                                    end
                                end
                                local avg = mode_price
                                
                                -- [FIX] Кэшируем СРАЗУ готовые строки, чтобы не вызывать форматтеры каждый кадр
                                local pr_str = avg > 0 and formatMoney(avg) .. " $" or u8"Нет данных"
                                local meta_str = u8"Сделок в базе: " .. #data.p
                                
                                table.insert(display_cars, {
                                    name = name, 
                                    u8_name = u8(name), 
                                    data = data, 
                                    avg = avg,
                                    pr_str = pr_str,
                                    meta_str = meta_str
                                })
                            end
                        end
                        
                        table.sort(display_cars, function(a, b) return a.name < b.name end)
                        
                        CarMarket.ui_cache.query = search_q
                        CarMarket.ui_cache.list = display_cars
                    end
                    
                    local display_cars = CarMarket.ui_cache.list
                    
                    if #display_cars == 0 then
                        imgui.Dummy(imgui.ImVec2(0, S(50)))
                        local t1 = u8"Нет данных"
                        local t1_sz = GetStaticTextSize(t1).x
                        imgui.SetCursorPosX((w - t1_sz)/2)
                        imgui.TextColored(CURRENT_THEME.text_hint, t1)
                    else
                        local dl = imgui.GetWindowDrawList()
                        
                        -- [FIX] Настоящий виртуальный скроллинг с поддержкой разной высоты карточек
                    local current_scroll = imgui.GetScrollY()
                    local win_h = imgui.GetWindowHeight()
                    local current_y_offset = 0
                    local spacing_y = S(8)
                    
                    for i, car in ipairs(display_cars) do
                        local is_expanded = (App.selected_car_cfg == car.name)
                        local item_h = S(55)
                        local full_h = is_expanded and (item_h + S(60)) or item_h
                        
                        -- КЛИППИНГ: Если карточка ниже видимой зоны, прерываем цикл (остальные тоже ниже)
                        if current_y_offset > current_scroll + win_h then
                            local remaining_items = #display_cars - i + 1
                            current_y_offset = current_y_offset + (remaining_items * (item_h + spacing_y))
                            break
                        end
                        
                        -- КЛИППИНГ: Рендерим ТОЛЬКО если карточка находится в видимой зоне
                        if current_y_offset + full_h >= current_scroll then
                            imgui.SetCursorPosY(current_y_offset)
                            local item_p = imgui.GetCursorScreenPos()
                            
                            -- Берем готовое среднее значение из кэша!
                            local avg = car.avg
                            
                            -- Фон карточки
                            local bg_col = is_expanded and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary
                            dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + w, item_p.y + full_h), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
                            
                            -- Акцентная полоса
                            dl:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + full_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)
                            
                            -- Иконка машины
                            local icon_sz = S(32)
                            local icon_y = item_p.y + (item_h - icon_sz)/2
                            dl:AddCircleFilled(imgui.ImVec2(item_p.x + S(25), icon_y + icon_sz/2), icon_sz/2, imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_main))
                            if font_fa then
                                imgui.PushFont(font_fa)
                                local c_ic = fa('car_side')
                                local ci_sz = GetStaticTextSize(c_ic)
                                dl:AddText(imgui.ImVec2(item_p.x + S(25) - ci_sz.x/2, icon_y + (icon_sz - ci_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_secondary), c_ic)
                                imgui.PopFont()
                            end

                            -- Название
                            local text_x = item_p.x + S(50)
                            dl:AddText(imgui.ImVec2(text_x, item_p.y + S(10)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), car.u8_name)
                            
                            -- Статистика записей
                            -- Статистика записей
                            dl:AddText(imgui.ImVec2(text_x, item_p.y + S(30)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), car.meta_str)
                            
                            -- Цена справа
                            imgui.PushFont(font_default)
                            local pr_sz = GetStaticTextSize(car.pr_str)
                            dl:AddText(imgui.ImVec2(item_p.x + w - pr_sz.x - S(15), item_p.y + (item_h - pr_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), car.pr_str)
                            imgui.PopFont()
                            
                            -- Кнопка взаимодействия с карточкой (открытие настроек)
                            imgui.SetCursorScreenPos(item_p)
                            if imgui.InvisibleButton("##car_btn_"..i, imgui.ImVec2(w, item_h)) then
                                if App.selected_car_cfg == car.name then App.selected_car_cfg = nil else App.selected_car_cfg = car.name end
                            end
                            
                            if imgui.IsItemHovered() then
                                dl:AddRect(item_p, imgui.ImVec2(item_p.x + w, item_p.y + full_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), S(8), 15, S(1))
                            end
                            
                            -- БЛОК НАСТРОЕК (ЛИМИТЫ)
                            if is_expanded then
                                local lim_p = imgui.ImVec2(item_p.x + S(10), item_p.y + item_h)
                                local limits_w = w - S(20)
                                local limits_h = S(50)
                                
                                dl:AddLine(imgui.ImVec2(lim_p.x, lim_p.y), imgui.ImVec2(lim_p.x + limits_w, lim_p.y), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light), 1)
                                
                                if not CarMarket.input_bufs[car.name] then
                                    CarMarket.input_bufs[car.name] = {
                                        min = imgui.new.char[32](tostring(car.data.min)),
                                        max = imgui.new.char[32](tostring(car.data.max))
                                    }
                                end
                                
                                local bufs = CarMarket.input_bufs[car.name]
                                local inp_w = (limits_w - S(90)) / 2
                                
                                imgui.SetCursorScreenPos(imgui.ImVec2(lim_p.x + S(5), lim_p.y + S(8)))
                                renderModernInput("##cmin_"..i, bufs.min, inp_w, "Отбрасывать дешевле...")
                                if imgui.IsItemDeactivatedAfterEdit() then
                                    car.data.min = tonumber(ffi.string(bufs.min)) or 0
                                    SaveScheduler.cars_dirty = true
                                end
                                
                                imgui.SetCursorScreenPos(imgui.ImVec2(lim_p.x + S(15) + inp_w, lim_p.y + S(8)))
                                renderModernInput("##cmax_"..i, bufs.max, inp_w, "Отбрасывать дороже...")
                                if imgui.IsItemDeactivatedAfterEdit() then
                                    car.data.max = tonumber(ffi.string(bufs.max)) or 0
                                    SaveScheduler.cars_dirty = true
                                end
                                
                                imgui.SetCursorScreenPos(imgui.ImVec2(lim_p.x + limits_w - S(65), lim_p.y + S(8)))
                                if renderCustomButton(u8"Сброс", S(65), S(34), CURRENT_THEME.bg_main) then
                                    car.data.p = {}
                                    SaveScheduler.cars_dirty = true
                                    addToastNotification("История цен авто очищена", "info")
                                end
                                if imgui.IsItemHovered() then imgui.SetTooltip(u8"Очистить все сохраненные цены на это авто") end
                            end
                        end -- Конец блока if видимости карточки (КЛИППИНГА)
                        
                        current_y_offset = current_y_offset + full_h + spacing_y
                    end
                    
                    imgui.SetCursorPosY(current_y_offset) -- Устанавливаем финальную высоту для скроллбара
                end
                imgui.EndChild()
                imgui.PopStyleColor()
            end
            imgui.End()
            
            imgui.PopStyleColor(2)
            imgui.PopStyleVar(4)
        end
    end
    end -- <<< ВОТ ЭТОТ END ЗАКРЫВАЕТ if App.win_state[0] then
end)

function renderVipPromoOverlay(reason_text)
    local w = imgui.GetContentRegionAvail().x
    local h = imgui.GetContentRegionAvail().y
    local p = imgui.GetCursorScreenPos()
    local center_y = h / 2
    
    -- Затемнение фона
    imgui.GetWindowDrawList():AddRectFilled(
        p, 
        imgui.ImVec2(p.x + w, p.y + h), 
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.05, 0.05, 0.07, 0.95))
    )
    
    -- Иконка короны
    if font_fa_big then
        imgui.PushFont(font_fa_big)
