        os.execute('explorer "https://t.me/rdnMarket_bot"') 
    end
end

local function renderMagnetOverlay()
    if not MagnetMove.active or not MagnetMove.item_data then return end

    if imgui.IsMouseClicked(1) and (os.clock() - MagnetMove.pickup_time > 0.2) then
        MagnetMove.active = false
        MagnetMove.item_data = nil
        addToastNotification("Перемещение отменено", "info")
        return
    end

    imgui.BeginTooltip()
    imgui.TextColored(CURRENT_THEME.accent_warning, u8"Перемещение:")
    imgui.SameLine()
    imgui.Text(u8(MagnetMove.item_data.name))
    imgui.TextDisabled(u8"ЛКМ - вставить | ПКМ - отмена")
    imgui.EndTooltip()
end

local function renderUndoSnackbar()
    if #App.undo_stack == 0 then return end
    
    local now = os.clock()
    if now > App.undo_timer then
        -- Время вышло, очищаем стек
        App.undo_stack = {}
        return
    end

    local draw_list = imgui.GetForegroundDrawList()
    local sw, sh = getScreenResolution()
    
    -- Формируем текст
    local last_deleted = App.undo_stack[#App.undo_stack]
    local name_short = last_deleted.item.name
    if #name_short > 25 then name_short = name_short:sub(1, 25) .. "..." end
    
    local text = u8"Удалено: " .. u8(name_short)
    local btn_text = u8"ВЕРНУТЬ (Ctrl+Z)"
    
    if font_default then imgui.PushFont(font_default) end
    local t_sz = GetStaticTextSize(text)
    local b_sz = GetStaticTextSize(btn_text)
    if font_default then imgui.PopFont() end

    local box_w = t_sz.x + b_sz.x + S(60)
    local box_h = S(45)
    local box_x = (sw - box_w) / 2
    local box_y = sh - S(80) -- Внизу по центру экрана

    -- Анимация появления
    local alpha = 1.0
    local time_left = App.undo_timer - now
    if time_left < 0.5 then alpha = time_left * 2.0 end -- Затухание перед исчезновением

    -- Фон (Стильный скругленный Pill)
    local bg_col = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.12, 0.12, 0.14, 0.95 * alpha))
    draw_list:AddRectFilled(imgui.ImVec2(box_x, box_y), imgui.ImVec2(box_x + box_w, box_y + box_h), bg_col, box_h / 2)
    draw_list:AddRect(imgui.ImVec2(box_x, box_y), imgui.ImVec2(box_x + box_w, box_y + box_h), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1,1,1,0.1*alpha)), box_h / 2, 15, S(1))

    -- Текст информации
    if font_default then imgui.PushFont(font_default) end
    draw_list:AddText(imgui.ImVec2(box_x + S(20), box_y + (box_h - t_sz.y)/2), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.8, 0.8, 0.8, alpha)), text)
    
    -- Кнопка "Вернуть"
    local btn_x = box_x + box_w - b_sz.x - S(25)
    
    -- Проверка наведения мыши
    local is_hovered = imgui.IsMouseHoveringRect(imgui.ImVec2(btn_x - S(10), box_y), imgui.ImVec2(btn_x + b_sz.x + S(10), box_y + box_h))
    local is_clicked = is_hovered and imgui.IsMouseClicked(0)
    
    -- Горячая клавиша Ctrl+Z
    local is_hotkey = isKeyDown(17) and isKeyJustPressed(90) -- VK_CONTROL и Z
    
    if is_clicked or is_hotkey then
        -- Восстанавливаем предмет
        local target_list = (last_deleted.list == "sell") and Data.sell_list or Data.buy_list
        local target_index = math.min(last_deleted.index, #target_list + 1)
        
        table.insert(target_list, target_index, last_deleted.item)
        table.remove(App.undo_stack, #App.undo_stack) -- Удаляем из стека
        
        saveListsConfig()
        if last_deleted.list == "sell" then calculateSellTotal() else calculateBuyTotal() end
        addToastNotification("Товар восстановлен!", "success")
    end

    local btn_col = is_hovered and CURRENT_THEME.accent_hover or CURRENT_THEME.accent_primary
    draw_list:AddText(imgui.ImVec2(btn_x, box_y + (box_h - b_sz.y)/2), imgui.ColorConvertFloat4ToU32(imgui.ImVec4(btn_col.x, btn_col.y, btn_col.z, alpha)), btn_text)
    if font_default then imgui.PopFont() end
end


