                imgui.TextColored(CURRENT_THEME.text_secondary, u8("Нажмите кнопку ниже для загрузки базы с нашего сервера."))
                
                imgui.Dummy(imgui.ImVec2(0, S(10)))
                
                if renderCustomButton(u8"Скачать базу", S(200), S(40), CURRENT_THEME.accent_primary, fa('cloud_arrow_down')) then
                    api_CheckAndDownloadItemsDB(true)
                end
                
                if items_count < 10 then
                    imgui.Dummy(imgui.ImVec2(0, S(10)))
                    imgui.TextColored(CURRENT_THEME.accent_danger, u8("Необходимо скачать базу для продолжения!"))
                end
            end

        elseif App.tutorial_step == 4 then
            -- СКАНИРОВАНИЕ ИНВЕНТАРЯ
            imgui.TextColored(CURRENT_THEME.text_primary, u8"Шаг 3: Ваш инвентарь")
            imgui.Dummy(imgui.ImVec2(0, S(10)))
            
            local inv_count = #Data.scanned_items
            local scan_inv_active = App.is_scanning or State.inventory_scan.active
            
            imgui.Text(u8("Скрипт должен знать, что у вас есть, для продажи."))
            
            if inv_count > 0 then
                imgui.Dummy(imgui.ImVec2(0, S(5)))
                imgui.TextColored(CURRENT_THEME.accent_success, fa('CIRCLE_CHECK') .. " " .. u8("Инвентарь считан (" .. inv_count .. " слотов)"))
            end
            
            imgui.Dummy(imgui.ImVec2(0, S(15)))
            
            if scan_inv_active then
                imgui.TextColored(CURRENT_THEME.accent_primary, fa('spinner') .. " " .. u8("Открываю инвентарь..."))
            else
                if renderCustomButton(u8"Сканировать", S(200), S(40), CURRENT_THEME.accent_secondary, fa('box_open')) then
                    startScanning()
                end
            end
            
        elseif App.tutorial_step == 5 then
            -- TELEGRAM
            imgui.TextColored(CURRENT_THEME.text_primary, u8"Шаг 4: Telegram уведомления")
            imgui.Dummy(imgui.ImVec2(0, S(10)))
            imgui.Text(u8"Бот @rdnMarket_bot пришлет уведомление, если у вас что-то купят, пока вы AFK.")
            imgui.Dummy(imgui.ImVec2(0, S(15)))
            
            renderModernInput("##tut_tg", Buffers.settings.telegram_token, content_width_avail - S(10), "Ключ из бота (не обязательно)", true)
            
        elseif App.tutorial_step == 6 then
            -- ФИНАЛ
            imgui.TextColored(CURRENT_THEME.accent_success, u8"Настройка завершена!")
            imgui.Dummy(imgui.ImVec2(0, S(15)))
            
            imgui.Text(u8"Теперь вы полностью готовы к торговле.")
            imgui.Dummy(imgui.ImVec2(0, S(5)))
            imgui.Text(u8"Чтобы открыть главное меню скрипта, введите:")
            
            imgui.Dummy(imgui.ImVec2(0, S(10)))
            imgui.SetWindowFontScale(1.5)
            imgui.TextColored(CURRENT_THEME.accent_primary, "/rmenu")
            imgui.SetWindowFontScale(1.0)
        end
        
        imgui.PopTextWrapPos()
        imgui.EndGroup()
        
        -- === КНОПКИ НАВИГАЦИИ ===
        local btn_area_y = p.y + h - S(60)
        local btn_h = S(35)
        local btn_w = S(110)
        
        -- Кнопка "Назад"
        if App.tutorial_step > 1 then
            imgui.SetCursorScreenPos(imgui.ImVec2(content_start_x, btn_area_y))
            if renderCustomButton(u8"Назад", btn_w, btn_h, CURRENT_THEME.bg_tertiary) then
                App.tutorial_step = App.tutorial_step - 1
            end
        end
        
        -- Кнопка "Далее" / "Завершить"
        local next_text = (App.tutorial_step == #steps) and u8"Завершить" or u8"Далее"
        local next_col = (App.tutorial_step == #steps) and CURRENT_THEME.accent_success or CURRENT_THEME.accent_primary
        local next_icon = (App.tutorial_step == #steps) and fa('check') or fa('arrow_right')
        
        if App.is_scanning or App.is_downloading_db then
            can_go_next = false
            next_text = u8"Ждите..."
            next_col = CURRENT_THEME.text_hint
        end
        
        local next_btn_x = window_right_edge - btn_w - S(25)
        imgui.SetCursorScreenPos(imgui.ImVec2(next_btn_x, btn_area_y))
        
        -- Рисуем кнопку только если можно идти дальше или это не блокирующий шаг
        if can_go_next then
            if renderCustomButton(next_text, btn_w, btn_h, next_col, next_icon) then
                if App.tutorial_step < #steps then
                    App.tutorial_step = App.tutorial_step + 1
                else
                    -- ЗАВЕРШЕНИЕ
                    Data.settings.tutorial_completed = true
                    App.show_tutorial = false
                    saveSettings(true)
                    
                    -- Открываем основное меню
                    App.win_state[0] = true
                    
                    addToastNotification("Настройка завершена! Меню: /rmenu", "success", 5.0)
                end
            end
        else
            -- Неактивная кнопка (визуально)
            renderCustomButton(next_text, btn_w, btn_h, imgui.ImVec4(0.2,0.2,0.2,1.0))
        end
    end
    imgui.End()
    
    imgui.PopStyleColor()
    imgui.PopStyleVar()
end

function renderCarSellOverlay()
    -- Дополнительная проверка на то, что диалог всё ещё открыт
    if not App.show_car_sell_dialog_overlay then return end
    if not sampIsDialogActive() then 
        App.show_car_sell_dialog_overlay = false 
        return 
    end

    local sw, sh = getScreenResolution()
    local w, h = S(380), S(450)
    
    -- Размещаем окно правее центра экрана (чтобы не перекрывать диалог SA-MP)
    imgui.SetNextWindowPos(imgui.ImVec2(sw / 2 + S(220), sh / 2), imgui.Cond.Always, imgui.ImVec2(0.0, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(w, h), imgui.Cond.Always)
    
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, S(12))
    imgui.PushStyleColor(imgui.Col.WindowBg, CURRENT_THEME.bg_main)
    imgui.PushStyleColor(imgui.Col.Border, CURRENT_THEME.accent_primary)
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, S(1))
    
    if imgui.Begin("##CarSellOverlay", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove) then
        local p = imgui.GetCursorScreenPos()
        local draw_list = imgui.GetWindowDrawList()
        
        -- === ХЕДЕР ===
        local header_h = S(55)
        draw_list:AddRectFilled(p, imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.bg_secondary), S(12), 5)
        draw_list:AddLine(imgui.ImVec2(p.x, p.y + header_h), imgui.ImVec2(p.x + w, p.y + header_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.border_light))
        
        imgui.SetCursorPos(imgui.ImVec2(S(15), (header_h - imgui.GetFontSize()) / 2))
        if font_fa then 
            imgui.PushFont(font_fa)
            imgui.TextColored(CURRENT_THEME.accent_primary, fa('car'))
            imgui.PopFont()
            imgui.SameLine(0, S(8))
        end
        imgui.TextColored(CURRENT_THEME.text_primary, u8"Средние цены автобазара")
        
        -- === ПОИСК ===
        imgui.SetCursorPos(imgui.ImVec2(S(15), header_h + S(15)))
        renderAnimatedSearchBar(Buffers.car_sell_search, "Найти авто...", w - S(30))
        
        -- === СПИСОК МАШИН ===
        local list_y = header_h + S(15) + S(42) + S(15)
        local list_h = h - list_y
        
        imgui.SetCursorPos(imgui.ImVec2(0, list_y))
        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0,0,0,0))
        
        renderSmoothScrollBox("##CarSellListScroll", imgui.ImVec2(w, list_h), function()
            local srv_db, _ = CarMarket.getCurrentServerDB()
            
            local search_q = ffi.string(Buffers.car_sell_search)
            if search_q ~= "" then search_q = u8:decode(search_q):lower() end
            
            local display_cars = {}
            for name, data in pairs(srv_db) do
                if search_q == "" or name:lower():find(search_q, 1, true) then
                    -- ПРЕДРАСЧЕТ: Ищем самую частую цену (Моду)
                    local counts = {}
                    local max_count = 0
                    local mode_price = 0
                    
                    for _, price in ipairs(data.p) do
                        counts[price] = (counts[price] or 0) + 1
                        -- Если количество совпадений больше, ИЛИ равно, но цена выше (в пользу продавца)
                        if counts[price] > max_count or (counts[price] == max_count and price > mode_price) then
                            max_count = counts[price]
                            mode_price = price
                        end
                    end
                    local avg = mode_price
                    
                    if avg > 0 then
                        table.insert(display_cars, {
                            name = name, 
                            u8_name = u8(name),
                            avg = avg,
                            count = #data.p
                        })
                    end
                end
            end
            
            table.sort(display_cars, function(a, b) return a.name < b.name end)
            
            if #display_cars == 0 then
                imgui.Dummy(imgui.ImVec2(0, S(40)))
                local t1 = u8"Машины не найдены"
                local t1_sz = GetStaticTextSize(t1).x
                imgui.SetCursorPosX((w - t1_sz)/2)
                imgui.TextColored(CURRENT_THEME.text_hint, t1)
            else
                local item_h = S(50)
                local margin_x = S(15)
                local item_w = w - (margin_x * 2)
                
                -- Виртуальный скроллинг
                local total_items = #display_cars
                local current_scroll = imgui.GetScrollY()
                local visible_height = imgui.GetWindowHeight()
                local start_idx = math.floor(current_scroll / item_h) + 1
                local end_idx = start_idx + math.ceil(visible_height / item_h) + 1
                start_idx = math.max(1, start_idx)
                end_idx = math.min(total_items, end_idx)
                
                imgui.SetCursorPosY((start_idx - 1) * (item_h + S(6)))
                
                for i = start_idx, end_idx do
                    local car = display_cars[i]
                    if car then
                        imgui.SetCursorPosX(margin_x)
                        local item_p = imgui.GetCursorScreenPos()
                        
                        -- Невидимая кнопка во весь ряд
                        if imgui.InvisibleButton("##sell_car_"..i, imgui.ImVec2(item_w, item_h)) then
                            -- == ГЛАВНОЕ ДЕЙСТВИЕ ==
                            -- 1. Отправляем ответ в диалог (ID: 148, Button: 1 (Выставить), List: 0, Input: Цена)
                            sampSendDialogResponse(148, 1, 0, tostring(car.avg))
                            
                            -- 2. Скрываем диалог SA-MP визуально
                            sampCloseCurrentDialogWithButton(0)
                            
                            -- 3. Закрываем наш оверлей
                            App.show_car_sell_dialog_overlay = false
                            
                            addToastNotification("Цена установлена: " .. formatMoney(car.avg) .. " $", "success")
                        end
                        
                        local is_hovered = imgui.IsItemHovered()
                        
                        -- Фон
                        local bg_col = is_hovered and CURRENT_THEME.bg_tertiary or CURRENT_THEME.bg_secondary
                        draw_list:AddRectFilled(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(bg_col), S(8))
                        
                        if is_hovered then
                            draw_list:AddRect(item_p, imgui.ImVec2(item_p.x + item_w, item_p.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 15, S(1))
                            imgui.SetTooltip(u8"Кликните, чтобы выставить за " .. formatMoney(car.avg) .. " $")
                        end
                        
                        -- Декоративная полоса
                        draw_list:AddRectFilled(item_p, imgui.ImVec2(item_p.x + S(4), item_p.y + item_h), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_primary), S(8), 5)
                        
                        -- Название
                        draw_list:AddText(imgui.ImVec2(item_p.x + S(15), item_p.y + S(8)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_primary), car.u8_name)
                        
                        -- Стата (Сделок)
                        draw_list:AddText(imgui.ImVec2(item_p.x + S(15), item_p.y + S(28)), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.text_hint), u8("Сделок в базе: " .. car.count))
                        
                        -- Цена
                        imgui.PushFont(font_default)
                        local price_str = formatMoney(car.avg) .. " $"
                        local p_sz = GetStaticTextSize(price_str)
                        draw_list:AddText(imgui.ImVec2(item_p.x + item_w - p_sz.x - S(10), item_p.y + (item_h - p_sz.y)/2), imgui.ColorConvertFloat4ToU32(CURRENT_THEME.accent_success), price_str)
                        imgui.PopFont()
                        
                        imgui.SetCursorPosY(imgui.GetCursorPosY() + S(6))
                    end
                end
                
                if end_idx < total_items then
                    local remaining = total_items - end_idx
                    imgui.SetCursorPosY(imgui.GetCursorPosY() + (remaining * (item_h + S(6))))
                end
            end
        end)
        imgui.PopStyleColor()
    end
    imgui.End()
    
    imgui.PopStyleColor(2)
    imgui.PopStyleVar(3)
end

function drawRadiusGraphics()
    if not App.render_radius then return end
    if isCursorVisible() then return end

    local now = os.clock()
    local dt  = now - lastFrameTime
    lastFrameTime = now

    if #lavkas > 0 then
        screenCacheCounter = screenCacheCounter + 1
        if screenCacheCounter >= SCREEN_CACHE_EVERY then
            screenCacheCounter = 0
            rebuildScreenZones()
        end
    end

    local sW, sH = getScreenResolution()

    local activeLav = (#lavkas > 0) and getPlayerInsideLav() or nil
    local canPlace  = (activeLav ~= nil)

    local px2, py2 = getCharCoordinates(playerPed)
    local nearAny   = false
    for _, lav in ipairs(lavkas) do
        local d2 = dist2d_sq(px2, py2, lav.cx, lav.cy)
        if d2 <= FADE_END * FADE_END then
            nearAny = true
            break
        end
    end

    if nearAny then
        overlayVisible  = true
        overlayCanPlace = canPlace
        overlayAlpha    = math.min(1.0, overlayAlpha + dt * OVERLAY_FADE_SPD)
    else
        overlayAlpha = math.max(0.0, overlayAlpha - dt * OVERLAY_FADE_SPD)
        if overlayAlpha <= 0.0 then
            overlayVisible = false
        end
    end

    imgui.SetNextWindowPos(imgui.ImVec2(0, 0))
    imgui.SetNextWindowSize(imgui.ImVec2(sW, sH))
    imgui.Begin("##lavkazones", nil, WIN_FLAGS)

    local dl = imgui.GetWindowDrawList()

    -- ==================== УЛУЧШЕННАЯ ОТРИСОВКА РАДИУСА ====================
    -- [FPS BOOST] Предрасчет квадратов радиуса (убирает лаги от квадратного корня)
    local fade_end_sq = FADE_END * FADE_END
    
    if #cachedScreenZones > 0 then
        -- PASS 1: Отрисовка внешнего свечения (тень/ареол)
        for i = 1, #cachedScreenZones do
            local sz = cachedScreenZones[i]
            local isThis = (sz.lav == activeLav)
            local d2 = dist2d_sq(px2, py2, sz.lav.cx, sz.lav.cy)
            
            -- Если лавка дальше зоны отрисовки - даже не считаем альфу
            if isThis or d2 <= fade_end_sq then
                local dist = math.sqrt(d2)
                local alpha = isThis and 1.0 or calcFadeAlpha(dist)

                local glowColor = isThis and imColor(32, 160, 220, math.floor(25 * alpha)) or imColor(100, 200, 150, math.floor(15 * alpha))
                dl:AddPolyline(sz.buf, sz.validN, glowColor, true, 8.0)
            end
        end

        -- PASS 2: Основная заливка с градиентным эффектом
        for i = 1, #cachedScreenZones do
            local sz = cachedScreenZones[i]
            local isThis = (sz.lav == activeLav)
            local d2 = dist2d_sq(px2, py2, sz.lav.cx, sz.lav.cy)
            
            if isThis or d2 <= fade_end_sq then
                local dist = math.sqrt(d2)
                local alpha = isThis and 1.0 or calcFadeAlpha(dist)
                
                local cFill = isThis and imColor(58, 180, 240, math.floor(45 * alpha)) or imColor(102, 204, 128, math.floor(30 * alpha))
                dl:AddConvexPolyFilled(sz.buf, sz.validN, cFill)
            end
        end

        -- PASS 3: Границы с красивым свечением
        for i = 1, #cachedScreenZones do
            local sz = cachedScreenZones[i]
            local isThis = (sz.lav == activeLav)
            local d2 = dist2d_sq(px2, py2, sz.lav.cx, sz.lav.cy)
            
            if isThis or d2 <= fade_end_sq then
                local dist = math.sqrt(d2)
                local alpha = isThis and 1.0 or calcFadeAlpha(dist)
                
                local cBord = isThis and imColor(100, 210, 255, math.floor(255 * alpha)) or imColor(64, 180, 220, math.floor(180 * alpha))
                dl:AddPolyline(sz.buf, sz.validN, cBord, true, 2.5)
            end
        end

        -- PASS 4: Дополнительный эффект для активной зоны (пульсирующая внутренняя граница)
        if activeLav then
            local dist = math.sqrt(dist2d_sq(px2, py2, activeLav.cx, activeLav.cy))
            local alpha = calcFadeAlpha(dist)
            local pulseAlpha = math.sin(now * 3.0) * 0.3 + 0.4
            local pulseColor = imColor(150, 220, 255, math.floor(150 * alpha * pulseAlpha))
            
            for i = 1, #cachedScreenZones do
                local sz = cachedScreenZones[i]
                if sz.lav == activeLav then
                    dl:AddPolyline(sz.buf, sz.validN, pulseColor, true, 1.5)
                    break
                end
            end
        end
    end

    if overlayVisible or overlayAlpha > 0.01 then
        drawPlacementOverlay(dl, sW, sH, overlayCanPlace, overlayAlpha)
    end

    imgui.End()
end

function Marketplace_Clear(force)
    if not Marketplace.enabled and not force then return end
    if Marketplace.is_cleared and not force then return end
    
    local ip, port = sampGetCurrentServerAddress()
    local my_nick = getSafeLocalNickname()
    
    local payload = {
        username = u8(my_nick),
        serverId = normalizeServerId(ip .. ":" .. port),
        enabled = false, 
        token = Marketplace.sessionToken, 
        items_sell = {}, count_sell = {}, price_sell = {},
        items_buy = {}, count_buy = {}, price_buy = {}
    }
    
    signed_request("POST", MarketConfig.HOST .. "/marketplace?action=insert", payload, function(r) end)
    
    Marketplace.enabled = false
    Marketplace.is_cleared = true
    Marketplace.publish_sell = false
    Marketplace.publish_buy = false
    
    -- Полностью очищаем локальную базу витрины
    Data.live_shop = { sell = {}, buy = {} }
    saveLiveShopState()
    
    Marketplace.sessionToken = nil
    saveSessionToken() 
    
    MarketConfig.SYNC_QUEUED_TIME = 0 -- [FIX RACE CONDITION] Очищаем очередь при закрытии лавки
    MarketConfig.LAST_SYNC = 0
    
    App.live_shop_active = false
    print("[RMarket] Лавка удалена с сервера (Session Closed)")
end

addEventHandler('onWindowMessage', function(msg, wparam, lparam)
    -- 27 = VK_ESCAPE
    if wparam == 27 then
        local consumed = false
		
		if App.radial_menu_active then
            App.radial_menu_active = false
        end

        -- 1. Сначала проверяем модальные окна (менеджеры конфигов)
        if App.show_config_selector or App.show_config_manager or App.show_sell_config_manager then
            if msg == 0x0101 then -- Key Up
                App.show_config_selector = false
                App.show_config_manager = false
                App.show_sell_config_manager = false
            end
            consumed = true
        
        -- 2. Затем окно просмотра чужой лавки (если открыто)
        elseif App.remote_shop_active and Data.settings.show_remote_shop_menu then
            if msg == 0x0101 then
                App.remote_shop_active = false
                if ScanCollector.current_shop_owner then
                    api_SubmitPassiveShop()
                end
                App.tasks.remove_by_name("submit_passive_shop")
                Data.remote_shop_items = {}
                sendCEF("inventoryClose")
            end
            consumed = true

        -- 3. И наконец, основное меню скрипта
        elseif App.win_state[0] then
            -- Не закрываем на ESC, если идет обучение (туториал)
            if not App.show_tutorial then
                if msg == 0x0101 then
                    App.win_state[0] = false
                    -- [FIX] Сбрасываем дочерние окна при закрытии через ESC
                    App.show_config_selector = false
                    App.show_config_manager = false
                    App.show_sell_config_manager = false
                    App.show_gen_config_modal = false
                    VipData.show_graph_modal = false
                    ShareState.modal_active = false
                    App.undo_stack = {}
                end
                consumed = true
            end
        end

        -- Если мы закрыли какое-то окно скрипта, блокируем открытие меню паузы игры
        if consumed and msg == 0x0100 then -- Key Down
            consumeWindowMessage(true, false)
        end
    end
end)

function clearBuyList()
    if #Data.buy_list > 0 then
        for i = 1, #Data.buy_list do Data.buy_list[i] = nil end
        saveListsConfig()
        calculateBuyTotal()
        addToastNotification("Список скупки очищен", "success")
    else
        addToastNotification("Список уже пуст", "info")
    end
end

function enableAllSellItems()
    local count = 0
    for _, item in ipairs(Data.sell_list) do
        -- Включаем товар, ТОЛЬКО если он выключен И он есть в наличии (не missing)
        if not item.active and not item.missing then
            item.active = true
            count = count + 1
        end
    end
    
    if count > 0 then
        saveListsConfig()
        calculateSellTotal()
        addToastNotification("Активировано товаров: " .. count, "success")
    else
        addToastNotification("Нет доступных товаров для включения", "info")
    end
end

function clearSellList()
    if #Data.sell_list > 0 then
        Data.sell_list = {}
        rebuildLookupTables() -- [FIX] Мгновенно сбрасываем галочки в инвентаре
        saveListsConfig()
        calculateSellTotal()
        addToastNotification("Список продажи очищен", "success")
    else
        addToastNotification("Список уже пуст", "info")
    end
end

function addAllToSell()
    local added_count = 0
    local skipped_cheap = 0
    
    -- Получаем глобальную настройку дисконта (например, 5% для быстрой продажи)
    local markdown_percent = Data.settings.price_download_percent or 0
    local multiplier = (100 - markdown_percent) / 100
    
    for _, item in ipairs(Data.scanned_items) do
        repeat
            -- 1. Пропускаем заблокированные
            local lock_key = tostring(item.model_id) .. "_" .. tostring(item.slot)
            if Data.locked_items[lock_key] then break end
            
            -- 2. Пропускаем арендованные
            if item.time and tonumber(item.time) > 0 then break end
            
            -- 3. Пропускаем уже добавленные
            if isSlotInSellList(item.slot, item.model_id) then break end
            
            -- 3.5 Пропускаем деньги (их нельзя выставить на продажу)
            if item.model_id == 3660 then break end
            
            -- 4. Получаем среднюю цену (СТРОГУЮ продажу)
            local avg_price = getAveragePriceForItem(item, "sell", true)
            if not avg_price or avg_price == 0 then 
                avg_price = getAveragePriceForItem(item, "sell", false) or 0
            end
            
            -- SMART FILTER: Пропускаем мусор (вещи дешевле 50к, если нет строгой цены)
            -- Это избавляет лавку от хлама
            if avg_price < 50000 and not getAveragePriceForItem(item, "sell", true) then
                skipped_cheap = skipped_cheap + 1
                break
            end
            
            -- Применяем умную наценку/скидку
            if avg_price > 0 and markdown_percent > 0 then
                avg_price = roundPriceToClean(avg_price * multiplier)
            end
            
            -- 5. Добавляем
            table.insert(Data.sell_list, {
                name = item.original_name or item.name,
                price = avg_price, 
                amount = item.amount or 1,
                model_id = item.model_id, 
                slot = item.slot, 
                missing = false, 
                active = true,
                auto_max = true
            })
            
            local uid = tostring(os.clock()) .. "_" .. math.random(1000,9999) .. "_addAll"
            Data.sell_list[#Data.sell_list]._uid_cache = uid
            
            local key = "sp_" .. uid .. "_s"
            if not Buffers.sell_input_buffers[key] then
                 Buffers.sell_input_buffers[key] = imgui.new.char[32](tostring(avg_price))
            end
            
            added_count = added_count + 1
        until true
    end
    
    if added_count > 0 then
        rebuildLookupTables() -- [FIX] Синхронизируем кнопки
        saveListsConfig()
        calculateSellTotal()
        triggerScrollToBottom("SellItemsScroll")
        addToastNotification(string.format("Магия! Добавлено %d ликвидных товаров (Пропущено мусора: %d)", added_count, skipped_cheap), "success", 5.0)
    else
        addToastNotification("Не найдено подходящих товаров для авто-сборки", "info")
    end
end

function main()
    while not isSampAvailable() do wait(100) end
    while not sampIsLocalPlayerSpawned() do wait(100) end

    _G.CURRENT_PROJECT = "rodina"
    local ip, port = sampGetCurrentServerAddress()
    local srv_cfg = findServerConfig(ip .. ":" .. port)
    
    if srv_cfg then
        print("[RMarket] Подключено к серверу: " .. srv_cfg.name)
    end
    
    -- Инициализируем пути (по умолчанию в корень)
    initProjectEcosystem(_G.CURRENT_PROJECT)

    -- [FPS BOOST] Делаем сборщик мусора по-настоящему плавным
    collectgarbage("setpause", 100) -- Запуск GC при минимальном росте памяти
    collectgarbage("setstepmul", 500) -- Очень быстрый проход, чтобы не стопить кадры игры

    initHttpWorker() -- << ДОБАВИТЬ ЭТУ СТРОКУ
    
    samp_loaded = true
    ensureDirectories()
    
    -- [PROTECT] Инициализируем флаг защиты при запуске
    App.data_loading = false
    
    -- Инициализация данных (Тут загрузится ник из файла)
    loadAllData()
    
    detectCurrentServerIndex()
    
    -- [УДАЛЕНО] Блок умной авторизации lua_thread.create удален отсюда. 
    -- Теперь проверка происходит при вводе /rmenu.

    -- Регистрация команды меню (код из пункта 1 выше)
    sampRegisterChatCommand('rmenu', function()
        lua_thread.create(function()
            if not App.script_loaded then
                sampAddChatMessage('[RMarket] {FF0000}Загрузка...', -1)
                return
            end

            -- Сценарий 1: Мы не знаем ID аккаунта (первый запуск или вайп данных)
            if LOCAL_PLAYER_NICK == nil or LOCAL_ACCOUNT_ID == 0 then
                sampAddChatMessage('[RMarket] {FFFF00}Авторизация...', -1)
                Data.vip_checked = false 
                State.stats_requested_by_script = true
                App.pending_menu_open = true
                sampSendChat("/stats")
            else
                -- Сценарий 2: Мы знаем ID, но еще не проверяли VIP в этой сессии
                -- (Например, если токен есть, но скрипт только запустился)
                if not Data.vip_checked and Data.settings.telegram_token ~= "" then
                    checkVipStatus(Data.settings.telegram_token)
                end

                -- Открытие окна
                if not Data.settings.tutorial_completed then
                    App.show_tutorial = not App.show_tutorial
                    if App.show_tutorial then App.win_state[0] = false end
                else
                    App.win_state[0] = not App.win_state[0]
                    App.show_tutorial = false
                    
                    -- [FIX] Если закрываем меню командой, сбрасываем дочерние окна
                    if not App.win_state[0] then
                        App.show_config_selector = false
                        App.show_config_manager = false
                        App.show_sell_config_manager = false
                        App.show_gen_config_modal = false
                        VipData.show_graph_modal = false
                        ShareState.modal_active = false
                        App.undo_stack = {}
                    end
                end
            end
        end)
    end)

    -- Сохранение информации о версии
    saveJsonFile(PATHS.ROOT .. 'version_info.json', {
        version = SCRIPT_CURRENT_VERSION,
        path = thisScript().path
    })

    sampAddChatMessage('[RMarket] {00FF00}Команда: /rmenu', -1)

    local last_action_check = 0
    local script_load_time = os.clock()
	
	addEventHandler('onReceivePacket', function(id, bs)
        if id == PACKET_DISCONNECTION_NOTIFICATION then
            sendDisconnectNotification("Потеря соединения (Disconnection Notification)")
        elseif id == PACKET_CONNECTION_LOST then
            sendDisconnectNotification("Потеряно соединение (Таймаут / Краш интернета)")
        elseif id == PACKET_CONNECTION_BANNED then
            sendDisconnectNotification("Вам забанило IP адрес")
        end
    end)
    
    addEventHandler('onReceiveRpc', function(id, bs)
        if id == RPC_CONNECTIONREJECTED then
            sendDisconnectNotification("Подключение отклонено (Слишком много попыток)")
        end
    end)

    addEventHandler('onReceivePacket', function(id, bs)
		if id ~= 220 then return end

		local packet_id = raknetBitStreamReadInt8(bs)
		local packet_type = raknetBitStreamReadInt8(bs)
		
		if packet_type ~= 17 then return end

		raknetBitStreamIgnoreBits(bs, 32)
		local length = raknetBitStreamReadInt16(bs)
		if length <= 0 or length > 100000 then return end

		local encoded = raknetBitStreamReadInt8(bs)
		local str = ""

        -- [ОПТИМИЗАЦИЯ] Избегаем создания функции в pcall каждый кадр
        if length > 0 and length <= 100000 then
            if encoded ~= 0 then 
                str = raknetBitStreamDecodeString(bs, length + encoded)
            else 
                str = raknetBitStreamReadString(bs, length) 
            end
        end

		if not str or str == "" then return end
		
		if string.find(str, "/%*RM_INJ%*/", 1, true) then return true end

		if not (string.find(str, "event.", 1, true) or string.find(str, "cef.", 1, true) or string.find(str, "console.log", 1, true)) then 
			return true 
		end

		if string.find(str, "event.setActiveView", 1, true) then
			if string.find(str, '["InteractionMenu"]', 1, true) then
				App.radial_menu_active = true
			else
				App.radial_menu_active = false
			end
		end

		if str:find("transportInteraction%.shop%.initialize") then
			-- [FIX] Пуленепробиваемый парсинг JSON. Ищем от первой '[' до последней ']'.
			-- Это решает проблему вложенных массивов, бэктиков (`) и лишних скобок.
			local start_idx = str:find("%[")
			local end_idx = str:match("^.*()%]") 
			
			local json_str = nil
			if start_idx and end_idx and start_idx < end_idx then
				json_str = str:sub(start_idx, end_idx)
			end
			
			if json_str then
				local ok, parsed = pcall(json.decode, json_str)
				if ok and type(parsed) == "table" and type(parsed[1]) == "table" then
					local carData = parsed[1]
					local rawName = carData.carName
					local rarity = carData.rarity
					-- [FIX] Поддержка разных ключей для цены (иногда бывает price вместо priceButton)
					local price = tonumber(carData.priceButton) or tonumber(carData.price) or 0
					
					if rawName and rarity and price > 0 then
						local r_map = { ["tier1"] = "Хлам", ["tier2"] = "Обычное", ["tier3"] = "Идеальное" }
						local r_text = r_map[rarity] or "Обычное"
						local fullLocalName = rawName .. " [" .. r_text .. "]"
						
						-- [FIX] ВСЕГДА сохраняем и отправляем цену в Node.js (пополняем общую базу)
						CarMarket.processPrice(rawName, rarity, price)
						
						-- [FIX] А вот отрисовку плашки в интерфейсе делаем только если включены подсказки
						if Data.settings.car_hints then
							-- Считаем среднюю цену
							local srv_db, _ = CarMarket.getCurrentServerDB()
							local avg = 0
							
							if srv_db[fullLocalName] then
								if srv_db[fullLocalName].avg and srv_db[fullLocalName].avg > 0 then
									avg = srv_db[fullLocalName].avg
								elseif #srv_db[fullLocalName].p > 0 then
									local counts = {}
									local max_count = 0
									local mode_price = 0
									for _, p in ipairs(srv_db[fullLocalName].p) do
										counts[p] = (counts[p] or 0) + 1
										if counts[p] > max_count or (counts[p] == max_count and p > mode_price) then
											max_count = counts[p]
											mode_price = p
										end
									end
									avg = mode_price
								end
							end
							
							local avg_str = avg > 0 and formatMoney(avg) .. " $" or "Сбор данных..."
							local diff = avg > 0 and (avg - price) or 0
							local diff_str = ""
							local color = "#AAAAAA"
							
							if avg > 0 then
								if diff > 0 then
									color = "#4CAF50" -- Зеленый
									diff_str = "Выгода: +" .. formatMoney(diff) .. " $"
								elseif diff < 0 then
									color = "#F44336" -- Красный
									diff_str = "Переплата: " .. formatMoney(math.abs(diff)) .. " $"
								else
									color = "#FFC107" -- Желтый
									diff_str = "Цена в рынке"
								end
							end
							
							local js_code = string.format([[
                                (() => {
								    let carRmarketInt = setInterval(() => {
									    const carWindow = document.querySelector('.transport-interaction-shop__window-car');
									const btnsContainer = document.querySelector('.transport-interaction-shop__window-car-buttons');
									
									if (carWindow && btnsContainer) {
										if (!document.getElementById('rmarket-car-price')) {
											const badge = document.createElement('div');
											badge.id = 'rmarket-car-price';
											
											badge.style.cssText = 'position: relative; margin-top: 15px; background: rgba(20, 20, 25, 0.9); border: 1px solid %s; border-radius: 8px; padding: 12px; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%%; box-sizing: border-box; backdrop-filter: blur(4px); margin-bottom: 20px;';
											
											badge.innerHTML = '<span style="color: rgba(255,255,255,0.7); font-size: 11px; text-transform: uppercase; font-weight: 800; letter-spacing: 0.5px; margin-bottom: 4px;">RMarket Аналитика (' + '%s' + ')</span>' +
											'<span style="font-size: 18px; font-family: sans-serif; font-weight: 600; color: #fff;">Рынок: <b style="color: %s">%s</b></span>' + 
											'<span style="font-size: 13px; color: %s; font-weight: 700; margin-top: 4px;">%s</span>';
											
											// Вставляем строго ПЕРЕД контейнером с кнопками покупки
											carWindow.insertBefore(badge, btnsContainer);
										}
										clearInterval(carRmarketInt);
									}
								}, 50);
								setTimeout(() => clearInterval(carRmarketInt), 3000);
                                })();
							]], color, u8(r_text), color, u8(avg_str), color, u8(diff_str))
							
							lua_thread.create(function()
								wait(100)
								injectJS(js_code)
							end)
						end -- конец проверки Data.settings.car_hints
					end
				end
			end
		end

		-- [NEW] ИНТЕГРАЦИЯ ЦЕН В МЕНЮ "МОЙ ТРАНСПОРТ" (АВТОБАЗАР)
		if str:find("event%.vehicleMenu%.initializeVehicleList") then
			-- Захватываем JSON массив автомобилей из пакета
			local s, e = str:find("%[%{.*%}%]")
			if s then
				local json_candidate = str:sub(s, e)
				local ok, vehicles = pcall(json.decode, json_candidate)
				
				if ok and type(vehicles) == "table" then
					local srv_db, _ = CarMarket.getCurrentServerDB()
					local is_modified = false
					
					for _, veh in ipairs(vehicles) do
						if veh.title and srv_db[veh.title] and #srv_db[veh.title].p > 0 then
							-- Высчитываем среднюю цену (Моду)
							local counts = {}
							local max_count = 0
							local mode_price = 0
							
							for _, price in ipairs(srv_db[veh.title].p) do
								counts[price] = (counts[price] or 0) + 1
								if counts[price] > max_count or (counts[price] == max_count and price > mode_price) then
									max_count = counts[price]
									mode_price = price
								end
							end
							
							-- Если цена есть, добавляем её в список лейблов авто
							if mode_price > 0 then
								if not veh.labels then veh.labels = {} end
								
								-- Интегрируем в существующий UI (ставим на 1 место, чтобы цена была сверху)
								table.insert(veh.labels, 1, {
									title = "Рынок: " .. formatMoney(mode_price) .. " $",
									icon = "icon-stats" -- Используем системную иконку из CEF Родины
								})
								is_modified = true
							end
						end
					end
					
					if is_modified then
						-- Пересобираем пакет с нашими данными
						local new_json = json.encode(vehicles)
						
						-- [FIX] Инжектим CSS стиль для исправления слоев (Z-Index), чтобы текст был поверх картинки авто
						local css_fix = [[
							if (!document.getElementById('rmarket-car-fix')) {
								const style = document.createElement('style');
								style.id = 'rmarket-car-fix';
								style.innerHTML = `
									.vehicle-menu-vehicle-item__labels { 
										position: relative !important; 
										z-index: 99 !important; 
										text-shadow: 1px 1px 3px rgba(0,0,0,0.8) !important;
									}
								`;
								document.head.appendChild(style);
							}
						]]
						
						-- Формируем строку: Сначала применяем CSS, затем вызываем событие CEF
						local new_str = string.format("%s window.executeEvent('event.vehicleMenu.initializeVehicleList', `[%s]`);", css_fix, new_json)
						
						-- Инжектим измененный пакет с минимальной задержкой
						lua_thread.create(function()
							wait(0)
							injectJS(new_str)
						end)
						
						return false -- Блокируем оригинальный "пустой" пакет от сервера
					end
				end
			end
		end

		if App.is_selling_cef or App.is_removing_sale or App.is_removing_buy then
			if str:find("event%.inventory%.playerInventory") then
				parseCEFInventory(str)
				return false
			end
			
			if str:find("event%.setActiveView") or 
			   str:find("event%.inventory%.setStoreVisible") or
			   str:find("cef%.hud%.updateVisibleComponents") then
				return false
			end
		end
		
		if str:find("event%.callApp%.updateCallStatus") then
			local json_candidate = str:match("executeEvent%('event%.callApp%.updateCallStatus',%s*[`\"'](%[.*%])[`\"']%s*%);?")
			if json_candidate then
				local ok, data = pcall(json.decode, json_candidate)
				if ok and type(data) == "table" and data[1] then
					local call_data = data[1]
					
					if call_data.type == 0 and call_data.timer == 0 then
						local now = os.clock()
						if not App.last_call_time then App.last_call_time = 0 end
						
						-- Антифлуд: 15 секунд
						if now - App.last_call_time > 15.0 then
							App.last_call_time = now
							local caller = call_data.nickname or "Неизвестный"
							local phone = call_data.phoneNumber or "Скрыт"
							
							local caller_cp1251 = caller
							if u8 then
								local s, r = pcall(u8.decode, u8, caller)
								if s then caller_cp1251 = r end
							end
							
							sendCallNotification(caller_cp1251, phone)
							addToastNotification("Входящий звонок: " .. caller_cp1251, "warning", 5.0)
						end
					end
				end
			end
		end
		
		-- [NEW] Перехват конца вызова, чтобы сбросить статус в боте
		if str:find("Собеседник сбросил звонок") or (str:find("event%.callApp%.changeScreen") and str:find('"history"')) then
			if not App.last_call_end_time or os.clock() - App.last_call_end_time > 2.0 then
				App.last_call_end_time = os.clock()
				local payload = {
					secret_key = Data.settings.telegram_token,
					data = { type = "phone_ended" }
				}
				signed_request("POST", MarketConfig.HOST .. "/notify", payload)
			end
		end
		
		if str:find("cef%.modals%.showModal") then
			local json_candidate = str:match("executeEvent%('cef%.modals%.showModal', `([^`]+)`%);")
			
			if not json_candidate then
				local s, e = str:find("%[.*%]")
				if s then json_candidate = str:sub(s, e) end
			end
			
			if json_candidate then
				local ok2, data = pcall(json.decode, json_candidate)
				if ok2 and data and data[2] then
					local dialog_data = data[2]
					local dialog_id = tonumber(dialog_data.id)
					local header = dialog_data.header or ""
					local body = dialog_data.body or ""
                    
					-- === [NEW] ПАРСИНГ НИКА ПРОДАВЦА ПРИ РУЧНОЙ ПОКУПКЕ ===
					local clean_header_temp = cleanTextColors(header)
					if clean_header_temp:find("Покупка товара") or clean_header_temp:find("Продажа товара") then
						local clean_body = cleanTextColors(body)
						-- Ищем текст вида: "купить у продавца Растаман Чр[510]" или "продать скупщику ..."
						local seller = clean_body:match("продавца%s+(.-)%[%d+%]")
						if not seller then
							seller = clean_body:match("скупщику%s+(.-)%[%d+%]")
						end
						if seller then
							App.last_manual_buy_seller = seller
						end
					end
					-- ======================================================

					if header:find("Статистика игрока") or body:find("Текущее состояние счета") then
						local clean_text = cleanTextColors(body)
						for line in clean_text:gmatch("[^\r\n]+") do
							if line:find("Имя %(en%.%):") then
								local nick_en = line:match("Имя %(en%.%):%s*([%w_]+)")
								if nick_en then
									LOCAL_PLAYER_NICK = nick_en
									local _, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
									LOCAL_PLAYER_ID = myId
								end
								break
							end
						end
						local stats = parseStatsDialog(body)
						if stats and stats.level and stats.level > 0 then
							sendStatsToAPI(stats)
						end
						if State.stats_requested_by_script then
							State.stats_requested_by_script = false
							return false
						end
					end

					if (dialog_id == 1296 or dialog_id == 1295) and Data.auto_pr.pending_vr_response then
						local payload = string.format("sendResponse|%d|0|1|", dialog_id)
						sendCEF(payload)
						if dialog_id == 1295 then
							Data.auto_pr.pending_vr_response = false
							App.tasks.remove_by_name("vr_dialog_failsafe")
							if Data.auto_pr.last_vr_time then Data.auto_pr.last_vr_time = os.time() end
						end
						return false 
					end
					
					-- Обработка диалогов обмена денег
					if MoneyUseState.active then
						if MoneyUseState.step == 3 and dialog_id == 518 then
							MoneyUseState.step = 4
							App.tasks.add("money_use_step4", function()
								local payload = string.format("sendResponse|518|0|1|%d", MoneyUseState.amount)
								sendCEF(payload)
							end, 500)
							return false -- Скрываем диалог ввода суммы
						elseif MoneyUseState.step == 4 and dialog_id == 0 then
							MoneyUseState.step = 0
							MoneyUseState.active = false
							App.tasks.remove_by_name("money_use_timeout")
							
							App.tasks.add("money_use_step5", function()
								local payload = "sendResponse|0|0|1|"
								sendCEF(payload)
								
								-- Закрываем инвентарь и обновляем стату
								App.tasks.add("money_use_close", function()
									sendCEF("inventoryClose")
									sampAddChatMessage('[RMarket] {00ff00}Деньги успешно зачислены на баланс!', -1)
									
									sampSendChat("/stats")
									State.stats_requested_by_script = true
								end, 800)
							end, 500)
							return false -- Скрываем диалог успеха
						end
					end

					if App.is_selling_cef and App.current_processing_item and dialog_id == 240 then
						App.tasks.remove_by_name("cef_dialog_timeout")

						local payload
						local item = App.current_processing_item
						
						local clean_body = cleanTextColors(body)
						local body_lower = clean_body:lower()
						
						-- === [NEW] ПАРСИНГ ЗАТОЧКИ ===
						local upgrade_lvl = clean_body:match("Улучшение:%s*(%d+)%s*/") or clean_body:match("Заточка:%s*(%d+)")
						
						local suffix = ""
						if upgrade_lvl and tonumber(upgrade_lvl) > 0 then
							suffix = suffix .. " +" .. upgrade_lvl
						end

						if suffix ~= "" then
							if not item.name:find(suffix, 1, true) then
								item.name = item.name .. suffix
							end
							
							-- Синхронизируем новое имя с главным списком продажи, 
							-- чтобы оно попало в Market и отображалось в интерфейсе
							if Data.sell_list then
								for _, s_item in ipairs(Data.sell_list) do
									if s_item.slot == item.slot and s_item.model_id == item.model then
										if not s_item.name:find(suffix, 1, true) then
											s_item.name = s_item.name .. suffix
											s_item._u8_display_name = nil -- Сброс кэша имени для UI
											s_item._price_check_time = 0  -- Принудительное обновление UI
										end
										break
									end
								end
								saveListsConfig()
							end
						end
						-- ========================================

						local needs_comma = false
						-- [FIX] Более строгая проверка. 
						-- Раньше искало просто "количество", и это срабатывало на описание (например, "количество кликов" у граблей).
						-- Теперь ищем явное указание на ввод количества или запятой.
						if body_lower:find("запятую") or body_lower:find("введите количество") or body_lower:find("укажите количество") then
							needs_comma = true
						end
						
						local safe_price = tonumber(item.price) or 0
						local safe_amount = math.floor(tonumber(item.amount) or 1)

						if needs_comma then
							local stack_in_dialog = clean_body:match("стаке:%s*(%d+)")
							if stack_in_dialog then
								local real_stack = tonumber(stack_in_dialog)
								if real_stack and real_stack > 1 then
									if safe_amount == 1 then safe_amount = real_stack
									elseif safe_amount > real_stack then safe_amount = real_stack end
								end
							end
							payload = string.format("sendResponse|240|0|1|%d,%.0f", safe_amount, safe_price)
						else
							-- Для товаров без стака (аксы, инструменты) отправляем только цену
							payload = string.format("sendResponse|240|0|1|%.0f", safe_price)
						end

						sendCEF(payload)
						
						App.current_processing_item = nil
						
						-- [CRASH FIX] Жестко ограничиваем минимальную задержку.
						local delay = math.max(Data.settings.delay_placement or 150, 150)

						App.tasks.add("cef_next_item_delay", processNextCEFSellItem, delay)
						return false 
					end
				end
			end
		end
		
		if str:find("console.log") and str:find("modal: 7") then
			if Data.auto_pr.pending_vr_response or App.is_selling_cef or State.stats_requested_by_script then
				return false
			end
		end

		if str:find("event%.setActiveView") and str:find('%["Auth"%]') then
			Marketplace_Clear(true)
		end

		if str:find("cef%.addNotification") and str:find("Вы завершили торговлю") then
			Marketplace_Clear(true)
		end
		
		if str:find("cef%.addNotification") and str:find("ALT") then
			if App.render_radius then
                App.render_radius = false
                addToastNotification("Радиус выключен (лавка установлена)", "success")
            end
		end
		
		if str:find("cef%.addNotification") and (str:find("Вы успешно купили") or str:find("Вы успешно продали")) then
			local is_sale = str:find("Вы успешно продали")
			local action_word = is_sale and "продали" or "купили"
            
			-- Паттерны для поиска текста в сырой строке
			local pattern1 = "Вы успешно " .. action_word .. " (.-)%s*%((%d+) шт%.%) за ([%d%.%,%s]+) руб%."
			local pattern2 = "Вы успешно " .. action_word .. " (.-)%s*за ([%d%.%,%s]+) руб%."

			-- Ищем совпадение напрямую в строке
			local raw_item, amount_str, total_str = str:match(pattern1)
					
			if not raw_item then
				raw_item, total_str = str:match(pattern2)
				amount_str = "1"
			end
					
			if raw_item and total_str then
				-- Очищаем имя от префиксов (Предмет, Аксессуар и т.д.)
				local final_item_name = cleanItemName(raw_item)
				
				-- [FIX] Жесткая очистка неразрывных CEF пробелов
				local amount = tonumber((amount_str:gsub("%D", ""))) or 1
				local total = tonumber((total_str:gsub("%D", ""))) or 0
				local price = amount > 0 and math.floor(total / amount) or total
				
				-- Берем английский ник из кэша сканера лавки (самый точный), либо русский из модалки
				local seller_nick = ScanCollector.current_shop_owner or App.last_manual_buy_seller or "Неизвестный"
                
				local transaction = {
					timestamp = os.time(),
					date = os.date("%Y-%m-%d %H:%M:%S"),
					type = is_sale and "sale" or "purchase", 
					player = seller_nick,
					item = final_item_name,
					amount = amount,
					price = price,
					total = total
				}
						
				-- Функция сама запишет всё в Логи, посчитает маржу, добавит в статистику и вышлет в ТГ!
				addTransactionLog(transaction)
				App.last_manual_buy_seller = nil 
			end
		end
		
		if str:find("cef%.addNotification") and str:find("Вы успешно загрузили") then
			if State.restoration.waiting_confirmation then
                Data.live_shop.sell = {}
                for i, v in ipairs(State.restoration.pending_sell) do Data.live_shop.sell[i] = v end
                
                Data.live_shop.buy = {}
                for i, v in ipairs(State.restoration.pending_buy) do Data.live_shop.buy[i] = v end
					
				reconstructInventoryFromCache()
					
				App.live_shop_active = true
				Marketplace.enabled = true
				Marketplace.is_cleared = false
				Marketplace.publish_sell = (#Data.sell_list > 0)
				Marketplace.publish_buy = (#Data.buy_list > 0)
					
				Marketplace.LavkaUid = os.time()
					
				saveListsConfig()
				calculateSellTotal()
				calculateBuyTotal()
					
				MarketConfig.LAST_SYNC = 0 
				PrepareMarketplaceData()
					
				State.restoration.waiting_confirmation = false
				State.restoration.pending_sell = {}
				State.restoration.pending_buy = {}
					
				sampAddChatMessage('[RMarket] {00ff00}Лавка синхронизирована', -1)
			end
		end

		if str:find("event%.setActiveView") or str:find("window.rodina") then
			if App.remote_shop_active and not str:find("Inventory") then
				App.remote_shop_active = false
				Data.remote_shop_items = {} 
			end
		end

		if str:find("event%.inventory%.playerInventory") or str:find('%[%s*{%s*"action"') then
			if MoneyUseState.active then
				if str:find('"action":2') and MoneyUseState.step == 1 then
					MoneyUseState.step = 2
					App.tasks.add("money_use_step2", function()
						local payload = string.format('rightClickOnBlock|{"slot": %d, "type": 1}', MoneyUseState.slot)
						sendCEF(payload)
					end, 600)
				elseif str:find('"action":3') and MoneyUseState.step == 2 then
					MoneyUseState.step = 3
					App.tasks.add("money_use_step3", function()
						local payload = string.format('clickOnButton|{"type": 1,"slot": %d, "action": 1}', MoneyUseState.slot)
						sendCEF(payload)
					end, 300)
				end
			end
			parseCEFInventory(str)
		end

		return true
	end)

    ----------------------------------------------------------------
    -- ОСНОВНОЙ ЦИКЛ
    ----------------------------------------------------------------
    while true do
        wait(0)
        
        -- [NEW] ОТСЛЕЖИВАНИЕ СОСТОЯНИЯ ПОДКЛЮЧЕНИЯ (Кик / Рестарт / Таймаут)
        local current_gamestate = sampGetGamestate()
        -- 3 = GAMESTATE_CONNECTED (Игрок на сервере)
        if last_gamestate == 3 and current_gamestate ~= 3 then
            if not is_currently_disconnected then
                is_currently_disconnected = true
                sendDisconnectNotification("Потеря соединения (Кик / Рестарт сервера / Таймаут)", false)
            end
        elseif current_gamestate == 3 then
            is_currently_disconnected = false
        end
        last_gamestate = current_gamestate
        -- [END NEW]
        
        if Data.auto_pr.active then
            local now = os.time()
            if not Data.auto_pr.global_cooldown then Data.auto_pr.global_cooldown = 0 end
            if not Data.auto_pr.last_vr_time then Data.auto_pr.last_vr_time = 0 end
            
            -- Проверяем глобальный кулдаун (чтобы не спамить мгновенно)
            if now >= Data.auto_pr.global_cooldown then
                
                -- Проход по всем элементам верхнего уровня
                for i, item in ipairs(Data.auto_pr.items) do
                    if item.active then
                        -- Инициализация времени, если его нет
                        if not item.next_send then item.next_send = now + 2 + i end
                        
                        -- [NEW] ПРОВЕРКА ЛАВКИ
                        if item.shop_only and not isShopTrulyActive() then
                             -- ВАЖНО: Если лавка требуется, но её нет, мы не просто пропускаем,
                             -- а "толкаем" таймер вперёд. Это предотвращает мгновенный спам 
                             -- всеми накопившимися сообщениями сразу после создания лавки.
                             if now >= item.next_send then
                                 item.next_send = now + 1
                             end
                        else
                            -- Пришло ли время для этого элемента?
                            if now >= item.next_send then
                                
                                local text_to_send = nil
                                local channel_to_send = 1
                                local delay_after = 60
                                
                                -- ЛОГИКА 1: ОДИНОЧНОЕ СООБЩЕНИЕ
                                if item.type == "single" then
                                    text_to_send = item.text
                                    channel_to_send = item.channel
                                    delay_after = item.delay or 60
                                    
                                -- ЛОГИКА 2: ГРУППА
                                elseif item.type == "group" and item.items and #item.items > 0 then
                                    -- Берем текущий индекс
                                    if not item.current_idx then item.current_idx = 1 end
                                    if item.current_idx > #item.items then item.current_idx = 1 end
                                    
                                    local sub_item = item.items[item.current_idx]
                                    
                                    if sub_item then
                                        text_to_send = sub_item.text
                                        channel_to_send = sub_item.channel
                                        -- Задержка берется из настройки ГРУППЫ
                                        delay_after = item.delay or 10 
                                    end
                                    
                                    -- Готовим индекс для следующего раза
                                    item.current_idx = item.current_idx + 1
                                    if item.current_idx > #item.items then item.current_idx = 1 end
                                end
                                
                                -- ОТПРАВКА (Если есть текст)
                                if text_to_send and text_to_send ~= "" then
                                    local can_send_vr = true
                                    
                                    -- Проверка VIP чата (VR) на анти-флуд (раз в 5 мин)
                                    if channel_to_send == 1 then
                                        local time_since_vr = now - Data.auto_pr.last_vr_time
                                        -- Если прошло меньше 305 сек, VR отправлять нельзя
                                        if time_since_vr < 305 then 
                                            can_send_vr = false 
                                            -- Не сбрасываем next_send, ждем, пока освободится VR
                                        end
                                    end
                                    
                                    if can_send_vr then
                                        -- [NEW] ПОДСТАНОВКА ПЕРЕМЕННЫХ
                                        local final_text = processPRVariables(text_to_send)
                                        
                                        if channel_to_send == 1 then 
                                            Data.auto_pr.pending_vr_response = true
                                            App.tasks.add("vr_dialog_failsafe", function() Data.auto_pr.pending_vr_response = false end, 3000)
                                            sampSendChat("/vr " .. final_text)
                                            Data.auto_pr.last_vr_time = now 
                                        elseif channel_to_send == 2 then sampSendChat("/b " .. final_text)
                                        elseif channel_to_send == 3 then sampSendChat("/s " .. final_text)
                                        elseif channel_to_send == 4 then sampSendChat(final_text)
                                        elseif channel_to_send == 5 then sampSendChat("/fam " .. final_text) -- NEW
                                        elseif channel_to_send == 6 then sampSendChat("/al " .. final_text)  -- NEW
                                        end
                                        
                                        -- Ставим следующее время срабатывания ТОЛЬКО после успешной отправки
                                        item.next_send = now + delay_after
                                        Data.auto_pr.global_cooldown = now + 1.5 -- Глобальная пауза между любыми сообщениями
                                        
                                        break -- Прерываем цикл, чтобы отправить только одно сообщение за кадр
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        
        processHttpCallbacks()

        -- Снижаем частоту запросов с 6.0 до 8.0 секунд для разгрузки сети
        if os.clock() - last_action_check > 8.0 then
            checkRemoteActions()
            last_action_check = os.clock()
        end

        -- [NEW RADIUS UPDATE]
        if App.render_radius then
            local now = os.clock()
            if now - lastUpdate > UPDATE_INTERVAL then
                lastUpdate = now
                updateLavkas()
            end
        end

        if os.clock() - SaveScheduler.last_save_time > SaveScheduler.SAVE_DELAY then
            if SaveScheduler.lists_dirty then
                saveListsConfig(true)
                SaveScheduler.lists_dirty = false
            end
            if SaveScheduler.settings_dirty then
                saveSettings(true)
                SaveScheduler.settings_dirty = false
            end
            
            -- [CLOUD] Отложенная синхронизация конфигов
            if CloudSync.needs_push and not CloudSync.is_syncing then
                if os.clock() - CloudSync.last_push > 3.0 then -- 3 секунды задержки после последнего изменения
                    api_SyncConfigsToMiniApp()
                    CloudSync.needs_push = false
                    CloudSync.last_push = os.clock()
                end
            end
            
            if SaveScheduler.cars_dirty then
                CarMarket.save()
                SaveScheduler.cars_dirty = false
            end
            SaveScheduler.last_save_time = os.clock()
        end

        if App.script_loaded then
            -- [FIX RACE CONDITION] Обработка отложенной синхронизации (Debounce)
            if MarketConfig.SYNC_QUEUED_TIME and MarketConfig.SYNC_QUEUED_TIME > 0 then
                if os.clock() >= MarketConfig.SYNC_QUEUED_TIME then
                    MarketConfig.SYNC_QUEUED_TIME = 0
                    MarketConfig.LAST_SYNC = 0 -- Форсируем отправку ОДНОГО полного пакета
                end
            end
            
            ProcessMarketplaceSync()
            ProcessMarketplacePing()
        end

        if not App.script_loaded and os.clock() - script_load_time > 5.0 then
            if Data.sell_list then App.script_loaded = true end
        end

        App.tasks.process()

        local now = os.time()
        if now - ShopState.last_check_time > ShopState.check_interval then
            local active = false
            for _, item in ipairs(Data.sell_list) do if item.active then active = true break end end
            if not active then for _, item in ipairs(Data.buy_list) do if item.active then active = true break end end end
            ShopState.has_active_items = active
            ShopState.last_check_time = now
        end
    end
end

function onScriptTerminate(script, quit)
    if script == thisScript() then
        
        -- [FIX] Корректно завершаем фоновые Effil потоки, чтобы избежать залипания каналов при перезагрузке
        if HttpSystem.threads_initialized then
            for i = 1, #HttpSystem.threads do
                HttpSystem.channel_in:push({ command = 'STOP' })
            end
        end

        -- [NEW] ОТПРАВКА УВЕДОМЛЕНИЯ ПРИ ВЫХОДЕ / КРАШЕ
        if quit then
            -- Вызываем СИНХРОННУЮ отправку. 
            -- Скрипт "подвиснет" на 0.5 - 1 секунду перед закрытием окна игры, 
            -- чтобы 100% успеть доставить пакет на сервер.
            sendDisconnectNotification("Выход из игры (/q) или Краш клиента", true)
        end

        -- [PROTECT] Сбрасываем флаг загрузки
        App.data_loading = false
        
        -- CRITICAL GUARD 1: Если скрипт не успел загрузиться, НЕ СОХРАНЯЕМ ничего
        if not App.script_loaded or not Lifecycle.settings_loaded then 
            print("[RMarket] Terminate during load (Safety Trigger). SAVE ABORTED.") 
            return 
        end
        
        -- CRITICAL GUARD 2: Проверка целостности данных
        if not validateDataIntegrity() then
            print("[RMarket] Terminate with corrupted data structures. SAVE ABORTED.")
            return
        end
        
        -- CRITICAL GUARD 3: Проверка на пустые списки (защита от вайпа)
        if #Data.buy_configs == 0 and doesFileExist(PATHS.PROFILES_BUY) then
             -- Дополнительная логика защиты
        end

        print("[RMarket] Graceful shutdown. Saving data...")
        
        -- Сохраняем только если прошли все проверки
        local status_list, _ = pcall(saveListsConfig, true)
        if not status_list then print("[RMarket] Error saving lists on terminate") end
        
        local status_sets, _ = pcall(saveSettings, true)
        if not status_sets then print("[RMarket] Error saving settings on terminate") end
        
        pcall(saveLiveShopState)

        -- Кэши (не критично)
        pcall(saveJsonFile, PATHS.DATA .. 'item_amounts.json', Data.inventory_item_amounts)
        pcall(saveJsonFile, PATHS.CACHE .. 'scanned_items.json', Data.scanned_items)
        pcall(saveJsonFile, PATHS.LOGS .. 'transactions.json', Data.transaction_logs)
        pcall(saveJsonFile, FILES.CACHE_DAILY, Data.daily_item_prices)
    end
end

function injectJS(code)
    code = "/*RM_INJ*/ " .. code
    local bs = raknetNewBitStream()
    raknetBitStreamWriteInt8(bs, 17)
    raknetBitStreamWriteInt32(bs, 0)
    raknetBitStreamWriteInt16(bs, #code)
    raknetBitStreamWriteInt8(bs, 0)
    raknetBitStreamWriteString(bs, code)
    raknetEmulPacketReceiveBitStream(220, bs)
    raknetDeleteBitStream(bs)
end
